import { AGENT_FX_LIBRARY } from "./agent-effects-data.js";

console.log("SCRIPT START");

// ========================
// CORE UTILITIES (EARLY LOAD FIX)
// ========================

function safeNumber(v, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function safeDivide(numerator, denominator) {
  const num = Number(numerator);
  const den = Number(denominator);
  if (!Number.isFinite(num) || !Number.isFinite(den) || den === 0) return 0;
  return num / den;
}

function nowISO() {
  return new Date().toISOString();
}

function getCurrentDayKey() {
  return nowISO().slice(0, 10);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Central language guardrail for generated coaching copy. Keep tactical terms clear,
// human, and consistent with Ask Coach instead of letting engine fallbacks drift.
const RANKEDCOACH_LANGUAGE_REPLACEMENTS = [
  [/\bside split\b/gi, "ATK/DEF"],
  [/\bside disparity\b/gi, "ATK/DEF gap"],
  [/\btracked rounds\b/gi, "rounds reported"],
  [/\bclass\b/gi, "Weapon Category"],
  [/\bseen\b/gi, "reported"],
  [/\bself-reported\b/gi, "self-rated"],
  [/\bcluster\b/gi, "pattern"],
  [/\bedge\b/gi, "strength"],
  [/\bleak\b/gi, "issue"],
  [/\bMachine Learning model\b/g, "coaching model"],
  [/\bmoving average\b/gi, "profile baseline"],
  [/\bjudgement\b/gi, "judgment"],
  [/\bdiagnosis\b/gi, "read"],
  [/\bdata read\b/gi, "coaching read"],
  [/\bfour-lens\b/gi, "four-category"],
  [/\blens\b/gi, "category"],
  [/\bPractice Theme Is Emerging\b/g, "Focus Category to Observe"],
  [/\bPractice Theme is Emerging\b/g, "Focus Category to Observe"],
  [/\bReliable Duel Output\b/g, "Reliable Dueling"],
  [/Weapon reliance is context, not a penalty\. It helps RankedCoach avoid grading every profile like rifle-only play\./g, "Weapon reliance is context being applied to the Machine Learning model. It helps RankedCoach avoid grading every profile like rifle-only play."],
  [/Your combat impact is showing up at a healthy level in the current sample\./g, "Your combat impact is strong in your profile."],
  [/Your recent matches are below your season average, so RankedCoach is reading this as a short-term dip\./g, "Your recent matches are below your average level of play, so RankedCoach is reading this as a short-term dip in performance."],
  [/Your accuracy is stable enough that RankedCoach can look beyond aim alone\./g, "Your precision is stable enough that RankedCoach can look beyond aim alone."]
];

function normalizeRankedCoachCopy(value = "") {
  if (value == null) return value;
  if (typeof value !== "string") return value;

  let text = value;
  RANKEDCOACH_LANGUAGE_REPLACEMENTS.forEach(([pattern, replacement]) => {
    text = text.replace(pattern, replacement);
  });

  return text.replace(/(^|[.!?]\s+)([a-z])/g, (_match, prefix, firstLetter) => `${prefix}${firstLetter.toUpperCase()}`);
}

function logCountLabel(count = 0) {
  const safeCount = Math.round(safeNumber(count));
  return `${safeCount} log${safeCount === 1 ? "" : "s"}`;
}

function parseLocalDate(value) {
  if (typeof value === "string" && /^\d{4}-\d{2}-\d{2}$/.test(value)) {
    const [year, month, day] = value.split("-").map(Number);
    return new Date(year, month - 1, day);
  }
  return new Date(value);
}

function formatDateLabel(value) {
  const d = parseLocalDate(value);
  if (Number.isNaN(d.getTime())) return "Unknown Session";
  return d.toLocaleDateString(undefined, {
    month: "short",
    day: "numeric",
    year: "numeric"
  });
}

function getWeekStart(date = new Date()) {
  const d = new Date(date);
  const day = d.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  d.setHours(0, 0, 0, 0);
  d.setDate(d.getDate() + diff);
  return d;
}

function formatLocalDateKey(date = new Date()) {
  const d = new Date(date);
  if (Number.isNaN(d.getTime())) return "";
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatWeeklyFocusDate(date = new Date()) {
  return getWeekStart(date).toLocaleDateString(undefined, {
    month: "numeric",
    day: "numeric",
    year: "numeric"
  });
}

function formatWeeklyFocusRange(date = new Date()) {
  const start = getWeekStart(date);
  const end = getWeekEnd(date);
  return `${start.toLocaleDateString(undefined, { month: "short", day: "numeric" })} - ${end.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}`;
}

function updateWeeklyFocusDateLabel(date = new Date()) {
  const wf = document.getElementById("weeklyFocusDate");
  if (wf) {
    wf.textContent = formatWeeklyFocusDate(date);
    wf.title = `Current weekly review window: ${formatWeeklyFocusRange(date)}`;
  }
}

let weeklyFocusRolloverTimer = null;

function scheduleWeeklyFocusRollover() {
  if (typeof window === "undefined") return;
  if (weeklyFocusRolloverTimer) {
    window.clearTimeout(weeklyFocusRolloverTimer);
  }

  const now = new Date();
  const nextWeekStart = getWeekStart(now);
  nextWeekStart.setDate(nextWeekStart.getDate() + 7);
  nextWeekStart.setMilliseconds(250);

  weeklyFocusRolloverTimer = window.setTimeout(() => {
    updateWeeklyFocusDateLabel();
    renderInsights();
    scheduleWeeklyFocusRollover();
  }, Math.max(1000, nextWeekStart.getTime() - now.getTime()));
}

const DAILY_WARMUP_DRILL_LIMIT = 4;
const DAILY_WARMUP_PROMPT_STORAGE_PREFIX = "valtracker_daily_warmup_prompt_v1:";
const DAILY_WARMUP_DRILLS = Object.freeze({
  "weapon-choice": "Weapon Choice",
  "burst-peeking": "Burst Peeking",
  "burst-peeking-strafe": "Burst Peeking w/ Strafe",
  "tap-fire-rhythm": "Tap Fire Rhythm Training",
  "easy-bots-flicking": "Easy Bots Flicking",
  "medium-bots-flicking": "Medium Bots Flicking",
  "hard-bots-flicking": "Hard Bots Flicking",
  "head-tracking": "Head Tracking",
  "head-tracking-strafe": "Head Tracking w/ Strafe",
  "drone-target-switching": "Drone Target Switching",
  "spray-control-dummy": "Spray Control Target Dummy"
});
const DAILY_WARMUP_DRILL_ALIASES = Object.freeze({
  aimstars: "drone-target-switching",
  miyagi: "head-tracking",
  "range-accuracy": "easy-bots-flicking",
  "range-tracking": "head-tracking-strafe",
  reaction: "hard-bots-flicking",
  weapon: "weapon-choice",
  "gunfight-hygiene": "burst-peeking"
});
let dailyWarmupPromptTimer = 0;
let profileStreakAnnouncementTimer = 0;
const warmupVerificationInFlight = new Set();

function getDailyWarmupPromptDate(profile = getActiveProfile?.()) {
  if (!profile?.id) return "";
  let localDate = "";
  try {
    localDate = localStorage.getItem(`${DAILY_WARMUP_PROMPT_STORAGE_PREFIX}${profile.id}`) || "";
  } catch (_error) {
    // The synced profile field still enforces the guard if storage is unavailable.
  }
  return String(profile.lastWarmupPromptDate || localDate || "");
}

function markDailyWarmupPromptDate(profile, date) {
  if (!profile?.id || !date) return;
  try {
    localStorage.setItem(`${DAILY_WARMUP_PROMPT_STORAGE_PREFIX}${profile.id}`, date);
  } catch (_error) {
    // Profile persistence below remains the source of truth across devices.
  }
}

function normalizeWarmupLogEntry(entry = {}) {
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(entry?.date || "")) ? String(entry.date) : "";
  if (!date) return null;
  const drillsSelected = [...new Set((Array.isArray(entry?.drillsSelected) ? entry.drillsSelected : [])
    .map(value => String(value || "").trim())
    .map(value => DAILY_WARMUP_DRILL_ALIASES[value] || value)
    .filter(value => Object.prototype.hasOwnProperty.call(DAILY_WARMUP_DRILLS, value)))]
    .slice(0, DAILY_WARMUP_DRILL_LIMIT);
  return {
    date,
    drillsSelected,
    weapon: String(entry?.weapon || "").trim().slice(0, 30),
    rangeDrillsSelfReported: entry?.rangeDrillsSelfReported === true,
    dmTdmSelfReported: entry?.dmTdmSelfReported === true,
    dmTdmAutoVerified: entry?.dmTdmAutoVerified === true,
    dmTdmVerifiedMatches: Math.max(0, safeNumber(entry?.dmTdmVerifiedMatches)),
    warmupLogEntryId: String(entry?.warmupLogEntryId || ""),
    warmupFeedMarkerHidden: entry?.warmupFeedMarkerHidden === true,
    postGameAimTrainingCommitted: entry?.postGameAimTrainingCommitted === true,
    postGameCommittedAt: String(entry?.postGameCommittedAt || ""),
    postGameLogEntryId: String(entry?.postGameLogEntryId || ""),
    skipped: entry?.skipped === true,
    status: ["prompted", "completed", "skipped"].includes(entry?.status) ? entry.status : "prompted",
    promptedAt: String(entry?.promptedAt || ""),
    completedAt: String(entry?.completedAt || ""),
    verifiedAt: String(entry?.verifiedAt || "")
  };
}

function normalizeWarmupLog(entries = []) {
  const byDate = new Map();
  (Array.isArray(entries) ? entries : []).forEach(entry => {
    const normalized = normalizeWarmupLogEntry(entry);
    if (normalized) byDate.set(normalized.date, normalized);
  });
  return [...byDate.values()].sort((a, b) => a.date.localeCompare(b.date)).slice(-180);
}

function getProfileMatchDateKeys(profile = getActiveProfile?.()) {
  const profileMatches = Array.isArray(profile?.matches)
    ? profile.matches
    : (profile?.id === activeProfileId && Array.isArray(matches) ? matches : []);
  return [...new Set(profileMatches.map(match => {
    const core = getMatchCore(match);
    const playedAt = core?.createdAt || match?.createdAt || match?.metadata?.playedAt || match?.matchRecord?.playedAt || "";
    const date = new Date(playedAt);
    return Number.isNaN(date.getTime()) ? "" : formatLocalDateKey(date);
  }).filter(Boolean))];
}

function getConsecutiveDayStreak(dateKeys = [], anchorDate = new Date()) {
  const dates = new Set(dateKeys);
  const cursor = new Date(anchorDate);
  cursor.setHours(12, 0, 0, 0);
  if (!dates.has(formatLocalDateKey(cursor))) return 0;
  let streak = 0;
  while (dates.has(formatLocalDateKey(cursor))) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 1);
  }
  return streak;
}

function getTrainingWeekKey(dateValue = new Date()) {
  const date = dateValue instanceof Date ? new Date(dateValue) : new Date(`${dateValue}T12:00:00`);
  if (Number.isNaN(date.getTime())) return "";
  date.setHours(12, 0, 0, 0);
  const day = (date.getDay() + 6) % 7;
  date.setDate(date.getDate() - day);
  return formatLocalDateKey(date);
}

function getConsecutiveAimWeekStreak(warmupLog = [], anchorDate = new Date()) {
  const completedWeeks = new Set(normalizeWarmupLog(warmupLog)
    .filter(entry => entry.postGameAimTrainingCommitted)
    .map(entry => getTrainingWeekKey(entry.date))
    .filter(Boolean));
  const cursor = new Date(anchorDate);
  cursor.setHours(12, 0, 0, 0);
  cursor.setDate(cursor.getDate() - ((cursor.getDay() + 6) % 7));
  if (!completedWeeks.has(formatLocalDateKey(cursor))) return 0;
  let streak = 0;
  while (completedWeeks.has(formatLocalDateKey(cursor))) {
    streak += 1;
    cursor.setDate(cursor.getDate() - 7);
  }
  return streak;
}

function getProfileTrainingStreaks(profile = getActiveProfile?.()) {
  const warmupLog = normalizeWarmupLog(profile?.warmupLog);
  const completedWarmupDates = warmupLog.filter(isDailyWarmupCompleted).map(entry => entry.date);
  return {
    games: getConsecutiveDayStreak(getProfileMatchDateKeys(profile)),
    warmups: getConsecutiveDayStreak(completedWarmupDates),
    aimWeeks: getConsecutiveAimWeekStreak(warmupLog)
  };
}

function getRankedGameStreakLabel(days = 0) {
  if (days >= 30) return "Ranked Demon";
  if (days >= 25) return "Nightmare Streak";
  if (days >= 20) return "Riot Streak";
  if (days >= 15) return "Rampage Streak";
  if (days >= 10) return "Frenzy Streak";
  if (days >= 5) return "Hot Streak";
  return `${days}-Day Ranked Streak`;
}

function announceProfileStreaks(profile = getActiveProfile?.()) {
  if (!profile?.id || !currentAuthUser) return;
  const streaks = getProfileTrainingStreaks(profile);
  const messages = [];
  if (streaks.games > 0) messages.push(`${getRankedGameStreakLabel(streaks.games)}: ${streaks.games} consecutive game day${streaks.games === 1 ? "" : "s"}.`);
  if (streaks.warmups > 0) messages.push(`${streaks.warmups}-day warm-up streak.`);
  if (streaks.aimWeeks > 0) messages.push(`${streaks.aimWeeks}-week aim-training streak.`);
  if (!messages.length) return;
  const today = formatLocalDateKey();
  const fingerprint = `${streaks.games}:${streaks.warmups}:${streaks.aimWeeks}`;
  const storageKey = `rankedcoach-streak-announcement:${profile.id}:${today}`;
  try {
    if (localStorage.getItem(storageKey) === fingerprint) return;
    localStorage.setItem(storageKey, fingerprint);
  } catch (_error) {
    // A blocked storage write should not block the player-facing confirmation.
  }
  showToast?.(messages.join(" "), {
    title: streaks.games >= 5 ? getRankedGameStreakLabel(streaks.games) : "Training streak updated",
    tone: "success"
  });
}

function scheduleProfileStreakAnnouncement(delay = 850) {
  window.clearTimeout(profileStreakAnnouncementTimer);
  profileStreakAnnouncementTimer = window.setTimeout(() => {
    profileStreakAnnouncementTimer = 0;
    announceProfileStreaks(getActiveProfile?.());
  }, Math.max(0, delay));
}

function buildProfileActivityHeatmapMarkup(profile = getActiveProfile?.()) {
  const counts = new Map();
  const profileMatches = Array.isArray(profile?.matches)
    ? profile.matches
    : (profile?.id === activeProfileId && Array.isArray(matches) ? matches : []);
  profileMatches.forEach(match => {
    const core = getMatchCore(match);
    const date = new Date(core?.createdAt || match?.createdAt || match?.metadata?.playedAt || 0);
    if (Number.isNaN(date.getTime())) return;
    const key = formatLocalDateKey(date);
    counts.set(key, (counts.get(key) || 0) + 1);
  });
  const days = [];
  let activeDays = 0;
  const cursor = new Date();
  cursor.setHours(12, 0, 0, 0);
  cursor.setDate(cursor.getDate() - 29);
  for (let index = 0; index < 30; index += 1) {
    const date = new Date(cursor);
    date.setDate(cursor.getDate() + index);
    const key = formatLocalDateKey(date);
    const count = counts.get(key) || 0;
    if (count > 0) activeDays += 1;
    const level = count === 0 ? 0 : count === 1 ? 1 : count <= 3 ? 2 : count <= 5 ? 3 : 4;
    const label = `${date.toLocaleDateString(undefined, { month: "short", day: "numeric" })}: ${count} ranked game${count === 1 ? "" : "s"}`;
    days.push(`<span class="profile-activity-day level-${level}" title="${escapeHtml(label)}" aria-label="${escapeHtml(label)}"></span>`);
  }
  return `
    <section class="profile-activity-heatmap" aria-label="Ranked games played over the last 30 days">
      <div class="profile-activity-heading">
        <strong>30-Day Ranked Activity</strong>
        <span>${activeDays} active days</span>
      </div>
      <div class="profile-activity-grid">${days.join("")}</div>
      <div class="profile-activity-legend"><span>Less</span><i class="level-0"></i><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><span>More</span></div>
    </section>
  `;
}

function getDailyWarmupRecord(profile = getActiveProfile?.(), date = formatLocalDateKey()) {
  return normalizeWarmupLog(profile?.warmupLog).find(entry => entry.date === date) || null;
}

function isDailyWarmupCompleted(record = null) {
  return Boolean(record && record.skipped !== true && (
    record.status === "completed"
    || record.dmTdmSelfReported === true
    || record.dmTdmAutoVerified === true
    || (Array.isArray(record.drillsSelected) && record.drillsSelected.length > 0)
  ));
}

function getTrainingEntryDate(entry = {}) {
  const date = new Date(entry?.createdAt || 0);
  return Number.isNaN(date.getTime()) ? "" : formatLocalDateKey(date);
}

function getDailyTrainingEntries(date = formatLocalDateKey(), profileId = activeProfileId) {
  return getProfileLogEntries?.(profileId)
    .filter(entry => getTrainingEntryDate(entry) === date)
    .sort((a, b) => new Date(a?.createdAt || 0).getTime() - new Date(b?.createdAt || 0).getTime());
}

function resolveWarmupTrainingEntry(entries = [], record = null) {
  if (!record || record.warmupFeedMarkerHidden === true || !isDailyWarmupCompleted(record)) return null;
  const ordered = (Array.isArray(entries) ? entries : [])
    .slice()
    .sort((a, b) => new Date(a?.createdAt || 0) - new Date(b?.createdAt || 0));
  const explicit = ordered.find(entry => String(entry.id) === String(record.warmupLogEntryId || ""));
  if (explicit) return explicit;
  const completedAt = new Date(record.completedAt || 0).getTime();
  if (Number.isFinite(completedAt) && completedAt > 0) {
    return ordered.find(entry => new Date(entry?.createdAt || 0).getTime() >= completedAt) || null;
  }
  const manuallyMarked = ordered.find(entry => entry?.warmup === true);
  if (manuallyMarked) return manuallyMarked;
  return ordered[0] || null;
}

function persistWarmupTrainingEntry(profile = getActiveProfile?.(), date = formatLocalDateKey()) {
  const record = getDailyWarmupRecord(profile, date);
  if (!profile?.id || !record || record.warmupLogEntryId) return null;
  const linkedEntry = resolveWarmupTrainingEntry(getDailyTrainingEntries(date, profile.id), record);
  if (!linkedEntry?.id) return null;
  writeDailyWarmupRecord(profile, { date, warmupLogEntryId: String(linkedEntry.id) });
  return linkedEntry;
}

function getDailyTrainingFeedMarkers(entries = getProfileLogEntries?.(), profile = getActiveProfile?.()) {
  const groups = new Map();
  (Array.isArray(entries) ? entries : []).forEach(entry => {
    const date = getTrainingEntryDate(entry);
    if (!date) return;
    if (!groups.has(date)) groups.set(date, []);
    groups.get(date).push(entry);
  });

  const markers = new Map();
  groups.forEach((dayEntries, date) => {
    const record = getDailyWarmupRecord(profile, date);
    if (!record) return;
    const ordered = dayEntries.slice().sort((a, b) => new Date(a?.createdAt || 0) - new Date(b?.createdAt || 0));
    const linkedWarmup = resolveWarmupTrainingEntry(ordered, record);
    const linkedPostGame = ordered.find(entry => String(entry.id) === String(record.postGameLogEntryId || "")) || null;
    if (linkedWarmup) {
      markers.set(linkedWarmup.id, { ...(markers.get(linkedWarmup.id) || {}), warmup: true, date });
    }
    if (record.postGameAimTrainingCommitted && linkedPostGame) {
      markers.set(linkedPostGame.id, { ...(markers.get(linkedPostGame.id) || {}), postGame: true, date });
    }
  });
  return markers;
}

function getTrainingCrosshairMarkup() {
  return `<svg viewBox="0 0 24 24" focusable="false" aria-hidden="true"><circle cx="12" cy="12" r="5"></circle><path d="M12 2v5M12 17v5M2 12h5M17 12h5"></path></svg>`;
}

function writeDailyWarmupRecord(profile, patch = {}) {
  if (!profile?.id) return null;
  const date = String(patch.date || formatLocalDateKey());
  const current = getDailyWarmupRecord(profile, date) || { date, status: "prompted" };
  const next = normalizeWarmupLogEntry({ ...current, ...patch, date });
  const warmupLog = normalizeWarmupLog([
    ...normalizeWarmupLog(profile.warmupLog).filter(entry => entry.date !== date),
    next
  ]);
  updateProfile(profile.id, {
    warmupLog,
    lastWarmupPromptDate: patch.lastWarmupPromptDate ?? profile.lastWarmupPromptDate
  });
  return next;
}

function getWarmupCorrelation(profile = getActiveProfile?.()) {
  return globalThis.RankedCoachWarmupCorrelation?.compute?.({
    warmupLog: profile?.warmupLog || [],
    matches: profile?.matches || []
  }) || { ready: false, status: "unavailable" };
}

function renderDailyWarmupCorrelationStatus(profile = getActiveProfile?.()) {
  const target = document.getElementById("dailyWarmupCorrelationStatus");
  if (!target) return;
  const correlation = getWarmupCorrelation(profile);
  if (correlation.ready) {
    target.textContent = `${correlation.confidence}: ${correlation.warm.days} warm-up days vs ${correlation.comparison.days} comparison days. Correlation is shown as context, not proof of cause.`;
    return;
  }
  const required = correlation.requiredDaysPerGroup || 7;
  target.textContent = correlation.status === "no-warmup-days"
    ? `Correlation starts after ${required} warm-up days and ${required} comparison days with ranked matches.`
    : `Building correlation sample: ${correlation.warm?.days || 0}/${required} warm-up days and ${correlation.comparison?.days || 0}/${required} comparison days.`;
}

function renderDailyWarmupVerification(profile = getActiveProfile?.(), date = formatLocalDateKey()) {
  const target = document.getElementById("dailyWarmupVerification");
  if (!target) return;
  const record = getDailyWarmupRecord(profile, date);
  target.classList.toggle("is-verified", record?.dmTdmAutoVerified === true);
  if (record?.dmTdmAutoVerified) {
    target.textContent = `Henrik verified ${record.dmTdmVerifiedMatches || 1} DM/TDM warm-up match${record.dmTdmVerifiedMatches === 1 ? "" : "es"} today.`;
  } else if (profile?.puuid) {
    target.textContent = "Henrik verification will check today's retained DM/TDM history after sync.";
  } else {
    target.textContent = "Range drills and DM/TDM stay self-reported until a Henrik profile is linked.";
  }
}

function renderLoggingTrainingMenuState(profile = getActiveProfile?.()) {
  const button = document.getElementById("loggingTrainingMenuBtn");
  if (!button) return;
  const record = getDailyWarmupRecord(profile);
  const warmupComplete = isDailyWarmupCompleted(record);
  const postGameComplete = record?.postGameAimTrainingCommitted === true;
  const fire = document.getElementById("loggingTrainingMenuFire");
  const crosshair = document.getElementById("loggingTrainingMenuCrosshair");
  const title = document.getElementById("loggingTrainingMenuTitle");
  const status = document.getElementById("loggingTrainingMenuStatus");
  button.dataset.trainingMode = warmupComplete ? "postgame" : "warmup";
  button.classList.toggle("is-complete", postGameComplete);
  if (fire) fire.hidden = warmupComplete;
  if (crosshair) crosshair.hidden = !warmupComplete;
  if (title) title.textContent = warmupComplete ? "Post-Game Aim Training" : "Warm-Up Menu";
  if (status) {
    status.textContent = postGameComplete
      ? "Completed after your latest linked game. Tap to review or remove it."
      : warmupComplete
        ? "Warm-up saved. Return here after your final game."
        : "Choose up to four drills before your first ranked game.";
  }
  button.setAttribute("aria-label", `${title?.textContent || "Training menu"}. ${status?.textContent || ""}`);
}

function renderDailyPostgameState(profile = getActiveProfile?.(), date = formatLocalDateKey()) {
  const record = getDailyWarmupRecord(profile, date);
  const committed = record?.postGameAimTrainingCommitted === true;
  const button = document.getElementById("dailyWarmupPostgameCommit");
  const text = document.getElementById("dailyWarmupPostgameCommitText");
  const status = document.getElementById("dailyWarmupPostgameStatus");
  const entries = getDailyTrainingEntries(date, profile?.id);
  button?.classList.toggle("is-complete", committed);
  button?.setAttribute("aria-pressed", committed ? "true" : "false");
  if (text) text.textContent = committed ? "Post-game training completed" : "Mark post-game training complete";
  if (status) {
    status.textContent = committed
      ? "Linked to the game this training followed. Select again to remove the marker."
      : entries.length
        ? "Completion will attach to your latest game from this session."
        : "Complete or import a ranked game before marking post-game training.";
  }
  if (button) button.disabled = !committed && entries.length === 0;
}

function setDailyTrainingModalMode(mode = "warmup", options = {}) {
  const modal = document.getElementById("dailyWarmupModal");
  const resolvedMode = mode === "postgame" ? "postgame" : "warmup";
  if (!modal) return;
  modal.dataset.trainingMode = resolvedMode;
  modal.dataset.trainingDate = String(options.date || formatLocalDateKey());
  modal.dataset.dismissBehavior = options.dismissBehavior === "skip" ? "skip" : "close";
  document.querySelectorAll('[data-daily-training-section="warmup"]').forEach(element => {
    element.hidden = resolvedMode !== "warmup";
  });
  const postGame = document.querySelector('[data-daily-training-section="postgame"]');
  if (postGame) postGame.hidden = resolvedMode !== "postgame";
  const kicker = document.getElementById("dailyWarmupKicker");
  const title = document.getElementById("dailyWarmupTitle");
  const skip = document.getElementById("dailyWarmupSkip");
  const close = document.getElementById("dailyWarmupClose");
  if (kicker) kicker.textContent = resolvedMode === "postgame" ? "Post-Game Aim Training" : "Daily Warm-Up Check";
  if (title) title.textContent = resolvedMode === "postgame" ? "Close the session with clean reps" : "Get your first fights ready";
  if (skip) skip.textContent = modal.dataset.dismissBehavior === "skip" ? "Skip today" : "Close";
  if (close) close.setAttribute("aria-label", resolvedMode === "postgame" ? "Close post-game aim training" : "Close warm-up menu");
}

function resetDailyWarmupModal(profile = getActiveProfile?.(), date = document.getElementById("dailyWarmupModal")?.dataset.trainingDate || formatLocalDateKey()) {
  const record = getDailyWarmupRecord(profile, date);
  const warmupMode = document.getElementById("dailyWarmupModal")?.dataset.trainingMode !== "postgame";
  const selected = new Set(record?.drillsSelected || []);
  document.querySelectorAll("[data-warmup-drill]").forEach(button => {
    const isSelected = selected.has(button.dataset.warmupDrill);
    button.classList.toggle("is-selected", isSelected);
    button.setAttribute("aria-pressed", isSelected ? "true" : "false");
  });
  const count = document.getElementById("dailyWarmupCount");
  if (count) count.textContent = `${selected.size} / ${DAILY_WARMUP_DRILL_LIMIT}`;
  const weaponField = document.getElementById("dailyWarmupWeaponField");
  if (weaponField) weaponField.hidden = !warmupMode || !selected.has("weapon-choice");
  const weapon = document.getElementById("dailyWarmupWeapon");
  if (weapon) weapon.value = record?.weapon || "";
  const dmTdm = document.getElementById("dailyWarmupDmTdm");
  if (dmTdm) dmTdm.checked = record?.dmTdmSelfReported === true;
  renderDailyWarmupVerification(profile, date);
  renderDailyWarmupCorrelationStatus(profile);
  renderDailyPostgameState(profile, date);
  renderLoggingTrainingMenuState(profile);
}

function openDailyTrainingMenu(options = {}) {
  const profile = getActiveProfile?.();
  if (!profile?.id) return false;
  const date = String(options.date || formatLocalDateKey());
  const record = getDailyWarmupRecord(profile, date);
  const mode = options.mode || (isDailyWarmupCompleted(record) ? "postgame" : "warmup");
  setDailyTrainingModalMode(mode, {
    date,
    dismissBehavior: options.dismissBehavior || "close"
  });
  resetDailyWarmupModal(profile, date);
  showModalById?.("dailyWarmupModal");
  return true;
}

function openDailyWarmupCheck() {
  const profile = getActiveProfile?.();
  if (!profile?.id) return false;
  const today = formatLocalDateKey();
  if (getDailyWarmupPromptDate(profile) === today) return false;
  markDailyWarmupPromptDate(profile, today);
  writeDailyWarmupRecord(profile, {
    date: today,
    status: "prompted",
    skipped: false,
    promptedAt: nowISO(),
    lastWarmupPromptDate: today
  });
  return openDailyTrainingMenu({ mode: "warmup", date: today, dismissBehavior: "skip" });
}

function canOpenDailyWarmupCheck() {
  if (document.documentElement?.classList.contains("app-booting")) return false;
  if (!hasCompletedAppEntryChoice?.()) return false;
  const activePage = getActivePageElement?.()?.id || "";
  if (!["page-home", "page-logging"].includes(activePage)) return false;
  const blockingModal = [...document.querySelectorAll(".lens-modal-overlay.active, .lens-modal-overlay.is-opening")]
    .some(modal => modal.id !== "dailyWarmupModal" && modal.getAttribute("aria-hidden") !== "true");
  return !blockingModal;
}

function scheduleDailyWarmupCheck(delay = 700) {
  if (dailyWarmupPromptTimer) window.clearTimeout(dailyWarmupPromptTimer);
  const profile = getActiveProfile?.();
  if (!profile || getDailyWarmupPromptDate(profile) === formatLocalDateKey()) return;
  dailyWarmupPromptTimer = window.setTimeout(() => {
    dailyWarmupPromptTimer = 0;
    if (canOpenDailyWarmupCheck()) openDailyWarmupCheck();
    else if (["page-home", "page-logging"].includes(getActivePageElement?.()?.id || "")) scheduleDailyWarmupCheck(700);
  }, Math.max(100, delay));
}

function skipDailyWarmupCheck() {
  const profile = getActiveProfile?.();
  const date = document.getElementById("dailyWarmupModal")?.dataset.trainingDate || formatLocalDateKey();
  if (profile) {
    writeDailyWarmupRecord(profile, {
      date,
      status: "skipped",
      skipped: true,
      drillsSelected: [],
      rangeDrillsSelfReported: false,
      dmTdmSelfReported: false,
      warmupLogEntryId: "",
      warmupFeedMarkerHidden: true
    });
  }
  hideModalById?.("dailyWarmupModal");
  showToast?.("Warm-up skipped for today. Queue when you feel ready.", { tone: "neutral" });
}

function closeDailyTrainingMenu() {
  const modal = document.getElementById("dailyWarmupModal");
  if (modal?.dataset.dismissBehavior === "skip" && modal?.dataset.trainingMode === "warmup") {
    skipDailyWarmupCheck();
    return;
  }
  hideModalById?.("dailyWarmupModal");
}

async function refreshWarmupAutoVerification(profile = getActiveProfile?.(), options = {}) {
  if (!profile?.id || !profile?.puuid || !globalThis.RankedCoachRiotSync?.checkWarmupMatches) return null;
  if (warmupVerificationInFlight.has(profile.id)) return null;
  warmupVerificationInFlight.add(profile.id);
  const target = document.getElementById("dailyWarmupVerification");
  if (target && getActiveProfile?.()?.id === profile.id) target.textContent = "Checking Henrik for today's DM/TDM matches...";
  try {
    const result = await globalThis.RankedCoachRiotSync.checkWarmupMatches({
      puuid: profile.puuid,
      region: profile.region,
      count: 10
    });
    const countsByDate = new Map();
    (result?.matches || []).forEach(match => {
      const key = formatLocalDateKey(new Date(match.playedAt || 0));
      if (!key) return;
      countsByDate.set(key, (countsByDate.get(key) || 0) + 1);
    });
    const currentProfile = profiles.find(item => item.id === profile.id);
    if (!currentProfile) return result;
    let changed = false;
    const warmupLog = normalizeWarmupLog(currentProfile.warmupLog).map(entry => {
      const verifiedMatches = countsByDate.get(entry.date) || 0;
      if (!verifiedMatches || (entry.dmTdmAutoVerified && entry.dmTdmVerifiedMatches === verifiedMatches)) return entry;
      changed = true;
      return {
        ...entry,
        dmTdmAutoVerified: true,
        dmTdmVerifiedMatches: verifiedMatches,
        verifiedAt: nowISO()
      };
    });
    if (changed) {
      updateProfile(currentProfile.id, { warmupLog });
      renderInsights?.();
      if (options.announce !== false) showToast?.("Henrik verified today's DM/TDM warm-up.", { tone: "success" });
    }
    if (getActiveProfile?.()?.id === profile.id) {
      renderDailyWarmupVerification(getActiveProfile());
      renderDailyWarmupCorrelationStatus(getActiveProfile());
    }
    return result;
  } catch (error) {
    if (target && getActiveProfile?.()?.id === profile.id) target.textContent = "Henrik DM/TDM verification is unavailable right now; your self-report is still saved.";
    return { matches: [], failures: [{ error: error?.message || "Verification failed." }] };
  } finally {
    warmupVerificationInFlight.delete(profile.id);
  }
}

function saveDailyWarmupCheck() {
  const profile = getActiveProfile?.();
  if (!profile) return;
  const date = document.getElementById("dailyWarmupModal")?.dataset.trainingDate || formatLocalDateKey();
  const drillsSelected = [...document.querySelectorAll("[data-warmup-drill].is-selected")]
    .map(button => button.dataset.warmupDrill)
    .filter(Boolean)
    .slice(0, DAILY_WARMUP_DRILL_LIMIT);
  const dmTdmSelfReported = document.getElementById("dailyWarmupDmTdm")?.checked === true;
  if (!drillsSelected.length && !dmTdmSelfReported) {
    const currentRecord = getDailyWarmupRecord(profile, date);
    if (currentRecord && (isDailyWarmupCompleted(currentRecord) || currentRecord.warmupLogEntryId)) {
      writeDailyWarmupRecord(profile, {
        date,
        status: "prompted",
        skipped: false,
        drillsSelected: [],
        weapon: "",
        rangeDrillsSelfReported: false,
        dmTdmSelfReported: false,
        completedAt: "",
        warmupLogEntryId: "",
        warmupFeedMarkerHidden: true
      });
      hideModalById?.("dailyWarmupModal");
      renderLoggingTrainingMenuState(getActiveProfile());
      renderLogFeed?.({ force: true });
      showToast?.("Warm-up marker removed from this session.", { tone: "neutral" });
      return;
    }
    const target = document.getElementById("dailyWarmupVerification");
    if (target) target.textContent = "Choose at least one drill, mark DM/TDM complete, or skip today.";
    return;
  }
  const record = writeDailyWarmupRecord(profile, {
    date,
    status: "completed",
    skipped: false,
    drillsSelected,
    weapon: drillsSelected.includes("weapon-choice") ? document.getElementById("dailyWarmupWeapon")?.value || "" : "",
    rangeDrillsSelfReported: drillsSelected.length > 0,
    dmTdmSelfReported,
    warmupFeedMarkerHidden: false,
    completedAt: getDailyWarmupRecord(profile, date)?.completedAt || nowISO()
  });
  persistWarmupTrainingEntry(getActiveProfile(), date);
  hideModalById?.("dailyWarmupModal");
  renderLoggingTrainingMenuState(getActiveProfile());
  renderLogFeed?.({ force: true });
  showToast?.(`Warm-up saved: ${record?.drillsSelected?.length || 0} drill${record?.drillsSelected?.length === 1 ? "" : "s"}${dmTdmSelfReported ? " plus DM/TDM" : ""}.`, { tone: "success" });
  scheduleProfileStreakAnnouncement();
  void refreshWarmupAutoVerification(getActiveProfile(), { announce: true });
}

function toggleDailyPostgameTraining() {
  const profile = getActiveProfile?.();
  if (!profile) return;
  const modal = document.getElementById("dailyWarmupModal");
  const date = modal?.dataset.trainingDate || formatLocalDateKey();
  const record = getDailyWarmupRecord(profile, date);
  const removing = record?.postGameAimTrainingCommitted === true;
  const entries = getDailyTrainingEntries(date, profile.id);
  const latest = entries[entries.length - 1] || null;
  if (!removing && !latest) {
    renderDailyPostgameState(profile, date);
    return;
  }
  writeDailyWarmupRecord(profile, {
    date,
    postGameAimTrainingCommitted: !removing,
    postGameCommittedAt: removing ? "" : nowISO(),
    postGameLogEntryId: removing ? "" : String(latest.id || "")
  });
  renderLoggingTrainingMenuState(getActiveProfile());
  renderLogFeed?.({ force: true });
  hideModalById?.("dailyWarmupModal");
  showToast?.(removing ? "Post-game training marker removed." : "Post-game aim training linked to your latest game.", {
    tone: removing ? "neutral" : "success"
  });
  if (!removing) scheduleProfileStreakAnnouncement();
}

function bindDailyWarmupEvents() {
  if (window.__rankedCoachDailyWarmupBound) return;
  window.__rankedCoachDailyWarmupBound = true;
  document.addEventListener("click", event => {
    if (event.target?.closest?.("[data-warmup-info]")) return;
    const drill = event.target?.closest?.("[data-warmup-drill]");
    if (drill) {
      const selected = [...document.querySelectorAll("[data-warmup-drill].is-selected")];
      const shouldSelect = !drill.classList.contains("is-selected");
      if (shouldSelect && selected.length >= DAILY_WARMUP_DRILL_LIMIT) {
        const target = document.getElementById("dailyWarmupVerification");
        if (target) target.textContent = "Choose up to four drills so the warm-up stays focused.";
        return;
      }
      drill.classList.toggle("is-selected", shouldSelect);
      drill.setAttribute("aria-pressed", shouldSelect ? "true" : "false");
      const count = document.getElementById("dailyWarmupCount");
      const nextCount = document.querySelectorAll("[data-warmup-drill].is-selected").length;
      if (count) count.textContent = `${nextCount} / ${DAILY_WARMUP_DRILL_LIMIT}`;
      const weaponField = document.getElementById("dailyWarmupWeaponField");
      if (weaponField) weaponField.hidden = !document.querySelector('[data-warmup-drill="weapon-choice"].is-selected');
      const date = document.getElementById("dailyWarmupModal")?.dataset.trainingDate || formatLocalDateKey();
      renderDailyWarmupVerification(getActiveProfile?.(), date);
      return;
    }
    if (event.target?.id === "dailyWarmupSave") saveDailyWarmupCheck();
    if (event.target?.closest?.("#dailyWarmupPostgameCommit")) toggleDailyPostgameTraining();
    if (event.target?.closest?.("#loggingTrainingMenuBtn")) openDailyTrainingMenu();
    if (event.target?.id === "dailyWarmupSkip") {
      const modal = document.getElementById("dailyWarmupModal");
      if (modal?.dataset.dismissBehavior === "skip") skipDailyWarmupCheck();
      else closeDailyTrainingMenu();
    }
    if (event.target?.id === "dailyWarmupClose") closeDailyTrainingMenu();
    if (event.target?.id === "dailyWarmupModal") closeDailyTrainingMenu();
  });
}

function buildWarmupCorrelationInsight(profile = getActiveProfile?.()) {
  const correlation = getWarmupCorrelation(profile);
  if (!correlation.ready) return null;
  const winDelta = Math.round(correlation.delta.winRate);
  const kastDelta = Number.isFinite(correlation.delta.kast) ? Math.round(correlation.delta.kast) : null;
  const acsDelta = Number.isFinite(correlation.delta.acs) ? Math.round(correlation.delta.acs) : null;
  const sampleCopy = `${correlation.warm.days} warm-up days and ${correlation.comparison.days} comparison days`;
  if (correlation.direction === "positive") {
    return {
      type: "good",
      title: "Warm-Up Days Are Holding Up Better",
      preview: `Ranked win rate is ${Math.abs(winDelta)} points higher on logged warm-up days in this sample.`,
      what: `The coach sees better ranked results on warm-up days across ${sampleCopy}.`,
      why: `This is correlation, not proof that warm-up caused the change${kastDelta !== null ? `; KAST is ${kastDelta >= 0 ? "+" : ""}${kastDelta} points different` : ""}${acsDelta !== null ? ` and ACS is ${acsDelta >= 0 ? "+" : ""}${acsDelta}` : ""}.`,
      action: "Keep the routine short and repeatable, then carry the same crosshair and fight discipline into the first ranked rounds.",
      sources: ["Daily Warm-Up Check", "Henrik Match History"],
      focus: "Session Preparation",
      category: "discipline",
      priority: 72
    };
  }
  return {
    type: correlation.direction === "negative" ? "warn" : "good",
    title: correlation.direction === "negative" ? "Warm-Up Has Not Transferred Yet" : "Warm-Up Results Are Still Even",
    preview: `The current warm-up and comparison samples are within ${Math.abs(winDelta)} win-rate points.`,
    what: `The coach sees no reliable ranked lift from warm-up yet across ${sampleCopy}.`,
    why: "Range and DM mechanics do not automatically transfer into live-round decisions, utility timing, or trade spacing.",
    action: "Keep one drill, then name the exact match habit it should change before queueing.",
    sources: ["Daily Warm-Up Check", "Henrik Match History"],
    focus: "Practice Transfer",
    category: "discipline",
    priority: 64
  };
}

function getWeekEnd(date = new Date()) {
  const d = getWeekStart(date);
  d.setDate(d.getDate() + 6);
  d.setHours(23, 59, 59, 999);
  return d;
}

