function getActivePageElement() {
  return document.querySelector(".page.is-current-page")
    || document.querySelector(".page.active:not(.exiting):not(.is-mobile-swipe-preview)")
    || document.querySelector(".page.active:not(.is-mobile-swipe-preview)")
    || document.querySelector(".page.active");
}

// Keep inactive mobile pages fully laid out but invisible so swipes stay compositor-only.
const MOBILE_PAGE_WARM_STYLE_PROPERTIES = [
  "position", "display", "top", "left", "right", "bottom", "width", "max-width",
  "height", "margin", "visibility", "opacity", "pointer-events", "content-visibility",
  "contain", "overflow", "transform", "z-index"
];
const mobilePageWarmStyleState = new WeakMap();
const mobilePageCompositorStyleState = new WeakMap();

function setMobilePageCompositorReady(page, enabled = false) {
  if (!(page instanceof HTMLElement)) return;
  const properties = ["will-change", "backface-visibility"];
  if (enabled) {
    if (mobilePageCompositorStyleState.has(page)) return;
    mobilePageCompositorStyleState.set(page, properties.reduce((snapshot, property) => {
      snapshot[property] = {
        value: page.style.getPropertyValue(property),
        priority: page.style.getPropertyPriority(property)
      };
      return snapshot;
    }, {}));
    page.style.setProperty("will-change", "transform", "important");
    page.style.setProperty("backface-visibility", "hidden", "important");
    return;
  }

  const snapshot = mobilePageCompositorStyleState.get(page);
  if (!snapshot) return;
  mobilePageCompositorStyleState.delete(page);
  Object.entries(snapshot).forEach(([property, state]) => {
    if (state?.value) {
      page.style.setProperty(property, state.value, state.priority || "");
    } else {
      page.style.removeProperty(property);
    }
  });
}

function setMobilePageWarmLayout(page, shouldWarm = false) {
  if (!(page instanceof HTMLElement)) return;
  if (shouldWarm) {
    if (mobilePageWarmStyleState.has(page)) return;
    mobilePageWarmStyleState.set(page, MOBILE_PAGE_WARM_STYLE_PROPERTIES.reduce((snapshot, property) => {
      snapshot[property] = {
        value: page.style.getPropertyValue(property),
        priority: page.style.getPropertyPriority(property)
      };
      return snapshot;
    }, {}));
    const warmStyles = {
      position: "fixed",
      display: "block",
      top: "0px",
      left: "0px",
      right: "auto",
      bottom: "auto",
      width: "calc(100vw - 24px)",
      "max-width": "calc(100vw - 24px)",
      height: "auto",
      margin: "0px",
      visibility: "hidden",
      opacity: "0",
      "pointer-events": "none",
      "content-visibility": "visible",
      contain: "layout paint style",
      overflow: "hidden",
      transform: "none",
      "z-index": "-1"
    };
    Object.entries(warmStyles).forEach(([property, value]) => {
      page.style.setProperty(property, value, "important");
    });
    return;
  }

  const snapshot = mobilePageWarmStyleState.get(page);
  if (!snapshot) return;
  mobilePageWarmStyleState.delete(page);
  Object.entries(snapshot).forEach(([property, state]) => {
    if (state?.value) {
      page.style.setProperty(property, state.value, state.priority || "");
    } else {
      page.style.removeProperty(property);
    }
  });
}

function syncMobilePageWarmLayouts() {
  const isMobile = isMobileLayoutViewport();
  document.querySelectorAll(".page").forEach(page => {
    if (page.classList.contains("is-mobile-swipe-preview") || page.classList.contains("is-mobile-swipe-outgoing")) {
      return;
    }
    const shouldWarm = isMobile
      && page.classList.contains("is-mobile-page-ready")
      && !page.classList.contains("is-current-page")
      && !page.classList.contains("is-mobile-swipe-preview");
    setMobilePageWarmLayout(page, shouldWarm);
  });
}

function isStatsMobileLayout() {
  return (
    isMobileLayoutViewport() ||
    document.documentElement?.classList.contains("is-mobile-layout") ||
    document.body?.classList.contains("is-mobile-layout") ||
    document.body?.classList.contains("access-mobile-layout")
  );
}

function portalMobileProfileSurface(id) {
  const el = document.getElementById(id);
  if (!el || !document.body || !isMobileLayoutViewport()) return el;

  if (!mobileProfilePortalMarkers.has(id) && el.parentNode) {
    const marker = document.createComment(`mobile-${id}-portal`);
    el.parentNode.insertBefore(marker, el);
    mobileProfilePortalMarkers.set(id, marker);
  }

  if (el.parentNode !== document.body) {
    document.body.appendChild(el);
  }

  return el;
}

function restoreMobileProfileSurfaces() {
  mobileProfilePortalMarkers.forEach((marker, id) => {
    const el = document.getElementById(id);
    if (!el || !marker.parentNode) return;
    marker.parentNode.insertBefore(el, marker.nextSibling);
    marker.remove();
  });
  mobileProfilePortalMarkers.clear();
}

function setImportantStyle(el, property, value) {
  if (!el) return;
  el.style.setProperty(property, value, "important");
}

function clearInlineStyles(el, properties = []) {
  if (!el) return;
  properties.forEach((property) => el.style.removeProperty(property));
}

function applyMobileScrollSurfaceState() {
  const html = document.documentElement;
  const body = document.body;
  const root = document.querySelector(".app-root");
  const isMobile = isMobileLayoutViewport();
  const modalOpen = Boolean(body?.classList.contains("mobile-modal-open"));
  const isTouchDevice =
    isMobile ||
    window.matchMedia?.("(hover: none), (pointer: coarse)")?.matches ||
    navigator.maxTouchPoints > 0;

  html?.classList.toggle("is-touch-layout", isTouchDevice);
  body?.classList.toggle("is-touch-layout", isTouchDevice);

  if (!isMobile) {
    clearInlineStyles(html, [
      "width",
      "height",
      "min-height",
      "max-height",
      "overflow",
      "overflow-x",
      "overflow-y",
      "overscroll-behavior",
      "touch-action"
    ]);
    clearInlineStyles(body, [
      "position",
      "inset",
      "width",
      "min-width",
      "height",
      "min-height",
      "max-height",
      "overflow",
      "overflow-x",
      "overflow-y",
      "overscroll-behavior",
      "touch-action"
    ]);
    clearInlineStyles(root, [
      "position",
      "inset",
      "height",
      "max-width",
      "min-height",
      "max-height",
      "overflow",
      "overflow-x",
      "overflow-y",
      "overscroll-behavior-y",
      "-webkit-overflow-scrolling",
      "touch-action"
    ]);
    return;
  }

  setImportantStyle(html, "width", "100%");
  setImportantStyle(html, "height", "100dvh");
  setImportantStyle(html, "min-height", "100dvh");
  setImportantStyle(html, "max-height", "100dvh");
  setImportantStyle(html, "overflow", "hidden");
  setImportantStyle(html, "overflow-x", "hidden");
  setImportantStyle(html, "overflow-y", "hidden");
  setImportantStyle(html, "overscroll-behavior", "none");
  setImportantStyle(html, "touch-action", "pan-y");

  if (body) {
    setImportantStyle(body, "position", "static");
    setImportantStyle(body, "inset", "auto");
    setImportantStyle(body, "width", "100%");
    setImportantStyle(body, "min-width", "0");
    setImportantStyle(body, "height", "100dvh");
    setImportantStyle(body, "min-height", "100dvh");
    setImportantStyle(body, "max-height", "100dvh");
    setImportantStyle(body, "overflow", "hidden");
    setImportantStyle(body, "overflow-x", "hidden");
    setImportantStyle(body, "overflow-y", "hidden");
    setImportantStyle(body, "overscroll-behavior", "none");
    setImportantStyle(body, "touch-action", "pan-y");
  }

  if (root) {
    setImportantStyle(root, "position", "relative");
    setImportantStyle(root, "inset", "auto");
    setImportantStyle(root, "height", "100dvh");
    setImportantStyle(root, "max-width", "100vw");
    setImportantStyle(root, "min-height", "100dvh");
    setImportantStyle(root, "max-height", "100dvh");
    setImportantStyle(root, "overflow-x", "hidden");
    setImportantStyle(root, "overflow-y", modalOpen ? "hidden" : "auto");
    setImportantStyle(root, "overscroll-behavior-y", "contain");
    setImportantStyle(root, "-webkit-overflow-scrolling", "touch");
    setImportantStyle(root, "touch-action", "pan-y");
  }
}

function syncMobileViewportState() {
  const isMobile = isMobileLayoutViewport();
  document.documentElement.classList.toggle("is-mobile-layout", isMobile);
  document.body?.classList.toggle("is-mobile-layout", isMobile);
  if (lastStatsMobileRenderState !== isMobile) {
    lastStatsMobileRenderState = isMobile;
    window.requestAnimationFrame?.(() => {
      renderStatsAgents?.();
      renderStatsWeapons?.();
    });
  }
  syncManualEntryModeBodyClass();
  if (isMobile) installMobileTouchScrollGuard();

  if (!isMobile) {
    const currentPage = getActivePageElement();
    document.querySelectorAll(".page").forEach(page => {
      page.classList.remove("is-mobile-page-ready", "is-current-page", "is-mobile-swipe-preview", "is-mobile-swipe-outgoing");
      if (page !== currentPage) page.classList.remove("active", "entering", "exiting");
      setMobilePageCompositorReady(page, false);
    });
    syncMobilePageWarmLayouts();
    document.body?.classList.remove("mobile-nav-hidden");
    document.body?.classList.remove("mobile-modal-open");
    restoreMobileProfileSurfaces();
    document.documentElement.style.overflowY = "";
    document.body && (document.body.style.overflowY = "");
  } else if (document.body?.classList.contains("has-active-modal")) {
    document.body.classList.add("mobile-modal-open");
  }

  applyMobileScrollSurfaceState();

  if (document.body) {
    window.requestAnimationFrame(() => {
      syncMobileBottomShellState();
      syncMobileHeaderActionsState();
      ensureMobileLoggingTabs();
      ensureMobileStatsTabs();
      ensureMobileTrendCarousel();
      ensureMobileStatsBreakdownCarousel();
      ensureMobileInsightCardCarousel();
      ensureMobileInsightTrendCarousel();
      ensureMobileManualReportControls();
      ensureMobileSwipeAffordances();
      installMobileHomePullToRefresh();
      scheduleMobileScrollExtentSync();
      if (isMobile && !document.querySelector(".page.is-mobile-page-ready")) {
        const activePageId = getActivePageElement()?.id?.replace("page-", "") || "home";
        activatePage(activePageId);
      }
    });
  }

  return isMobile;
}

function getMobileNavPageLabel(page = "") {
  const labels = {
    home: "Home",
    logging: "Logging",
    stats: "Stats",
    insights: "Insights",
    library: "Library"
  };
  return labels[page] || page;
}

function closeAllMobileOverlays() {
  closeMobileProfilePopover();
  setProfileRatingDropdownOpen?.(false);
  [profileSwitcher, profileDropdown].forEach((menu) => {
    if (!menu) return;
    menu.classList.remove("open");
    menu.style.left = "";
    menu.style.right = "";
    menu.style.top = "";
    menu.style.bottom = "";
    menu.style.transform = "";
  });
  closeAskCoachModal?.();
  closeAccountSupportModal?.();
  hideModalById?.("editProfileModal");
  closeSecuritySettingsModal?.();
  closeRiotProfileConfirmModal?.();
  hideModalById?.("bugReportModal");
  hideModalById?.("goalRankModal");
  closeStatsActMobileMenu?.();
}

function ensureMobileBottomShell() {
  if (mobileBottomShell || !document.body) return mobileBottomShell;

  mobileBottomShell = document.createElement("nav");
  mobileBottomShell.id = "mobileBottomShell";
  mobileBottomShell.className = "mobile-bottom-shell";
  mobileBottomShell.setAttribute("aria-label", "Mobile app navigation");
  mobileBottomShell.innerHTML = `
    <div class="mobile-bottom-pages" aria-label="Pages">
      ${["home", "logging", "stats", "insights", "library"].map((page) => `
        <button type="button" class="mobile-bottom-page-btn" data-mobile-page="${page}" aria-label="${getMobileNavPageLabel(page)} page">
          ${getMobileNavPageLabel(page)}
        </button>
      `).join("")}
    </div>
  `;

  let pageTouchStart = null;
  let suppressPageClickUntil = 0;
  const selectMobileBottomPage = (pageButton) => {
    if (!pageButton) return;
    closeAllMobileOverlays();
    const pageId = pageButton.dataset.mobilePage;
    if (pageId === "library" && getActivePageElement()?.id === "page-library") {
      globalThis.RankedCoachGamesenseLibrary?.reset?.();
      return;
    }
    if (getActivePageElement()?.id !== `page-${pageId}`) {
      activatePage(pageId, { mobileNavHandoff: true });
    }
  };

  mobileBottomShell.addEventListener("touchstart", (event) => {
    const pageButton = event.target.closest("[data-mobile-page]");
    const touch = event.touches?.[0];
    pageTouchStart = pageButton && touch
      ? { button: pageButton, identifier: touch.identifier, x: touch.clientX, y: touch.clientY }
      : null;
  }, { passive: true });

  mobileBottomShell.addEventListener("touchend", (event) => {
    const start = pageTouchStart;
    pageTouchStart = null;
    if (!start) return;
    const touch = Array.from(event.changedTouches || []).find(item => item.identifier === start.identifier);
    if (!touch || Math.hypot(touch.clientX - start.x, touch.clientY - start.y) > 14) return;
    event.preventDefault();
    suppressPageClickUntil = Date.now() + 500;
    selectMobileBottomPage(start.button);
  }, { passive: false });

  mobileBottomShell.addEventListener("touchcancel", () => {
    pageTouchStart = null;
  }, { passive: true });

  mobileBottomShell.addEventListener("click", (event) => {
    const pageButton = event.target.closest("[data-mobile-page]");
    if (pageButton) {
      event.preventDefault();
      if (Date.now() >= suppressPageClickUntil) selectMobileBottomPage(pageButton);
      return;
    }

    closeMobileProfilePopover();
  });

  document.body.appendChild(mobileBottomShell);

  if (!mobileBottomShellTimer) {
    mobileBottomShellTimer = window.setInterval(() => {
      syncMobileBottomShellState({ deferExtent: true });
    }, 1200);
  }

  return mobileBottomShell;
}

