function repairTrendSignalMedia() {
  document.querySelectorAll(".trend-signal-media.has-image img").forEach((img) => {
    const markBroken = () => {
      const media = img.closest(".trend-signal-media");
      media?.classList.add("is-empty");
      media?.classList.remove("has-image");
      img.remove();
    };
    img.addEventListener("error", markBroken, { once: true });
    if (img.complete && !img.naturalWidth) markBroken();
  });
}

function ensureMobileInsightTrendCarousel() {
  const page = document.getElementById("page-insights");
  const wrap = page?.querySelector(".insight-trends");
  if (!page || !wrap) return;

  const rows = [...wrap.querySelectorAll(".insight-trend-row")];
  const contents = [...wrap.querySelectorAll(".trend-content")];
  if (!rows.length || !contents.length) return;

  let tabs = document.getElementById("mobileInsightTrendTabs");
  if (!tabs) {
    tabs = document.createElement("div");
    tabs.id = "mobileInsightTrendTabs";
    tabs.className = "mobile-insight-trend-tabs";
    tabs.addEventListener("click", (event) => {
      const button = event.target.closest("[data-mobile-insight-trend]");
      if (!button) return;
      event.preventDefault();
      mobileInsightTrendKey = String(button.dataset.mobileInsightTrend || "performance").toLowerCase();
      mobileInsightTrendIndex = 0;
      ensureMobileInsightTrendCarousel();
    });
  }

  let nav = document.getElementById("mobileInsightTrendNav");
  if (!nav) {
    nav = document.createElement("div");
    nav.id = "mobileInsightTrendNav";
    nav.className = "mobile-insight-trend-nav";
    nav.innerHTML = `
      <button type="button" data-mobile-insight-trend-step="-1" aria-label="Previous trend read">&lsaquo;</button>
      <span id="mobileInsightTrendCounter">1 / 1</span>
      <button type="button" data-mobile-insight-trend-step="1" aria-label="Next trend read">&rsaquo;</button>
    `;
    nav.addEventListener("click", (event) => {
      const button = event.target.closest("[data-mobile-insight-trend-step]");
      if (!button) return;
      event.preventDefault();
      const activeContent = contents.find((content) => String(content.dataset.trendContent || "").toLowerCase() === mobileInsightTrendKey) || contents[0];
      const cards = [...activeContent.querySelectorAll(".trend-signal-card")];
      if (!cards.length) return;
      const step = Number(button.dataset.mobileInsightTrendStep || 0);
      mobileInsightTrendIndex = (mobileInsightTrendIndex + step + cards.length) % cards.length;
      ensureMobileInsightTrendCarousel();
    });
  }

  tabs.innerHTML = rows.map((row) => {
    const key = String(row.dataset.trend || "").toLowerCase();
    const label = row.querySelector(".stats-main-text, .insight-trend-title, .trend-title")?.textContent?.trim()
      || row.textContent?.trim()
      || key;
    return `<button type="button" data-mobile-insight-trend="${escapeHtml(key)}">${escapeHtml(label)}</button>`;
  }).join("");

  if (!mobileInsightTrendKey || !rows.some((row) => String(row.dataset.trend || "").toLowerCase() === mobileInsightTrendKey)) {
    mobileInsightTrendKey = String(wrap.dataset.openTrend || rows[0]?.dataset.trend || "performance").toLowerCase();
  }

  if (tabs.parentElement !== wrap) wrap.insertBefore(tabs, wrap.firstChild);
  if (nav.parentElement !== wrap) tabs.insertAdjacentElement("afterend", nav);

  rows.forEach((row) => {
    const isActive = String(row.dataset.trend || "").toLowerCase() === mobileInsightTrendKey;
    row.classList.toggle("is-mobile-trend-tab-active", isActive);
  });
  tabs.querySelectorAll("[data-mobile-insight-trend]").forEach((button) => {
    const isActive = String(button.dataset.mobileInsightTrend || "").toLowerCase() === mobileInsightTrendKey;
    button.classList.toggle("active", isActive);
    button.setAttribute("aria-pressed", isActive ? "true" : "false");
  });

  let activeCards = [];
  contents.forEach((content) => {
    const isActiveContent = String(content.dataset.trendContent || "").toLowerCase() === mobileInsightTrendKey;
    content.classList.toggle("is-mobile-trend-content-active", isActiveContent);
    if (isActiveContent) activeCards = [...content.querySelectorAll(".trend-signal-card")];
  });

  if (mobileInsightTrendIndex >= activeCards.length) mobileInsightTrendIndex = 0;
  contents.forEach((content) => {
    content.querySelectorAll(".trend-signal-card").forEach((card, index) => {
      const isActiveContent = content.classList.contains("is-mobile-trend-content-active");
      const isActive = isActiveContent && index === mobileInsightTrendIndex;
      card.classList.toggle("is-mobile-insight-trend-active", isActive);
      card.setAttribute("aria-hidden", isActive ? "false" : "true");
    });
  });

  const counter = document.getElementById("mobileInsightTrendCounter");
  if (counter) counter.textContent = activeCards.length ? `${mobileInsightTrendIndex + 1} / ${activeCards.length}` : "0 / 0";
  nav.hidden = !activeCards.length;
  repairTrendSignalMedia();
}

const MOBILE_SWIPE_MIN_DISTANCE = 42;
const MOBILE_SWIPE_MAX_VERTICAL_RATIO = 1.35;
const MOBILE_LOCAL_SWIPE_MAX_DURATION = 320;
const MOBILE_PAGE_SWIPE_ORDER = ["home", "logging", "stats", "insights", "library"];
const MOBILE_PAGE_SWIPE_MIN_DISTANCE = 68;
const MOBILE_PAGE_SWIPE_MIN_DURATION = 180;
const MOBILE_PAGE_SWIPE_MAX_VERTICAL_RATIO = 1.1;
const MOBILE_SWIPE_PREVIEW_START_DISTANCE = 12;
const MOBILE_SWIPE_PREVIEW_MAX_RATIO = 0.28;
const MOBILE_SWIPE_PREVIEW_CANCEL_MS = 180;
const MOBILE_SWIPE_PREVIEW_COMMIT_MS = 170;
const MOBILE_SWIPE_PREVIEW_ENTRY_MS = 210;
let mobileSwipeHandledTimestamp = -1;
let mobileSwipeSuppressClickUntil = 0;
let mobileSwipeClickGuardInstalled = false;
const mobileSwipePreviewClassState = new WeakMap();
const mobileSwipeTouchStartOwners = new WeakMap();

function getMobileSwipeDirection(startX, startY, endX, endY, options = {}) {
  const minDistance = Number.isFinite(options.minDistance) ? options.minDistance : MOBILE_SWIPE_MIN_DISTANCE;
  const maxVerticalRatio = Number.isFinite(options.maxVerticalRatio) ? options.maxVerticalRatio : MOBILE_SWIPE_MAX_VERTICAL_RATIO;
  const deltaX = endX - startX;
  const deltaY = endY - startY;
  if (Math.abs(deltaX) < minDistance) return 0;
  if (Math.abs(deltaX) < Math.abs(deltaY) * maxVerticalRatio) return 0;
  return deltaX < 0 ? 1 : -1;
}

function isMobileSwipeInsideCenterZone(x, y) {
  const viewportWidth = window.innerWidth || document.documentElement?.clientWidth || 390;
  const viewportHeight = window.innerHeight || document.documentElement?.clientHeight || 844;
  const sideInset = Math.max(28, viewportWidth * 0.14);
  const topInset = Math.max(96, viewportHeight * 0.16);
  const bottomInset = Math.max(118, viewportHeight * 0.16);
  return x >= sideInset
    && x <= viewportWidth - sideInset
    && y >= topInset
    && y <= viewportHeight - bottomInset;
}

function shouldAllowMobilePageSwipeStart(target, startX, startY) {
  if (!isMobileLayoutViewport()) return false;
  if (document.body?.classList.contains("mobile-modal-open")) return false;
  if (!target?.closest?.(".page.active")) return false;
  if (target?.closest?.("[data-gamesense-map-viewport], .gamesense-map-tools, .gamesense-map-view-tabs")) return false;
  if (!isMobileSwipeInsideCenterZone(startX, startY)) return false;
  return !target?.closest?.("input, textarea, select, option, [contenteditable='true']");
}

function ensureMobileSwipeClickGuard() {
  if (mobileSwipeClickGuardInstalled) return;
  mobileSwipeClickGuardInstalled = true;
  document.addEventListener("click", (event) => {
    if (!isMobileLayoutViewport()) return;
    if (Date.now() >= mobileSwipeSuppressClickUntil) return;
    event.preventDefault();
    event.stopPropagation();
  }, true);
}

function waitForMobileSwipeAnimation(durationMs = 0) {
  return new Promise((resolve) => window.setTimeout(resolve, Math.max(0, durationMs)));
}

function waitForMobileSwipeFrame() {
  return new Promise((resolve) => {
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(resolve);
    });
  });
}

function captureMobileSwipeInlineStyles(target) {
  if (!target) return null;
  const properties = [
    "transform",
    "opacity",
    "transition",
    "will-change",
    "pointer-events",
    "background-color",
    "overflow",
    "overflow-x",
    "overflow-y",
    "isolation",
    "display",
    "visibility",
    "position",
    "top",
    "left",
    "width",
    "height",
    "z-index",
    "content-visibility",
    "contain",
    "backface-visibility"
  ];
  return properties.reduce((snapshot, property) => {
    snapshot[property] = {
      value: target.style.getPropertyValue(property),
      priority: target.style.getPropertyPriority(property)
    };
    return snapshot;
  }, {});
}

function restoreMobileSwipeInlineStyles(target, snapshot) {
  if (!target || !snapshot) return;
  Object.entries(snapshot).forEach(([property, state]) => {
    if (state?.value) {
      target.style.setProperty(property, state.value, state.priority || "");
    } else {
      target.style.removeProperty(property);
    }
  });
}

function prepareMobileSwipePreviewClasses(target, options = {}) {
  if (!target || !options.previewCompanionMirrorActive || mobileSwipePreviewClassState.has(target)) return;
  mobileSwipePreviewClassState.set(target, {
    active: target.classList.contains("active"),
    preview: target.classList.contains("is-mobile-swipe-preview")
  });
  target.classList.add("active", "is-mobile-swipe-preview");
}

function restoreMobileSwipePreviewClasses(target, options = {}) {
  if (!target || !mobileSwipePreviewClassState.has(target)) return;
  const snapshot = mobileSwipePreviewClassState.get(target);
  mobileSwipePreviewClassState.delete(target);
  if (!snapshot?.preview) target.classList.remove("is-mobile-swipe-preview");
  if (!options.keepActive && !snapshot?.active) target.classList.remove("active");
}

function resolveMobileSwipePreviewTarget(options = {}, context = {}) {
  if (!options.previewTarget) return null;
  if (typeof options.previewTarget === "function") {
    return options.previewTarget(context) || null;
  }
  return options.previewTarget || null;
}

function resolveMobileSwipePreviewCompanionTarget(direction = 0, options = {}, context = {}) {
  if (!direction || !options.previewCompanionTarget) return null;
  if (typeof options.previewCompanionTarget === "function") {
    return options.previewCompanionTarget(direction, context) || null;
  }
  return options.previewCompanionTarget || null;
}

function resolveMobileSwipePreviewCompanionFrame(target, currentTarget, options = {}, context = {}) {
  if (!options.previewCompanionFrame) return null;
  if (typeof options.previewCompanionFrame === "function") {
    return options.previewCompanionFrame(target, currentTarget, context) || null;
  }
  return options.previewCompanionFrame || null;
}

function getMobileSwipePreviewSpan(target, options = {}, context = {}) {
  if (typeof options.previewSpan === "function") {
    return Math.max(1, safeNumber(options.previewSpan(context), 0));
  }
  if (Number.isFinite(options.previewSpan)) {
    return Math.max(1, options.previewSpan);
  }
  return Math.max(1, safeNumber(target?.getBoundingClientRect?.().width, window.innerWidth || 390));
}

function getMobileSwipeCommitDistance(target, options = {}, context = {}) {
  if (typeof options.commitDistance === "function") {
    return Math.max(MOBILE_SWIPE_MIN_DISTANCE, safeNumber(options.commitDistance(context), MOBILE_SWIPE_MIN_DISTANCE));
  }
  if (Number.isFinite(options.commitDistance)) {
    return Math.max(MOBILE_SWIPE_MIN_DISTANCE, options.commitDistance);
  }
  const span = getMobileSwipePreviewSpan(target, options, context);
  return Math.max(MOBILE_SWIPE_MIN_DISTANCE, Math.min(96, span * 0.18));
}

function getMobileSwipeCommitDuration(span = 1, previewOffset = 0, options = {}, context = {}) {
  if (typeof options.commitDurationMs === "function") {
    return Math.max(80, safeNumber(options.commitDurationMs({ span, previewOffset, ...context }), MOBILE_SWIPE_PREVIEW_COMMIT_MS));
  }
  if (Number.isFinite(options.commitDurationMs)) {
    return Math.max(80, options.commitDurationMs);
  }
  if (!options.fluidPageSwipe) return MOBILE_SWIPE_PREVIEW_COMMIT_MS;
  const remainingRatio = Math.max(0, Math.min(1, 1 - (Math.abs(previewOffset) / Math.max(1, span))));
  return Math.round(130 + (remainingRatio * 130));
}

function getMobileSwipePreviewStartDistance(options = {}) {
  if (Number.isFinite(options.previewStartDistance)) {
    return Math.max(1, options.previewStartDistance);
  }
  return MOBILE_SWIPE_PREVIEW_START_DISTANCE;
}

function getMobileSwipePreviewDirection(offsetPx = 0) {
  if (!Number.isFinite(offsetPx) || Math.abs(offsetPx) < 1) return 0;
  return offsetPx < 0 ? 1 : -1;
}

function getMobileSwipePreviewCompanionDisplay(target, currentTarget, options = {}, context = {}) {
  if (typeof options.previewCompanionDisplay === "function") {
    const value = String(options.previewCompanionDisplay(context) || "").trim();
    if (value) return value;
  }
  if (typeof options.previewCompanionDisplay === "string" && options.previewCompanionDisplay.trim()) {
    return options.previewCompanionDisplay.trim();
  }
  const targetDisplay = target ? window.getComputedStyle(target).display : "";
  if (targetDisplay && targetDisplay !== "none") return targetDisplay;
  const currentDisplay = currentTarget ? window.getComputedStyle(currentTarget).display : "";
  if (currentDisplay && currentDisplay !== "none") return currentDisplay;
  return "block";
}

function getMobileSwipePreviewBackdropColor() {
  const bodyColor = window.getComputedStyle(document.body || document.documentElement).backgroundColor;
  return bodyColor && bodyColor !== "rgba(0, 0, 0, 0)"
    ? bodyColor
    : "var(--bg, #071029)";
}

function applyMobileSwipePreview(target, offsetPx = 0, renderState = null) {
  if (!target) return;
  if (!renderState?.currentPrepared) {
    target.style.setProperty("position", target.style.getPropertyValue("position") || "relative", "important");
    target.style.setProperty("z-index", "2141", "important");
    target.style.setProperty("background-color", renderState?.backdropColor || getMobileSwipePreviewBackdropColor(), "important");
    target.style.setProperty("overflow", "hidden", "important");
    target.style.setProperty("overflow-x", "hidden", "important");
    target.style.setProperty("overflow-y", "hidden", "important");
    target.style.setProperty("isolation", "isolate", "important");
    target.style.setProperty("will-change", "transform", "important");
    target.style.setProperty("transition", "none", "important");
    target.style.setProperty("backface-visibility", "hidden", "important");
    if (renderState) renderState.currentPrepared = true;
  }
  target.style.setProperty("transform", `translate3d(${Math.round(offsetPx)}px,0,0)`, "important");
  target.style.setProperty("opacity", "1", "important");
  target.style.setProperty("pointer-events", "none", "important");
}

function applyMobileSwipeCompanionPreview(target, currentTarget, offsetPx = 0, options = {}, context = {}, renderState = null) {
  if (!target || !currentTarget || target === currentTarget) return;
  const direction = getMobileSwipePreviewDirection(offsetPx);
  if (!direction) return;
  let layout = renderState?.companionLayout || null;
  if (!layout) {
    const currentRect = currentTarget.getBoundingClientRect?.();
    if (!currentRect) return;
    const visualSpan = Math.max(1, safeNumber(currentRect.width, getMobileSwipePreviewSpan(currentTarget, options, context)));
    const companionFrame = resolveMobileSwipePreviewCompanionFrame(target, currentTarget, options, { ...context, currentRect }) || {};
    layout = {
      visualSpan,
      baseLeft: Number.isFinite(companionFrame.left)
        ? companionFrame.left
        : currentRect.left - safeNumber(offsetPx, 0),
      baseTop: Number.isFinite(companionFrame.top) ? companionFrame.top : currentRect.top,
      baseWidth: Number.isFinite(companionFrame.width) ? companionFrame.width : currentRect.width,
      baseHeight: Number.isFinite(companionFrame.height) ? companionFrame.height : null,
      display: getMobileSwipePreviewCompanionDisplay(target, currentTarget, options, context)
    };
    if (renderState) renderState.companionLayout = layout;
  }
  const visualSpan = layout.visualSpan;
  const companionOffset = offsetPx + (direction > 0 ? visualSpan : -visualSpan);
  if (!renderState?.companionPrepared) {
    target.style.setProperty("display", layout.display, "important");
    target.style.setProperty("visibility", "visible", "important");
    target.style.setProperty("content-visibility", "visible", "important");
    target.style.setProperty("contain", "layout paint style", "important");
    target.style.setProperty("position", "fixed", "important");
    target.style.setProperty("top", `${Math.round(layout.baseTop)}px`, "important");
    target.style.setProperty("left", `${Math.round(layout.baseLeft)}px`, "important");
    target.style.setProperty("width", `${Math.max(1, Math.round(layout.baseWidth))}px`, "important");
    if (Number.isFinite(layout.baseHeight)) {
      target.style.setProperty("height", `${Math.max(1, Math.round(layout.baseHeight))}px`, "important");
    } else {
      target.style.removeProperty("height");
    }
    target.style.setProperty("z-index", "2140", "important");
    target.style.setProperty("background-color", renderState?.backdropColor || getMobileSwipePreviewBackdropColor(), "important");
    target.style.setProperty("overflow", "hidden", "important");
    target.style.setProperty("overflow-x", "hidden", "important");
    target.style.setProperty("overflow-y", "hidden", "important");
    target.style.setProperty("isolation", "isolate", "important");
    target.style.setProperty("will-change", "transform", "important");
    target.style.setProperty("transition", "none", "important");
    target.style.setProperty("backface-visibility", "hidden", "important");
    if (renderState) renderState.companionPrepared = true;
  }
  target.style.setProperty("transform", `translate3d(${Math.round(companionOffset)}px,0,0)`, "important");
  target.style.setProperty("opacity", "1", "important");
  target.style.setProperty("pointer-events", "none", "important");
}

async function animateMobileSwipeReset(target, snapshot, companionTarget = null, companionSnapshot = null) {
  if (!target) return;
  target.style.setProperty("will-change", "transform, opacity", "important");
  target.style.setProperty("transition", `transform ${MOBILE_SWIPE_PREVIEW_CANCEL_MS}ms cubic-bezier(.22,.61,.36,1)`, "important");
  target.style.setProperty("transform", "translate3d(0,0,0)", "important");
  target.style.setProperty("opacity", "1", "important");
  await waitForMobileSwipeAnimation(MOBILE_SWIPE_PREVIEW_CANCEL_MS + 24);
  restoreMobileSwipeInlineStyles(target, snapshot);
  restoreMobileSwipeInlineStyles(companionTarget, companionSnapshot);
  restoreMobileSwipePreviewClasses(companionTarget);
  target.classList.remove("is-mobile-swipe-outgoing");
  syncMobilePageWarmLayouts();
}

async function animateMobileSwipeCommit(direction, context = {}, applyState = () => {}, options = {}) {
  const currentTarget = context.previewTarget || resolveMobileSwipePreviewTarget(options, context);
  const currentSnapshot = context.previewSnapshot || captureMobileSwipeInlineStyles(currentTarget);
  const companionTarget = context.previewCompanionTarget || resolveMobileSwipePreviewCompanionTarget(direction, options, context);
  const companionSnapshot = context.previewCompanionSnapshot || captureMobileSwipeInlineStyles(companionTarget);
  const usesCompanionPreview = Boolean(companionTarget && companionTarget !== currentTarget);
  const span = getMobileSwipePreviewSpan(currentTarget, options, context);
  const commitDuration = getMobileSwipeCommitDuration(span, context.previewOffset || 0, options, context);
  const exitDirection = direction > 0 ? -1 : 1;
  const exitOffset = exitDirection * Math.max(span, Math.abs(context.previewOffset || 0) + 48);

  if (currentTarget) {
    currentTarget.style.setProperty("will-change", "transform, opacity", "important");
    currentTarget.style.setProperty("transition", `transform ${commitDuration}ms cubic-bezier(.2,.78,.24,1)`, "important");
    currentTarget.style.setProperty("transform", `translate3d(${Math.round(exitOffset)}px,0,0)`, "important");
    currentTarget.style.setProperty("opacity", "1", "important");
  }
  if (usesCompanionPreview) {
    companionTarget.style.setProperty("will-change", "transform, opacity", "important");
    companionTarget.style.setProperty("transition", `transform ${commitDuration}ms cubic-bezier(.2,.78,.24,1)`, "important");
    companionTarget.style.setProperty("transform", "translate3d(0,0,0)", "important");
    companionTarget.style.setProperty("opacity", "1", "important");
  }
  if (currentTarget || usesCompanionPreview) {
    await waitForMobileSwipeAnimation(commitDuration);
  }

  const callbackResult = applyState(direction, context.event, context);
  if (callbackResult === false) {
    restoreMobileSwipeInlineStyles(currentTarget, currentSnapshot);
    restoreMobileSwipeInlineStyles(companionTarget, companionSnapshot);
    restoreMobileSwipePreviewClasses(companionTarget);
    currentTarget?.classList.remove("is-mobile-swipe-outgoing");
    syncMobilePageWarmLayouts();
    return false;
  }

  await waitForMobileSwipeFrame();

  const nextTarget = resolveMobileSwipePreviewTarget(options, context) || currentTarget;
  const reusesCompanionTarget = Boolean(usesCompanionPreview && nextTarget && nextTarget === companionTarget);
  const reusesCurrentTarget = Boolean(nextTarget && currentTarget && nextTarget === currentTarget);
  const nextSnapshot = reusesCurrentTarget ? currentSnapshot : captureMobileSwipeInlineStyles(nextTarget);
  if (nextTarget && !reusesCompanionTarget) {
    nextTarget.style.setProperty("will-change", "transform, opacity", "important");
    nextTarget.style.setProperty("transition", "none", "important");
    nextTarget.style.setProperty("transform", `translate3d(${Math.round(-exitOffset * 0.42)}px,0,0)`, "important");
    nextTarget.style.setProperty("background-color", getMobileSwipePreviewBackdropColor(), "important");
    nextTarget.style.setProperty("overflow", "hidden", "important");
    nextTarget.style.setProperty("overflow-x", "hidden", "important");
    nextTarget.style.setProperty("overflow-y", "hidden", "important");
    nextTarget.style.setProperty("isolation", "isolate", "important");
    nextTarget.style.setProperty("opacity", "1", "important");
    nextTarget.style.setProperty("pointer-events", "none", "important");
    await waitForMobileSwipeFrame();
    nextTarget.style.setProperty("transition", `transform ${MOBILE_SWIPE_PREVIEW_ENTRY_MS}ms cubic-bezier(.22,.61,.36,1)`, "important");
    nextTarget.style.setProperty("transform", "translate3d(0,0,0)", "important");
    nextTarget.style.setProperty("opacity", "1", "important");
    await waitForMobileSwipeAnimation(MOBILE_SWIPE_PREVIEW_ENTRY_MS + 24);
    restoreMobileSwipeInlineStyles(nextTarget, nextSnapshot);
  }
  if (reusesCompanionTarget) {
    restoreMobileSwipeInlineStyles(nextTarget, companionSnapshot);
    restoreMobileSwipePreviewClasses(nextTarget, { keepActive: true });
  }

  if (currentTarget && currentTarget !== nextTarget) {
    restoreMobileSwipeInlineStyles(currentTarget, currentSnapshot);
  }
  if (usesCompanionPreview && companionTarget && companionTarget !== nextTarget) {
    restoreMobileSwipeInlineStyles(companionTarget, companionSnapshot);
    restoreMobileSwipePreviewClasses(companionTarget);
  }
  currentTarget?.classList.remove("is-mobile-swipe-outgoing");
  syncMobilePageWarmLayouts();
  return callbackResult;
}

function bindMobileSwipe(element, callback, options = {}) {
  if (!element) return;
  ensureMobileSwipeClickGuard();
  const bindingKey = String(options.bindKey || "default")
    .replace(/[^a-z0-9]+/gi, " ")
    .trim()
    .replace(/(?:^|\s+)([a-z])/g, (_, char) => char.toUpperCase());
  const datasetKey = `mobileSwipeBound${bindingKey || "Default"}`;
  if (element.dataset[datasetKey] === "true") return;
  element.dataset[datasetKey] = "true";
  element.style.touchAction = element.style.touchAction || "pan-y";
  let startX = 0;
  let startY = 0;
  let startedAt = 0;
  let startTarget = null;
  let tracking = false;
  let previewing = false;
  let previewTarget = null;
  let previewSnapshot = null;
  let previewOffset = 0;
  let previewDirection = 0;
  let previewCompanionTarget = null;
  let previewCompanionSnapshot = null;
  let previewSpan = 0;
  let previewRenderFrame = 0;
  let previewRenderContext = null;
  let previewRenderState = null;

  const renderMobileSwipeFrame = () => {
    previewRenderFrame = 0;
    if (!previewTarget || !previewRenderContext) return;
    applyMobileSwipePreview(previewTarget, previewOffset, previewRenderState);
    applyMobileSwipeCompanionPreview(
      previewCompanionTarget,
      previewTarget,
      previewOffset,
      options,
      previewRenderContext,
      previewRenderState
    );
  };

  const scheduleMobileSwipeFrame = () => {
    if (previewRenderFrame) return;
    previewRenderFrame = window.requestAnimationFrame(renderMobileSwipeFrame);
  };

  const flushMobileSwipeFrame = () => {
    if (previewRenderFrame) {
      window.cancelAnimationFrame(previewRenderFrame);
      previewRenderFrame = 0;
    }
    renderMobileSwipeFrame();
  };

  const cancelMobileSwipeFrame = () => {
    if (!previewRenderFrame) return;
    window.cancelAnimationFrame(previewRenderFrame);
    previewRenderFrame = 0;
  };

  const shouldIgnoreTarget = (target) => {
    const formFieldSelector = options.formFieldIgnoreSelector || "input, textarea, select, option, [contenteditable='true']";
    if (target?.closest?.(formFieldSelector)) return true;
    if (options.allowControls) return false;
    const ignoreSelector = options.ignoreSelector || "button, a, [role='button'], [role='option'], [tabindex]";
    return Boolean(target?.closest?.(ignoreSelector));
  };

  element.addEventListener("touchstart", (event) => {
    const existingOwner = mobileSwipeTouchStartOwners.get(event);
    if (existingOwner && existingOwner !== element) {
      tracking = false;
      return;
    }
    if (!isMobileLayoutViewport() || event.touches.length !== 1 || shouldIgnoreTarget(event.target)) {
      tracking = false;
      return;
    }
    const touch = event.touches[0];
    if (typeof options.shouldHandleStart === "function" && !options.shouldHandleStart(event.target, touch, event, element)) {
      tracking = false;
      return;
    }
    // Touchstart bubbles from the deepest bound card to the app root. Claiming
    // it here gives nested carousels priority without changing their wraparound.
    mobileSwipeTouchStartOwners.set(event, element);
    startX = touch.clientX;
    startY = touch.clientY;
    startedAt = Date.now();
    startTarget = event.target;
    tracking = true;
    previewing = false;
    previewTarget = null;
    previewSnapshot = null;
    previewOffset = 0;
    previewDirection = 0;
    previewCompanionTarget = null;
    previewCompanionSnapshot = null;
    previewSpan = 0;
    previewRenderContext = null;
    previewRenderState = null;
    cancelMobileSwipeFrame();
  }, { passive: true });

  element.addEventListener("touchmove", (event) => {
    if (!tracking || !isMobileLayoutViewport()) return;
    const touch = event.touches?.[0];
    if (!touch) return;
    const elapsedMs = Date.now() - startedAt;
    if (Number.isFinite(options.previewStartMinDurationMs) && elapsedMs < options.previewStartMinDurationMs) return;
    if (Number.isFinite(options.previewStartMaxDurationMs) && elapsedMs > options.previewStartMaxDurationMs) return;

    const deltaX = touch.clientX - startX;
    const deltaY = touch.clientY - startY;
    if (Math.abs(deltaX) < getMobileSwipePreviewStartDistance(options)) return;
    if (Math.abs(deltaX) < Math.abs(deltaY) * 0.92) return;

    if (!previewTarget) {
      previewTarget = resolveMobileSwipePreviewTarget(options, {
        element,
        startTarget,
        startX,
        startY,
        event
      });
      previewSnapshot = captureMobileSwipeInlineStyles(previewTarget);
      if (options.fluidPageSwipe) previewTarget?.classList.add("is-mobile-swipe-outgoing");
    }
    if (!previewTarget) return;

    if (!previewSpan) {
      previewSpan = getMobileSwipePreviewSpan(previewTarget, options, {
        element,
        startTarget,
        startX,
        startY,
        event,
        previewTarget
      });
    }
    const previewMaxRatio = Number.isFinite(options.previewMaxRatio)
      ? Math.max(0.1, Math.min(1, options.previewMaxRatio))
      : MOBILE_SWIPE_PREVIEW_MAX_RATIO;
    const maxTravel = Math.max(28, previewSpan * previewMaxRatio);
    previewOffset = Math.max(-maxTravel, Math.min(maxTravel, deltaX));
    const nextPreviewDirection = getMobileSwipePreviewDirection(previewOffset);
    if (previewCompanionTarget && previewDirection && nextPreviewDirection !== previewDirection) {
      restoreMobileSwipeInlineStyles(previewCompanionTarget, previewCompanionSnapshot);
      restoreMobileSwipePreviewClasses(previewCompanionTarget);
      previewCompanionTarget = null;
      previewCompanionSnapshot = null;
      if (previewRenderState) {
        previewRenderState.companionPrepared = false;
        previewRenderState.companionLayout = null;
      }
    }
    previewDirection = nextPreviewDirection;
    if (!previewCompanionTarget && previewDirection) {
      previewCompanionTarget = resolveMobileSwipePreviewCompanionTarget(previewDirection, options, {
        element,
        startTarget,
        startX,
        startY,
        event,
        previewTarget,
        previewOffset,
        previewDirection
      });
      previewCompanionSnapshot = captureMobileSwipeInlineStyles(previewCompanionTarget);
      prepareMobileSwipePreviewClasses(previewCompanionTarget, options);
      if (typeof options.onPreviewCompanionPrepared === "function") {
        options.onPreviewCompanionPrepared(previewCompanionTarget, {
          element,
          startTarget,
          startX,
          startY,
          event,
          previewTarget,
          previewOffset,
          previewDirection,
          previewCompanionTarget
        });
      }
    }
    previewing = true;
    if (!previewRenderState) {
      previewRenderState = {
        currentPrepared: false,
        companionPrepared: false,
        companionLayout: null,
        backdropColor: getMobileSwipePreviewBackdropColor()
      };
    }
    previewRenderContext = {
      element,
      startTarget,
      startX,
      startY,
      event,
      previewTarget,
      previewOffset,
      previewDirection,
      previewCompanionTarget
    };
    scheduleMobileSwipeFrame();
    event.preventDefault();
  }, { passive: false });

  element.addEventListener("touchend", async (event) => {
    if (!tracking || !isMobileLayoutViewport()) return;
    tracking = false;
    if (mobileSwipeHandledTimestamp === event.timeStamp) return;
    const touch = event.changedTouches?.[0];
    if (!touch) return;
    if (previewing) flushMobileSwipeFrame();
    const durationMs = Date.now() - startedAt;
    const context = {
      durationMs,
      startTarget,
      startX,
      startY,
      endX: touch.clientX,
      endY: touch.clientY,
      element,
      event,
      previewing,
      previewTarget,
      previewSnapshot,
      previewOffset,
      previewDirection,
      previewCompanionTarget,
      previewCompanionSnapshot
    };
    const commitDistance = getMobileSwipeCommitDistance(previewTarget || element, options, context);
    const crossedCommitDistance = Math.max(Math.abs(touch.clientX - startX), Math.abs(previewOffset || 0)) >= commitDistance;
    let direction = getMobileSwipeDirection(startX, startY, touch.clientX, touch.clientY, options);
    if (!direction && previewing && crossedCommitDistance) {
      direction = getMobileSwipePreviewDirection(previewOffset);
    }
    const timingFailed = (Number.isFinite(options.minDurationMs) && durationMs < options.minDurationMs)
      || (Number.isFinite(options.maxDurationMs) && durationMs > options.maxDurationMs);

    if (!direction || (timingFailed && !crossedCommitDistance)) {
      if (previewing && previewTarget) {
        await animateMobileSwipeReset(previewTarget, previewSnapshot, previewCompanionTarget, previewCompanionSnapshot);
      }
      return;
    }

    if (!crossedCommitDistance) {
      if (previewing && previewTarget) {
        await animateMobileSwipeReset(previewTarget, previewSnapshot, previewCompanionTarget, previewCompanionSnapshot);
      }
      return;
    }

    const handled = previewTarget
      ? await animateMobileSwipeCommit(direction, context, callback, options)
      : callback(direction, event, context);

    if (handled !== false) {
      mobileSwipeHandledTimestamp = event.timeStamp;
      mobileSwipeSuppressClickUntil = Date.now() + 380;
    }
  }, { passive: true });

  element.addEventListener("touchcancel", async () => {
    cancelMobileSwipeFrame();
    if (previewing && previewTarget) {
      await animateMobileSwipeReset(previewTarget, previewSnapshot, previewCompanionTarget, previewCompanionSnapshot);
    } else {
      restoreMobileSwipePreviewClasses(previewCompanionTarget);
    }
    tracking = false;
    previewing = false;
    previewTarget = null;
    previewSnapshot = null;
    previewOffset = 0;
    previewDirection = 0;
    previewCompanionTarget = null;
    previewCompanionSnapshot = null;
    previewSpan = 0;
    previewRenderContext = null;
    previewRenderState = null;
  }, { passive: true });
}

function stepMobileValue(currentValue, values, direction) {
  if (!values.length) return currentValue;
  const currentIndex = Math.max(0, values.indexOf(currentValue));
  return values[(currentIndex + direction + values.length) % values.length];
}

function ensureMobileSwipeAffordances() {
  if (!isMobileLayoutViewport()) return;

  const getCurrentPageElement = () => getActivePageElement();
  const getPageKeyFromElement = (page) => page?.id?.replace("page-", "") || "";
  const getSteppedMobilePageKey = (direction = 0) => {
    const active = getPageKeyFromElement(getCurrentPageElement()) || MOBILE_PAGE_SWIPE_ORDER[0];
    return stepMobileValue(active, MOBILE_PAGE_SWIPE_ORDER, direction);
  };
  const getActivePageSwipeTarget = () => getCurrentPageElement();
  const getMobilePagePreviewFrame = (currentTarget, context = {}) => {
    if (!currentTarget) return null;
    const rect = context.currentRect || currentTarget.getBoundingClientRect?.();
    if (!rect) return null;
    const scrollContainer = getMobileScrollContainer();
    const scrollTop = Math.max(0, scrollContainer?.scrollTop || document.body?.scrollTop || document.documentElement?.scrollTop || window.scrollY || 0);
    const previewOffset = safeNumber(context?.previewOffset, 0);
    return {
      top: rect.top + scrollTop,
      left: rect.left - previewOffset,
      width: rect.width
    };
  };
  const getAdjacentPageSwipeTarget = (direction = 0) => {
    const nextPageKey = getSteppedMobilePageKey(direction);
    return document.getElementById(`page-${nextPageKey}`);
  };
  const getActiveLoggingSwipeTarget = () => {
    const page = document.getElementById("page-logging");
    if (!page) return null;
    return page.dataset.mobileLoggingView === "feed"
      ? page.querySelector(".logging-feed-card")
      : page.querySelector(".logging-card");
  };
  const getActiveStatsViewSwipeTarget = () => {
    const page = document.getElementById("page-stats");
    if (!page) return null;
    const view = page.dataset.mobileStatsView || "agents";
    const selectorMap = {
      agents: ".stats-agents-card",
      maps: ".stats-maps-card",
      weapons: ".stats-weapons-card"
    };
    return page.querySelector(selectorMap[view] || selectorMap.agents);
  };
  const getActiveProfileEditPanelTarget = () => document.querySelector("#editProfileModal .profile-edit-panel.is-active");
  const getBannerCategorySwipeTarget = () => document.querySelector("#editProfileModal .profile-edit-panel[data-profile-panel=\"banner\"].is-active") || document.getElementById("editProfileBannerGallery");

  bindMobileSwipe(document.querySelector(".app-root"), (direction, _event, context = {}) => {
    const active = getPageKeyFromElement(context.previewTarget) || getPageKeyFromElement(getCurrentPageElement()) || MOBILE_PAGE_SWIPE_ORDER[0];
    const nextPage = stepMobileValue(active, MOBILE_PAGE_SWIPE_ORDER, direction);
    if (nextPage === active) return false;
    closeAllMobileOverlays();
    activatePage(nextPage, { mobileSwipeHandoff: true });
    syncMobileBottomShellState();
  }, {
    bindKey: "pageRoot",
    allowControls: true,
    minDistance: MOBILE_PAGE_SWIPE_MIN_DISTANCE,
    minDurationMs: MOBILE_PAGE_SWIPE_MIN_DURATION,
    maxVerticalRatio: MOBILE_PAGE_SWIPE_MAX_VERTICAL_RATIO,
    previewStartDistance: 4,
    previewMaxRatio: 1,
    fluidPageSwipe: true,
    previewTarget: getActivePageSwipeTarget,
    previewCompanionTarget: (direction) => getAdjacentPageSwipeTarget(direction),
    previewCompanionMirrorActive: true,
    previewCompanionDisplay: "block",
    previewCompanionFrame: (_target, currentTarget, context) => getMobilePagePreviewFrame(currentTarget, context),
    previewSpan: () => window.innerWidth || document.documentElement?.clientWidth || 390,
    shouldHandleStart: (target, touch) => shouldAllowMobilePageSwipeStart(target, touch.clientX, touch.clientY)
  });

  bindMobileSwipe(document.querySelector("#mobileBottomShell .mobile-bottom-pages"), (direction, _event, context = {}) => {
    const active = getPageKeyFromElement(context.previewTarget) || getPageKeyFromElement(getCurrentPageElement()) || MOBILE_PAGE_SWIPE_ORDER[0];
    closeAllMobileOverlays();
    activatePage(stepMobileValue(active, MOBILE_PAGE_SWIPE_ORDER, direction), { mobileSwipeHandoff: true });
    syncMobileBottomShellState();
  }, {
    allowControls: true,
    bindKey: "bottomPages",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartDistance: 4,
    previewMaxRatio: 1,
    fluidPageSwipe: true,
    previewTarget: getActivePageSwipeTarget,
    previewCompanionTarget: (direction) => getAdjacentPageSwipeTarget(direction),
    previewCompanionMirrorActive: true,
    previewCompanionDisplay: "block",
    previewCompanionFrame: (_target, currentTarget, context) => getMobilePagePreviewFrame(currentTarget, context),
    previewSpan: () => window.innerWidth || document.documentElement?.clientWidth || 390
  });

  bindMobileSwipe(document.getElementById("mobileLoggingTabs"), (direction) => {
    const page = document.getElementById("page-logging");
    if (!page) return;
    page.dataset.mobileLoggingView = stepMobileValue(page.dataset.mobileLoggingView || "form", ["form", "feed"], direction);
    ensureMobileLoggingTabs();
  }, {
    allowControls: true,
    bindKey: "loggingTabs",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: getActiveLoggingSwipeTarget
  });

  bindMobileSwipe(document.getElementById("mobileStatsTabs"), (direction) => {
    const page = document.getElementById("page-stats");
    if (!page) return;
    page.dataset.mobileStatsView = stepMobileValue(page.dataset.mobileStatsView || "agents", ["agents", "maps", "weapons"], direction);
    ensureMobileStatsTabs();
  }, {
    allowControls: true,
    bindKey: "statsTabs",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: getActiveStatsViewSwipeTarget
  });

  bindMobileSwipe(document.querySelector("#editProfileModal .profile-edit-nav"), (direction) => {
    const order = ["theme", "icon", "borderColor", "border", "banner"];
    const current = document.querySelector("#editProfileModal .profile-edit-tab.is-active")?.dataset?.profileTab || "theme";
    activateProfileEditTab(stepMobileValue(current, order, direction));
  }, {
    allowControls: true,
    bindKey: "profileTabs",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: getActiveProfileEditPanelTarget
  });

  bindMobileSwipe(document.querySelector("#editProfileModal .banner-category-toggle"), (direction) => {
    const current = activeProfileBannerCategory || "official";
    setProfileBannerCategory(stepMobileValue(current, ["official", "unofficial"], direction));
  }, {
    allowControls: true,
    bindKey: "bannerCategories",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: getBannerCategorySwipeTarget
  });

  bindMobileSwipe(document.querySelector("#page-stats .stats-agents-card"), (direction) => {
    mobileStatsAgentRole = stepMobileValue(mobileStatsAgentRole || "duelist", ["duelist", "controller", "initiator", "sentinel"], direction);
    renderStatsAgentsModel();
    ensureMobileSwipeAffordances();
  }, {
    allowControls: true,
    bindKey: "statsAgentsCard",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-stats .stats-agents-card")
  });

  bindMobileSwipe(document.querySelector("#page-stats .stats-weapons-card"), (direction) => {
    const values = STATS_WEAPON_FAMILIES.map((family) => family.key);
    mobileStatsWeaponFamily = stepMobileValue(mobileStatsWeaponFamily || values[0] || "rifle", values, direction);
    renderStatsWeaponsModel();
    ensureMobileSwipeAffordances();
  }, {
    allowControls: true,
    bindKey: "statsWeaponsCard",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-stats .stats-weapons-card")
  });

  bindMobileSwipe(document.querySelector("#page-stats .stats-performance-card"), (direction, event, context) => {
    if (context?.startTarget?.closest?.("#mobileTrendTabs, .mobile-trend-tabs")) {
      const page = document.getElementById("page-stats");
      const filters = ["all", "needs", "watch", "strengths"];
      if (!page) return false;
      page.dataset.mobileTrendFilter = stepMobileValue(page.dataset.mobileTrendFilter || "all", filters, direction);
      mobileStatsTrendIndex = 0;
      ensureMobileTrendCarousel();
      return true;
    }
    const chart = document.getElementById("statsPerformanceChart");
    const visibleCards = [...(chart?.querySelectorAll(".stats-trend-card") || [])].filter(item => !item.classList.contains("mobile-trend-filtered"));
    if (!visibleCards.length) return;
    mobileStatsTrendIndex = (mobileStatsTrendIndex + direction + visibleCards.length) % visibleCards.length;
    ensureMobileTrendCarousel();
  }, {
    allowControls: true,
    bindKey: "statsPerformanceCard",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-stats .stats-trend-card.is-mobile-trend-active")
      || document.querySelector("#page-stats .stats-trend-card:not(.mobile-trend-filtered)")
  });

  bindMobileSwipe(document.querySelector("#page-stats .stats-breakdown-card"), (direction) => {
    const container = document.getElementById("statsBreakdown");
    const cards = [...(container?.querySelectorAll(".stats-breakdown-cardlet") || [])];
    if (!cards.length) return;
    mobileStatsBreakdownIndex = (mobileStatsBreakdownIndex + direction + cards.length) % cards.length;
    ensureMobileStatsBreakdownCarousel();
  }, {
    allowControls: true,
    bindKey: "statsBreakdownCard",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-stats .stats-breakdown-cardlet.is-mobile-breakdown-active")
      || document.querySelector("#page-stats .stats-breakdown-cardlet")
  });

  bindMobileSwipe(document.querySelector("#page-insights .insights-top-card"), (direction) => {
    const container = document.getElementById("insightsList");
    const cards = [...(container?.querySelectorAll(".insight-card:not(.insight-empty)") || [])];
    if (!cards.length) return false;
    mobileInsightCardIndex = (mobileInsightCardIndex + direction + cards.length) % cards.length;
    ensureMobileInsightCardCarousel();
    return true;
  }, {
    allowControls: true,
    bindKey: "insightCards",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-insights .insight-card.is-mobile-insight-active")
      || document.querySelector("#page-insights .insight-card:not(.insight-empty)")
  });

  bindMobileSwipe(document.querySelector("#page-insights .insights-trends-card"), (direction, event, context) => {
    const wrap = document.querySelector("#page-insights .insight-trends");
    const rows = [...(wrap?.querySelectorAll(".insight-trend-row[data-trend]") || [])];
    if (!rows.length) return false;

    if (context?.startTarget?.closest?.("#mobileInsightTrendTabs, .mobile-insight-trend-tabs, .insight-trend-row[data-trend]")) {
      const values = rows.map((row) => String(row.dataset.trend || "").toLowerCase()).filter(Boolean);
      if (!values.length) return false;
      mobileInsightTrendKey = stepMobileValue(mobileInsightTrendKey || values[0], values, direction);
      mobileInsightTrendIndex = 0;
      ensureMobileInsightTrendCarousel();
      return true;
    }

    const activeContent = wrap.querySelector(".trend-content.is-mobile-trend-content-active") || wrap.querySelector(".trend-content");
    const cards = [...(activeContent?.querySelectorAll(".trend-signal-card") || [])];
    if (!cards.length) return false;
    mobileInsightTrendIndex = (mobileInsightTrendIndex + direction + cards.length) % cards.length;
    ensureMobileInsightTrendCarousel();
    return true;
  }, {
    allowControls: true,
    bindKey: "insightTrendCard",
    maxDurationMs: MOBILE_LOCAL_SWIPE_MAX_DURATION,
    previewStartMaxDurationMs: 170,
    previewTarget: () => document.querySelector("#page-insights .trend-signal-card.is-mobile-insight-trend-active")
      || document.querySelector("#page-insights .trend-content.is-mobile-trend-content-active .trend-signal-card")
  });
}

function ensureMobileManualReportControls() {
  const panel = document.getElementById("manualMatchPanel");
  if (!panel) return;
  syncManualEntryModeBodyClass();

  let openButton = document.getElementById("mobileManualReportToggle");
  if (!openButton) {
    openButton = document.createElement("button");
    openButton.id = "mobileManualReportToggle";
    openButton.type = "button";
    openButton.className = "mobile-manual-report-toggle";
    openButton.textContent = "Create Match Report";
    panel.insertAdjacentElement("beforebegin", openButton);
    openButton.addEventListener("click", (event) => {
      event.preventDefault();
      setManualEntryMode(true);
      syncManualEntryModeBodyClass();
      panel.hidden = false;
      panel.classList.add("mobile-manual-open");
    });
  }

  let doneButton = document.getElementById("mobileManualReportDone");
  if (!doneButton) {
    doneButton = document.createElement("button");
    doneButton.id = "mobileManualReportDone";
    doneButton.type = "button";
    doneButton.className = "mobile-manual-report-done";
    doneButton.textContent = "Done";
    panel.appendChild(doneButton);
    doneButton.addEventListener("click", (event) => {
      event.preventDefault();
      panel.classList.remove("mobile-manual-open");
      panel.hidden = true;
    });
  }

  const enabled = isManualEntryModeEnabled();
  openButton.hidden = !enabled;
  if (!enabled) {
    panel.hidden = true;
    panel.classList.remove("mobile-manual-open");
  }
}

function syncMobileBottomShellState(options = {}) {
  const isMobile = isMobileLayoutViewport();
  const shell = ensureMobileBottomShell();
  if (!shell) return;

  shell.hidden = !isMobile;
  if (!isMobile) return;

  const activePageId = getActivePageElement()?.id?.replace("page-", "") || "home";
  shell.querySelectorAll("[data-mobile-page]").forEach((button) => {
    const isActive = button.dataset.mobilePage === activePageId;
    if (button.classList.contains("active") !== isActive) {
      button.classList.toggle("active", isActive);
    }
    const ariaCurrent = isActive ? "page" : "false";
    if (button.getAttribute("aria-current") !== ariaCurrent) {
      button.setAttribute("aria-current", ariaCurrent);
    }
  });

  if (!options.deferExtent) scheduleMobileScrollExtentSync();
}

function syncMobileBottomAvatarVisuals(profile = getActiveProfile()) {
  const button = document.querySelector(".mobile-bottom-avatar-btn");
  if (!button || !profile) return;
  const requestedThemeKey = String(profile?.themeKey || profile?.frameTheme || "default").toLowerCase();
  const theme = getThemePreset(requestedThemeKey);
  const borderStyle = normalizeProfileBorderStyle(profile?.profileBorder || "standard");
  const borderColor = normalizeProfileBorderColor(profile?.profileBorderColor || "theme");
  const resolvedBorderColor = getResolvedProfileBorderColor(borderColor, theme);
  const colors = theme?.colors || {};
  const ringBackground = colorMixOrFallback(
    `linear-gradient(135deg, ${colors.card || "#0b1220"}, color-mix(in srgb, ${resolvedBorderColor} 18%, ${colors.card2 || "#0f172a"}))`,
    `linear-gradient(135deg, ${colors.card || "#0b1220"}, ${colors.card2 || "#0f172a"})`
  );
  const ringGlow = colorMixOrFallback(`color-mix(in srgb, ${resolvedBorderColor} 52%, transparent)`, colors.glow || "rgba(255,70,85,0.55)");

  Array.from(button.classList).forEach((className) => {
    if (className.startsWith("border-")) button.classList.remove(className);
  });
  button.classList.add(`border-${borderStyle}`);
  button.classList.toggle("border-animated", !!profile?.profileBorderRotate);
  button.dataset.profileBorder = borderStyle;
  button.dataset.profileBorderColor = borderColor;
  button.style.setProperty("--profile-ring-border", resolvedBorderColor);
  button.style.setProperty("--profile-ring-bg", ringBackground);
  button.style.setProperty("--profile-ring-glow", ringGlow);
  renderMobileBottomAvatarFrame(button, borderStyle, resolvedBorderColor, !!profile?.profileBorderRotate);
}

function getMobileAvatarFramePath(borderStyle = "standard") {
  const framePaths = {
    standard: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    halo: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    double: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    split: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    notched: "M50 8 62 20 80 20 80 38 92 50 80 62 80 80 62 80 50 92 38 80 20 80 20 62 8 50 20 38 20 20 38 20Z",
    hex: "M28 10H72L94 50 72 90H28L6 50Z",
    diamond: "M50 5 95 50 50 95 5 50Z",
    shield: "M50 6 88 20 80 70 50 94 20 70 12 20Z",
    crown: "M16 72 16 30 34 48 50 18 66 48 84 30 84 72Q50 88 16 72Z",
    blade: "M16 84 16 22Q16 12 28 12H84V70Q84 84 70 84Z",
    pulse: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    arc: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    spike: "M50 4 94 34 80 94H20L6 34Z",
    crosshair: "M50 8a42 42 0 1 1 0 84a42 42 0 1 1 0-84",
    vanguard: "M16 16H84V66L50 92 16 66Z"
  };
  return framePaths[borderStyle] || framePaths.standard;
}

function getMobileAvatarFrameMarkup(borderStyle = "standard") {
  const normalizedStyle = normalizeProfileBorderStyle(borderStyle || "standard");
  const path = getMobileAvatarFramePath(normalizedStyle);
  const isArc = normalizedStyle === "arc";
  const isCrosshair = normalizedStyle === "crosshair";
  return `
    <span class="rc-mobile-avatar-frame" data-mobile-frame="${escapeHtml(normalizedStyle)}" aria-hidden="true">
      <svg class="rc-mobile-avatar-frame-svg" viewBox="0 0 100 100" focusable="false" aria-hidden="true">
        <path class="rc-mobile-frame-fill" d="${path}"></path>
        <path class="rc-mobile-frame-main" d="${path}" pathLength="100"></path>
        <path class="rc-mobile-frame-glint" d="${path}" pathLength="100"></path>
        ${isArc ? `<path class="rc-mobile-frame-arc" d="${path}" pathLength="100"></path>` : ""}
        ${isCrosshair ? `
          <g class="rc-mobile-frame-crosshair">
            <path d="M50 0V22"></path>
            <path d="M50 78V100"></path>
            <path d="M0 50H22"></path>
            <path d="M78 50H100"></path>
          </g>
        ` : ""}
      </svg>
    </span>
  `;
}

function setAvatarFrameAnimationState(target, enabled = true) {
  if (!target) return;
  target.querySelectorAll(".rc-mobile-frame-fill, .rc-mobile-frame-main, .rc-mobile-frame-glint, .rc-mobile-frame-arc, .rc-mobile-frame-crosshair path").forEach((part) => {
    if (enabled) {
      part.style.removeProperty("animation");
      part.style.removeProperty("animation-name");
      part.style.removeProperty("animation-duration");
      part.style.removeProperty("animation-play-state");
      return;
    }
    part.style.setProperty("animation", "none", "important");
    part.style.setProperty("animation-name", "none", "important");
    part.style.setProperty("animation-duration", "0s", "important");
    part.style.setProperty("animation-play-state", "paused", "important");
  });
}

function renderMobileBottomAvatarFrame(button, borderStyle = "standard", resolvedBorderColor = "#ff4655", animationsEnabled = true) {
  if (!button) return;
  const normalizedStyle = normalizeProfileBorderStyle(borderStyle || "standard");
  let frame = button.querySelector(".rc-mobile-avatar-frame");
  if (!frame) {
    frame = document.createElement("span");
    frame.className = "rc-mobile-avatar-frame";
    frame.setAttribute("aria-hidden", "true");
    const avatar = button.querySelector(".mobile-bottom-avatar-img, .profile-avatar-img");
    if (avatar) {
      button.insertBefore(frame, avatar);
    } else {
      button.appendChild(frame);
    }
  }

  frame.dataset.mobileFrame = normalizedStyle;
  frame.outerHTML = getMobileAvatarFrameMarkup(normalizedStyle);
  button.classList.add("has-rc-mobile-frame");
  button.dataset.mobileFrame = normalizedStyle;
  button.style.setProperty("--rc-mobile-frame-color", resolvedBorderColor);
  setAvatarFrameAnimationState(button, !!animationsEnabled);
}

function getMobileScrollContainer() {
  if (!isMobileLayoutViewport()) return null;
  return document.querySelector(".app-root") || document.scrollingElement || document.documentElement;
}

function ensureMobileScrollSentinel() {
  const root = document.querySelector(".app-root");
  if (!root) return null;
  if (mobileScrollSentinel?.isConnected) return mobileScrollSentinel;

  mobileScrollSentinel = document.createElement("div");
  mobileScrollSentinel.id = "mobileScrollSentinel";
  mobileScrollSentinel.className = "mobile-scroll-sentinel";
  mobileScrollSentinel.setAttribute("aria-hidden", "true");
  root.appendChild(mobileScrollSentinel);
  return mobileScrollSentinel;
}

function getMobileActivePageContentBottom(root, activePage) {
  if (!root || !activePage) return 0;
  const rootRect = root.getBoundingClientRect();
  const rootScrollTop = root.scrollTop || 0;
  const pageRect = activePage.getBoundingClientRect();
  if (!pageRect.width && !pageRect.height) return 0;
  const pageTop = pageRect.top - rootRect.top + rootScrollTop;
  const pageHeight = Math.max(pageRect.height, activePage.scrollHeight || 0);
  return Math.max(0, pageTop + pageHeight);
}

function syncMobileScrollExtent() {
  mobileScrollExtentRaf = 0;
  const root = document.querySelector(".app-root");
  const sentinel = ensureMobileScrollSentinel();

  if (!root || !sentinel || !isMobileLayoutViewport() || document.body?.classList.contains("mobile-modal-open")) {
    if (sentinel) sentinel.hidden = true;
    return;
  }

  const activePage = getActivePageElement();
  if (!activePage) {
    sentinel.hidden = true;
    return;
  }

  const bottomShellHeight = document.getElementById("mobileBottomShell")?.getBoundingClientRect().height || 78;
  const safeBottomSpace = Math.max(44, bottomShellHeight + 28);
  const contentBottom = getMobileActivePageContentBottom(root, activePage);
  const sentinelTop = Math.ceil(Math.max(root.clientHeight + 1, contentBottom + safeBottomSpace));

  sentinel.hidden = false;
  setImportantStyle(sentinel, "display", "block");
  setImportantStyle(sentinel, "position", "absolute");
  setImportantStyle(sentinel, "left", "0");
  setImportantStyle(sentinel, "top", `${sentinelTop}px`);
  setImportantStyle(sentinel, "width", "1px");
  setImportantStyle(sentinel, "height", "1px");
  setImportantStyle(sentinel, "pointer-events", "none");
  setImportantStyle(sentinel, "opacity", "0");
}

function scheduleMobileScrollExtentSync() {
  if (mobileScrollExtentRaf) return;
  mobileScrollExtentRaf = window.requestAnimationFrame(syncMobileScrollExtent);
}

function updateMobileNavVisibility() {
  mobileNavScrollRaf = 0;
  const body = document.body;
  if (!body || !isMobileLayoutViewport()) {
    body?.classList.remove("mobile-nav-hidden");
    mobileNavLastScrollY = 0;
    return;
  }

  const scrollContainer = getMobileScrollContainer();
  const scrollTop = Math.max(0, scrollContainer?.scrollTop || body.scrollTop || window.scrollY || document.documentElement.scrollTop || 0);
  body.classList.remove("mobile-nav-hidden");
  mobileNavLastScrollY = scrollTop;
  scheduleMobileScrollExtentSync();
}

function scheduleMobileNavVisibility() {
  if (mobileNavScrollRaf) return;
  mobileNavScrollRaf = window.requestAnimationFrame(updateMobileNavVisibility);
}

function installMobileNavBehavior() {
  if (mobileNavListenersInstalled) return;
  mobileNavListenersInstalled = true;

  window.addEventListener("scroll", scheduleMobileNavVisibility, { passive: true });
  document.body?.addEventListener?.("scroll", scheduleMobileNavVisibility, { passive: true });
  document.querySelector(".app-root")?.addEventListener?.("scroll", scheduleMobileNavVisibility, { passive: true });
  window.addEventListener("resize", () => {
    syncMobileViewportState();
    scheduleMobileNavVisibility();
    scheduleMobileScrollExtentSync();
  }, { passive: true });
  window.visualViewport?.addEventListener?.("resize", () => {
    syncMobileViewportState();
    scheduleMobileNavVisibility();
    scheduleMobileScrollExtentSync();
  }, { passive: true });
}

function installMobileTouchScrollGuard() {
  if (mobileTouchScrollGuardInstalled) return;
  mobileTouchScrollGuardInstalled = true;

  const clearStaleScrollLocks = () => {
    if (!isMobileLayoutViewport() || !document.body) return;
    refreshActiveModalState();
    applyMobileScrollSurfaceState();
  };

  const canBridgeTouchScroll = (event) => {
    if (!isMobileLayoutViewport() || document.body?.classList.contains("mobile-modal-open")) return false;
    if (!event.touches || event.touches.length !== 1) return false;
    const target = event.target;
    if (target?.closest?.("input, textarea, select, option, [contenteditable='true']")) return false;
    if (target?.closest?.(".lens-modal-overlay.active, .agent-modal.active, .profile-edit-overlay.active, .auth-modal-overlay.active, .app-tutorial-overlay.active")) return false;
    return false;
  };

  window.addEventListener("touchstart", (event) => {
    clearStaleScrollLocks();
    if (!canBridgeTouchScroll(event)) {
      mobileTouchScrollState = null;
      return;
    }
    const touch = event.touches[0];
    mobileTouchScrollState = {
      x: touch.clientX,
      y: touch.clientY,
      startedAt: Date.now(),
      moved: false
    };
  }, { passive: true, capture: true });

  window.addEventListener("touchmove", (event) => {
    if (!mobileTouchScrollState || !canBridgeTouchScroll(event)) return;
    const touch = event.touches[0];
    const deltaX = mobileTouchScrollState.x - touch.clientX;
    const deltaY = mobileTouchScrollState.y - touch.clientY;
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);
    if (absY < 4 || absY < absX * 1.15) return;

    const scroller = getMobileScrollContainer();
    if (!scroller) return;
    const maxTop = Math.max(0, scroller.scrollHeight - scroller.clientHeight);
    const nextTop = Math.max(0, Math.min(maxTop, scroller.scrollTop + deltaY));
    if (nextTop !== scroller.scrollTop) {
      scroller.scrollTop = nextTop;
      mobileTouchScrollState.moved = true;
      mobileTouchScrollState.x = touch.clientX;
      mobileTouchScrollState.y = touch.clientY;
      event.preventDefault();
      scheduleMobileNavVisibility();
    }
  }, { passive: false, capture: true });

  window.addEventListener("touchstart", clearStaleScrollLocks, { passive: true, capture: true });
  window.addEventListener("touchend", () => {
    mobileTouchScrollState = null;
    clearStaleScrollLocks();
  }, { passive: true, capture: true });
  window.addEventListener("touchcancel", () => {
    mobileTouchScrollState = null;
    clearStaleScrollLocks();
  }, { passive: true, capture: true });
  window.addEventListener("orientationchange", () => {
    window.setTimeout(clearStaleScrollLocks, 160);
  }, { passive: true });
}

function scrollMobilePageToTop(options = {}) {
  if (isMobileLayoutViewport()) {
    const scrollContainer = getMobileScrollContainer();
    if (scrollContainer) scrollContainer.scrollTop = 0;
    if (document.body) document.body.scrollTop = 0;
    if (document.documentElement) document.documentElement.scrollTop = 0;
    if (!options.deferExtent) scheduleMobileScrollExtentSync();
  }
  window.scrollTo({ top: 0, left: 0, behavior: "auto" });
}

function supportsCssDeclaration(property, value) {
  const css = window.CSS;
  if (!css?.supports) return false;
  try {
    return css.supports(property, value) || css.supports(`(${property}:${value})`);
  } catch (_error) {
    return false;
  }
}

function detectBrowserFeatureSupport() {
  return {
    backdropFilter:
      supportsCssDeclaration("backdrop-filter", "blur(1px)") ||
      supportsCssDeclaration("-webkit-backdrop-filter", "blur(1px)"),
    colorMix:
      supportsCssDeclaration("color", "color-mix(in srgb, red 50%, white)") ||
      supportsCssDeclaration("background", "color-mix(in srgb, red 50%, white)"),
    contentVisibility: supportsCssDeclaration("content-visibility", "auto"),
    individualTransform:
      supportsCssDeclaration("translate", "0 0") &&
      supportsCssDeclaration("scale", "1"),
    maskImage:
      supportsCssDeclaration("mask-image", "linear-gradient(#000,#000)") ||
      supportsCssDeclaration("-webkit-mask-image", "linear-gradient(#000,#000)"),
    mixBlendMode: supportsCssDeclaration("mix-blend-mode", "screen")
  };
}

const browserFeatureSupport = detectBrowserFeatureSupport();

function isBrowserCompatibilityBasicMode() {
  return document.body?.classList.contains("compat-basic");
}

function colorMixOrFallback(value, fallback) {
  return browserFeatureSupport.colorMix ? value : fallback;
}

function applyBrowserCompatibilityMode() {
  const body = document.body;
  if (!body) return;
  const compatBasic =
    !browserFeatureSupport.backdropFilter ||
    !browserFeatureSupport.colorMix ||
    !browserFeatureSupport.individualTransform ||
    !browserFeatureSupport.maskImage ||
    !browserFeatureSupport.mixBlendMode;

  body.classList.toggle("compat-basic", compatBasic);
  body.classList.toggle("compat-no-backdrop", !browserFeatureSupport.backdropFilter);
  body.classList.toggle("compat-no-color-mix", !browserFeatureSupport.colorMix);
  body.classList.toggle("compat-no-content-visibility", !browserFeatureSupport.contentVisibility);
  body.classList.toggle("compat-no-individual-transform", !browserFeatureSupport.individualTransform);
  body.classList.toggle("compat-no-mask", !browserFeatureSupport.maskImage);
  body.classList.toggle("compat-no-mix-blend", !browserFeatureSupport.mixBlendMode);
  body.dataset.browserCompatibility = compatBasic ? "basic" : "full";
}

function updateViewportPerformanceMode(viewportWidth, viewportHeight, scale) {
  const body = document.body;
  if (!body) return;

  const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
  const devicePixelBudget = viewportWidth * viewportHeight * dpr * dpr;
  const shouldOptimize =
    viewportWidth >= LARGE_VIEWPORT_WIDTH_THRESHOLD ||
    viewportHeight >= LARGE_VIEWPORT_HEIGHT_THRESHOLD ||
    scale >= LARGE_VIEWPORT_SCALE_THRESHOLD ||
    devicePixelBudget >= LARGE_VIEWPORT_DEVICE_PIXEL_BUDGET;
  const shouldUltraOptimize =
    viewportWidth >= ULTRA_VIEWPORT_WIDTH_THRESHOLD ||
    viewportHeight >= ULTRA_VIEWPORT_HEIGHT_THRESHOLD ||
    devicePixelBudget >= ULTRA_VIEWPORT_DEVICE_PIXEL_BUDGET;
  const wasOptimized = body.classList.contains("viewport-performance-mode");

  body.classList.toggle("viewport-performance-mode", shouldOptimize);
  body.classList.toggle("viewport-ultra-performance-mode", shouldUltraOptimize);
  body.dataset.renderBudget = shouldUltraOptimize ? "ultra" : shouldOptimize ? "large" : "standard";
  document.documentElement.style.setProperty("--viewport-render-scale", `${scale}`);

  if (wasOptimized !== shouldOptimize && typeof syncThemeBuilderFxEngine === "function") {
    syncThemeBuilderFxEngine();
  }
}

function scaleApp() {
  const wrap = document.querySelector(".app-scale-wrap");
  const root = document.querySelector(".app-root");
  if (!wrap || !root) return;
  syncMobileViewportState();

  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || APP_BASE_WIDTH;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || APP_BASE_HEIGHT;
  const effectiveBaseWidth = viewportWidth;
  const effectiveBaseHeight = viewportHeight;
  const legacyDesignScale = Math.min(
    viewportWidth / APP_BASE_WIDTH,
    viewportHeight / APP_BASE_HEIGHT
  );

  document.documentElement.style.setProperty("--app-base-width", `${effectiveBaseWidth}`);
  document.documentElement.style.setProperty("--app-base-height", `${effectiveBaseHeight}`);
  document.documentElement.style.setProperty("--app-scale", `${legacyDesignScale}`);

  wrap.style.alignItems = "stretch";
  wrap.style.justifyContent = "flex-start";

  root.style.width = "100%";
  root.style.height = "100%";
  root.style.maxWidth = "100%";
  root.style.maxHeight = "100%";
  root.style.transformOrigin = "top left";
  root.style.transform = "none";

  updateViewportPerformanceMode(viewportWidth, viewportHeight, legacyDesignScale);
}

let viewportRefreshTimer = 0;
let viewportRefreshRaf = 0;
let viewportRefreshNeedsChart = false;
let viewportRefreshNeedsThemeBuilder = false;

function flushViewportRefresh() {
  viewportRefreshTimer = 0;
  viewportRefreshRaf = 0;
  const shouldRenderChart = viewportRefreshNeedsChart;
  const shouldRefreshThemeBuilder = viewportRefreshNeedsThemeBuilder;

  viewportRefreshNeedsChart = false;
  viewportRefreshNeedsThemeBuilder = false;

  scaleApp();
  if (typeof scaleImpactCard === "function") scaleImpactCard();
  if (typeof updateAgentFrameMetrics === "function") updateAgentFrameMetrics();
  if (shouldRenderChart && typeof renderChart === "function") renderChart(currentSize);
  if (shouldRefreshThemeBuilder && typeof applyThemeBuilderRuntimeStyles === "function") {
    applyThemeBuilderRuntimeStyles();
  }
  scheduleLoadoutValueTextFit();
}

function scheduleViewportRefresh({
  renderChart: shouldRenderChart = true,
  applyThemeBuilder: shouldRefreshThemeBuilder = true
} = {}) {
  viewportRefreshNeedsChart = viewportRefreshNeedsChart || shouldRenderChart;
  viewportRefreshNeedsThemeBuilder = viewportRefreshNeedsThemeBuilder || shouldRefreshThemeBuilder;

  if (viewportRefreshTimer) {
    window.clearTimeout(viewportRefreshTimer);
  }
  viewportRefreshTimer = window.setTimeout(() => {
    if (viewportRefreshRaf) return;
    viewportRefreshRaf = window.requestAnimationFrame(flushViewportRefresh);
  }, 80);
}


function getActiveAnalytics() {
  return getPlayerModel();
}

function getMapIconUrl(mapName) {
  const normalized = String(mapName || "").trim();
  return `https://raw.githubusercontent.com/michealdoolittle-cyber/images/main/icons/${encodeURIComponent(normalized)}.png`;
}

function average(values = []) {
  const nums = values.filter((value) => Number.isFinite(Number(value))).map(Number);
  if (!nums.length) return 0;
  return nums.reduce((sum, value) => sum + value, 0) / nums.length;
}

function getSortedMatches(matchList = []) {
  return (matchList || []).slice().sort((a, b) =>
    new Date(a?.createdAt || 0).getTime() - new Date(b?.createdAt || 0).getTime()
  );
}

function getMatchCore(match = {}) {
  const record = match?.matchRecord?.schemaVersion
    ? match.matchRecord
    : (window.RankedCoachMatchRecord?.fromLegacyMatch?.(match) || null);
  if (record) {
    const agent = record.agent || "Unknown";
    return {
      agent,
      role: record.role || agentRoles?.[agent] || "Unknown",
      map: record.map || "Unknown",
      result: record.result || "draw",
      kills: safeNumber(record.stats?.kills),
      deaths: safeNumber(record.stats?.deaths),
      assists: safeNumber(record.stats?.assists),
      acs: safeNumber(record.stats?.acs),
      adr: safeNumber(record.stats?.adr),
      hs: safeNumber(record.stats?.hsPercent),
      createdAt: record.playedAt || record.createdAt || nowISO()
    };
  }

  const stats = match?.segments?.[0]?.stats || {};
  const metadata = match?.metadata || {};
  const agent = metadata.agent || match.agent || "Unknown";
  const map = metadata.mapName || match.map || "Unknown";
  const result = metadata.result || match.result || "draw";
  const kills = safeNumber(stats.kills?.value);
  const deaths = safeNumber(stats.deaths?.value);
  const assists = safeNumber(stats.assists?.value);
  const acs = safeNumber(stats.scorePerRound?.value);
  const adr = safeNumber(stats.damagePerRound?.value, safeNumber(match?.adr));
  const hs = safeNumber(stats.headshotsPercentage?.value);

  return {
    agent,
    role: agentRoles?.[agent] || "Unknown",
    map,
    result,
    kills,
    deaths,
    assists,
    acs,
    adr,
    hs,
    createdAt: match?.createdAt || metadata.playedAt || nowISO()
  };
}

function createPerformanceBucket(label) {
  return {
    label,
    matchesPlayed: 0,
    matchesWon: 0,
    matchesLost: 0,
    kills: 0,
    deaths: 0,
    assists: 0,
    acsTotal: 0,
    adrTotal: 0,
    hsTotal: 0
  };
}

function finalizePerformanceBucket(bucket = {}) {
  const matchesPlayed = safeNumber(bucket.matchesPlayed);
  const matchesWon = safeNumber(bucket.matchesWon);
  const matchesLost = safeNumber(bucket.matchesLost);
  const deaths = safeNumber(bucket.deaths);

  return {
    ...bucket,
    matchesPlayed,
    matchesWon,
    matchesLost,
    winrate: matchesPlayed ? (matchesWon / matchesPlayed) * 100 : 0,
    kd: deaths ? safeNumber(bucket.kills) / deaths : safeNumber(bucket.kills),
    acs: matchesPlayed ? safeNumber(bucket.acsTotal) / matchesPlayed : 0,
    adr: matchesPlayed ? safeNumber(bucket.adrTotal) / matchesPlayed : 0,
    hs: matchesPlayed ? safeNumber(bucket.hsTotal) / matchesPlayed : 0
  };
}

function rankBuckets(mapObj = {}, labelKey) {
  return Object.values(mapObj)
    .map(finalizePerformanceBucket)
    .sort((a, b) => {
      if (b.matchesPlayed !== a.matchesPlayed) return b.matchesPlayed - a.matchesPlayed;
      if (b.winrate !== a.winrate) return b.winrate - a.winrate;
      return String(a[labelKey] || a.label || "").localeCompare(String(b[labelKey] || b.label || ""));
    });
}

function clampPercent(value) {
  return Math.max(0, Math.min(100, Math.round(safeNumber(value))));
}

function normalizeDistributionTo100(entries = {}) {
  const keys = Object.keys(entries);
  if (!keys.length) return {};

  const safeEntries = {};
  let total = 0;

  keys.forEach((key) => {
    const value = Math.max(0, safeNumber(entries[key]));
    safeEntries[key] = value;
    total += value;
  });

  if (!total) {
    const fallback = {};
    const base = Math.floor(100 / keys.length);
    let remainder = 100 - (base * keys.length);
    keys.forEach((key, index) => {
      fallback[key] = base + (index < remainder ? 1 : 0);
    });
    return fallback;
  }

  const exact = keys.map((key) => ({
    key,
    value: (safeEntries[key] / total) * 100
  }));

  const rounded = {};
  let roundedTotal = 0;

  exact.forEach((entry) => {
    rounded[entry.key] = Math.floor(entry.value);
    roundedTotal += rounded[entry.key];
  });

  let remainder = 100 - roundedTotal;
  exact
    .slice()
    .sort((a, b) => (b.value - Math.floor(b.value)) - (a.value - Math.floor(a.value)))
    .forEach((entry) => {
      if (remainder <= 0) return;
      rounded[entry.key] += 1;
      remainder -= 1;
    });

  return rounded;
}

function getConfidenceLabel(score) {
  if (score >= 80) return "High Confidence";
  if (score >= 55) return "Medium Confidence";
  return "Low Confidence";
}

function getPriorityLabel(score) {
  if (score >= 90) return "Immediate";
  if (score >= 75) return "High";
  if (score >= 55) return "Moderate";
  return "Watch";
}

const COACHING_EVIDENCE_SOURCES = Object.freeze([
  {
    id: "riot-match-history",
    label: "Riot match history",
    status: "player-authorized",
    use: "Match results, agents, maps, combat stats, role samples, round context when imported."
  },
  {
    id: "rankedcoach-reflection-logs",
    label: "RankedCoach reflection logs",
    status: "player-authored",
    use: "Mood, focus category, confidence, comms, teammate context, AFK/DC/toxicity notes, and self-review."
  },
  {
    id: "riot-content-catalog",
    label: "Riot content catalog",
    status: "reference",
    use: "Current Valorant agents, maps, acts, and content identity."
  },
  {
    id: "public-rank-baselines",
    label: "Public rank baselines",
    status: "requires-fresh-cache",
    use: "Rank-specific comparisons only when a current trusted baseline is available."
  },
  {
    id: "pro-reference-context",
    label: "Pro reference context",
    status: "requires-fresh-cache",
    use: "Agent, role, and map examples only when a current trusted esports source is available."
  }
]);

function buildSampleConfidenceContext({ matchCount = 0, logCount = 0, statCoverage = 0, scopeLabel = "current scope" } = {}) {
  const matches = safeNumber(matchCount);
  const logs = safeNumber(logCount);
  const coverage = clampPercent(statCoverage);
  const score = clampPercent((Math.min(matches, 40) * 1.6) + (Math.min(logs, 20) * 1.2) + (coverage * 0.18));
  const label = getConfidenceLabel(score);
  const explanation = matches < 6
    ? `This is an early read from ${matches} ${scopeLabel} match${matches === 1 ? "" : "es"} and ${logs} reflection log${logs === 1 ? "" : "s"}. Treat it as direction, not proof.`
    : matches < 15
      ? `This is a developing read from ${matches} ${scopeLabel} matches and ${logs} reflection logs. It can guide the next block, but it should not overrule repeated future data.`
      : `This read has a healthier sample: ${matches} ${scopeLabel} matches and ${logs} reflection logs.`;

  return { score, label, explanation, matchCount: matches, logCount: logs, statCoverage: coverage };
}

function buildCoachingEvidenceLayer({
  orderedMatches = [],
  logs = [],
  overview = {},
  importedAnalytics = null,
  currentSignalAgent = "",
  currentSignalRole = "",
  coachingContext = {},
  mechanicsAdjustment = null,
  seasonLabel = "Recent Matches"
} = {}) {
  const matchCount = safeNumber(overview.matchesPlayed || orderedMatches.length);
  const logCount = safeNumber(logs.length);
  const statCoverage = clampPercent(
    (safeNumber(overview.kd) ? 20 : 0) +
    (safeNumber(overview.adr) ? 20 : 0) +
    (safeNumber(overview.hs) ? 14 : 0) +
    (safeNumber(overview.winrate) ? 18 : 0) +
    (safeNumber(importedAnalytics?.overview?.attackKAST) || safeNumber(importedAnalytics?.overview?.defenseKAST) ? 14 : 0) +
    (safeNumber(coachingContext?.weaponRounds) ? 14 : 0)
  );
  const sample = buildSampleConfidenceContext({
    matchCount,
    logCount,
    statCoverage,
    scopeLabel: seasonLabel
  });
  const familyShares = coachingContext?.familyShares || {};
  const shotgunShare = safeNumber(familyShares.shotgun);
  const sniperShare = safeNumber(familyShares.sniper);
  const rifleShare = safeNumber(familyShares.rifle);
  const mechanicReasons = mechanicsAdjustment?.reasons || [];
  const hsWeight = Math.round((mechanicsAdjustment?.hsWeightMultiplier ?? 1) * 100) / 100;
  const hsIsDownWeighted = hsWeight < 0.92 || shotgunShare >= 16 || sniperShare >= 18 || (rifleShare > 0 && rifleShare < 45);
  const hsReason = hsIsDownWeighted
    ? `${formatList(mechanicReasons.length ? mechanicReasons : ["weapon mix changes how headshot percentage should be judged"])}.`
    : "Headshot percentage is being read normally because no major weapon context is changing the value of the stat.";

  return {
    sources: COACHING_EVIDENCE_SOURCES,
    sourcePolicy: [
      "Do not compare a player to public rank, all-time, or pro baselines unless that source exists in the current context and is fresh.",
      "Use All-time instead of Global. When a read combines every role, agent, map, season, or match source, label it as All-inclusive / All-time stat, information, or match data so the scope is obvious.",
      "When sample size is low, say what is assumed and keep the recommendation small.",
      "Stats are weighted by role, agent, weapon mix, map, economy context, and player logs before becoming coaching advice.",
      "A stat can be useful without being the main problem; avoid over-punishing low-value stats for the player's current playstyle."
    ],
    sample,
    currentContext: {
      seasonLabel,
      agent: currentSignalAgent || "",
      role: currentSignalRole || "",
      weaponRounds: safeNumber(coachingContext?.weaponRounds),
      weaponShares: {
        rifle: Math.round(rifleShare),
        shotgun: Math.round(shotgunShare),
        sniper: Math.round(sniperShare)
      },
      relianceFlags: coachingContext?.relianceFlags || []
    },
    metricWeights: {
      headshot: {
        baseWeight: 1,
        activeWeight: hsWeight,
        label: hsIsDownWeighted ? "Down-weighted" : "Normal",
        presumption: hsReason,
        rule: hsIsDownWeighted
          ? "Do not make headshot percentage the lead weakness unless fight conversion, damage, or round impact also supports it."
          : "Headshot percentage can be used as a normal mechanics signal."
      },
      winrate: {
        baseWeight: 1,
        activeWeight: matchCount >= 8 ? 1 : 0.72,
        label: matchCount >= 8 ? "Normal" : "Early signal",
        presumption: matchCount >= 8
          ? "Win rate has enough match volume to guide the profile."
          : "Win rate is visible, but the sample is still too small to treat as the whole player."
      },
      logs: {
        baseWeight: 1,
        activeWeight: logCount >= 5 ? 1 : 0.65,
        label: logCount >= 5 ? "Normal" : "Needs more reflections",
        presumption: logCount >= 5
          ? "Reflection logs have enough repetition to support behavior reads."
          : "Behavior reads should stay cautious until more reflections repeat the same pattern."
      }
    }
  };
}

const COACHING_LANGUAGE_RULES = Object.freeze([
  "Call out what the data proves, then separate what is only a reasonable assumption.",
  "Do not frame a best map, agent, weapon, or role as a strength when it is still below a winning pace.",
  "When every option in a group is under 50% win rate, coach the category as a conversion problem instead of praising the highest option.",
  "Down-weight raw mechanics stats when weapon mix, role, agent, economy, map, or sample size makes that stat less meaningful.",
  "Give the player one next action before adding more context."
]);

function getCoachingSampleTone(evidenceLayer = {}) {
  const sample = evidenceLayer?.sample || {};
  const matches = safeNumber(sample.matchCount);
  if (matches <= 0) {
    return {
      label: "No sample",
      short: "Import a few matches to see this here.",
      sentence: "No imported match sample exists yet, so this should stay as setup guidance."
    };
  }
  if (matches < 6) {
    return {
      label: "Early sample",
      short: `${matches} match${matches === 1 ? "" : "es"} is early.`,
      sentence: `Only ${matches} match${matches === 1 ? "" : "es"} are in this scope, so treat this as direction, not proof.`
    };
  }
  if (matches < 15) {
    return {
      label: "Developing sample",
      short: `${matches} matches is developing.`,
      sentence: `${matches} matches is enough to point you in a direction, but not enough to call the final verdict yet.`
    };
  }
  return {
    label: "Stable sample",
    short: `${matches} matches gives this read useful weight.`,
    sentence: `${matches} matches gives this read useful weight.`
  };
}

function getWinrateBand(winrate = 0, sample = 0) {
  const wr = safeNumber(winrate);
  const count = safeNumber(sample);
  if (count <= 0) return "none";
  if (count < 3) return "early";
  if (wr >= 55) return "strong";
  if (wr >= 50) return "working";
  if (wr >= 45) return "close";
  return "losing";
}

function getWinrateCoachingSentence(subject = "This", winrate = 0, sample = 0, options = {}) {
  const wr = Math.round(safeNumber(winrate));
  const count = safeNumber(sample);
  const band = getWinrateBand(wr, count);
  const lowerSubject = String(subject || "this").trim() || "this";
  const target = options?.target || "50%";
  if (band === "none") return `${lowerSubject} needs a few more matches before the read is fair.`;
  if (band === "early") return `${lowerSubject} is at ${wr}% WR, but ${count} match${count === 1 ? "" : "es"} is too small to judge hard.`;
  if (band === "strong") return `${lowerSubject} is winning at ${wr}% WR across ${count} matches, so keep testing what is working.`;
  if (band === "working") return `${lowerSubject} is above ${target} at ${wr}% WR, but the goal is to make the wins repeatable.`;
  if (band === "close") return `${lowerSubject} is close at ${wr}% WR, but it is not winning often enough yet.`;
  return `${lowerSubject} is at ${wr}% WR across ${count} matches, which means it is losing more than it wins.`;
}

function buildCoachingCopyContext(context = {}) {
  const evidenceLayer = context.evidenceLayer || {};
  const sampleTone = getCoachingSampleTone(evidenceLayer);
  const bestMap = context.bestMap || null;
  const weakestMap = context.weakestMap || null;
  const bestAgent = context.bestAgent || null;
  const weakestAgent = context.weakestAgent || null;
  const bestRole = context.bestRole || null;
  const weakestRole = context.weakestRole || null;
  const overview = context.overview || {};
  return {
    ...context,
    sampleTone,
    rules: COACHING_LANGUAGE_RULES,
    allRepeatedMapsBelowTarget: Boolean(bestMap?.matchesPlayed >= 2 && safeNumber(bestMap?.winrate) < 50),
    allRepeatedAgentsBelowTarget: Boolean(bestAgent?.matchesPlayed >= 3 && safeNumber(bestAgent?.winrate) < 50),
    bestMapText: bestMap
      ? getWinrateCoachingSentence(bestMap.map || "Your best repeated map", bestMap.winrate, bestMap.matchesPlayed)
      : "Play this map a few more times and we'll show your trend here.",
    weakestMapText: weakestMap
      ? getWinrateCoachingSentence(weakestMap.map || "Your weakest repeated map", weakestMap.winrate, weakestMap.matchesPlayed)
      : "No repeated map weakness is stable yet.",
    bestAgentText: bestAgent
      ? getWinrateCoachingSentence(bestAgent.agent || "Your best repeated agent", bestAgent.winrate, bestAgent.matchesPlayed)
      : "No repeated agent has enough matches yet.",
    weakestAgentText: weakestAgent
      ? getWinrateCoachingSentence(weakestAgent.agent || "Your weakest repeated agent", weakestAgent.winrate, weakestAgent.matchesPlayed)
      : "No repeated agent weakness is stable yet.",
    bestRoleText: bestRole
      ? getWinrateCoachingSentence(formatReadableLabel(bestRole.role || "Your best role"), bestRole.winrate, bestRole.matchesPlayed)
      : "No repeated role has enough matches yet.",
    winrateText: getWinrateCoachingSentence("This selected window", overview.winrate, overview.matchesPlayed)
  };
}

function normalizeCoachCopyObject(value) {
  if (Array.isArray(value)) return value.map(item => normalizeCoachCopyObject(item));
  if (!value || typeof value !== "object") return normalizeRankedCoachCopy(value);
  return Object.fromEntries(
    Object.entries(value).map(([key, entry]) => [
      key,
      key === "coachingRuleId" ? entry : normalizeCoachCopyObject(entry)
    ])
  );
}

function formatTrendCoachAction(what = "", how = "") {
  const cleanWhat = String(what || "").trim().replace(/[.]+$/, "");
  const cleanHow = String(how || "").trim().replace(/[.]+$/, "");
  return `${cleanWhat}. ${cleanHow}.`;
}

function describeCommsPracticeTarget(context = {}) {
  const averageSelfComms = safeNumber(context.averageSelfComms, NaN);
  const averageTeamComms = safeNumber(context.averageTeamComms, NaN);
  if (Number.isFinite(averageSelfComms) && averageSelfComms < 3) {
    return "keep improving self comms so your next call is clear before the fight starts";
  }
  if (Number.isFinite(averageTeamComms) && averageTeamComms < 3) {
    return "call your utility timing earlier so teammates know when to swing with it";
  }
  return "keep calling your timing so teammates can play off the value you create";
}

function describeTeamUtilityPracticeTarget(context = {}, roleName = "", agentName = "") {
  const baseTip = describeCommsPracticeTarget(context);
  const role = String(roleName || "").trim().toLowerCase();
  const agent = String(agentName || "").trim();
  if (role === "sentinel") return `make one clear call when ${agent || "your setup"} is about to create contact`;
  if (role === "controller") return "call smoke or molly timing before teammates are forced to guess";
  if (role === "initiator") return "call when your info lands so teammates know when to move";
  if (role === "duelist") return "say when you are about to take space so teammates can trade you";
  return baseTip;
}

function describeTeamUtilityRead(roleName = "", valueNumber = 0) {
  const role = String(roleName || "").trim().toLowerCase();
  const strong = safeNumber(valueNumber) >= 8;
  if (role === "sentinel") return strong ? "Your setup value is turning into real assists" : "Your setup value is helping rounds";
  if (role === "controller") return strong ? "Your utility is giving teammates real help" : "Your controller utility is helping rounds";
  if (role === "initiator") return strong ? "Your info is turning into team value" : "Your info is helping teammates act";
  if (role === "duelist") return strong ? "Your entry work is still helping teammates" : "Your duelist impact is showing some team value";
  return strong ? "Your assists are genuinely impactful" : "Your teamwork is helping rounds";
}

function describeDamageRead(roleName = "", adr = 0) {
  const role = String(roleName || "").trim().toLowerCase();
  const elite = safeNumber(adr) >= 240;
  if (role === "sentinel") return elite ? "Your damage is doing real work for a Sentinel profile" : "Your Sentinel damage is a strong point";
  if (role === "controller") return elite ? "Your damage is strong for a Controller sample" : "Your Controller damage is helping rounds";
  if (role === "initiator") return elite ? "Your damage is adding real impact to your info role" : "Your Initiator damage is a strong point";
  if (role === "duelist") return elite ? "Your damage is giving the team real entry pressure" : "Your Duelist damage is a strong point";
  return elite ? "Your damage is excellent and genuinely impactful" : "Your damage is a strong point";
}

function describeDamagePracticeTarget(context = {}, roleName = "", agentName = "") {
  const role = String(roleName || "").trim().toLowerCase();
  const agent = String(agentName || "").trim();
  const weaponLabel = formatReadableLabel(context.topWeaponFamilyLabel || "");
  if (role === "sentinel") return `keep using ${agent || "your setup"} to make attackers walk into worse fights`;
  if (role === "controller") return `keep using ${agent || "your utility"} to make fights easier before you swing`;
  if (role === "initiator") return `turn your info into earlier damage instead of spending utility with no follow-up`;
  if (role === "duelist") return "use that pressure to take space, then avoid giving away the second fight";
  if (weaponLabel) return `keep using ${weaponLabel.toLowerCase()} when it gives you the cleanest fights`;
  return "turn the damage into earlier round control instead of late exits";
}

function describeRolePracticeTarget(roleName = "", agentName = "") {
  const role = String(roleName || "").trim().toLowerCase();
  const agent = String(agentName || "").trim();
  if (role === "duelist") return "keep entering with a trade plan instead of turning the round into solo fights";
  if (role === "controller") return "stay alive long enough to refresh smokes and make the retake playable";
  if (role === "initiator") return "use info first, then make sure someone is ready to act on it";
  if (role === "sentinel") return `keep using ${agent || "your setup"} to control space, then adapt once the attackers avoid it`;
  return "keep the round plan simple enough to repeat under pressure";
}

function describeProfilePracticeLever(context = {}, options = {}) {
  const prefer = Array.isArray(options.prefer) ? options.prefer : [];
  const avoid = new Set(Array.isArray(options.avoid) ? options.avoid : []);
  const bestMap = context.bestMap || null;
  const weakestMap = context.weakestMap || null;
  const bestAgent = context.bestAgent || null;
  const weakestAgent = context.weakestAgent || null;
  const bestRole = context.bestRole || null;
  const weakestRole = context.weakestRole || null;
  const focusEntry = context.weeklyTopFocusEntry || context.topFocusEntry || null;
  const moodEntry = context.weeklyTopMoodEntry || context.topMoodEntry || null;
  const averageSelfComms = safeNumber(context.averageSelfComms, NaN);
  const averageTeamComms = safeNumber(context.averageTeamComms, NaN);
  const topWeaponLabel = formatReadableLabel(context.topWeaponFamilyLabel || "");
  const topWeaponWinrate = safeNumber(context.topWeaponFamilyWinrate, NaN);
  const topWeaponShare = safeNumber(context.topWeaponFamilyShare, NaN);

  const candidates = [];
  const addCandidate = (type, score, phrase, action) => {
    if (!type || avoid.has(type) || !phrase || !action) return;
    const preferBoost = prefer.includes(type) ? 30 : 0;
    candidates.push({ type, score: safeNumber(score) + preferBoost, phrase, action });
  };

  if (focusEntry?.[0]) {
    addCandidate("focus", 82 + safeNumber(focusEntry[1]), `your ${focusEntry[0]} focus`, `make ${focusEntry[0]} the one thing you review after the next match`);
  }
  if (Number.isFinite(averageSelfComms) && averageSelfComms < 3) {
    addCandidate("self_comms", 88 - averageSelfComms * 8, "self comms", "make one clear call before you swing or rotate");
  }
  if (Number.isFinite(averageTeamComms) && averageTeamComms < 3) {
    addCandidate("team_comms", 84 - averageTeamComms * 8, "team comms", "call utility timing before teammates need to guess");
  }
  if (weakestMap?.map && safeNumber(weakestMap.matchesPlayed) >= 2) {
    addCandidate("weak_map", 100 - safeNumber(weakestMap.winrate), `${weakestMap.map} round plans`, `bring one attack plan and one defense fallback into the next ${weakestMap.map} game`);
  }
  if (weakestRole?.role && safeNumber(weakestRole.matchesPlayed) >= 2) {
    const roleLabel = formatReadableLabel(weakestRole.role);
    addCandidate("weak_role", 96 - safeNumber(weakestRole.winrate), `${roleLabel} role value`, `give ${roleLabel} one simple job before adding more complexity`);
  }
  if (weakestAgent?.agent && safeNumber(weakestAgent.matchesPlayed) >= 2) {
    addCandidate("weak_agent", 92 - safeNumber(weakestAgent.winrate), `${weakestAgent.agent} games`, `review where ${weakestAgent.agent} dies or loses value before swapping the whole agent pool`);
  }
  if (bestAgent?.agent && safeNumber(bestAgent.matchesPlayed) >= 3 && safeNumber(bestAgent.winrate) >= 55) {
    addCandidate("best_agent", safeNumber(bestAgent.winrate), `${bestAgent.agent} plans`, `repeat the ${bestAgent.agent} plans that are already producing wins`);
  }
  if (bestMap?.map && safeNumber(bestMap.matchesPlayed) >= 2 && safeNumber(bestMap.winrate) >= 55) {
    addCandidate("best_map", safeNumber(bestMap.winrate) - 4, `${bestMap.map} map plan`, `keep the same map plan and only change the round that keeps failing`);
  }
  if (topWeaponLabel && Number.isFinite(topWeaponWinrate)) {
    const weaponScore = topWeaponWinrate >= 52 ? topWeaponWinrate - 2 : 88 - topWeaponWinrate;
    const weaponPhrase = topWeaponWinrate >= 52
      ? `${topWeaponLabel} round conversion`
      : `${topWeaponLabel} round losses`;
    const weaponAction = topWeaponWinrate >= 52
      ? `keep using ${topWeaponLabel.toLowerCase()} when you can fight with teammate help or safely leave after the kill`
      : `review whether ${topWeaponLabel.toLowerCase()} rounds are losing more on attack, defense, or forced buys`;
    addCandidate("weapon", weaponScore, weaponPhrase, weaponAction);
  } else if (topWeaponLabel && Number.isFinite(topWeaponShare) && topWeaponShare >= 45) {
    addCandidate("weapon", topWeaponShare, `${topWeaponLabel} fights`, `judge mechanics through those ${topWeaponLabel.toLowerCase()} fights instead of raw aim alone`);
  }
  if (moodEntry?.[0] && ["annoyed", "tilted"].includes(String(moodEntry[0]).toLowerCase())) {
    addCandidate("mood", 76 + safeNumber(moodEntry[1]), `${moodEntry[0]} logs`, "reset between games before that mood changes the next round plan");
  }
  if (bestRole?.role && safeNumber(bestRole.matchesPlayed) >= 2 && safeNumber(bestRole.winrate) >= 55) {
    const roleLabel = formatReadableLabel(bestRole.role);
    addCandidate("best_role", safeNumber(bestRole.winrate) - 8, `${roleLabel} role value`, `use ${roleLabel} when you want the cleanest ranked baseline`);
  }

  return candidates.sort((a, b) => b.score - a.score)[0] || {
    type: "general",
    phrase: "one cleaner repeatable plan",
    action: "pick one focus for the next match and review only that first"
  };
}

function getStatsTrendQuickTakeaway(trend = {}, context = {}) {
  const id = String(trend.id || "").toLowerCase();
  const tone = String(trend.tone || "").toLowerCase();
  const overview = context.overview || {};
  const bestMap = context.bestMap || {};
  const bestAgent = context.bestAgent || {};
  const weaponLabel = formatReadableLabel(context.topWeaponFamilyLabel || trend.kicker || trend.mediaText || "Weapon");
  const signalAgent = String(context.currentSignalAgent || bestAgent?.agent || context.activeAgentName || "").trim();
  const signalRole = formatReadableLabel(context.currentSignalRole || context.activeRoleName || "");
  const averageSelfComms = safeNumber(context.averageSelfComms, NaN);
  const averageTeamComms = safeNumber(context.averageTeamComms, NaN);
  const matches = safeNumber(overview.matchesPlayed);
  const valueNumber = parseFloat(String(trend.value || "0").replace(/[^\d.-]/g, ""));
  const profileLever = describeProfilePracticeLever(context);

  if (!matches && !["weapon_pattern", "weapon_reliance", "side_balance", "multi_kill_pressure"].includes(id)) {
    return "No match sample yet.";
  }

  if (id === "fight_conversion") {
    const kd = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : safeNumber(overview.kd);
    const subject = trend.kicker || signalAgent || "This sample";
    if (kd >= 1.2) return formatTrendCoachAction(`${subject} is at ${kd.toFixed(2)} K/D, so your gunfights are a major strength`, "After the first kill, slow down and help your team keep the advantage");
    if (kd >= 1.05) return formatTrendCoachAction(`${subject} is at ${kd.toFixed(2)} K/D, so your fights are giving the profile real value`, `Keep taking fights that connect back to ${profileLever.phrase}`);
    if (kd >= 0.95) return formatTrendCoachAction(`${subject} is at ${kd.toFixed(2)} K/D, so your fights are close to even`, "Swing with support more often so close duels become traded rounds");
    return formatTrendCoachAction(`${subject} is at ${kd.toFixed(2)} K/D, so too many fights are going against you`, profileLever.action);
  }

  if (id === "match_conversion") {
    const wr = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : safeNumber(overview.winrate);
    const mapName = trend.kicker || bestMap?.map || "this map";
    const agentText = signalAgent ? ` with ${signalAgent}` : "";
    if (context.allRepeatedMapsBelowTarget && bestMap?.map) return formatTrendCoachAction(`${bestMap.map} is your best repeated map at ${Math.round(wr)}% WR, but it is still under 50%`, profileLever.action);
    if (wr >= 55) return formatTrendCoachAction(`${mapName} is going well at ${Math.round(wr)}% WR${agentText}`, `Keep repeating the ${signalAgent || mapName} plans that already win rounds`);
    if (wr >= 50) return formatTrendCoachAction(`${mapName} is barely above a winning pace at ${Math.round(wr)}% WR`, "Keep the plan, but review the close losses before changing everything");
    if (wr >= 45) return formatTrendCoachAction(`${mapName} is close at ${Math.round(wr)}% WR, but not stable yet`, "Review rounds lost after your team gets the first advantage");
    return formatTrendCoachAction(`${mapName} is at ${Math.round(wr)}% WR, so it is not converting enough wins yet`, profileLever.action);
  }

  if (id === "recent_form") {
    const recentWins = safeNumber(context.recentWins);
    const recentLosses = safeNumber(context.recentLosses);
    if (tone === "up") return formatTrendCoachAction("Your recent games are trending up", `Repeat the same ${signalAgent || "agent"} plan and keep ${profileLever.phrase} in view`);
    if (tone === "down") return formatTrendCoachAction(`Recent form is slipping with ${recentLosses || "more"} losses in the last block`, `Keep the next match simple and review ${profileLever.phrase} first`);
    return formatTrendCoachAction(`Recent form is steady at ${recentWins} wins and ${recentLosses} losses`, "Keep the same plan for one more block before changing focus");
  }

  if (id === "score_pressure") {
    const adr = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : safeNumber(overview.adr);
    const damageTip = describeDamagePracticeTarget(context, signalRole, signalAgent);
    if (adr >= 240) return formatTrendCoachAction(`${describeDamageRead(signalRole, adr)} at ${Math.round(adr)} ACS`, damageTip);
    if (adr >= 215) return formatTrendCoachAction(`${describeDamageRead(signalRole, adr)} at ${Math.round(adr)} ACS`, damageTip);
    if (adr >= 185) return formatTrendCoachAction(`Your damage is serviceable at ${Math.round(adr)} ACS`, "Make it matter sooner by fighting with clearer support");
    return formatTrendCoachAction(`Your damage is too quiet at ${Math.round(adr)} ACS`, profileLever.action);
  }

  if (id === "precision_signal") {
    const hsWeight = context.evidenceLayer?.metricWeights?.headshot;
    const hs = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : safeNumber(overview.hs);
    const subject = trend.kicker || signalAgent || "This sample";
    if (hsWeight?.label === "Down-weighted") return formatTrendCoachAction(`${subject} is at ${Math.round(hs)}% HS, so headshots are not the main issue for this profile`, `Spend more review time on ${profileLever.phrase}`);
    if (hs >= 28) return formatTrendCoachAction(`${subject} is at ${Math.round(hs)}% HS, so your aim is excellent already`, "Keep your composure after your first fight so the mechanics stay reliable");
    if (hs >= 22) return formatTrendCoachAction(`${subject} is at ${Math.round(hs)}% HS, so your aim is in a good place`, "Keep choosing the next fight with patience instead of forcing the follow-up peek");
    if (hs >= 18) return formatTrendCoachAction(`${subject} is at ${Math.round(hs)}% HS, so your aim is a little inconsistent`, "Slow down the first bullet and make the spray a backup plan");
    return formatTrendCoachAction(`${subject} is at ${Math.round(hs)}% HS, so aim is making fights harder`, "Start with cleaner crosshair placement before each swing");
  }

  if (id === "support_pressure") {
    const commsTip = describeTeamUtilityPracticeTarget(context, signalRole, signalAgent);
    const assists = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : safeNumber(context.assistsPerMatch);
    if (assists >= 8) return formatTrendCoachAction(`${describeTeamUtilityRead(signalRole, assists)} at ${assists.toFixed(1)} assists per match`, commsTip);
    if (assists >= 5) return formatTrendCoachAction(`${describeTeamUtilityRead(signalRole, assists)} at ${assists.toFixed(1)} assists per match`, commsTip);
    if (assists >= 3.5) return formatTrendCoachAction(`Your team impact shows up in flashes at ${assists.toFixed(1)} assists per match`, "Make the timing more repeatable with one clear call before contact");
    return formatTrendCoachAction(`Your team impact is too low at ${assists.toFixed(1)} assists per match`, "Play closer so your utility and trades actually help teammates");
  }

  if (id === "round_survivability") {
    const deaths = Number.isFinite(valueNumber) && valueNumber > 0 ? valueNumber : 0;
    if (tone === "up") return formatTrendCoachAction(`${signalRole || "Your role"} is at ${deaths.toFixed(1)} deaths per match, so survival is helping your rounds`, describeRolePracticeTarget(signalRole, signalAgent));
    if (tone === "down") return formatTrendCoachAction(`${signalRole || "Your role"} is at ${deaths.toFixed(1)} deaths per match, so you are dying before getting full value`, describeRolePracticeTarget(signalRole, signalAgent));
    return formatTrendCoachAction(`${signalRole || "Your role"} is at ${deaths.toFixed(1)} deaths per match, so survival is close to stable`, "Review whether deaths happen before or after your role job is done");
  }

  if (id === "kast_stability") {
    if (tone === "up") return formatTrendCoachAction("Your round impact is strong", "Stay connected to the team");
    return formatTrendCoachAction("Your impact is missing too often", "Stay close enough to help");
  }

  if (id === "side_balance") {
    return formatTrendCoachAction("One side of the map needs attention", "Fix that plan before changing everything");
  }

  if (id === "weapon_pattern" || id === "weapon_reliance") {
    const kd = safeNumber(overview.kd);
    const weaponWinrate = safeNumber(context.topWeaponFamilyWinrate, NaN);
    const primaryWeapon = formatReadableLabel(context.topWeaponPrimaryWeapon || "");
    const sideGap = Math.abs(safeNumber(context.topWeaponFamilyAttackWinrate) - safeNumber(context.topWeaponFamilyDefenseWinrate));
    const weakerSide = safeNumber(context.topWeaponFamilyAttackWinrate) < safeNumber(context.topWeaponFamilyDefenseWinrate) ? "attack" : "defense";
    const weaponName = primaryWeapon && primaryWeapon !== "--" ? primaryWeapon : weaponLabel;
    if (Number.isFinite(weaponWinrate) && weaponWinrate >= 55) return formatTrendCoachAction(`${weaponLabel} rounds are a real strength at ${Math.round(weaponWinrate)}% WR`, `Keep using ${weaponName} in rounds where you can trade out or safely leave after the first kill`);
    if (Number.isFinite(weaponWinrate) && weaponWinrate >= 50) return formatTrendCoachAction(`${weaponLabel} rounds are winning slightly more than they lose`, sideGap >= 12 ? `Review ${weakerSide} rounds so the weapon value holds on both sides` : "Keep buying it when your credits support the plan, then avoid forcing extra peeks after a kill");
    if (Number.isFinite(weaponWinrate) && weaponWinrate >= 45) return formatTrendCoachAction(`${weaponLabel} rounds are close, but not stable yet`, sideGap >= 12 ? `Start with the weaker ${weakerSide} side before blaming the weapon` : "Review whether these rounds are lost from positioning, timing, or the buy itself");
    if (Number.isFinite(weaponWinrate)) return formatTrendCoachAction(`${weaponLabel} rounds are losing too often right now`, sideGap >= 12 ? `Start with the weaker ${weakerSide} side and change one buy habit at a time` : "Do not make this the default buy until the round plan improves");
    if (valueNumber >= 55 && kd >= 1) return formatTrendCoachAction(`${weaponLabel} rounds fit your profile well`, "Keep taking clean fights and avoid forcing extra peeks after a kill");
    if (valueNumber >= 45) return formatTrendCoachAction(`${weaponLabel} is shaping your profile`, profileLever.action);
    return formatTrendCoachAction(`${weaponLabel} needs more clean data before judging hard`, `Keep logging it and compare it against ${profileLever.phrase}`);
  }

  if (id === "multi_kill_pressure") {
    return formatTrendCoachAction("Your multi-kills are creating chances", "Slow down and secure the round");
  }

  return trend.detail || "Tap for the full read.";
}

function polishCoachingInsight(insight = {}, context = {}) {
  const title = String(insight?.title || "").toLowerCase();
  const output = { ...insight };
  const sampleSentence = context.sampleTone?.sentence || "";
  const bestAgent = context.bestAgent || {};
  const bestMap = context.bestMap || {};
  const weakestMap = context.weakestMap || {};
  const bestRole = context.bestRole || {};
  const weakestRole = context.weakestRole || {};
  const overview = context.overview || {};
  const vocabularyVariant = (key, seed, values = {}) => globalThis.RankedCoachValorantVocabulary?.selectCardVariant?.(key, seed, values) || null;

  if (title === "core agent strength" && bestAgent?.agent) {
    const wr = Math.round(safeNumber(bestAgent.winrate));
    const games = safeNumber(bestAgent.matchesPlayed);
    if (wr < 50) {
      output.type = "warn";
      output.title = "Best Available Agent Still Needs Work";
      output.preview = `${bestAgent.agent} is your best repeated pick at ${wr}% WR, but that is still below a winning pace.`;
      output.what = `${bestAgent.agent} is the clearest agent sample right now, not a proven strength yet.`;
      output.why = `The pick has enough games to review, but ${wr}% WR means the rounds are not converting often enough. ${sampleSentence}`;
      output.action = `Keep ${bestAgent.agent} only if the map fits, then give the next game one clear ${formatReadableLabel(agentRoles?.[bestAgent.agent] || "role")} job.`;
      output.priority = Math.max(safeNumber(output.priority), 86);
    } else {
      Object.assign(output, vocabularyVariant("agentStrength", `${bestAgent.agent}:${games}:${wr}`, {
        agent: bestAgent.agent,
        games,
        winrate: wr
      }) || {});
    }
  }

  if (title === "map preparation gap" && weakestMap?.map) {
    const bestWr = Math.round(safeNumber(bestMap?.winrate));
    if (context.allRepeatedMapsBelowTarget) {
      output.title = "Map Pool Is Not Converting Yet";
      output.preview = `No repeated map is above 50% WR right now. Best available: ${bestMap?.map || "unknown"} at ${bestWr}% WR.`;
      output.what = "This is not just one bad map. The current map pool is losing more than it wins.";
      output.why = `${context.bestMapText} That points to round plans, side discipline, or role fit more than one isolated map mistake.`;
      output.action = "Pick one map to simplify first: one attack plan, one defense default, and one mid-round fallback.";
      output.priority = Math.max(safeNumber(output.priority), 96);
    } else {
      Object.assign(output, vocabularyVariant("mapWeakness", `${weakestMap.map}:${weakestMap.matchesPlayed}:${Math.round(safeNumber(weakestMap.winrate))}`, {
        map: weakestMap.map,
        games: safeNumber(weakestMap.matchesPlayed),
        winrate: Math.round(safeNumber(weakestMap.winrate))
      }) || {});
    }
  }

  if (title === "multi-kill impact is showing up") {
    output.title = "Multi-Kill Rounds Are Creating Chances";
    output.what = "Your multi-kill rounds are creating round-winning chances.";
    output.why = "The next question is whether those advantages are being traded into safer round wins instead of extra risky fights.";
    output.action = "After the first advantage, slow the round down, group up, and make the trade easy.";
  }

  if (title === "map side bias matters here") {
    output.title = "One Side Of The Map Needs A Plan";
    output.what = "One side of this map is performing much better than the other.";
    output.why = "Attack and defense ask for different habits, so the weaker side should be reviewed separately.";
    output.action = "Keep the stronger side simple, then build one clear rule for the weaker side.";
  }

  if (title === "damage delta is being judged in agent context") {
    output.title = "Damage Needs Agent Context";
    output.preview = normalizeRankedCoachCopy(output.preview || "Damage is being checked against the agent you are playing.");
    output.what = "Damage output is being read through the agent, not as a flat number.";
    output.why = "Some agents should create pressure with utility, while others create value through space, info, or survival.";
    output.action = "Check whether your damage helped create an easier fight, a stalled hit, or a round win.";
  }

  if (title === "mechanics need weapon context") {
    output.what = "Raw headshot percentage is not being treated like a rifle-only stat for this profile.";
    output.why = context.evidenceLayer?.metricWeights?.headshot?.presumption || output.why;
    output.action = "Check fight conversion, damage timing, positioning, and round wins before making aim the whole issue.";
  }

  if (title === "fights are slipping") {
    output.preview = `Your K/D is ${Number(safeNumber(overview.kd)).toFixed(2)}, so fight value needs attention in this window.`;
    output.what = "Too many fights are being lost or taken without enough support.";
    output.why = "This can be aim, but it can also be dry peeks, bad spacing, late trades, or taking contact before utility is ready.";
    output.action = "For the next block, choose one fight rule: swing with a teammate, clear one angle at a time, or stop the first solo death.";
  }

  if (title === "reliable dueling") {
    output.preview = `Your K/D is ${Number(safeNumber(overview.kd)).toFixed(2)}, which gives the profile something real to build from.`;
    output.what = "Your fights are producing value.";
    output.why = safeNumber(overview.winrate) < 50
      ? "The issue is likely what happens after the fight advantage, because the match record still is not converting enough."
      : "The fights and the match record are lining up well enough to keep leaning into this style.";
    output.action = safeNumber(overview.winrate) < 50
      ? "After a pick, group up and turn the advantage into a safer round."
      : "Keep taking initiative, but avoid turning a won fight into an unnecessary second risk.";
  }

  if (title === "recent mechanical form is slipping") {
    output.title = "Recent Form Is Slipping";
    Object.assign(output, vocabularyVariant("recentLosses", `${overview.matchesPlayed}:${overview.matchesLost}`) || {});
  }

  if (title === "recent mechanical form is strong") {
    output.title = "Recent Form Is Working";
    Object.assign(output, vocabularyVariant("recentWins", `${overview.matchesPlayed}:${overview.matchesWon}`) || {});
  }

  if (title === "focus category to observe") {
    output.title = "Repeated Focus Category";
    Object.assign(output, vocabularyVariant("weeklyFocus", `${output.focus}:${context.logs?.length || 0}`, {
      focus: output.focus || "This focus"
    }) || {});
  }

  if (title.endsWith("benchmark check")) {
    output.preview = `${output.benchmark?.rankLabel || "Rank"} check: ${Number(safeNumber(overview.kd)).toFixed(2)} K/D, ${Math.round(safeNumber(overview.adr))} ADR, ${Math.round(safeNumber(overview.hs))}% HS in this window.`;
    output.what = output.what || "The current match window has one rank-relative gap worth watching.";
    output.why = "The rank sample is context, not a verdict. Agent, map, weapon, and round decisions still decide what the number means.";
  }

  if (title === "no map is winning enough yet") {
    output.title = "Map Pool Is Not Converting Yet";
    output.what = "No repeated map is turning enough rounds into match wins in this window.";
    output.why = "When the whole pool is below 50%, start with defaults, side plans, and comfort picks instead of blaming one map.";
    output.action = "Choose one map, one attack default, one defense setup, and one fallback call before the next queue.";
  }

  if (title === "clutch closing") {
    output.what = `${Math.round(safeNumber(overview.clutchWins))} of ${Math.round(safeNumber(overview.clutchRounds))} late rounds ended with you getting the final kill.`;
    output.why = "These are rounds where your timing and last-fight choice decided whether the advantage actually closed.";
    output.action = safeNumber(overview.clutchConversionRate) >= 50
      ? "Keep isolating the final duel and make the opponent swing into your timing."
      : "Slow the last fight down, clear the trade, and use the spike clock before giving the opponent a clean duel.";
  }

  if (title === "trade support split") {
    output.what = "The trade window shows how often teammates answer your death and how often you answer theirs.";
    output.why = "A gap between those two rates usually points to spacing, entry timing, or being too far away when first contact happens.";
    output.action = "Start the next hit close enough to swing the same angle within the trade window, then reset together after the pick.";
  }

  if (title === "damage consistency") {
    output.what = "Your round-to-round damage is changing enough to affect how reliable your pressure feels.";
    output.why = "Big swings often come from taking very different fights each round, arriving late, or getting removed before utility creates a clean duel.";
    output.action = "Repeat the same opening job for a few rounds and judge whether your damage arrives before the round is already decided.";
  }

  if (title === "repeated availability flag") {
    output.title = "Rounds Lost Before You Could Play Them";
    output.what = "The import found repeated rounds where you were unavailable before your normal role value could be used.";
    output.why = "AFK or spawn-idle rounds distort combat stats and leave the team playing the round short-handed.";
    output.action = "Treat this as a queue-readiness issue, not an aim issue; only start when you can play the full match.";
  }

  if (title === "confidence is running low") {
    output.title = "Confidence Needs A Reset Plan";
    output.what = "Recent logs show confidence or self-rating dropping.";
    output.why = "Low confidence usually makes players hesitate, rush fixes, or chase back a bad round.";
    output.action = "Use a small reset: one breath, one useful comm, then play the next round plan.";
  }

  if (title === "role results are uneven" && bestRole?.role && weakestRole?.role) {
    const bestRoleLabel = formatReadableLabel(bestRole.role);
    const weakestRoleLabel = formatReadableLabel(weakestRole.role);
    if (safeNumber(bestRole.winrate) < 50) {
      output.title = "Role Fit Is Still Unsettled";
      output.preview = `${bestRoleLabel} is your best role sample, but it is still under 50% WR.`;
      output.what = `${bestRoleLabel} is best available, not fully working yet.`;
      output.why = `${weakestRoleLabel} is lagging behind, but the best role still needs cleaner round conversion.`;
      output.action = `Queue ${bestRoleLabel} only with a simple role job, then compare it against ${weakestRoleLabel} after more games.`;
      output.priority = Math.max(safeNumber(output.priority), 84);
    } else {
      output.what = `${bestRoleLabel} is giving you better results than ${weakestRoleLabel}.`;
      output.why = "That usually means your comfort, decisions, or impact timing fits one role better right now.";
      output.action = `Use ${bestRoleLabel} when you want stability, and give ${weakestRoleLabel} one specific practice goal when you play it.`;
    }
  }

  return normalizeCoachCopyObject(output);
}

function polishTrendRead(trend = {}, context = {}) {
  const output = { ...trend };
  const id = String(output.id || "").toLowerCase();
  const overview = context.overview || {};
  const sampleSentence = context.sampleTone?.sentence || "";
  const tone = String(output.tone || trend?.tone || "").toLowerCase();

  if (id === "fight_conversion") {
    output.detail = !safeNumber(overview.matchesPlayed)
      ? "No match sample yet."
      : safeNumber(overview.kd) >= 1.1
        ? "You are winning enough fights to build around it. Now prove those picks become rounds."
        : safeNumber(overview.kd) >= 1
          ? "The fights are playable. The next check is whether they are turning into wins."
          : "Too many fights are being lost or isolated. Check spacing and trade timing before blaming aim only.";
    output.read = safeNumber(overview.kd) >= 1
      ? "The fight value is playable. The next read is conversion."
      : "Fight value is costing rounds often enough to stay near the top of the plan.";
  }

  if (id === "match_conversion") {
    output.detail = !safeNumber(overview.matchesPlayed)
      ? "No match sample yet."
      : safeNumber(overview.winrate) >= 52
        ? "This window is winning. Keep the setup stable and find what is repeating."
        : safeNumber(overview.winrate) >= 50
          ? "This is barely positive. Protect the rounds you already know how to win."
          : safeNumber(overview.winrate) >= 45
            ? "This is close, but still under target. One or two rounds per match are slipping."
            : "This window is losing more than it wins. Start with the repeat context costing rounds.";
    output.read = context.allRepeatedMapsBelowTarget
      ? "No repeated map is above 50% WR, so this is a full map-pool conversion problem, not a single-map flex."
      : output.detail;
  }

  if (id === "recent_form") {
    output.detail = tone === "down"
      ? "Latest matches are below your usual level. Lower the scope and stabilize one focus."
      : tone === "up"
        ? "Latest matches are beating your baseline. Repeat the same agent and focus block."
        : "Latest matches are close to your usual level. Keep the plan stable for more signal.";
    output.read = tone === "down"
      ? "Recent form is dipping. Keep the next match simple enough to measure."
      : "Recent form is stable enough to repeat the current plan.";
  }

  if (id === "score_pressure") {
    output.label = "Damage Pressure";
    output.detail = !safeNumber(overview.matchesPlayed)
      ? "No match sample yet."
      : safeNumber(overview.adr) >= 215
        ? "Damage is creating pressure. Now make sure it is ending in round wins."
        : safeNumber(overview.adr) >= 185
          ? "Damage is present but not decisive. Check whether it arrives early enough to matter."
          : "Damage pressure is low. Fights may be too late, too isolated, or not setting up teammates.";
    output.read = safeNumber(overview.adr) >= 200
      ? "Damage pressure is showing up. Keep tying it to round wins."
      : "Damage pressure is a supporting issue, especially if fights or KAST are also low.";
  }

  if (id === "precision_signal") {
    const hsWeight = context.evidenceLayer?.metricWeights?.headshot;
    output.detail = hsWeight?.label === "Down-weighted"
      ? "HS% is not the main story here. Judge the fights by conversion, position, and weapon mix."
      : safeNumber(overview.hs) >= 22
        ? "Precision is not blocking you right now. Look at conversion and decision timing next."
        : safeNumber(overview.hs) >= 18
          ? "Precision is borderline. Clean up first-bullet fights without making aim the whole review."
          : "Precision is low enough to hurt fights. Pair crosshair discipline with better fight choice.";
    output.read = hsWeight?.label === "Down-weighted"
      ? `${hsWeight.presumption} Check fight conversion before making aim the full answer.`
      : output.read;
  }

  if (id === "support_pressure") {
    const assistsValue = parseFloat(String(output.value || "0").replace(/[^\d.]/g, ""));
    output.detail = assistsValue >= 5
      ? "Team value is showing up. Keep pairing utility and trades with round wins."
      : assistsValue >= 3.5
        ? "Team value is present but inconsistent. Check comm timing and trade spacing."
        : "Low assists can mean fights are too solo or utility is not helping teammates enough.";
    output.read = "This matters most when it lines up with role choice and round wins.";
  }

  if (id === "round_survivability") {
    output.detail = tone === "up"
      ? "Deaths are controlled enough to keep your role value alive longer."
      : tone === "down"
        ? "Too many rounds are ending before your role value is spent."
        : "Survival is close, but the timing of deaths still needs review.";
    output.read = "Survival matters when dying early removes utility, trade value, or map control.";
  }

  if (id === "kast_stability") {
    output.detail = tone === "up"
      ? "You are staying connected to more rounds. Keep protecting that involvement."
      : "Too many rounds are happening without you connected to the trade, assist, or survival.";
    output.read = "Low KAST usually means too many rounds are happening without you staying connected to the team.";
  }

  if (id === "side_balance") {
    output.detail = "ATK/DEF gaps are reviewed separately because the two halves ask for different plans.";
    output.read = "Do not fix the whole map at once. Fix the weaker side first.";
  }

  if (id === "weapon_pattern" || id === "weapon_reliance") {
    const weaponLabel = output.kicker || output.mediaText || "Weapon";
    const weaponShare = parseFloat(String(output.value || "0").replace(/[^\d.]/g, ""));
    output.detail = weaponShare >= 45
      ? `${weaponLabel} is shaping this profile. Judge it by clean fights, survival after the kill, and round wins.`
      : `${weaponLabel} is part of the picture, but it is not taking over the whole read.`;
    output.read = "A weapon-heavy profile should be reviewed by fight quality, positioning, and round impact, not HS% alone.";
  }

  if (id === "multi_kill_pressure") {
    output.detail = "Multi-kill rounds show that you can swing rounds, but conversion still matters.";
    output.read = "After the first advantage, group up and make the trade easy.";
  }

  output.detail = getStatsTrendQuickTakeaway(output, context);

  if (sampleSentence && !String(output.sourceLabel || "").includes(sampleSentence)) {
    output.sampleNote = sampleSentence;
  }

  return normalizeCoachCopyObject(output);
}

function polishBreakdownRead(card = {}, context = {}) {
  const output = { ...card };
  const label = String(output.label || "").toLowerCase();
  const bestAgent = context.bestAgent || {};
  const bestMap = context.bestMap || {};
  const weakestMap = context.weakestMap || {};
  const bestRole = context.bestRole || {};

  if (label === "mechanics") {
    output.detail = context.evidenceLayer?.metricWeights?.headshot?.label === "Down-weighted"
      ? "Mechanics are being read through fights, damage timing, positioning, and weapon mix."
      : "Mechanics are being read through fight value, damage, and precision together.";
  }

  if (label === "average adr") {
    output.label = "Damage Pressure";
    output.detail = "Damage matters most when it creates a cleaner fight, a stalled hit, or a converted round.";
  }

  if (label === "agent selection" && bestAgent?.agent) {
    output.detail = safeNumber(bestAgent.winrate) >= 50
      ? `${bestAgent.agent} is winning enough to keep in the active pool.`
      : `${bestAgent.agent} is the best repeated pick available, but ${Math.round(safeNumber(bestAgent.winrate))}% WR is still not working enough yet.`;
  }

  if (label === "coaching focus category") {
    output.detail = context.coachDiagnosis || output.detail;
  }

  if (label === "confidence rating") {
    output.detail = context.sampleTone?.sentence || output.detail;
    output.tooltip = `${output.detail} Confidence also checks logs and stat coverage.`;
  }

  if (label === "round survivability") {
    output.detail = "Deaths are reviewed by timing and role value. The goal is not passive play; it is staying alive when your life still has value.";
  }

  if (label === "support value") {
    output.detail = "Assist value helps show whether trades, utility, or follow-up timing are helping teammates convert rounds.";
  }

  if (label === "map pattern") {
    if (context.allRepeatedMapsBelowTarget && bestMap?.map) {
      output.value = `${bestMap.map} ${Math.round(safeNumber(bestMap.winrate))}% WR`;
      output.detail = "This is the best repeated map, but it is still below 50%, so the map pool needs a simpler plan.";
    } else if (weakestMap?.map) {
      output.detail = `${weakestMap.map} is the repeated map most worth reviewing first.`;
    }
  }

  if (label === "role fit" && bestRole?.role) {
    output.detail = safeNumber(bestRole.winrate) >= 50
      ? `${formatReadableLabel(bestRole.role)} is the clearest stable role signal right now.`
      : `${formatReadableLabel(bestRole.role)} is best available, but still below a winning pace.`;
  }

  if (label === "weapon category") {
    output.detail = "Weapon category changes how aim, HS%, and conversion should be read.";
  }

  if (label === "mood pattern") {
    output.detail = "Mood logs explain session quality. They should guide resets, not blame the player.";
  }

  return normalizeCoachCopyObject(output);
}

function polishWeeklyCandidate(candidate = {}, context = {}) {
  const output = { ...candidate };
  const key = String(output.key || "").toLowerCase();

  if (key === "tilt") {
    const moodLabel = String(output.label || "").replace(/^Most tilt mentions:?\s*/i, "").trim();
    output.label = moodLabel && !/^Most/i.test(moodLabel) ? `Mood pattern: ${moodLabel}` : "Mood pattern";
    output.summary = output.summary && !/No clear/i.test(output.summary)
      ? output.summary.replace(/focus category/i, "mood pattern")
      : "No repeated tilt pattern is stored yet.";
    output.read = output.read && !/not enough/i.test(output.read)
      ? "This points to session emotion affecting decisions. Treat it as a reset cue, not a character flaw."
      : "Log your mood a few more times and we'll tell you if tilt's affecting your games.";
  }

  if (key === "ratings") {
    output.label = output.label.replace(/^Weakest self ratings/i, "Lowest self-rated focus");
    output.read = output.read && !/not enough/i.test(output.read)
      ? "This is where the player is rating their own games lowest, so it is a practical place to review first."
      : "You haven't logged enough low-rated games yet to spot a real pattern.";
  }

  if (key === "losses") {
    output.read = context.allRepeatedMapsBelowTarget
      ? "Losses are not isolated to one winning map pool yet. Start by simplifying the most repeated losing context."
      : output.read;
  }

  if (key === "impactful") {
    output.label = output.label.replace(/^Biggest coaching category gap:/i, "Compass gap:");
    output.read = output.read && !/No impact/i.test(output.read)
      ? "This is the lowest compass pillar right now, so it is the best long-term development target."
      : output.read;
  }

  return normalizeCoachCopyObject(output);
}

function polishTrendBreakdownItem(item = {}, context = {}) {
  const output = { ...item };
  const kicker = String(output.kicker || "").toLowerCase();
  const title = String(output.title || "").toLowerCase();

  if (kicker.includes("map") && context.allRepeatedMapsBelowTarget) {
    output.detail = "The map read is below a winning pace. Review the plan before calling it a strength.";
  }
  if (kicker.includes("agent") && context.allRepeatedAgentsBelowTarget) {
    output.detail = "The agent read is best available, but not winning enough to call stable yet.";
  }
  if (kicker.includes("emotional") || title.includes("positive") || title.includes("negative")) {
    output.detail = "Mood logs are context for reset habits and decision quality.";
  }
  if (kicker.includes("engine health")) {
    output.detail = context.sampleTone?.sentence || output.detail;
  }
  return normalizeCoachCopyObject(output);
}

function polishRecentImprovementItem(item = {}, context = {}) {
  const output = { ...item };
  output.detail = output.detail || "This moved in the right direction in the recent window.";
  output.comparisonLabel = output.comparisonLabel || "Recent window compared against the earlier profile baseline.";
  output.sourceLabel = output.sourceLabel || "Built from the current match/log sample.";
  output.formula = output.formula || "Recent value minus earlier value.";
  if (context.sampleTone?.label === "Early sample") {
    output.sourceLabel = `${output.sourceLabel} ${context.sampleTone.sentence}`;
  }
  return normalizeCoachCopyObject(output);
}

function buildCoachRecommendation(kind, entity = {}, model = {}) {
  const overview = model?.overview || {};
  const weeklyFocus = model?.weekly?.mostPracticed || model?.focus || "the current focus category";

  if (kind === "map") {
    const mapName = entity?.map || "this map";
    const mapWr = Math.round(safeNumber(entity?.winrate));
    const sample = safeNumber(entity?.matchesPlayed);
    const agent = entity?.agent || "your most repeated agent";
    const attackWr = safeNumber(entity?.attackWinPct);
    const defenseWr = safeNumber(entity?.defenseWinPct);
    const sideGap = Math.abs(attackWr - defenseWr);
    const weakerSide = attackWr && defenseWr
      ? attackWr < defenseWr ? "ATK" : "DEF"
      : "";

    if (sample < 2) {
      return {
        diagnosis: `${mapName} needs a few more matches before this is a fair map read.`,
        emphasis: "One game can point at a problem, but it should not decide the whole map plan.",
        recommendation: `Play one more ${mapName} match and log what side felt harder.`
      };
    }

    if (mapWr >= 55) {
      return {
        diagnosis: `${mapName} is winning enough to keep in the active pool.`,
        emphasis: `${agent} looks comfortable here, but the goal is still repeatable round plans.`,
        recommendation: sideGap >= 12 && weakerSide
          ? `Keep what is working, then clean up the ${weakerSide} half.`
          : `Keep your ${mapName} plan simple and repeat what is winning rounds.`
      };
    }

    if (mapWr >= 45) {
      return {
        diagnosis: `${mapName} is close, but still not winning enough yet.`,
        emphasis: sideGap >= 12 && weakerSide ? `${weakerSide} rounds are the first thing to review.` : "The map needs a simpler plan.",
        recommendation: sideGap >= 12 && weakerSide
          ? `Go in with one ${weakerSide} plan and one backup call.`
          : `Pick one attack plan and one defense fallback before your next ${mapName} game.`
      };
    }

    return {
      diagnosis: `${mapName} is losing more than it wins right now.`,
      emphasis: "Do not treat this as a small stat dip until the plan gets simpler.",
      recommendation: `Review your ${mapName} prep first: one attack default, one defense default, one fallback call.`
    };
  }

  if (kind === "agent") {
    const agentName = entity?.agent || "this agent";
    const winrate = Math.round(safeNumber(entity?.winrate));
    const kd = Number(entity?.kd || 0);
    const role = agentRoles?.[agentName] || "role";
    const sample = safeNumber(entity?.matchesPlayed);

    if (sample < 3) {
      return {
        diagnosis: `${agentName} needs a few more games before this is a fair agent read.`,
        emphasis: "Do not overreact to a tiny sample.",
        recommendation: `Play ${agentName} when the map fits, then check whether the next few games repeat the same pattern.`
      };
    }

    if (winrate >= 55 && kd >= 1) {
      return {
        diagnosis: `${agentName} is one of your cleaner picks right now.`,
        emphasis: `Your ${role} play on this agent is helping rounds convert.`,
        recommendation: `Keep ${agentName} in your active pool.`
      };
    }

    if (winrate >= 50 || kd >= 1) {
      return {
        diagnosis: `${agentName} is showing value, but the wins are not clean yet.`,
        emphasis: kd >= 1 ? "The fights are there. The rounds need more structure." : "The rounds are close. The fights need more discipline.",
        recommendation: `Give ${agentName} one job next game and judge whether that job helped convert rounds.`
      };
    }

    return {
      diagnosis: `${agentName} is not winning enough right now.`,
      emphasis: "Narrow the job you expect from this pick.",
      recommendation: `Play ${agentName} with one clear ${role} goal next game.`
    };
  }

  if (kind === "role") {
    const roleName = entity?.role || "this role";
    const winrate = Math.round(safeNumber(entity?.winrate));
    return {
      diagnosis: winrate >= 50 ? `${roleName} is winning enough to keep testing.` : `${roleName} is not leading to enough wins right now.`,
      emphasis: winrate >= 50 ? "Lean into the habits that are already converting rounds." : "Make the role simpler before adding more plans.",
      recommendation: winrate >= 50
        ? `Queue ${roleName} when you want a steadier path.`
        : `Give this role one small job next game.`
    };
  }

  return {
    diagnosis: overview.kd >= 1 ? "Your profile has fight value to build from." : "Your profile needs a stronger baseline before the read gets sharp.",
    emphasis: `Use ${weeklyFocus} as the next review target.`,
    recommendation: "Keep the next goal small enough to actually notice if it worked."
  };
}

function clampScore(value, min = 0, max = 100) {
  return Math.max(min, Math.min(max, Number(value) || 0));
}

function normalizeMetricAgainstBaseline(value, baseline, spread = null, options = {}) {
  const { inverse = false, center = 50, scale = 18 } = options;
  const safeValue = safeNumber(value);
  const safeBaseline = safeNumber(baseline, safeValue || 1);
  const safeSpread = Math.max(0.08, safeNumber(spread, Math.max(Math.abs(safeBaseline) * 0.18, 0.12)));
  const delta = (safeValue - safeBaseline) / safeSpread;
  return clampScore(center + ((inverse ? -delta : delta) * scale));
}

const COMPASS_STAT_BENCHMARKS = {
  acs: { floor: 145, average: 200, strong: 245, elite: 305 },
  kd: { floor: 0.75, average: 1.0, strong: 1.2, elite: 1.45 },
  hs: { floor: 12, average: 22, strong: 32, elite: 40 },
  winrate: { floor: 40, average: 50, strong: 56, elite: 64 },
  assists: { floor: 1.5, average: 3.2, strong: 5.2, elite: 7.0 },
  deaths: { floor: 20, average: 16.5, strong: 13, elite: 10, inverse: true },
  kast: { floor: 60, average: 70, strong: 76, elite: 82 },
  econ: { floor: 35, average: 55, strong: 75, elite: 95 }
};

const COMPASS_ROLE_EXPECTATION_MODIFIERS = {
  duelist: { acs: 1.06, kd: 1.04, assists: 0.84, deaths: 1.03, hs: 1.0 },
  initiator: { acs: 0.97, kd: 0.97, assists: 1.18, deaths: 1.0, hs: 0.98 },
  controller: { acs: 0.95, kd: 0.96, assists: 1.16, deaths: 0.98, hs: 0.97 },
  sentinel: { acs: 0.97, kd: 1.0, assists: 1.0, deaths: 0.96, hs: 0.99 },
  unknown: { acs: 1, kd: 1, assists: 1, deaths: 1, hs: 1 }
};

function getCompassRoleKey(roleName = "Unknown") {
  const role = String(roleName || "unknown").trim().toLowerCase();
  if (role.includes("duelist")) return "duelist";
  if (role.includes("initiator")) return "initiator";
  if (role.includes("controller")) return "controller";
  if (role.includes("sentinel")) return "sentinel";
  return "unknown";
}

function adjustCompassBenchmark(benchmark = {}, modifier = 1) {
  const safeModifier = Math.max(0.5, safeNumber(modifier, 1));
  return {
    ...benchmark,
    floor: safeNumber(benchmark.floor) * safeModifier,
    average: safeNumber(benchmark.average) * safeModifier,
    strong: safeNumber(benchmark.strong) * safeModifier,
    elite: safeNumber(benchmark.elite) * safeModifier
  };
}

function interpolateCompassScore(value, startValue, endValue, startScore, endScore) {
  const range = endValue - startValue;
  if (!range) return startScore;
  const progress = Math.max(0, Math.min(1, (value - startValue) / range));
  return startScore + ((endScore - startScore) * progress);
}

function scoreMetricAgainstBenchmark(value, benchmark = {}, options = {}) {
  const { fallback = 50 } = options;
  const safeValue = safeNumber(value, NaN);
  if (!Number.isFinite(safeValue) || safeValue <= 0) return fallback;

  const floor = safeNumber(benchmark.floor);
  const average = safeNumber(benchmark.average);
  const strong = safeNumber(benchmark.strong);
  const elite = safeNumber(benchmark.elite);
  const inverse = Boolean(benchmark.inverse);

  if (inverse) {
    if (safeValue >= floor) return clampScore(interpolateCompassScore(safeValue, floor, floor * 1.35, 35, 12));
    if (safeValue >= average) return clampScore(interpolateCompassScore(safeValue, average, floor, 55, 35));
    if (safeValue >= strong) return clampScore(interpolateCompassScore(safeValue, strong, average, 78, 55));
    if (safeValue >= elite) return clampScore(interpolateCompassScore(safeValue, elite, strong, 94, 78));
    return clampScore(94 + Math.min(6, (elite - safeValue) * 2));
  }

  if (safeValue <= floor) return clampScore(interpolateCompassScore(safeValue, floor * 0.65, floor, 12, 35));
  if (safeValue <= average) return clampScore(interpolateCompassScore(safeValue, floor, average, 35, 55));
  if (safeValue <= strong) return clampScore(interpolateCompassScore(safeValue, average, strong, 55, 78));
  if (safeValue <= elite) return clampScore(interpolateCompassScore(safeValue, strong, elite, 78, 94));
  return clampScore(94 + Math.min(6, ((safeValue - elite) / Math.max(1, elite * 0.12)) * 6));
}

function blendCompassScores(primary, secondary, primaryWeight = 0.78) {
  const safePrimary = safeNumber(primary);
  const safeSecondary = safeNumber(secondary);
  const weight = Math.max(0, Math.min(1, safeNumber(primaryWeight, 0.78)));
  return clampScore((safePrimary * weight) + (safeSecondary * (1 - weight)));
}

function combineWeightedCompassScores(parts = []) {
  let total = 0;
  let totalWeight = 0;

  parts.forEach(part => {
    const score = Array.isArray(part) ? part[0] : part?.score;
    const weight = Array.isArray(part) ? part[1] : part?.weight;
    const safeScore = Number(score);
    const safeWeight = Number(weight);
    if (!Number.isFinite(safeScore) || !Number.isFinite(safeWeight) || safeWeight <= 0) return;
    total += safeScore * safeWeight;
    totalWeight += safeWeight;
  });

  return totalWeight ? clampScore(total / totalWeight) : 0;
}

function summarizeContextMatches(matchEntries = []) {
  const matchesPlayed = matchEntries.length;
  const kills = matchEntries.reduce((sum, match) => sum + safeNumber(getMatchCore(match).kills), 0);
  const deaths = matchEntries.reduce((sum, match) => sum + safeNumber(getMatchCore(match).deaths), 0);
  const assists = matchEntries.reduce((sum, match) => sum + safeNumber(getMatchCore(match).assists), 0);
  const acs = averageValue(matchEntries.map(match => safeNumber(getMatchCore(match).acs)));
  const hs = averageValue(matchEntries.map(match => safeNumber(getMatchCore(match).hs)));
  const wins = matchEntries.filter(match => getMatchCore(match).result === "win").length;
  const losses = matchEntries.filter(match => getMatchCore(match).result === "loss").length;

  return {
    matchesPlayed,
    kills,
    deaths,
    assists,
    kd: deaths ? kills / deaths : kills,
    assistsPerMatch: safeDivide(assists, matchesPlayed),
    deathsPerMatch: safeDivide(deaths, matchesPlayed),
    acs,
    hs,
    winrate: safeDivide(wins * 100, matchesPlayed),
    wins,
    losses
  };
}

function buildBenchmarkMetricScores(matchSummary = {}, roleName = "Unknown", importedAnalytics = null) {
  const roleKey = getCompassRoleKey(roleName);
  const modifiers = COMPASS_ROLE_EXPECTATION_MODIFIERS[roleKey] || COMPASS_ROLE_EXPECTATION_MODIFIERS.unknown;
  const importedOverview = importedAnalytics?.overview || {};
  const percentiles = importedOverview?.percentiles || {};
  const avgKast = averageValue([
    safeNumber(importedOverview.attackKAST),
    safeNumber(importedOverview.defenseKAST),
    safeNumber(importedOverview.kast)
  ].filter(value => value > 0));
  const econValue = safeNumber(importedOverview.econ) > 100
    ? safeNumber(importedOverview.econ) / 25
    : safeNumber(importedOverview.econ);
  const acsValue = safeNumber(matchSummary.acs) || safeNumber(importedOverview.scorePerRound) || safeNumber(importedOverview.acs);
  const kdValue = safeNumber(matchSummary.kd) || safeNumber(importedOverview.kd);
  const assistsValue = safeNumber(matchSummary.assistsPerMatch) || safeNumber(importedOverview.assistsPerMatch);
  const deathsValue = safeNumber(matchSummary.deathsPerMatch) || safeNumber(importedOverview.deathsPerMatch);
  const hsValue = safeNumber(matchSummary.hs) || safeNumber(importedOverview.hs);
  const winrateValue = safeNumber(matchSummary.winrate) || safeNumber(importedOverview.winrate);
  const benchmarkScores = {
    acs: scoreMetricAgainstBenchmark(
      acsValue,
      adjustCompassBenchmark(COMPASS_STAT_BENCHMARKS.acs, modifiers.acs)
    ),
    kd: scoreMetricAgainstBenchmark(
      kdValue,
      adjustCompassBenchmark(COMPASS_STAT_BENCHMARKS.kd, modifiers.kd)
    ),
    assists: scoreMetricAgainstBenchmark(
      assistsValue,
      adjustCompassBenchmark(COMPASS_STAT_BENCHMARKS.assists, modifiers.assists)
    ),
    deaths: scoreMetricAgainstBenchmark(
      deathsValue,
      adjustCompassBenchmark(COMPASS_STAT_BENCHMARKS.deaths, modifiers.deaths)
    ),
    hs: scoreMetricAgainstBenchmark(
      hsValue,
      adjustCompassBenchmark(COMPASS_STAT_BENCHMARKS.hs, modifiers.hs)
    ),
    winrate: scoreMetricAgainstBenchmark(winrateValue, COMPASS_STAT_BENCHMARKS.winrate),
    kast: avgKast ? scoreMetricAgainstBenchmark(avgKast, COMPASS_STAT_BENCHMARKS.kast) : 50,
    econ: econValue ? scoreMetricAgainstBenchmark(econValue, COMPASS_STAT_BENCHMARKS.econ) : 50
  };

  return Object.fromEntries(Object.entries(benchmarkScores).map(([key, score]) => {
    const percentile = safeNumber(percentiles?.[key], 0);
    return [key, percentile ? blendCompassScores(percentile, score, 0.35) : score];
  }));
}

function buildRoleAdjustedMetricScores(matchSummary = {}, baselineSummary = {}, roleName = "Unknown", importedAnalytics = null) {
  const roleModifiers = {
    duelist: { acs: 1.15, kd: 1.15, assists: 0.82, deaths: 0.92, hs: 1.08 },
    initiator: { acs: 0.98, kd: 0.94, assists: 1.18, deaths: 1.02, hs: 0.96 },
    controller: { acs: 0.92, kd: 0.90, assists: 1.24, deaths: 1.04, hs: 0.94 },
    sentinel: { acs: 0.94, kd: 1.02, assists: 1.04, deaths: 1.08, hs: 0.98 },
    unknown: { acs: 1, kd: 1, assists: 1, deaths: 1, hs: 1 }
  };
  const modifiers = roleModifiers[String(roleName || "unknown").toLowerCase()] || roleModifiers.unknown;
  const importedOverview = importedAnalytics?.overview || {};

  return {
    acs: normalizeMetricAgainstBaseline(safeNumber(matchSummary.acs) * modifiers.acs, safeNumber(baselineSummary.acs), Math.max(8, safeNumber(baselineSummary.acs) * 0.16), { center: 52, scale: 16 }),
    kd: normalizeMetricAgainstBaseline(safeNumber(matchSummary.kd) * modifiers.kd, safeNumber(baselineSummary.kd), Math.max(0.12, safeNumber(baselineSummary.kd) * 0.2), { center: 52, scale: 18 }),
    assists: normalizeMetricAgainstBaseline(safeNumber(matchSummary.assistsPerMatch) * modifiers.assists, safeNumber(baselineSummary.assistsPerMatch), 1.5, { center: 48, scale: 16 }),
    deaths: normalizeMetricAgainstBaseline(safeNumber(matchSummary.deathsPerMatch) / Math.max(0.72, modifiers.deaths), safeNumber(baselineSummary.deathsPerMatch), 1.8, { center: 52, scale: 15, inverse: true }),
    hs: normalizeMetricAgainstBaseline(safeNumber(matchSummary.hs) * modifiers.hs, safeNumber(baselineSummary.hs), 6, { center: 48, scale: 14 }),
    winrate: normalizeMetricAgainstBaseline(safeNumber(matchSummary.winrate), safeNumber(baselineSummary.winrate, 50), 12, { center: 50, scale: 14 }),
    kast: safeNumber(importedOverview.attackKAST) || safeNumber(importedOverview.defenseKAST) ? clampScore(averageValue([importedOverview.attackKAST, importedOverview.defenseKAST])) : 50,
    econ: safeNumber(importedOverview.econ) ? clampScore(importedOverview.econ) : 50
  };
}

function buildCompassMetricScores(matchSummary = {}, baselineSummary = {}, roleName = "Unknown", importedAnalytics = null) {
  const benchmarkScores = buildBenchmarkMetricScores(matchSummary, roleName, importedAnalytics);
  const relativeScores = buildRoleAdjustedMetricScores(matchSummary, baselineSummary, roleName, importedAnalytics);

  return Object.fromEntries(Object.keys(benchmarkScores).map(key => [
    key,
    blendCompassScores(benchmarkScores[key], relativeScores[key], 0.82)
  ]));
}

function summarizeAdvancedContextMatches(matchEntries = []) {
  const matchesPlayed = matchEntries.length;
  const roundEntries = matchEntries.flatMap(match => match?.advanced?.rounds || []);
  const attackBlocks = matchEntries.map(match => match?.advanced?.attack || {}).filter(Boolean);
  const defenseBlocks = matchEntries.map(match => match?.advanced?.defense || {}).filter(Boolean);
  const totalAttackRounds = attackBlocks.reduce((sum, block) => sum + safeNumber(block?.roundsPlayed), 0);
  const totalDefenseRounds = defenseBlocks.reduce((sum, block) => sum + safeNumber(block?.roundsPlayed), 0);
  const totalRounds = totalAttackRounds + totalDefenseRounds || roundEntries.length;
  const buyBuckets = {
    eco: { played: 0, won: 0 },
    light: { played: 0, won: 0 },
    full: { played: 0, won: 0 }
  };
  let utilityBeforeContactCount = 0;
  let utilityTimingKnownCount = 0;
  let firstBloodRounds = 0;
  let firstDeathRounds = 0;

  roundEntries.forEach(round => {
    const buyType = String(round?.buyType || "").toLowerCase();
    if (buyType.includes("eco")) buyBuckets.eco.played += 1;
    else if (buyType.includes("light")) buyBuckets.light.played += 1;
    else if (buyType.includes("full")) buyBuckets.full.played += 1;

    if (round?.roundWon) {
      if (buyType.includes("eco")) buyBuckets.eco.won += 1;
      else if (buyType.includes("light")) buyBuckets.light.won += 1;
      else if (buyType.includes("full")) buyBuckets.full.won += 1;
    }

    const utilityPattern = String(round?.utilityPattern || "").toLowerCase();
    if (utilityPattern && !utilityPattern.includes("unavailable") && !utilityPattern.includes("no-utility")) {
      utilityTimingKnownCount += 1;
    }
    if (utilityPattern.includes("before contact")) {
      utilityBeforeContactCount += 1;
    }
    if (round?.firstEvent === "first-blood") firstBloodRounds += 1;
    if (round?.firstEvent === "first-death") firstDeathRounds += 1;
  });

  const attackWins = attackBlocks.reduce((sum, block) => sum + safeNumber(block?.roundsWon), 0);
  const defenseWins = defenseBlocks.reduce((sum, block) => sum + safeNumber(block?.roundsWon), 0);
  const attackFirstBloods = attackBlocks.reduce((sum, block) => sum + safeNumber(block?.firstBloods), 0);
  const defenseFirstBloods = defenseBlocks.reduce((sum, block) => sum + safeNumber(block?.firstBloods), 0);
  const attackFirstDeaths = attackBlocks.reduce((sum, block) => sum + safeNumber(block?.firstDeaths), 0);
  const defenseFirstDeaths = defenseBlocks.reduce((sum, block) => sum + safeNumber(block?.firstDeaths), 0);

  return {
    matchesPlayed,
    rrPerMatch: averageValue(matchEntries.map(match => safeNumber(match?.rr))),
    attackWinPct: safeDivide(attackWins * 100, totalAttackRounds),
    defenseWinPct: safeDivide(defenseWins * 100, totalDefenseRounds),
    attackFirstBloodRate: safeDivide(attackFirstBloods * 100, totalAttackRounds),
    defenseFirstBloodRate: safeDivide(defenseFirstBloods * 100, totalDefenseRounds),
    attackOpeningSurvival: 100 - safeDivide(attackFirstDeaths * 100, totalAttackRounds),
    defenseOpeningSurvival: 100 - safeDivide(defenseFirstDeaths * 100, totalDefenseRounds),
    attackKAST: weightedAverage(attackBlocks, "kast", "roundsPlayed"),
    defenseKAST: weightedAverage(defenseBlocks, "kast", "roundsPlayed"),
    attackADR: weightedAverage(attackBlocks, "damagePerRound", "roundsPlayed"),
    defenseADR: weightedAverage(defenseBlocks, "damagePerRound", "roundsPlayed"),
    fullBuyWinRate: safeDivide(buyBuckets.full.won * 100, buyBuckets.full.played),
    ecoWinRate: safeDivide(buyBuckets.eco.won * 100, buyBuckets.eco.played),
    lightBuyWinRate: safeDivide(buyBuckets.light.won * 100, buyBuckets.light.played),
    utilityBeforeContactRate: utilityTimingKnownCount
      ? safeDivide(utilityBeforeContactCount * 100, utilityTimingKnownCount)
      : null,
    utilityTimingKnownRounds: utilityTimingKnownCount,
    firstBloodRoundRate: safeDivide(firstBloodRounds * 100, roundEntries.length),
    firstDeathAvoidRate: 100 - safeDivide(firstDeathRounds * 100, roundEntries.length),
    roundWinRate: safeDivide((attackWins + defenseWins) * 100, totalRounds)
  };
}

function summarizeLogContext(logList = []) {
  const entries = (logList || []).slice();
  const positiveMoodRate = safeDivide(
    entries.filter(entry => ["focused", "fun", "calm"].includes(String(entry?.mood || "").toLowerCase())).length * 100,
    entries.length
  );
  const calmMoodRate = safeDivide(
    entries.filter(entry => ["focused", "calm"].includes(String(entry?.mood || "").toLowerCase())).length * 100,
    entries.length
  );
  const commsEnabledRate = safeDivide(
    entries.filter(entry => !entry?.commsDisabled).length * 100,
    entries.length
  );
  const lowDistractionRate = safeDivide(
    entries.filter(entry => !entry?.musicOn).length * 100,
    entries.length
  );

  return {
    entries: entries.length,
    avgRating: averageValue(entries.map(entry => safeNumber(entry?.rating))),
    positiveMoodRate,
    calmMoodRate,
    commsEnabledRate,
    lowDistractionRate,
    rolePlanScore: averageValue(entries.map(entry => safeNumber(entry?.rolePlanScore))),
    utilityTimingScore: averageValue(entries.map(entry => safeNumber(entry?.utilityTimingScore))),
    entryTimingScore: averageValue(entries.map(entry => safeNumber(entry?.entryTimingScore))),
    spacingScore: averageValue(entries.map(entry => safeNumber(entry?.spacingScore)))
  };
}

