function clampMetric(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function formatPercent(value, digits = 1) {
  const n = Number(value);
  if (!Number.isFinite(n)) return "--";
  return `${n.toFixed(digits).replace(/\.0$/, "")}%`;
}

function averageValue(values = []) {
  const clean = values.map(Number).filter(Number.isFinite);
  if (!clean.length) return 0;
  return clean.reduce((sum, value) => sum + value, 0) / clean.length;
}

function weightedAverage(items = [], valueKey, weightKey) {
  const totalWeight = items.reduce((sum, item) => sum + safeNumber(item?.[weightKey]), 0);
  if (!totalWeight) return 0;
  return items.reduce((sum, item) => {
    return sum + (safeNumber(item?.[valueKey]) * safeNumber(item?.[weightKey]));
  }, 0) / totalWeight;
}

const UTILITY_DAMAGE_ROLE_EXPECTATION = {
  raze: 16,
  brimstone: 12,
  sova: 10,
  gekko: 8,
  killjoy: 8,
  harbor: 7,
  kayo: 6,
  phoenix: 6,
  breach: 5,
  viper: 5
};

function getUtilityDamageExpectation(agentName = "") {
  return safeNumber(UTILITY_DAMAGE_ROLE_EXPECTATION[String(agentName || "").toLowerCase()]);
}

function statItem(label, stat, formula) {
  return {
    label: normalizeRankedCoachCopy(label),
    stat: normalizeRankedCoachCopy(stat),
    formula: normalizeRankedCoachCopy(formula)
  };
}

function getMostCommonValue(values = [], fallback = "--") {
  const counts = new Map();
  values
    .map(value => String(value || "").trim())
    .filter(Boolean)
    .forEach(value => counts.set(value, (counts.get(value) || 0) + 1));

  let winner = fallback;
  let bestCount = 0;
  counts.forEach((count, value) => {
    if (count > bestCount) {
      bestCount = count;
      winner = value;
    }
  });
  return winner;
}

function formatReadableLabel(value = "") {
  return String(value || "")
    .trim()
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .replace(/\b\w/g, char => char.toUpperCase());
}

function isInsufficientDataReadCard(card = {}) {
  const value = String(card?.value ?? "").trim();
  const detail = String(card?.detail ?? "").trim();
  const joined = `${value} ${detail}`.toLowerCase();
  return !value
    || /^--$/.test(value)
    || /\b(no data|build sample|no stable|waiting|pending|not enough data)\b/i.test(joined);
}

function getBehaviorRoleContext(model = getPlayerModel()) {
  const negativeLogs = (logEntries || []).filter(entry => {
    const mood = String(entry?.mood || entry?.tilt || "").toLowerCase();
    const rating = Number(entry?.rating ?? entry?.selfRating ?? entry?.self_rating);
    return ["tilted", "annoyed", "frustrated", "angry", "stressed"].some(token => mood.includes(token))
      || (Number.isFinite(rating) && rating > 0 && rating <= 2);
  });

  const roleFromLogs = getMostCommonValue(negativeLogs.map(entry => (
    entry?.role
    || agentRoles?.[entry?.agent]
    || entry?.agentRole
    || ""
  )), "");

  const fallbackRole = model?.scoring?.activeRoleName
    || model?.roles?.[0]?.role
    || getMostCommonValue((matches || []).map(match => getMatchCore(match).role), "");
  return formatReadableLabel(roleFromLogs || fallbackRole || "Current role");
}

function buildDataReadDetailTabs(card = {}, analytics = getPlayerModel()) {
  const label = normalizeRankedCoachCopy(card?.label || "Data Read");
  const value = normalizeRankedCoachCopy(card?.value || "No Data");
  const detail = normalizeRankedCoachCopy(card?.detail || card?.tooltip || "RankedCoach needs more match and log context before this read becomes specific.");
  const toneMeta = getSignalToneMeta(card?.tone || (String(value).toLowerCase().includes("no data") ? "down" : "warn"));
  const behaviorRole = /^behavior development$/i.test(String(card?.label || ""))
    ? getBehaviorRoleContext(analytics)
    : "";
  const sourceLabel = analytics?.overview?.matchesPlayed
    ? `${Math.round(safeNumber(analytics?.overview?.matchesPlayed))} imported matches${logEntries?.length ? ` and ${logCountLabel(logEntries.length)}` : ""}`
    : logEntries?.length
      ? logCountLabel(logEntries.length)
      : "No player data yet";

  const readItems = [
    behaviorRole ? statItem("Role Context", behaviorRole, "This is the role most tied to low-rated or frustrated saved logs in the current profile.") : null,
    statItem("Read", label, "Selected match pattern card."),
    statItem("Current Value", value, "Current value shown on this card."),
    statItem("What It Means", detail, "Plain-language explanation generated from the current profile context."),
    statItem("Signal", toneMeta.label, "Signal tone is based on whether the read is a strength, watch item, or needs-work item.")
  ].filter(Boolean);

  return [
    {
      key: "read",
      label: "Read",
      items: readItems
    },
    {
      key: "context",
      label: "Context",
      items: [
        statItem("Data Source", sourceLabel, "This combines imported matches, saved logs, and the active profile."),
        statItem("Data Confidence", analytics?.confidenceLabel || "Low Confidence", "Shows how much data supports this read."),
        statItem("Priority", analytics?.priorityLabel || "Watch", "Priority describes how soon this read should affect the next review block.")
      ]
    },
    {
      key: "formula",
      label: "Formula",
      items: [
        statItem("Why This Shows Up", Number.isFinite(Number(card?.selectionScore)) ? `${Math.round(Number(card.selectionScore))}/100` : "Not enough info yet", "RankedCoach looks at severity, sample size, and whether the read is useful right now."),
        statItem("Tooltip", card?.tooltip || detail, "Tooltip/detail text used for this selected read.")
      ]
    }
  ];
}

function getAgentMapInsights(agentName, analytics) {
  return (analytics?.maps || [])
    .filter(item => String(item.agent || "").toLowerCase() === String(agentName || "").toLowerCase())
    .sort((a, b) => {
      const wrA = safeNumber(a.matchesWon) / Math.max(1, safeNumber(a.matchesPlayed));
      const wrB = safeNumber(b.matchesWon) / Math.max(1, safeNumber(b.matchesPlayed));
      return wrB - wrA;
    });
}

function getEntityRounds({ agentName = "", roleName = "", side = "", matchEntries = matches } = {}) {
  return (matchEntries || []).flatMap(match => {
    const core = getMatchCore(match);
    const agentMatch = !agentName || String(core.agent || "").toLowerCase() === String(agentName || "").toLowerCase();
    const roleMatch = !roleName || String(core.role || agentRoles?.[core.agent] || "").toLowerCase() === String(roleName || "").toLowerCase();
    if (!agentMatch || !roleMatch) return [];

    return (match?.advanced?.rounds || []).filter(round =>
      !side || String(round?.side || "").toLowerCase() === String(side || "").toLowerCase()
    );
  });
}

function getSideMetricsFromMaps(mapEntries = [], side = "attack") {
  const roundsKey = side === "attack" ? "attackRoundsPlayed" : "defenseRoundsPlayed";
  const roundsWonKey = side === "attack" ? "attackRoundsWon" : "defenseRoundsWon";
  const firstBloodsKey = side === "attack" ? "attackFirstBloods" : "defenseFirstBloods";
  const firstDeathsKey = side === "attack" ? "attackFirstDeaths" : "defenseFirstDeaths";
  const tradedKey = side === "attack" ? "attackTraded" : "defenseTraded";
  const survivedKey = side === "attack" ? "attackSurvived" : "defenseSurvived";
  const adrKey = side === "attack" ? "attackDamagePerRound" : "defenseDamagePerRound";
  const kastKey = side === "attack" ? "attackKAST" : "defenseKAST";
  const killsKey = side === "attack" ? "attackKills" : "defenseKills";

  const roundsPlayed = mapEntries.reduce((sum, item) => sum + safeNumber(item?.[roundsKey]), 0);
  const roundsWon = mapEntries.reduce((sum, item) => sum + safeNumber(item?.[roundsWonKey]), 0);

  return {
    roundsPlayed,
    roundsWon,
    winPct: roundsPlayed ? (roundsWon / roundsPlayed) * 100 : 0,
    firstBloods: mapEntries.reduce((sum, item) => sum + safeNumber(item?.[firstBloodsKey]), 0),
    firstDeaths: mapEntries.reduce((sum, item) => sum + safeNumber(item?.[firstDeathsKey]), 0),
    traded: mapEntries.reduce((sum, item) => sum + safeNumber(item?.[tradedKey]), 0),
    survived: mapEntries.reduce((sum, item) => sum + safeNumber(item?.[survivedKey]), 0),
    kills: mapEntries.reduce((sum, item) => sum + safeNumber(item?.[killsKey]), 0),
    damagePerRound: weightedAverage(mapEntries, adrKey, roundsKey),
    kast: weightedAverage(mapEntries, kastKey, roundsKey)
  };
}

function getWeaponRoundRates(rounds = []) {
  const buckets = new Map();
  rounds.forEach(round => {
    const key = String(round?.weapon || "").trim();
    if (!key) return;
    const current = buckets.get(key) || { weapon: key, rounds: 0, wins: 0 };
    current.rounds += 1;
    current.wins += round?.roundWon ? 1 : 0;
    buckets.set(key, current);
  });

  return [...buckets.values()]
    .map(entry => ({
      ...entry,
      conversionPct: safeDivide(entry.wins, entry.rounds) * 100
    }))
    .sort((a, b) => b.conversionPct - a.conversionPct || b.rounds - a.rounds);
}

const MAP_ECONOMY_ROUND_FORMULAS = {
  pistolWin: "Pistol Round Win % = pistol round wins on rounds 1 and 13 / pistol rounds played on rounds 1 and 13 x 100.",
  bonusWin: "Bonus Round Win % = wins on confirmed bonus rounds / confirmed bonus rounds played x 100. Round 2/14 is bonus after a pistol win, and round 3/15 is bonus when the pistol winner also wins the buy-up round.",
  bonusLoss: "Bonus Round Loss % = losses on confirmed bonus rounds / confirmed bonus rounds played x 100. Round 2/14 is bonus after a pistol win, and round 3/15 is bonus when the pistol winner also wins the buy-up round.",
  saveWin: "Save Round Win % = wins on confirmed save rounds / confirmed save rounds played x 100. Round 2/14 is normally a save after losing pistol unless economy data says otherwise.",
  fullBuyWin: "Full Buy Round Win % = wins on confirmed full-buy rounds / confirmed full-buy rounds played x 100. Round 3/15 after a pistol-loss save is a full buy, and later full buys depend on economy/loadout data.",
  fullBuyLoss: "Full Buy Round Loss % = losses on confirmed full-buy rounds / confirmed full-buy rounds played x 100. Half buys around rifle plus light armor are not counted as full buys."
};

function getMatchMapName(match = {}) {
  return String(match?.metadata?.mapName || match?.map || getMatchCore(match).map || "").trim();
}

function getMatchRoundEntries(match = {}) {
  const candidates = [
    match?.advanced?.rounds,
    match?.rounds,
    match?.roundResults,
    match?.matchInfo?.roundResults
  ];
  const rounds = candidates.find(Array.isArray);
  return rounds || [];
}

function getRawRoundNumber(round = {}, fallbackIndex = 0) {
  const raw = round?.round ?? round?.roundNumber ?? round?.roundNum ?? round?.roundIndex ?? round?.number;
  const numeric = Number(raw);
  return Number.isFinite(numeric) ? numeric : fallbackIndex + 1;
}

function getNormalizedRoundNumber(round = {}, fallbackIndex = 0, zeroBased = false) {
  const raw = getRawRoundNumber(round, fallbackIndex);
  return zeroBased ? raw + 1 : raw;
}

function getRoundEconomyLabel(round = {}) {
  const values = [
    round?.buyType,
    round?.economy,
    round?.buy_type,
    round?.loadoutType,
    round?.loadout,
    round?.teamEconomy,
    round?.roundEconomy
  ];
  return String(values.find(value => String(value || "").trim()) || "").trim().toLowerCase();
}

function getRoundSpendValue(round = {}) {
  const values = [
    round?.creditsSpent,
    round?.creditSpend,
    round?.spent,
    round?.spend,
    round?.loadoutValue,
    round?.loadoutCost,
    round?.buyValue,
    round?.equipmentValue,
    round?.teamLoadoutValue,
    round?.roundLoadoutValue
  ];
  const numeric = values.map(value => Number(value)).find(value => Number.isFinite(value) && value > 0);
  return Number.isFinite(numeric) ? numeric : 0;
}

function getRoundWonValue(round = {}) {
  if (typeof round?.roundWon === "boolean") return round.roundWon;
  if (typeof round?.won === "boolean") return round.won;
  if (typeof round?.isWin === "boolean") return round.isWin;
  const result = String(round?.result || round?.outcome || round?.roundResult || "").toLowerCase();
  if (["win", "won", "victory", "true"].includes(result)) return true;
  if (["loss", "lost", "defeat", "false"].includes(result)) return false;
  return null;
}

function classifyPostPistolEconomy(round = {}, previousPistolWon = null) {
  const economy = getRoundEconomyLabel(round);
  if (economy.includes("bonus")) return "bonus";
  if (economy.includes("save") || economy.includes("eco")) return "save";
  if (previousPistolWon === true) return "bonus";
  if (previousPistolWon === false) return "save";
  if (economy.includes("light") || economy.includes("half")) return "save";
  return "";
}

function classifyLabeledEconomyPhase(round = {}) {
  const economy = getRoundEconomyLabel(round);
  if (economy.includes("bonus")) return "bonus";
  if (economy.includes("save") || economy.includes("eco")) return "save";
  if (economy.includes("light") || economy.includes("half")) return "half-buy";
  return "";
}

function classifyFullBuyEconomy(round = {}, allowInferredFullBuy = false) {
  const economy = getRoundEconomyLabel(round);
  if (economy.includes("save") || economy.includes("eco") || economy.includes("bonus") || economy.includes("light") || economy.includes("half") || economy.includes("force")) return "";
  const spend = getRoundSpendValue(round);
  if (spend >= 3300 && spend < 3900) return "";
  if (spend >= 3900) return "full-buy";
  if (!economy) return allowInferredFullBuy ? "full-buy" : "";
  if (economy.includes("full") || economy.includes("rifle") || economy.includes("buy")) return "full-buy";
  return "";
}

function classifyThirdRoundEconomy(round = {}, previousPistolWon = null, secondRoundWon = null) {
  const labeledPhase = classifyLabeledEconomyPhase(round);
  if (labeledPhase === "bonus" || labeledPhase === "save") return labeledPhase;
  if (previousPistolWon === true && secondRoundWon === true) return "bonus";
  if (classifyFullBuyEconomy(round, true) === "full-buy") return "full-buy";
  return "";
}

function createEconomyPhaseBucket(label) {
  return { label, total: 0, wins: 0, losses: 0 };
}

function addEconomyPhaseResult(bucket, won) {
  if (!bucket || won === null) return;
  bucket.total += 1;
  if (won) bucket.wins += 1;
  else bucket.losses += 1;
}

function getEconomyPhaseRate(bucket = {}, field = "wins") {
  return safeNumber(bucket.total) ? safeDivide(safeNumber(bucket[field]) * 100, safeNumber(bucket.total)) : null;
}

function formatEconomyPhaseRate(bucket = {}, field = "wins") {
  const value = getEconomyPhaseRate(bucket, field);
  return value === null ? "No Data" : formatPercent(value);
}

function formatEconomyPhaseFormula(bucket = {}, field = "wins", baseFormula = "") {
  const count = safeNumber(bucket[field]);
  const total = safeNumber(bucket.total);
  if (!total) {
    return `No confirmed ${String(bucket.label || "economy").toLowerCase()} rounds yet. ${baseFormula}`;
  }
  const resultLabel = field === "losses" ? "losses" : "wins";
  return `${resultLabel} / ${String(bucket.label || "economy").toLowerCase()} rounds = ${count} / ${total}. ${baseFormula}`;
}

function getMapEconomyRoundSummary(mapName = "", matchList = matches) {
  const target = String(mapName || "").trim().toLowerCase();
  const summary = {
    pistol: createEconomyPhaseBucket("Pistol"),
    bonus: createEconomyPhaseBucket("Bonus"),
    save: createEconomyPhaseBucket("Save"),
    fullBuy: createEconomyPhaseBucket("Full Buy"),
    confirmedRounds: 0,
    matchingMatches: 0
  };

  (matchList || []).forEach((match) => {
    if (String(getMatchMapName(match)).toLowerCase() !== target) return;
    summary.matchingMatches += 1;

    const rounds = getMatchRoundEntries(match);
    if (!rounds.length) return;

    const zeroBased = rounds.some((round, index) => getRawRoundNumber(round, index) === 0);
    const roundsByNumber = new Map();
    rounds.forEach((round, index) => {
      const roundNumber = getNormalizedRoundNumber(round, index, zeroBased);
      roundsByNumber.set(roundNumber, round);
    });

    rounds.forEach((round, index) => {
      const roundNumber = getNormalizedRoundNumber(round, index, zeroBased);
      const won = getRoundWonValue(round);
      if (won === null) return;

      if (roundNumber === 1 || roundNumber === 13) {
        addEconomyPhaseResult(summary.pistol, won);
        summary.confirmedRounds += 1;
        return;
      }

      if (roundNumber === 2 || roundNumber === 14) {
        const previousPistolRound = roundsByNumber.get(roundNumber === 2 ? 1 : 13);
        const previousPistolWon = previousPistolRound ? getRoundWonValue(previousPistolRound) : null;
        const phase = classifyPostPistolEconomy(round, previousPistolWon);
        if (phase === "bonus") {
          addEconomyPhaseResult(summary.bonus, won);
          summary.confirmedRounds += 1;
        } else if (phase === "save") {
          addEconomyPhaseResult(summary.save, won);
          summary.confirmedRounds += 1;
        }
        return;
      }

      if (roundNumber === 3 || roundNumber === 15) {
        const previousPistolRound = roundsByNumber.get(roundNumber === 3 ? 1 : 13);
        const previousSecondRound = roundsByNumber.get(roundNumber === 3 ? 2 : 14);
        const previousPistolWon = previousPistolRound ? getRoundWonValue(previousPistolRound) : null;
        const secondRoundWon = previousSecondRound ? getRoundWonValue(previousSecondRound) : null;
        const phase = classifyThirdRoundEconomy(round, previousPistolWon, secondRoundWon);
        if (phase === "bonus") {
          addEconomyPhaseResult(summary.bonus, won);
          summary.confirmedRounds += 1;
        } else if (phase === "save") {
          addEconomyPhaseResult(summary.save, won);
          summary.confirmedRounds += 1;
        } else if (phase === "full-buy") {
          addEconomyPhaseResult(summary.fullBuy, won);
          summary.confirmedRounds += 1;
        }
        return;
      }

      const labeledPhase = classifyLabeledEconomyPhase(round);
      if (labeledPhase === "bonus") {
        addEconomyPhaseResult(summary.bonus, won);
        summary.confirmedRounds += 1;
      } else if (labeledPhase === "save") {
        addEconomyPhaseResult(summary.save, won);
        summary.confirmedRounds += 1;
      } else if (classifyFullBuyEconomy(round) === "full-buy") {
        addEconomyPhaseResult(summary.fullBuy, won);
        summary.confirmedRounds += 1;
      }
    });
  });

  return summary;
}

function getMapEconomyStatItems(mapName = "", matchList = getScopedStatsData().matches) {
  const summary = getMapEconomyRoundSummary(mapName, matchList);
  return [
    statItem(
      "Pistol Round Win %",
      formatEconomyPhaseRate(summary.pistol, "wins"),
      formatEconomyPhaseFormula(summary.pistol, "wins", MAP_ECONOMY_ROUND_FORMULAS.pistolWin)
    ),
    statItem(
      "Bonus Round Win %",
      formatEconomyPhaseRate(summary.bonus, "wins"),
      formatEconomyPhaseFormula(summary.bonus, "wins", MAP_ECONOMY_ROUND_FORMULAS.bonusWin)
    ),
    statItem(
      "Bonus Round Loss %",
      formatEconomyPhaseRate(summary.bonus, "losses"),
      formatEconomyPhaseFormula(summary.bonus, "losses", MAP_ECONOMY_ROUND_FORMULAS.bonusLoss)
    ),
    statItem(
      "Save Round Win %",
      formatEconomyPhaseRate(summary.save, "wins"),
      formatEconomyPhaseFormula(summary.save, "wins", MAP_ECONOMY_ROUND_FORMULAS.saveWin)
    ),
    statItem(
      "Full Buy Round Win %",
      formatEconomyPhaseRate(summary.fullBuy, "wins"),
      formatEconomyPhaseFormula(summary.fullBuy, "wins", MAP_ECONOMY_ROUND_FORMULAS.fullBuyWin)
    ),
    statItem(
      "Full Buy Round Loss %",
      formatEconomyPhaseRate(summary.fullBuy, "losses"),
      formatEconomyPhaseFormula(summary.fullBuy, "losses", MAP_ECONOMY_ROUND_FORMULAS.fullBuyLoss)
    )
  ];
}

const STATS_WEAPON_FAMILIES = [
  { key: "rifle", typeKey: "rifle", label: "Rifle", weapons: ["Bulldog", "Guardian", "Phantom", "Vandal"] },
  { key: "pistol", typeKey: "pistol", label: "Pistol", weapons: ["Classic", "Shorty", "Frenzy", "Ghost", "Sheriff"] },
  { key: "shotgun", typeKey: "shotgun", label: "Shotgun", weapons: ["Bucky", "Judge"] },
  { key: "smg", typeKey: "smg", label: "SMG", weapons: ["Stinger", "Spectre"] },
  { key: "sniper", typeKey: "sniper", label: "Sniper", weapons: ["Marshal", "Outlaw", "Operator"] }
];

function normalizeStatsWeaponKey(value = "") {
  return String(value || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "-");
}

function getStatsWeaponMeta(value = "") {
  const key = normalizeStatsWeaponKey(value);
  if (!key) return null;

  for (const family of STATS_WEAPON_FAMILIES) {
    const weapon = family.weapons.find(name => normalizeStatsWeaponKey(name) === key);
    if (weapon) {
      return {
        key,
        name: weapon,
        familyKey: family.key,
        typeKey: family.typeKey,
        familyLabel: family.label,
        family
      };
    }
  }

  return null;
}

function getStatsWeaponAssetPath(value = "") {
  const meta = getStatsWeaponMeta(value);
  return meta ? `assets/weapons/${meta.key}.png` : "";
}

function getStatsWeaponOrderIndex(value = "") {
  const key = normalizeStatsWeaponKey(value);
  let offset = 0;
  for (const family of STATS_WEAPON_FAMILIES) {
    const index = family.weapons.findIndex(name => normalizeStatsWeaponKey(name) === key);
    if (index >= 0) return offset + index;
    offset += 100;
  }
  return 9999;
}

function getWeaponTypeMeta(weaponName = "") {
  const raw = String(weaponName || "").trim();
  const key = raw.toLowerCase();

  if (["classic", "shorty", "frenzy", "ghost", "sheriff"].includes(key)) {
    return { key: "pistol", label: "Pistol" };
  }
  if (["stinger", "spectre"].includes(key)) {
    return { key: "smg", label: "SMG" };
  }
  if (["bucky", "judge"].includes(key)) {
    return { key: "shotgun", label: "Shotgun" };
  }
  if (["bulldog", "guardian", "phantom", "vandal"].includes(key)) {
    return { key: "rifle", label: "Rifle" };
  }
  if (["marshal", "operator", "outlaw"].includes(key)) {
    return { key: "sniper", label: "Sniper" };
  }
  if (["ares", "odin"].includes(key)) {
    return { key: "machine-gun", label: "Machine Gun" };
  }

  return raw
    ? { key: "other", label: "Other" }
    : { key: "", label: "" };
}

function summarizeSpecificWeaponRounds(matchEntries = matches) {
  const buckets = new Map();

  (matchEntries || []).forEach((match) => {
    const rounds = Array.isArray(match?.advanced?.rounds) ? match.advanced.rounds : [];
    if (!rounds.length) return;

    const core = getMatchCore(match);
    const mapName = String(match?.metadata?.mapName || match?.map || "").trim();
    const localBuckets = new Map();

    rounds.forEach((round) => {
      const weaponMeta = getStatsWeaponMeta(round?.weapon);
      if (!weaponMeta) return;

      const current = localBuckets.get(weaponMeta.key) || {
        weaponKey: weaponMeta.key,
        weapon: weaponMeta.name,
        familyKey: weaponMeta.familyKey,
        typeKey: weaponMeta.typeKey,
        label: weaponMeta.familyLabel,
        rounds: 0,
        wins: 0,
        attackRounds: 0,
        attackWins: 0,
        defenseRounds: 0,
        defenseWins: 0,
        buyTypes: new Map(),
        maps: new Map(),
        roundEntries: []
      };

      current.rounds += 1;
      current.wins += round?.roundWon ? 1 : 0;
      if (String(round?.side || "").toLowerCase() === "attack") {
        current.attackRounds += 1;
        current.attackWins += round?.roundWon ? 1 : 0;
      } else if (String(round?.side || "").toLowerCase() === "defense") {
        current.defenseRounds += 1;
        current.defenseWins += round?.roundWon ? 1 : 0;
      }

      const buyType = String(round?.buyType || "").trim();
      if (buyType) current.buyTypes.set(buyType, (current.buyTypes.get(buyType) || 0) + 1);
      if (mapName) current.maps.set(mapName, (current.maps.get(mapName) || 0) + 1);
      current.roundEntries.push({ ...round, matchMap: mapName });
      localBuckets.set(weaponMeta.key, current);
    });

    const totalTaggedRounds = [...localBuckets.values()].reduce((sum, entry) => sum + entry.rounds, 0);
    if (!totalTaggedRounds) return;

    localBuckets.forEach((entry) => {
      const share = entry.rounds / totalTaggedRounds;
      const target = buckets.get(entry.weaponKey) || {
        weaponKey: entry.weaponKey,
        weapon: entry.weapon,
        familyKey: entry.familyKey,
        typeKey: entry.typeKey,
        label: entry.label,
        rounds: 0,
        wins: 0,
        attackRounds: 0,
        attackWins: 0,
        defenseRounds: 0,
        defenseWins: 0,
        matches: 0,
        kills: 0,
        deaths: 0,
        adrWeighted: 0,
        buyTypes: new Map(),
        maps: new Map(),
        roundEntries: []
      };

      target.rounds += entry.rounds;
      target.wins += entry.wins;
      target.attackRounds += entry.attackRounds;
      target.attackWins += entry.attackWins;
      target.defenseRounds += entry.defenseRounds;
      target.defenseWins += entry.defenseWins;
      target.matches += 1;
      target.kills += safeNumber(core.kills) * share;
      target.deaths += safeNumber(core.deaths) * share;
      target.adrWeighted += safeNumber(core.adr) * entry.rounds;
      entry.buyTypes.forEach((count, label) => {
        target.buyTypes.set(label, (target.buyTypes.get(label) || 0) + count);
      });
      entry.maps.forEach((count, label) => {
        target.maps.set(label, (target.maps.get(label) || 0) + count);
      });
      target.roundEntries.push(...entry.roundEntries);
      buckets.set(entry.weaponKey, target);
    });
  });

  return [...buckets.values()]
    .map((entry) => ({
      weaponKey: entry.weaponKey,
      weapon: entry.weapon,
      familyKey: entry.familyKey,
      typeKey: entry.typeKey,
      label: entry.label,
      rounds: entry.rounds,
      wins: entry.wins,
      matches: entry.matches,
      winrate: safeDivide(entry.wins * 100, entry.rounds),
      attackWinrate: safeDivide(entry.attackWins * 100, entry.attackRounds),
      defenseWinrate: safeDivide(entry.defenseWins * 100, entry.defenseRounds),
      attackRounds: entry.attackRounds,
      defenseRounds: entry.defenseRounds,
      kills: entry.kills,
      deaths: entry.deaths,
      adr: safeDivide(entry.adrWeighted, entry.rounds),
      killsPerRound: safeDivide(entry.kills, entry.rounds),
      deathsPerRound: safeDivide(entry.deaths, entry.rounds),
      buyTypes: [...entry.buyTypes.entries()].sort((a, b) => b[1] - a[1]),
      maps: [...entry.maps.entries()].sort((a, b) => b[1] - a[1]),
      roundEntries: entry.roundEntries
    }))
    .sort((a, b) => getStatsWeaponOrderIndex(a.weapon) - getStatsWeaponOrderIndex(b.weapon));
}

function getSpecificWeaponSummary(value = "", matchEntries = matches) {
  const key = normalizeStatsWeaponKey(value);
  if (!key) return null;
  return summarizeSpecificWeaponRounds(matchEntries).find(entry => entry.weaponKey === key) || null;
}

function getWeaponFamilySummary(family, summaryMap = new Map()) {
  const entries = (family?.weapons || [])
    .map(name => summaryMap.get(normalizeStatsWeaponKey(name)))
    .filter(Boolean);
  const rounds = entries.reduce((sum, entry) => sum + safeNumber(entry.rounds), 0);
  const wins = entries.reduce((sum, entry) => sum + safeNumber(entry.wins), 0);

  return {
    rounds,
    wins,
    winrate: safeDivide(wins * 100, rounds),
    kills: entries.reduce((sum, entry) => sum + safeNumber(entry.kills), 0),
    deaths: entries.reduce((sum, entry) => sum + safeNumber(entry.deaths), 0)
  };
}

function buildSpecificWeaponDetailTabs(weaponKey = "", matchEntries = getScopedStatsData().matches) {
  const meta = getStatsWeaponMeta(weaponKey);
  const weapon = getSpecificWeaponSummary(weaponKey, matchEntries);
  const rounds = weapon?.roundEntries || [];
  const attackRounds = rounds.filter(round => String(round?.side || "").toLowerCase() === "attack");
  const defenseRounds = rounds.filter(round => String(round?.side || "").toLowerCase() === "defense");
  const topMaps = (weapon?.maps || []).slice(0, 3).map(([name, count]) => `${name} (${count})`).join(", ");
  const topBuyTypes = (weapon?.buyTypes || []).slice(0, 3).map(([name, count]) => `${name} (${count})`).join(", ");
  const hasSample = Boolean(weapon?.rounds);

  return [
    {
      key: "overview",
      label: "Overview",
      items: [
        statItem("Weapon", meta?.name || "Weapon", "Exact weapon selected from the local Valorant weapon roster."),
        statItem("Weapon Category", meta?.familyLabel || "Weapon", "Weapon category row on the Stats page."),
        statItem("Round Win Rate", hasSample ? formatPercent(weapon.winrate) : "--", hasSample ? `round wins / rounds reported = ${Math.round(weapon.wins)} / ${Math.round(weapon.rounds)}` : "No imported rounds are tagged with this weapon yet."),
        statItem("Rounds Reported", hasSample ? `${Math.round(weapon.rounds)}` : "0", "Imported round-by-round weapon usage for this exact weapon."),
        statItem("Matches Reported", hasSample ? `${Math.round(weapon.matches)}` : "0", "Imported matches where this exact weapon was reported at least once."),
        statItem("Estimated Kills", hasSample ? `${Math.round(weapon.kills)}` : "--", "Kills are proportionally derived from match combat totals based on this weapon's share of rounds reported."),
        statItem("Estimated Deaths", hasSample ? `${Math.round(weapon.deaths)}` : "--", "Deaths are proportionally derived from match combat totals based on this weapon's share of rounds reported."),
        statItem("Estimated ADR", hasSample ? `${Math.round(weapon.adr)}` : "--", "ADR is weighted from imported match damage-per-round across rounds using this exact weapon.")
      ]
    },
    {
      key: "side-split",
      label: "ATK/DEF",
      items: [
        statItem("Attack Win Rate", hasSample ? formatPercent(weapon.attackWinrate) : "--", `attack wins / attack rounds with ${meta?.name || "this weapon"} = ${attackRounds.filter(round => round?.roundWon).length} / ${attackRounds.length || 1}`),
        statItem("Defense Win Rate", hasSample ? formatPercent(weapon.defenseWinrate) : "--", `defense wins / defense rounds with ${meta?.name || "this weapon"} = ${defenseRounds.filter(round => round?.roundWon).length} / ${defenseRounds.length || 1}`),
        statItem("Def/Atk Share", hasSample ? `${formatPercent(safeDivide(defenseRounds.length * 100, rounds.length))} / ${formatPercent(safeDivide(attackRounds.length * 100, rounds.length))}` : "-- / --", "Defense and attack rounds with this weapon divided by all rounds reported with it."),
        statItem("Kills / Round", hasSample ? Number(weapon.killsPerRound || 0).toFixed(2) : "--", "Estimated kills divided by rounds reported on this weapon."),
        statItem("Deaths / Round", hasSample ? Number(weapon.deathsPerRound || 0).toFixed(2) : "--", "Estimated deaths divided by rounds reported on this weapon.")
      ]
    },
    {
      key: "usage",
      label: "Usage",
      items: [
        statItem("Most Common Buy", topBuyTypes || "--", "Most common economy labels on rounds where this weapon was used."),
        statItem("Most Common Maps", topMaps || "--", "Maps where this exact weapon is reported most often in the imported round sample."),
        statItem("First Blood Lane", getMostCommonValue(rounds.map(round => round.firstKillLocation)), "Most common first-blood location on rounds tagged with this weapon."),
        statItem("First Death Lane", getMostCommonValue(rounds.map(round => round.firstDeathLocation)), "Most common first-death location on rounds tagged with this weapon.")
      ]
    },
    {
      key: "coach-read",
      label: "Coach Read",
      items: [
        statItem("Tracker-Style Read", hasSample ? `${meta?.name || "Weapon"} is converting ${formatPercent(weapon.winrate)} across ${Math.round(weapon.rounds)} rounds reported.` : `${meta?.name || "Weapon"} has no reported sample yet.`, "A compact read meant to mirror the quick weapon drill-down pattern from stat tracker pages."),
        statItem("Priority", hasSample && safeNumber(weapon.winrate) < 45 ? "Review positioning" : "Keep sampling", hasSample && safeNumber(weapon.winrate) < 45 ? "Low round conversion means this weapon should be reviewed by buy type and side." : "No urgent weakness detected from the current weapon sample."),
        statItem("Next Check", "Compare ATK/DEF and buy type", "Use the ATK/DEF and Usage tabs to decide whether the issue is attack usage, defense usage, or economy choice.")
      ]
    }
  ];
}

function summarizeWeaponRounds(matchEntries = matches) {
  const buckets = new Map();

  (matchEntries || []).forEach((match) => {
    const rounds = Array.isArray(match?.advanced?.rounds) ? match.advanced.rounds : [];
    if (!rounds.length) return;

    const core = getMatchCore(match);
    const localBuckets = new Map();

    rounds.forEach((round) => {
      const weaponName = String(round?.weapon || "").trim();
      const typeMeta = getWeaponTypeMeta(weaponName);
      if (!typeMeta.key) return;

      const current = localBuckets.get(typeMeta.key) || {
        typeKey: typeMeta.key,
        label: typeMeta.label,
        rounds: 0,
        wins: 0,
        attackRounds: 0,
        attackWins: 0,
        defenseRounds: 0,
        defenseWins: 0,
        weapons: new Map(),
        roundEntries: []
      };

      current.rounds += 1;
      current.wins += round?.roundWon ? 1 : 0;
      if (String(round?.side || "").toLowerCase() === "attack") {
        current.attackRounds += 1;
        current.attackWins += round?.roundWon ? 1 : 0;
      } else if (String(round?.side || "").toLowerCase() === "defense") {
        current.defenseRounds += 1;
        current.defenseWins += round?.roundWon ? 1 : 0;
      }
      current.weapons.set(weaponName, (current.weapons.get(weaponName) || 0) + 1);
      current.roundEntries.push(round);
      localBuckets.set(typeMeta.key, current);
    });

    const totalTaggedRounds = [...localBuckets.values()].reduce((sum, entry) => sum + entry.rounds, 0);
    if (!totalTaggedRounds) return;

    localBuckets.forEach((entry) => {
      const share = entry.rounds / totalTaggedRounds;
      const target = buckets.get(entry.typeKey) || {
        typeKey: entry.typeKey,
        label: entry.label,
        rounds: 0,
        wins: 0,
        attackRounds: 0,
        attackWins: 0,
        defenseRounds: 0,
        defenseWins: 0,
        matches: 0,
        kills: 0,
        deaths: 0,
        adrWeighted: 0,
        weapons: new Map(),
        roundEntries: []
      };

      target.rounds += entry.rounds;
      target.wins += entry.wins;
      target.attackRounds += entry.attackRounds;
      target.attackWins += entry.attackWins;
      target.defenseRounds += entry.defenseRounds;
      target.defenseWins += entry.defenseWins;
      target.matches += 1;
      target.kills += safeNumber(core.kills) * share;
      target.deaths += safeNumber(core.deaths) * share;
      target.adrWeighted += safeNumber(core.adr) * entry.rounds;
      entry.weapons.forEach((count, weaponName) => {
        target.weapons.set(weaponName, (target.weapons.get(weaponName) || 0) + count);
      });
      target.roundEntries.push(...entry.roundEntries);
      buckets.set(entry.typeKey, target);
    });
  });

  return [...buckets.values()]
    .map((entry) => {
      const weaponUsage = [...entry.weapons.entries()].sort((a, b) => b[1] - a[1]);
      const primaryWeapon = weaponUsage[0]?.[0] || "--";
      return {
        typeKey: entry.typeKey,
        label: entry.label,
        primaryWeapon,
        rounds: entry.rounds,
        matches: entry.matches,
        winrate: safeDivide(entry.wins * 100, entry.rounds),
        attackWinrate: safeDivide(entry.attackWins * 100, entry.attackRounds),
        defenseWinrate: safeDivide(entry.defenseWins * 100, entry.defenseRounds),
        kills: entry.kills,
        deaths: entry.deaths,
        adr: safeDivide(entry.adrWeighted, entry.rounds),
        killsPerRound: safeDivide(entry.kills, entry.rounds),
        deathsPerRound: safeDivide(entry.deaths, entry.rounds),
        usage: weaponUsage,
        roundEntries: entry.roundEntries
      };
    })
    .sort((a, b) => b.winrate - a.winrate || b.rounds - a.rounds || a.label.localeCompare(b.label));
}

function buildWeaponDetailTabs(weaponTypeKey = "", matchEntries = getScopedStatsData().matches) {
  const exactWeapon = getStatsWeaponMeta(weaponTypeKey);
  if (exactWeapon) return buildSpecificWeaponDetailTabs(weaponTypeKey, matchEntries);

  const normalizedTypeKey = normalizeStatsWeaponKey(weaponTypeKey) === "sidearm"
    ? "pistol"
    : normalizeStatsWeaponKey(weaponTypeKey);
  const weapon = summarizeWeaponRounds(matchEntries).find(entry => normalizeStatsWeaponKey(entry.typeKey) === normalizedTypeKey);
  const rounds = weapon?.roundEntries || [];
  const attackRounds = rounds.filter(round => String(round?.side || "").toLowerCase() === "attack");
  const defenseRounds = rounds.filter(round => String(round?.side || "").toLowerCase() === "defense");
  const buyCounts = {
    eco: rounds.filter(round => String(round?.buyType || "").toLowerCase().includes("eco")),
    light: rounds.filter(round => String(round?.buyType || "").toLowerCase().includes("light")),
    full: rounds.filter(round => String(round?.buyType || "").toLowerCase().includes("full"))
  };
  const topUsage = (weapon?.usage || []).slice(0, 3).map(([name, count]) => `${name} (${count})`).join(", ");

  return [
    {
      key: "overview",
      label: "Overview",
      items: [
        statItem("Weapon Category", weapon?.label || "Weapon", "Grouped from imported round-by-round weapon usage."),
        statItem("Primary Weapon", weapon?.primaryWeapon || "--", "Most-used weapon inside this weapon category."),
        statItem("Round Win Rate", formatPercent(weapon?.winrate), `rounds won with ${weapon?.label || "this weapon category"} / total rounds on that weapon category = ${Math.round(safeNumber(weapon?.winrate) * safeNumber(weapon?.rounds) / 100)} / ${Math.round(safeNumber(weapon?.rounds))}`),
        statItem("Estimated Kills", weapon ? `${Math.round(weapon.kills)}` : "--", "Kills are proportionally derived from match combat totals based on this weapon category's share of rounds reported."),
        statItem("Estimated Deaths", weapon ? `${Math.round(weapon.deaths)}` : "--", "Deaths are proportionally derived from match combat totals based on this weapon category's share of rounds reported."),
        statItem("Estimated ADR", weapon ? `${Math.round(weapon.adr)}` : "--", "ADR is weighted from imported match damage-per-round across rounds using this weapon category."),
        statItem("Kills / Round", weapon ? Number(weapon.killsPerRound || 0).toFixed(2) : "--", "Estimated kills divided by rounds reported on this weapon category."),
        statItem("Rounds Reported", weapon ? `${Math.round(weapon.rounds)}` : "--", "Imported rounds tagged with a weapon inside this weapon category."),
        statItem("Most Used Guns", topUsage || "--", "Top specific weapons inside this weapon category by rounds reported.")
      ]
    },
    {
      key: "attack",
      label: "Attack",
      items: [
        statItem("Attack Win Rate", formatPercent(safeDivide(attackRounds.filter(round => round?.roundWon).length * 100, attackRounds.length)), `attack rounds won / attack rounds with ${weapon?.label || "this weapon category"} = ${attackRounds.filter(round => round?.roundWon).length} / ${attackRounds.length || 1}`),
        statItem("Attack Share", formatPercent(safeDivide(attackRounds.length * 100, rounds.length)), "Attack rounds on this weapon category divided by all rounds reported on this weapon category."),
        statItem("Most Common First Blood Lane", getMostCommonValue(attackRounds.map(round => round.firstKillLocation)), "Most common opening lane when this weapon category was used on attack."),
        statItem("Most Common Buy Type", getMostCommonValue(attackRounds.map(round => round.buyType)), "Most common attack economy state when this weapon category was used.")
      ]
    },
    {
      key: "defense",
      label: "Defense",
      items: [
        statItem("Defense Win Rate", formatPercent(safeDivide(defenseRounds.filter(round => round?.roundWon).length * 100, defenseRounds.length)), `defense rounds won / defense rounds with ${weapon?.label || "this weapon category"} = ${defenseRounds.filter(round => round?.roundWon).length} / ${defenseRounds.length || 1}`),
        statItem("Defense Share", formatPercent(safeDivide(defenseRounds.length * 100, rounds.length)), "Defense rounds on this weapon category divided by all rounds reported on this weapon category."),
        statItem("Most Common First Death Lane", getMostCommonValue(defenseRounds.map(round => round.firstDeathLocation)), "Most common first-death lane when this weapon category was used on defense."),
        statItem("Most Common Buy Type", getMostCommonValue(defenseRounds.map(round => round.buyType)), "Most common defense economy state when this weapon category was used.")
      ]
    },
    {
      key: "economy",
      label: "Economy",
      items: [
        statItem("Eco Usage", `${buyCounts.eco.length} rounds`, "Eco rounds reported on this weapon category."),
        statItem("Light Usage", `${buyCounts.light.length} rounds`, "Light-buy rounds reported on this weapon category."),
        statItem("Full Usage", `${buyCounts.full.length} rounds`, "Full-buy rounds reported on this weapon category."),
        statItem("Eco Conversion", formatPercent(safeDivide(buyCounts.eco.filter(round => round?.roundWon).length * 100, buyCounts.eco.length)), "Eco round wins divided by eco rounds reported on this weapon category."),
        statItem("Light Conversion", formatPercent(safeDivide(buyCounts.light.filter(round => round?.roundWon).length * 100, buyCounts.light.length)), "Light-buy round wins divided by light-buy rounds reported on this weapon category."),
        statItem("Full Conversion", formatPercent(safeDivide(buyCounts.full.filter(round => round?.roundWon).length * 100, buyCounts.full.length)), "Full-buy round wins divided by full-buy rounds reported on this weapon category.")
      ]
    }
  ];
}

function buildRoleSideMetrics(roleName, sideMetrics = {}, rounds = [], side = "attack") {
  const roleKey = String(roleName || "").toLowerCase();
  const sideRounds = Math.max(1, safeNumber(sideMetrics.roundsPlayed) || rounds.length || 1);
  const firstKillLane = getMostCommonValue(rounds.map(round => round.firstKillLocation));
  const firstDeathLane = getMostCommonValue(rounds.map(round => round.firstDeathLocation));
  const firstDeathRate = safeDivide(sideMetrics.firstDeaths, sideRounds) * 100;
  const firstBloodRate = safeDivide(sideMetrics.firstBloods, sideRounds) * 100;
  const survivalRate = safeDivide(sideMetrics.survived, sideRounds) * 100;
  const sideLabel = side === "attack" ? "ATK" : "DEF";

  if (roleKey === "controller") {
    return side === "attack"
      ? [
          statItem("First Death Rate", formatPercent(firstDeathRate), `firstDeaths / ${sideLabel} rounds = ${safeNumber(sideMetrics.firstDeaths)} / ${sideRounds}`),
          statItem("Most Frequent First Blood Location", firstKillLane, "Most common first-blood location across imported rounds for this side.")
        ]
      : [
          statItem("Survival Rate", formatPercent(survivalRate), `survivedRounds / ${sideLabel} rounds = ${safeNumber(sideMetrics.survived)} / ${sideRounds}`),
          statItem("Round Conversion", formatPercent(sideMetrics.winPct), `roundsWon / ${sideLabel} rounds = ${safeNumber(sideMetrics.roundsWon)} / ${sideRounds}`),
          statItem("Most Frequent First Death Location", firstDeathLane, "Most common first-death location across imported rounds for this side."),
          statItem("Most Frequent First Blood Location", firstKillLane, "Most common first-blood location across imported rounds for this side.")
        ];
  }

  if (roleKey === "sentinel") {
    return side === "attack"
      ? [
          statItem("First Blood Rate", formatPercent(firstBloodRate), `firstBloods / ${sideLabel} rounds = ${safeNumber(sideMetrics.firstBloods)} / ${sideRounds}`),
          statItem("Survival Rate", formatPercent(survivalRate), `survivedRounds / ${sideLabel} rounds = ${safeNumber(sideMetrics.survived)} / ${sideRounds}`)
        ]
      : [
          statItem("Survival Rate", formatPercent(survivalRate), `survivedRounds / ${sideLabel} rounds = ${safeNumber(sideMetrics.survived)} / ${sideRounds}`),
          statItem("Round Conversion", formatPercent(sideMetrics.winPct), `roundsWon / ${sideLabel} rounds = ${safeNumber(sideMetrics.roundsWon)} / ${sideRounds}`),
          statItem("Most Frequent First Death Location", firstDeathLane, "Most common first-death location across imported rounds for this side.")
        ];
  }

  if (roleKey === "initiator") {
    return side === "attack"
      ? [
          statItem("First Blood Rate", formatPercent(firstBloodRate), `firstBloods / ${sideLabel} rounds = ${safeNumber(sideMetrics.firstBloods)} / ${sideRounds}`),
          statItem("Most Frequent First Blood Location", firstKillLane, "Most common first-blood location across imported rounds for this side.")
        ]
      : [
          statItem("Survival Rate", formatPercent(survivalRate), `survivedRounds / ${sideLabel} rounds = ${safeNumber(sideMetrics.survived)} / ${sideRounds}`),
          statItem("Most Frequent First Blood Location", firstKillLane, "Most common first-blood location across imported rounds for this side.")
        ];
  }

  return side === "attack"
    ? [
        statItem("First Blood Rate", formatPercent(firstBloodRate), `firstBloods / ${sideLabel} rounds = ${safeNumber(sideMetrics.firstBloods)} / ${sideRounds}`),
        statItem("Attack Side Survivability", formatPercent(100 - firstDeathRate), `1 - (firstDeaths / ${sideLabel} rounds) = 1 - (${safeNumber(sideMetrics.firstDeaths)} / ${sideRounds})`),
        statItem("Most Frequent First Blood Location", firstKillLane, "Most common first-blood location across imported rounds for this side.")
      ]
    : [
        statItem("First Blood Rate", formatPercent(firstBloodRate), `firstBloods / ${sideLabel} rounds = ${safeNumber(sideMetrics.firstBloods)} / ${sideRounds}`),
        statItem("Defense Side Survivability", formatPercent(100 - firstDeathRate), `1 - (firstDeaths / ${sideLabel} rounds) = 1 - (${safeNumber(sideMetrics.firstDeaths)} / ${sideRounds})`),
        statItem("Most Frequent First Death Location", firstDeathLane, "Most common first-death location across imported rounds for this side.")
      ];
}

function buildCalculatedAgentDetailTabs(agentName, analytics) {
  const agent = (analytics?.agents || []).find(item => String(item.agent || "").toLowerCase() === String(agentName || "").toLowerCase());
  const roleName = agentRoles?.[agentName] || "--";
  const scoped = getScopedStatsData();
  const coach = buildCoachRecommendation("agent", agent, analytics);
  const agentMaps = getAgentMapInsights(agentName, analytics);
  const bestMap = agentMaps[0];
  const worstMap = agentMaps[agentMaps.length - 1];
  const attackRounds = getEntityRounds({ agentName, side: "attack", matchEntries: scoped.matches });
  const defenseRounds = getEntityRounds({ agentName, side: "defense", matchEntries: scoped.matches });
  const attackMetrics = getSideMetricsFromMaps(agentMaps, "attack");
  const defenseMetrics = getSideMetricsFromMaps(agentMaps, "defense");
  const weaponRates = getWeaponRoundRates([...attackRounds, ...defenseRounds]);
  const bestGun = weaponRates[0] || null;
  const worstGun = weaponRates[weaponRates.length - 1] || null;
  const totalSideRounds = safeNumber(attackMetrics.roundsPlayed) + safeNumber(defenseMetrics.roundsPlayed);
  const overallKast = safeDivide(
    (safeNumber(attackMetrics.kast) * safeNumber(attackMetrics.roundsPlayed)) + (safeNumber(defenseMetrics.kast) * safeNumber(defenseMetrics.roundsPlayed)),
    totalSideRounds
  ) * 100;

  return [
    {
      key: "coach",
      label: "Coach",
      items: [
        statItem("Diagnosis", coach.diagnosis, "Coaching-layer diagnosis built from current agent stability and role fit."),
        statItem("Emphasis", coach.emphasis, "What should matter most when you queue this agent next."),
        statItem("Recommendation", coach.recommendation, "Next-step plan translated from the current agent sample."),
        statItem("Confidence", analytics?.confidenceLabel || "Low Confidence", "Shared model confidence based on imported sample size and reflection support."),
        statItem("Priority", analytics?.priorityLabel || "Watch", "Current coaching priority tier.")
      ]
    },
    {
      key: "general",
      label: "General",
      items: [
        statItem("Role", roleName, "Agent role mapping from the current roster table."),
        statItem("K/D", agent ? Number(agent.kd || 0).toFixed(2) : "--", `kills / deaths = ${safeNumber(agent?.kills)} / ${Math.max(1, safeNumber(agent?.deaths))}`),
        statItem("Overall KAST", formatPercent(overallKast), `weighted side KAST = ((ATK KAST Ã— ATK rounds) + (DEF KAST Ã— DEF rounds)) / total rounds`),
        statItem("Average ADR", agent ? `${Math.round(agent.adr || 0)}` : "--", `damagePerRound from imported agent segment = ${safeNumber(agent?.adr).toFixed(1)}`),
        statItem("Econ Rating", agent ? `${Math.round(agent.econ || 0)}` : "--", `econRating from imported agent segment = ${Math.round(safeNumber(agent?.econ))}`),
        statItem("Best Map Win Rate", bestMap ? `${bestMap.map} | ${formatPercent(safeDivide(safeNumber(bestMap.matchesWon), safeNumber(bestMap.matchesPlayed)) * 100)}` : "--", bestMap ? `matchesWon / matchesPlayed on ${bestMap.map} = ${safeNumber(bestMap.matchesWon)} / ${safeNumber(bestMap.matchesPlayed)}` : "No imported map segment."),
        statItem("Worst Map Win Rate", worstMap ? `${worstMap.map} | ${formatPercent(safeDivide(safeNumber(worstMap.matchesWon), safeNumber(worstMap.matchesPlayed)) * 100)}` : "--", worstMap ? `matchesWon / matchesPlayed on ${worstMap.map} = ${safeNumber(worstMap.matchesWon)} / ${safeNumber(worstMap.matchesPlayed)}` : "No imported map segment."),
        statItem("Best Gun Round Conversion", bestGun ? `${bestGun.weapon} | ${formatPercent(bestGun.conversionPct)}` : "--", bestGun ? `round wins with ${bestGun.weapon} / rounds using ${bestGun.weapon} = ${bestGun.wins} / ${bestGun.rounds}` : "No imported round weapon data."),
        statItem("Worst Gun Round Conversion", worstGun ? `${worstGun.weapon} | ${formatPercent(worstGun.conversionPct)}` : "--", worstGun ? `round wins with ${worstGun.weapon} / rounds using ${worstGun.weapon} = ${worstGun.wins} / ${worstGun.rounds}` : "No imported round weapon data."),
        statItem("Best Round Win Conversion", bestMap ? formatPercent(safeDivide(safeNumber(bestMap.roundsWon), safeNumber(bestMap.roundsPlayed)) * 100) : "--", bestMap ? `roundsWon / roundsPlayed on ${bestMap.map} = ${safeNumber(bestMap.roundsWon)} / ${safeNumber(bestMap.roundsPlayed)}` : "No imported map rounds."),
        statItem("Worst Map Round Recovery", worstMap ? formatPercent(safeDivide(safeNumber(worstMap.roundsWon), safeNumber(worstMap.roundsPlayed)) * 100) : "--", worstMap ? `roundsWon / roundsPlayed on ${worstMap.map} = ${safeNumber(worstMap.roundsWon)} / ${safeNumber(worstMap.roundsPlayed)}` : "No imported map rounds.")
      ]
    },
    {
      key: "attack",
      label: "Attack",
      items: [
        statItem("Attack Win Rate", formatPercent(attackMetrics.winPct), `attackRoundsWon / attackRoundsPlayed = ${safeNumber(attackMetrics.roundsWon)} / ${Math.max(1, safeNumber(attackMetrics.roundsPlayed))}`),
        statItem("Attack KAST", formatPercent(attackMetrics.kast), `weighted attack KAST from imported map segments across ${Math.round(safeNumber(attackMetrics.roundsPlayed))} rounds`),
        statItem("Attack ADR", attackMetrics.damagePerRound ? `${Math.round(attackMetrics.damagePerRound)}` : "--", `weighted attack ADR from imported map segments across ${Math.round(safeNumber(attackMetrics.roundsPlayed))} rounds`),
        statItem("Attack Kills", attackMetrics.kills ? `${Math.round(attackMetrics.kills)}` : "--", `sum of imported attack kills across agent-map segments = ${Math.round(safeNumber(attackMetrics.kills))}`),
        ...buildRoleSideMetrics(roleName, attackMetrics, attackRounds, "attack")
      ]
    },
    {
      key: "defense",
      label: "Defense",
      items: [
        statItem("Defense Win Rate", formatPercent(defenseMetrics.winPct), `defenseRoundsWon / defenseRoundsPlayed = ${safeNumber(defenseMetrics.roundsWon)} / ${Math.max(1, safeNumber(defenseMetrics.roundsPlayed))}`),
        statItem("Defense KAST", formatPercent(defenseMetrics.kast), `weighted defense KAST from imported map segments across ${Math.round(safeNumber(defenseMetrics.roundsPlayed))} rounds`),
        statItem("Defense ADR", defenseMetrics.damagePerRound ? `${Math.round(defenseMetrics.damagePerRound)}` : "--", `weighted defense ADR from imported map segments across ${Math.round(safeNumber(defenseMetrics.roundsPlayed))} rounds`),
        statItem("Defense Kills", defenseMetrics.kills ? `${Math.round(defenseMetrics.kills)}` : "--", `sum of imported defense kills across agent-map segments = ${Math.round(safeNumber(defenseMetrics.kills))}`),
        ...buildRoleSideMetrics(roleName, defenseMetrics, defenseRounds, "defense")
      ]
    }
  ];
}

function buildCalculatedRoleDetailTabs(roleName, analytics) {
  const role = (analytics?.roles || []).find(item => String(item.role || "").toLowerCase() === String(roleName || "").toLowerCase());
  const scoped = getScopedStatsData();
  const coach = buildCoachRecommendation("role", role, analytics);
  const filteredMaps = (analytics?.maps || []).filter(item => String(agentRoles?.[item.agent] || "").toLowerCase() === String(roleName || "").toLowerCase());
  const sortedMaps = filteredMaps.slice().sort((a, b) => safeDivide(safeNumber(b.matchesWon), safeNumber(b.matchesPlayed)) - safeDivide(safeNumber(a.matchesWon), safeNumber(a.matchesPlayed)));
  const bestMap = sortedMaps[0];
  const worstMap = sortedMaps[sortedMaps.length - 1];
  const attackRounds = getEntityRounds({ roleName, side: "attack", matchEntries: scoped.matches });
  const defenseRounds = getEntityRounds({ roleName, side: "defense", matchEntries: scoped.matches });
  const roleAttackMetrics = getSideMetricsFromMaps(filteredMaps, "attack");
  const roleDefenseMetrics = getSideMetricsFromMaps(filteredMaps, "defense");

  return [
    {
      key: "coach",
      label: "Coach",
      items: [
        statItem("Diagnosis", coach.diagnosis, "Coaching-layer diagnosis built from current role performance and fit."),
        statItem("Emphasis", coach.emphasis, "What should matter most when you queue this role family next."),
        statItem("Recommendation", coach.recommendation, "Next-step plan translated from the current role sample."),
        statItem("Confidence", analytics?.confidenceLabel || "Low Confidence", "Shared model confidence based on imported sample size and reflection support."),
        statItem("Priority", analytics?.priorityLabel || "Watch", "Current coaching priority tier.")
      ]
    },
    {
      key: "general",
      label: "General",
      items: [
        statItem("Role", roleName, "Role grouping based on the full roster mapping."),
        statItem("Role Win Rate", role ? formatPercent(safeDivide(safeNumber(role.matchesWon), safeNumber(role.matchesPlayed)) * 100) : "--", role ? `matchesWon / matchesPlayed = ${safeNumber(role.matchesWon)} / ${safeNumber(role.matchesPlayed)}` : "No imported role segment."),
        statItem("K/D", role ? Number(role.kd || 0).toFixed(2) : "--", `role kills / role deaths from imported role segment`),
        statItem("Average ADR", role ? `${Math.round(role.adr || 0)}` : "--", `damagePerRound from imported role segment = ${safeNumber(role?.adr).toFixed(1)}`),
        statItem("Headshot %", role ? formatPercent(role.hs) : "--", `headshotsPercentage from imported role segment = ${safeNumber(role?.hs).toFixed(1)}`),
        statItem("Best Map", bestMap ? `${bestMap.map} | ${formatPercent(safeDivide(safeNumber(bestMap.matchesWon), safeNumber(bestMap.matchesPlayed)) * 100)}` : "--", bestMap ? `matchesWon / matchesPlayed on ${bestMap.map} = ${safeNumber(bestMap.matchesWon)} / ${safeNumber(bestMap.matchesPlayed)}` : "No imported map segment."),
        statItem("Worst Map", worstMap ? `${worstMap.map} | ${formatPercent(safeDivide(safeNumber(worstMap.matchesWon), safeNumber(worstMap.matchesPlayed)) * 100)}` : "--", worstMap ? `matchesWon / matchesPlayed on ${worstMap.map} = ${safeNumber(worstMap.matchesWon)} / ${safeNumber(worstMap.matchesPlayed)}` : "No imported map segment.")
      ]
    },
    {
      key: "attack",
      label: "Attack",
      items: [
        statItem("Attack Win Rate", formatPercent(roleAttackMetrics.winPct), `attackRoundsWon / attackRoundsPlayed = ${safeNumber(roleAttackMetrics.roundsWon)} / ${Math.max(1, safeNumber(roleAttackMetrics.roundsPlayed))}`),
        statItem("Attack KAST", formatPercent(roleAttackMetrics.kast), `weighted attack KAST from imported map segments across ${Math.round(safeNumber(roleAttackMetrics.roundsPlayed))} rounds`),
        statItem("Attack ADR", roleAttackMetrics.damagePerRound ? `${Math.round(roleAttackMetrics.damagePerRound)}` : "--", `weighted attack ADR from imported map segments across ${Math.round(safeNumber(roleAttackMetrics.roundsPlayed))} rounds`),
        statItem("Attack Kills", roleAttackMetrics.kills ? `${Math.round(roleAttackMetrics.kills)}` : "--", `sum of imported attack kills across role-aligned map segments = ${Math.round(safeNumber(roleAttackMetrics.kills))}`),
        ...buildRoleSideMetrics(roleName, roleAttackMetrics, attackRounds, "attack")
      ]
    },
    {
      key: "defense",
      label: "Defense",
      items: [
        statItem("Defense Win Rate", formatPercent(roleDefenseMetrics.winPct), `defenseRoundsWon / defenseRoundsPlayed = ${safeNumber(roleDefenseMetrics.roundsWon)} / ${Math.max(1, safeNumber(roleDefenseMetrics.roundsPlayed))}`),
        statItem("Defense KAST", formatPercent(roleDefenseMetrics.kast), `weighted defense KAST from imported map segments across ${Math.round(safeNumber(roleDefenseMetrics.roundsPlayed))} rounds`),
        statItem("Defense ADR", roleDefenseMetrics.damagePerRound ? `${Math.round(roleDefenseMetrics.damagePerRound)}` : "--", `weighted defense ADR from imported map segments across ${Math.round(safeNumber(roleDefenseMetrics.roundsPlayed))} rounds`),
        statItem("Defense Kills", roleDefenseMetrics.kills ? `${Math.round(roleDefenseMetrics.kills)}` : "--", `sum of imported defense kills across role-aligned map segments = ${Math.round(safeNumber(roleDefenseMetrics.kills))}`),
        ...buildRoleSideMetrics(roleName, roleDefenseMetrics, defenseRounds, "defense")
      ]
    }
  ];
}

function renderSecondaryLensStats(list, items = []) {
  if (!list) return;
  list.innerHTML = items.map((item) => {
    const normalized = Array.isArray(item)
      ? { label: item[0], stat: item[1], formula: "" }
      : { label: item?.label, stat: item?.stat, formula: item?.formula || "" };
    normalized.label = normalizeRankedCoachCopy(normalized.label);
    normalized.stat = normalizeRankedCoachCopy(normalized.stat);
    normalized.formula = normalizeRankedCoachCopy(normalized.formula);

    return `
    <li class="lens-stat${normalized.formula ? " lens-stat-has-formula" : ""}" ${normalized.formula ? `data-formula="${escapeHtml(normalized.formula)}"` : ""}>
      <span>${escapeHtml(normalized.label)}</span>
      <strong>${escapeHtml(normalized.stat)}</strong>
    </li>
  `;
  }).join("");
}

function renderSecondaryLensTabs(tabsHost, list, tabs = []) {
  if (!tabsHost || !list) return;

  if (!tabs.length) {
    tabsHost.innerHTML = "";
    tabsHost.style.display = "none";
    return;
  }

  tabsHost.style.display = "flex";
  tabsHost.innerHTML = tabs.map((tab, index) => `
    <button type="button" class="lens-detail-tab ${index === 0 ? "active" : ""}" data-tab-key="${escapeHtml(tab.key)}">
      ${escapeHtml(normalizeRankedCoachCopy(tab.label))}
    </button>
  `).join("");

  const activateTab = (key) => {
    const nextTab = tabs.find(tab => tab.key === key) || tabs[0];
    tabsHost.querySelectorAll(".lens-detail-tab").forEach(button => {
      button.classList.toggle("active", button.dataset.tabKey === nextTab.key);
    });
    renderSecondaryLensStats(list, nextTab.items || []);
  };

  tabsHost.querySelectorAll(".lens-detail-tab").forEach(button => {
    button.addEventListener("click", () => activateTab(button.dataset.tabKey || ""));
  });

  activateTab(tabs[0].key);
}

function normalizeSignalTone(tone = "") {
  const normalized = String(tone || "").trim().toLowerCase();
  if (["up", "good", "positive"].includes(normalized)) return "up";
  if (["warn", "watch", "steady"].includes(normalized)) return "warn";
  if (["down", "bad", "negative"].includes(normalized)) return "down";
  return "neutral";
}

function getSignalToneMeta(tone = "") {
  const normalized = normalizeSignalTone(tone);
  if (normalized === "up") {
    return { tone: "up", label: "Strength", glyph: "" };
  }
  if (normalized === "warn") {
    return { tone: "warn", label: "Watch", glyph: "" };
  }
  if (normalized === "down") {
    return { tone: "down", label: "Needs Work", glyph: "" };
  }
  return { tone: "neutral", label: "Neutral", glyph: "" };
}

function getInsightMetaToneClass(kind = "", label = "", fallbackTone = "neutral") {
  const normalizedKind = String(kind || "").trim().toLowerCase();
  const normalizedLabel = String(label || "").trim().toLowerCase();

  if (normalizedKind === "priority") {
    if (normalizedLabel.includes("immediate") || normalizedLabel.includes("high")) return "tone-bad";
    if (normalizedLabel.includes("moderate")) return "tone-warn";
    if (normalizedLabel.includes("watch")) return "tone-good";
  }

  if (normalizedKind === "confidence") {
    if (normalizedLabel.includes("high")) return "tone-good";
    if (normalizedLabel.includes("medium")) return "tone-warn";
    if (normalizedLabel.includes("low")) return "tone-bad";
  }

  const normalizedFallback = normalizeSignalTone(fallbackTone);
  if (normalizedFallback === "up") return "tone-good";
  if (normalizedFallback === "warn") return "tone-warn";
  if (normalizedFallback === "down") return "tone-bad";
  return "tone-neutral";
}

function normalizeInsightFilterType(insight = {}) {
  const rawType = String(insight?.type || "").trim().toLowerCase();
  if (["bad", "needs", "needs-work", "need-work", "down", "negative"].includes(rawType)) return "bad";
  if (["warn", "watch", "warning", "neutral", "steady"].includes(rawType)) return "warn";
  if (["good", "strength", "strengths", "up", "positive"].includes(rawType)) return "good";

  const rawTone = String(insight?.tone || insight?.signal || insight?.status || "").trim().toLowerCase();
  if (["bad", "needs", "needs-work", "need-work", "down", "negative"].includes(rawTone)) return "bad";
  if (["warn", "watch", "warning", "neutral", "steady"].includes(rawTone)) return "warn";
  if (["good", "strength", "strengths", "up", "positive"].includes(rawTone)) return "good";

  const combinedCopy = [
    insight?.tag,
    insight?.label,
    insight?.title,
    insight?.preview
  ].map(value => String(value || "").toLowerCase()).join(" ");

  if (combinedCopy.includes("needs work") || combinedCopy.includes("bad") || combinedCopy.includes("loss") || combinedCopy.includes("slipping")) return "bad";
  if (combinedCopy.includes("strength") || combinedCopy.includes("strong") || combinedCopy.includes("good") || combinedCopy.includes("winning")) return "good";
  return "warn";
}

function getInsightFilterLabel(type = "warn") {
  const normalizedType = normalizeInsightFilterType({ type });
  if (normalizedType === "bad") return "Needs Work";
  if (normalizedType === "good") return "Strength";
  return "Watch";
}

function getInsightDisplayPool(model = getPlayerModel()) {
  const fullList = Array.isArray(model?.allInsights) ? model.allInsights : [];
  const topList = Array.isArray(model?.insights) ? model.insights : [];
  return fullList.length ? fullList : topList;
}

function getFilteredInsightDisplayList(filter = activeInsightFilter, model = getPlayerModel()) {
  const normalizedFilter = String(filter || "all").trim().toLowerCase();
  const sourceList = getInsightDisplayPool(model);
  if (normalizedFilter === "all") return sourceList.slice();
  return sourceList.filter(insight => normalizeInsightFilterType(insight) === normalizedFilter);
}

function applyInsightMetaPillTone(el, className = "tone-neutral") {
  if (!el) return;
  el.classList.remove("tone-good", "tone-warn", "tone-bad", "tone-neutral");
  el.classList.add(className || "tone-neutral");
}

function getTrendSignalMediaLabel(item = {}) {
  const explicitLabel = String(item?.mediaText || "").trim();
  if (explicitLabel) return explicitLabel;

  const mediaType = String(item?.mediaType || "").trim().toLowerCase();
  const mediaValue = String(item?.mediaValue || "").trim();
  if (mediaValue && mediaValue !== "--") {
    if (mediaType === "role") {
      return mediaValue.charAt(0).toUpperCase() + mediaValue.slice(1);
    }
    return mediaValue;
  }

  const title = String(item?.title || "").trim();
  if (title) return title;

  const kicker = String(item?.kicker || "").trim();
  if (kicker) return kicker;

  return "Insight";
}

function getTrendSignalSvgIcon(kind = "general", tone = "neutral") {
  const normalizedKind = String(kind || "general").trim().toLowerCase();
  const normalizedTone = normalizeSignalTone(tone);
  const iconClass = `trend-signal-svg trend-signal-svg-${escapeHtml(normalizedKind)} tone-${escapeHtml(normalizedTone)}`;

  if (normalizedKind === "logs") {
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 4h10a2 2 0 0 1 2 2v14H8a2 2 0 0 1-2-2V4Z"></path><path d="M8 4v14a2 2 0 0 0 2 2"></path><path d="M10 8h5M10 12h5M10 16h4"></path></svg>`;
  }

  if (normalizedKind === "split") {
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><path class="trend-split-up" d="M6 15l5-5h-3"></path><path class="trend-split-up" d="M11 10v3"></path><path class="trend-split-down" d="M18 9l-5 5h3"></path><path class="trend-split-down" d="M13 14v-3"></path></svg>`;
  }

  if (normalizedKind === "window") {
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5" width="16" height="15" rx="3"></rect><path d="M8 3v4M16 3v4M4 10h16M8 14h2M12 14h2M16 14h2"></path></svg>`;
  }

  if (normalizedKind === "form") {
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="5" r="2"></circle><path d="M12 8v5M8 12l4 2 4-2M7 19l5-4 5 4M5 21h14"></path></svg>`;
  }

  if (normalizedKind === "theme") {
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 19h16"></path><path d="M6 16l4-5 4 3 4-7"></path><path d="M6 16v3M10 11v8M14 14v5M18 7v12"></path></svg>`;
  }

  if (normalizedKind === "mood") {
    if (normalizedTone === "up") {
      return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 11v8"></path><path d="M10 19h6.5a2 2 0 0 0 1.9-1.4l1.2-4A2 2 0 0 0 17.7 11H15l.5-3.2A2 2 0 0 0 13.5 5L10 11v8Z"></path></svg>`;
    }
    if (normalizedTone === "down") {
      return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><path d="M17 13V5"></path><path d="M14 5H7.5a2 2 0 0 0-1.9 1.4l-1.2 4A2 2 0 0 0 6.3 13H9l-.5 3.2A2 2 0 0 0 10.5 19L14 13V5Z"></path></svg>`;
    }
    return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="7"></circle><path d="M9 10h.01M15 10h.01M9 15h6"></path></svg>`;
  }

  return `<svg class="${iconClass}" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="7"></circle><circle cx="12" cy="12" r="2"></circle><path d="M12 3v3M12 18v3M3 12h3M18 12h3"></path></svg>`;
}

function getTrendSignalIconMarkup(item = {}) {
  const mediaType = String(item?.mediaType || "").trim().toLowerCase();
  const mediaText = String(item?.mediaText || "").trim().toLowerCase();
  const mediaValue = String(item?.mediaValue || "").trim();
  const title = String(item?.title || "").trim().toLowerCase();
  const kicker = String(item?.kicker || "").trim().toLowerCase();
  const value = String(item?.value || "").trim().toLowerCase();
  const combined = `${mediaType} ${mediaText} ${title} ${kicker} ${value}`;

  if (mediaType === "role") {
    const roleKey = getCompassRoleKey(mediaValue || title || value);
    const roleIcon = ROLE_ICON_MAP?.[roleKey] || "";
    if (roleIcon) {
      return `
        <div class="trend-signal-media has-icon role-icon" data-icon-kind="role" data-role="${escapeHtml(roleKey)}">
          <img src="${escapeHtml(roleIcon)}" alt="${escapeHtml(roleKey)} role">
        </div>
      `;
    }
  }

  let icon = "";
  let iconKind = "general";
  if (combined.includes("log")) {
    iconKind = "logs";
    icon = getTrendSignalSvgIcon(iconKind, item?.tone);
  } else if (combined.includes("split") || combined.includes("win") || combined.includes("loss")) {
    iconKind = "split";
    icon = getTrendSignalSvgIcon(iconKind, item?.tone);
  } else if (combined.includes("window") || combined.includes("calendar") || combined.includes("season")) {
    iconKind = "window";
    icon = getTrendSignalSvgIcon(iconKind, item?.tone);
  } else if (combined.includes("form") || combined.includes("focus") || combined.includes("tilt") || combined.includes("mood")) {
    const tone = normalizeSignalTone(item?.tone);
    iconKind = combined.includes("form") ? "form" : "mood";
    icon = getTrendSignalSvgIcon(iconKind, tone);
  } else if (combined.includes("theme") || combined.includes("chart") || combined.includes("trend") || combined.includes("performance")) {
    iconKind = "theme";
    icon = getTrendSignalSvgIcon(iconKind, item?.tone);
  } else if (mediaType === "text") {
    const tone = normalizeSignalTone(item?.tone);
    iconKind = "mood";
    icon = getTrendSignalSvgIcon(iconKind, tone);
  }

  if (!icon) {
    iconKind = "general";
    icon = getTrendSignalSvgIcon(iconKind, item?.tone);
  }
  return `
    <div class="trend-signal-media has-icon" data-icon-kind="${escapeHtml(iconKind)}">
      <span class="trend-signal-icon" aria-hidden="true">${icon}</span>
    </div>
  `;
}

function getTrendSignalMediaMarkup(item = {}) {
  const mediaType = String(item?.mediaType || "").trim().toLowerCase();
  const mediaValue = String(item?.mediaValue || "").trim();
  const directMediaUrl = String(item?.mediaUrl || "").trim();
  let mediaUrl = "";
  let mediaAlt = getTrendSignalMediaLabel(item);

  const iconMarkup = getTrendSignalIconMarkup(item);
  if (iconMarkup) return iconMarkup;

  if (directMediaUrl) {
    mediaUrl = directMediaUrl;
  } else if (mediaType === "agent" && mediaValue) {
    mediaUrl = getAgentIconUrl(mediaValue);
    mediaAlt = `${mediaValue} agent`;
  } else if (mediaType === "map" && mediaValue && mediaValue !== "--") {
    mediaUrl = getMapIconUrl(mediaValue);
    mediaAlt = `${mediaValue} map`;
  }

  if (mediaUrl) {
    return `
      <div class="trend-signal-media has-image">
        <img src="${escapeHtml(mediaUrl)}" alt="${escapeHtml(mediaAlt)}" loading="lazy">
      </div>
    `;
  }

  return `
    <div class="trend-signal-media has-text">
      <span class="trend-signal-media-label">${escapeHtml(getTrendSignalMediaLabel(item))}</span>
    </div>
  `;
}

function renderTrendBreakdownCard(item = {}) {
  const toneMeta = getSignalToneMeta(item?.tone);
  return `
    <article class="trend-signal-card tone-${toneMeta.tone}" title="${escapeHtml(item?.detail || item?.value || "")}">
      <div class="trend-signal-top">
        ${getTrendSignalMediaMarkup(item)}
        <span class="trend-signal-tone">${toneMeta.label}</span>
      </div>
      <div class="trend-signal-kicker">${escapeHtml(item?.kicker || "Insight")}</div>
      <div class="trend-signal-title">${escapeHtml(item?.title || "Waiting for insight")}</div>
      <div class="trend-signal-value">${escapeHtml(item?.value || "--")}</div>
      <div class="trend-signal-detail">${escapeHtml(item?.detail || "No additional read available yet.")}</div>
    </article>
  `;
}

function getTrendBreakdownFallbackItems(key = "", model = {}) {
  const matchesPlayed = safeNumber(model?.overview?.matchesPlayed || matches.length);
  const focusLabel = model?.focus || getLockedWeeklyFocus() || "Weekly Focus";
  const roleLabel = model?.role || activeRole || "Primary Role";
  const mapLabel = model?.topMap || model?.maps?.[0]?.map || "Current Map Pool";

  const fallbacks = {
    performance: [
      {
        tone: matchesPlayed ? "warn" : "neutral",
        mediaType: "map",
        mediaValue: mapLabel,
        kicker: "Performance",
        title: "Match Insights",
        value: matchesPlayed ? `${matchesPlayed} matches tracked` : "Waiting for matches",
        detail: matchesPlayed ? "Current performance reads are built from imported match outcomes and stat trends." : "Import or log matches to unlock KD, win-rate, and map-performance reads."
      }
    ],
    behavior: [
      {
        tone: "warn",
        mediaType: "text",
        mediaText: "Logs",
        kicker: "Session Habits",
        title: "Log Reads",
        value: focusLabel,
        detail: "Log reads connect your focus category, mood, rating, comms, and notes into coaching patterns."
      }
    ],
    role: [
      {
        tone: "warn",
        mediaType: "role",
        mediaValue: roleLabel,
        kicker: "Role Results",
        title: "Role Reads",
        value: String(roleLabel || "Role").replace(/^\w/, char => char.toUpperCase()),
        detail: "Role reads compare how your current role is converting fights, utility, and round impact."
      }
    ],
    consistency: [
      {
        tone: "warn",
        mediaType: "text",
        mediaText: "Flow",
        kicker: "Consistency",
        title: "Consistency Reads",
        value: matchesPlayed ? "Pattern building" : "Needs more samples",
        detail: "Consistency reads look for repeated swings across matches, logs, focus categories, and recent form."
      }
    ]
  };

  return fallbacks[String(key || "").toLowerCase()] || [{
    tone: "neutral",
    mediaText: "Read",
    kicker: "Coaching",
    title: "Coaching Read",
    value: "Needs more games",
    detail: "This section fills as RankedCoach collects more profile context."
  }];
}

function buildPerformanceTrendDetailTabs(trend = {}, model = {}) {
  const proofItems = Array.isArray(trend?.proofItems) && trend.proofItems.length
    ? trend.proofItems
    : [statItem("Proof", "No proof items yet", "This read needs more imported context before it can show proof items.")];

  return [
    {
      key: "summary",
      label: "Summary",
      items: [
        statItem("Outcome", trend?.value || "--", trend?.detail || "Current displayed performance outcome."),
        statItem("Read", trend?.read || trend?.detail || "No coaching read available yet.", trend?.read || trend?.detail || "No coaching read available yet."),
        statItem("Source Window", trend?.sourceLabel || `${safeNumber(model?.overview?.matchesPlayed)} imported matches`, trend?.sourceLabel || "Current imported profile window.")
      ]
    },
    {
      key: "proof",
      label: "Proof",
      items: proofItems
    },
    {
      key: "formula",
      label: "Formula",
      items: [
        statItem("Formula", trend?.formula || "No formula available yet.", trend?.formula || "No formula available yet."),
        statItem("Benchmark", trend?.benchmark || "No benchmark available yet.", trend?.benchmark || "No benchmark available yet."),
        statItem("Tone", getSignalToneMeta(trend?.tone).label, "Card tone is assigned from the current benchmark and imported profile values.")
      ]
    }
  ];
}

function openStatsDetailModal(kind, value) {
  const modal = document.getElementById("lensModal");
  const title = document.getElementById("lensModalTitleSecondary");
  const list = document.getElementById("lensStatsListSecondary");
  const tabsHost = document.getElementById("lensDetailTabsSecondary");
  const analytics = getPlayerModel();
  const scopedStats = getScopedStatsData();
  if (!modal || !title || !list || !tabsHost) return;

  const items = [];
  tabsHost.innerHTML = "";
  tabsHost.style.display = "none";

  if (kind === "map") {
    const map = (analytics?.maps || []).find(item => String(item.map || "").toLowerCase() === String(value || "").toLowerCase());
    const coach = buildCoachRecommendation("map", map, analytics);
    title.textContent = `${value} Map Pattern`;
    items.push(statItem("Diagnosis", coach.diagnosis, "Coaching read built from map performance and sample size."));
    items.push(statItem("Priority", analytics?.priorityLabel || "Watch", "Shared coaching priority based on current top issue severity."));
    items.push(statItem("Recommendation", coach.recommendation, "Next-step recommendation translated from the current map trend."));
    items.push(statItem("Win Rate", map ? formatPercent(safeDivide(safeNumber(map.matchesWon), safeNumber(map.matchesPlayed)) * 100) : "--", map ? `matchesWon / matchesPlayed on ${value} = ${safeNumber(map.matchesWon)} / ${safeNumber(map.matchesPlayed)}` : "No imported map segment."));
    items.push(statItem("Agent", map?.agent || "--", "Highest-usage agent tied to this imported map segment."));
    items.push(statItem("Role", agentRoles?.[map?.agent] || "--", "Role derived from the roster mapping for the listed agent."));
    items.push(...getMapEconomyStatItems(value, scopedStats.matches));
  } else if (kind === "agent") {
    title.textContent = `${value} Agent Review`;
    renderSecondaryLensTabs(tabsHost, list, buildCalculatedAgentDetailTabs(value, analytics));
    showModalById("lensModal");
    return;
    const agent = (analytics?.agents || []).find(item => String(item.agent || "").toLowerCase() === String(value || "").toLowerCase());
    const sampleMatch = (matches || []).find(match => String(match?.metadata?.agent || "").toLowerCase() === String(value || "").toLowerCase());
    const roundExamples = sampleMatch?.advanced?.rounds || [];
    title.textContent = `${value} Agent Review`;
    items.push(["Role", agentRoles?.[value] || "--"]);
    items.push(["Win Rate", agent ? `${Math.round(safeNumber(agent.matchesWon) / Math.max(1, safeNumber(agent.matchesPlayed)) * 100)}%` : "--"]);
    items.push(["K/D", agent ? Number(agent.kd || 0).toFixed(2) : "--"]);
    items.push(["ADR", agent ? `${Math.round(agent.adr || 0)}` : "--"]);
    items.push(["Headshot %", agent ? `${Math.round(agent.hs || 0)}%` : "--"]);
    items.push(["Kills", agent ? `${Math.round(agent.kills || 0)}` : "--"]);
    items.push(["Deaths", agent ? `${Math.round(agent.deaths || 0)}` : "--"]);
    roundExamples.slice(0, 2).forEach(round => {
      items.push([`Reported Round ${round.round}`, `${round.weapon} | ${round.utility} | ${round.utilityPattern}`]);
    });
  } else if (kind === "breakdown") {
    const card = (analytics?.breakdown || []).find(item => String(item?.label || "").toLowerCase() === String(value || "").toLowerCase()) || null;
    if (!card || isInsufficientDataReadCard(card)) return;
    const behaviorRole = /^behavior development$/i.test(String(card?.label || ""))
      ? getBehaviorRoleContext(analytics)
      : "";
    title.textContent = behaviorRole
      ? `${behaviorRole} Mood Pattern Review`
      : `${card.label || "Data Read"} Review`;
    renderSecondaryLensTabs(tabsHost, list, buildDataReadDetailTabs(card, analytics));
    showModalById("lensModal");
    return;
  } else if (kind === "trend") {
    const trend = (analytics?.trends || []).find(item => String(item?.id || "").toLowerCase() === String(value || "").toLowerCase()) || null;
    title.textContent = `${trend?.label || "Performance Read"} Breakdown`;
    renderSecondaryLensTabs(tabsHost, list, buildPerformanceTrendDetailTabs(trend || {}, analytics));
    showModalById("lensModal");
    return;
  } else if (kind === "weapon") {
    const exactWeapon = getStatsWeaponMeta(value);
    const normalizedTypeKey = normalizeStatsWeaponKey(value) === "sidearm" ? "pistol" : normalizeStatsWeaponKey(value);
    const weapon = exactWeapon
      ? null
      : summarizeWeaponRounds(scopedStats.matches).find(entry => normalizeStatsWeaponKey(entry.typeKey) === normalizedTypeKey) || null;
    title.textContent = exactWeapon
      ? `${exactWeapon.name} Weapon Breakdown`
      : `${weapon?.label || "Weapon"} Weapon Review`;
    renderSecondaryLensTabs(tabsHost, list, buildWeaponDetailTabs(value, scopedStats.matches));
    showModalById("lensModal");
    return;
  } else if (kind === "role") {
    title.textContent = `${value} Role Review`;
    renderSecondaryLensTabs(tabsHost, list, buildCalculatedRoleDetailTabs(value, analytics));
    showModalById("lensModal");
    return;
    const role = (analytics?.roles || []).find(item => String(item.role || "").toLowerCase() === String(value || "").toLowerCase());
    title.textContent = `${value} Role Review`;
    items.push(["Win Rate", role ? `${Math.round(safeNumber(role.matchesWon) / Math.max(1, safeNumber(role.matchesPlayed)) * 100)}%` : "--"]);
    items.push(["K/D", role ? Number(role.kd || 0).toFixed(2) : "--"]);
    items.push(["ADR", role ? `${Math.round(role.adr || 0)}` : "--"]);
    items.push(["Headshot %", role ? `${Math.round(role.hs || 0)}%` : "--"]);
    items.push(["Context", "Act-level role view modeled after the homepage impact pill."]);
  }

  renderSecondaryLensStats(list, items);

  showModalById("lensModal");
}

// ========================
// INSIGHTS: BEHAVIOR HELPERS
// ========================

function getRecentLogs(limit = 10) {
  if (!logEntries || !logEntries.length) return [];
  return logEntries.slice(-limit);
}

function avg(arr) {
  if (!arr.length) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

// ========================
// CALCULATE FOCUS PROGRESS
// ========================

function calculateFocusProgress() {
  if (!activeInsightFocus || !logEntries) return 0;

  const recent = logEntries.slice(-10);
  let matchesFocus = 0;

  const target = activeInsightFocus.toLowerCase();

  const map = {
    mental: ["tilt", "mental"],
    aim: ["aim", "crosshair"],
    consistency: ["consistency", "discipline"],
    "game sense": ["sense", "awareness"],
    "agent mastery": ["agent"],
    "role discipline": ["role"],
    "map awareness": ["map"]
  };

  const keys = map[target] || [target];

  recent.forEach((l) => {
    const f = (l.focus || "").toLowerCase();

    if (keys.some((k) => f.includes(k)) || f === target) {
      matchesFocus++;
    }
  });

  focusProgress = Math.min(100, (matchesFocus / focusProgressMax) * 100);
  return focusProgress;
}

