function installMobileHomePullToRefresh() {
  if (!isMobileLayoutViewport() || mobilePullRefreshState?.installed) return;
  const root = document.querySelector(".app-root") || document.documentElement;
  if (!root) return;

  let startY = 0;
  let pulling = false;
  let distance = 0;
  let indicator = document.getElementById("mobilePullRefreshIndicator");
  if (!indicator) {
    indicator = document.createElement("div");
    indicator.id = "mobilePullRefreshIndicator";
    indicator.className = "mobile-pull-refresh-indicator";
    indicator.textContent = "Pull to refresh";
    document.body.appendChild(indicator);
  }

  const resetPull = () => {
    pulling = false;
    distance = 0;
    indicator.classList.remove("is-visible", "is-ready", "is-refreshing");
    indicator.style.setProperty("--pull-progress", "0");
  };

  root.addEventListener("touchstart", (event) => {
    if (!isMobileLayoutViewport()) return;
    if (getActivePageElement()?.id !== "page-home") return;
    const scrollTop = root.scrollTop || document.documentElement.scrollTop || 0;
    if (scrollTop > 2) return;
    startY = event.touches?.[0]?.clientY || 0;
    pulling = true;
    distance = 0;
  }, { passive: true });

  root.addEventListener("touchmove", (event) => {
    if (!pulling) return;
    const currentY = event.touches?.[0]?.clientY || 0;
    distance = Math.max(0, currentY - startY);
    if (distance < 12) return;
    const progress = Math.min(1, distance / 88);
    indicator.classList.add("is-visible");
    indicator.classList.toggle("is-ready", progress >= 1);
    indicator.textContent = progress >= 1 ? "Release to refresh" : "Pull to refresh";
    indicator.style.setProperty("--pull-progress", String(progress));
  }, { passive: true });

  root.addEventListener("touchend", () => {
    if (!pulling) return;
    const shouldRefresh = distance >= 88;
    resetPull();
    if (shouldRefresh) {
      indicator.classList.add("is-visible", "is-refreshing");
      indicator.textContent = "Refreshing...";
      void forceRefreshActiveProfile("pull").finally(() => {
        window.setTimeout(resetPull, 450);
      });
    }
  }, { passive: true });

  mobilePullRefreshState = { installed: true };
}

function ensureManualSessionStartModal() {
  let modal = document.getElementById("manualSessionStartModal");
  if (modal) return modal;

  modal = document.createElement("div");
  modal.id = "manualSessionStartModal";
  modal.className = "lens-modal-overlay manual-session-start-overlay";
  modal.setAttribute("aria-hidden", "true");
  modal.style.display = "none";
  modal.innerHTML = `
    <div class="lens-modal manual-session-start-modal" role="dialog" aria-modal="true" aria-labelledby="manualSessionStartTitle">
      <div class="lens-modal-head">
        <div>
          <div class="lens-modal-kicker">Manual Entry Session</div>
          <div id="manualSessionStartTitle" class="lens-modal-title">Set today's starting RR</div>
        </div>
      </div>
      <div class="manual-session-start-copy">
        Enter your RR inside your current rank before the first manual match of the day. RankedCoach uses this to keep RR to next rank and RR to goal rank accurate.
      </div>
      <label class="manual-session-start-field" for="manualSessionStartRRInput">
        <span>Current rank RR before game 1</span>
        <input id="manualSessionStartRRInput" type="number" min="0" step="1" inputmode="numeric">
      </label>
      <div class="manual-session-start-actions">
        <button id="manualSessionStartCancel" type="button">Cancel</button>
        <button id="manualSessionStartConfirm" type="button">Start Manual Session</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  return modal;
}

function openManualSessionStartPrompt() {
  const profile = getActiveProfile?.();
  if (!profile) return Promise.resolve(false);

  const modal = ensureManualSessionStartModal();
  const input = modal.querySelector("#manualSessionStartRRInput");
  const confirm = modal.querySelector("#manualSessionStartConfirm");
  const cancel = modal.querySelector("#manualSessionStartCancel");
  const close = modal.querySelector("#manualSessionStartClose");
  const currentAbsolute = Math.max(0, Math.round(safeNumber(getFreshCurrentRRAbsolute(profile), 0)));
  const currentRank = getTierRank(currentAbsolute) || RANK_THRESHOLDS[0];

  if (input) {
    input.value = String(getRankLocalRRForAbsoluteRR(currentAbsolute, currentRank));
    input.min = "0";
    input.dataset.rankLabel = currentRank.tierLabel;
  }

  return new Promise((resolve) => {
    let settled = false;
    const finish = (confirmed) => {
      if (settled) return;
      settled = true;
      modal.removeEventListener("click", onOverlayClick);
      confirm?.removeEventListener("click", onConfirm);
      cancel?.removeEventListener("click", onCancel);
      close?.removeEventListener("click", onCancel);
      hideModalById("manualSessionStartModal");
      resolve(Boolean(confirmed));
    };

    const onConfirm = (event) => {
      event.preventDefault();
      event.stopPropagation();
      const currentRankLabel = input?.dataset.rankLabel || currentRank.tierLabel;
      const enteredRR = Math.max(0, Math.round(safeNumber(input?.value, getRankLocalRRForAbsoluteRR(currentAbsolute, currentRank))));
      const startingRR = getAbsoluteRRForRankLocalRR(currentRankLabel, enteredRR);
      profile.startingRR = startingRR;
      profile.startingRRDate = getCurrentDayKey();
      profile.startingRRSource = "manual-session";
      saveProfiles?.();
      recomputeFromMatches?.();
      updateNavRRToRank?.();
      updateNavRRToGoalRank?.();
      updateDisplays?.();
      updateProfileHeaderUI?.();
      finish(true);
    };

    const onCancel = (event) => {
      event?.preventDefault?.();
      event?.stopPropagation?.();
      finish(false);
    };

    const onOverlayClick = (event) => {
      if (event.target === modal) onCancel(event);
    };

    confirm?.addEventListener("click", onConfirm);
    cancel?.addEventListener("click", onCancel);
    close?.addEventListener("click", onCancel);
    modal.addEventListener("click", onOverlayClick);
    showModalById("manualSessionStartModal");
    window.requestAnimationFrame(() => input?.focus());
  });
}

function readManualNumber(id, fallback = null) {
  const raw = document.getElementById(id)?.value;
  if (raw == null || String(raw).trim() === "") return fallback;
  const value = Number(raw);
  return Number.isFinite(value) ? value : fallback;
}

function getManualReportValues() {
  if (!isManualEntryModeEnabled()) return null;

  const result = String(document.getElementById("manualResult")?.value || "draw").toLowerCase();
  const rr = readManualNumber("manualRR", 0);

  return {
    result: ["win", "loss", "draw"].includes(result) ? result : "draw",
    rr: safeNumber(rr),
    roundsWon: readManualNumber("manualRoundsWon", null),
    roundsLost: readManualNumber("manualRoundsLost", null),
    kills: readManualNumber("manualKills", 0),
    deaths: readManualNumber("manualDeaths", 0),
    assists: readManualNumber("manualAssists", 0),
    acs: readManualNumber("manualACS", 0),
    adr: readManualNumber("manualADR", 0),
    hs: readManualNumber("manualHS", 0),
    pendingVerification: true
  };
}

function setManualReportFormValues(report = null) {
  const values = report || {};
  const assign = (id, value) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.value = value == null ? "" : String(value);
  };

  assign("manualResult", values.result || "win");
  assign("manualRR", values.rr);
  assign("manualRoundsWon", values.roundsWon);
  assign("manualRoundsLost", values.roundsLost);
  assign("manualKills", values.kills);
  assign("manualDeaths", values.deaths);
  assign("manualAssists", values.assists);
  assign("manualACS", values.acs);
  assign("manualADR", values.adr);
  assign("manualHS", values.hs);
}

function resetManualReportForm() {
  setManualReportFormValues({
    result: "win",
    rr: "",
    roundsWon: "",
    roundsLost: "",
    kills: "",
    deaths: "",
    assists: "",
    acs: "",
    adr: "",
    hs: ""
  });
}

function buildManualMatchFromLogEntry(entry = {}) {
  const schemaAdapter = window.RankedCoachMatchRecord;
  if (schemaAdapter?.fromManualLogEntry && schemaAdapter?.toLegacyMatch) {
    const record = schemaAdapter.fromManualLogEntry(entry);
    const legacyMatch = schemaAdapter.toLegacyMatch(record);
    return {
      ...legacyMatch,
      manualReport: {
        ...(legacyMatch.manualReport || {}),
        ...(entry.manualReport || entry.manual || {})
      },
      advanced: {
        ...(legacyMatch.advanced || {}),
        manual: true
      }
    };
  }

  const manual = entry.manualReport || entry.manual || {};
  const createdAt = entry.createdAt || nowISO();
  const result = ["win", "loss", "draw"].includes(String(manual.result || "").toLowerCase())
    ? String(manual.result).toLowerCase()
    : "draw";
  const rr = safeNumber(manual.rr, result === "win" ? 18 : result === "loss" ? -16 : 0);
  const agent = String(entry.agent || "").trim() || "Unknown";
  const mapName = String(entry.map || "").trim() || "Unknown";
  const matchId = entry.matchId || `manual-${entry.id || uuid()}`;

  return {
    id: matchId,
    matchId,
    source: "manual",
    manual: true,
    pendingVerification: true,
    rr,
    result,
    createdAt,
    agent,
    map: mapName,
    metadata: {
      id: matchId,
      matchId,
      manualLogId: entry.id,
      agent,
      mapName,
      result,
      playedAt: createdAt,
      source: "manual"
    },
    segments: [{
      type: "overview",
      stats: {
        kills: { value: safeNumber(manual.kills) },
        deaths: { value: safeNumber(manual.deaths) },
        assists: { value: safeNumber(manual.assists) },
        scorePerRound: { value: safeNumber(manual.acs) },
        damagePerRound: { value: safeNumber(manual.adr) },
        headshotsPercentage: { value: safeNumber(manual.hs) }
      }
    }],
    manualReport: {
      ...manual,
      result,
      rr,
      roundsWon: manual.roundsWon == null ? null : safeNumber(manual.roundsWon),
      roundsLost: manual.roundsLost == null ? null : safeNumber(manual.roundsLost)
    },
    advanced: {
      manual: true,
      roundsWon: manual.roundsWon == null ? null : safeNumber(manual.roundsWon),
      roundsLost: manual.roundsLost == null ? null : safeNumber(manual.roundsLost)
    }
  };
}

function upsertManualMatchForLogEntry(entry = {}) {
  if (!entry?.manualReport && !entry?.manual) return null;

  const profile = getActiveProfile?.();
  if (!profile) return null;

  const manualMatch = buildManualMatchFromLogEntry(entry);
  entry.matchId = manualMatch.matchId;
  entry.manualMatchId = manualMatch.matchId;

  const existing = Array.isArray(matches) ? matches : [];
  matches = existing
    .filter(match => String(match?.metadata?.manualLogId || match?.manualLogId || "") !== String(entry.id))
    .concat(manualMatch)
    .sort((a, b) => new Date(a?.createdAt || 0).getTime() - new Date(b?.createdAt || 0).getTime());

  profile.matches = matches.slice();
  profile.importSource = profile.importSource || "manual";
  profile.lastManualEntryAt = nowISO();
  saveProfiles?.();
  recomputeFromMatches?.();
  return manualMatch.matchId;
}

