function showToast(message, options = {}) {
  const stack = document.getElementById("appToastStack");
  if (!stack || !message) return;
  const toast = document.createElement("div");
  const title = String(options.title || "").trim();
  const iconUrl = String(options.iconUrl || "").trim();
  const durationMs = Math.max(1800, Math.min(4200, safeNumber(options.durationMs) || 2600));
  toast.className = "app-toast";
  toast.dataset.variant = String(options.variant || "default");
  toast.dataset.toastId = String(++appToastCounter);
  toast.setAttribute("role", "status");
  toast.innerHTML = `
    ${iconUrl ? `<img class="app-toast-icon" src="${escapeHtml(iconUrl)}" alt="">` : ""}
    <div class="app-toast-copy-wrap">
      ${title ? `<div class="app-toast-title">${escapeHtml(title)}</div>` : ""}
      <div class="app-toast-copy">${escapeHtml(message)}</div>
    </div>
  `;
  stack.appendChild(toast);
  window.requestAnimationFrame(() => toast.classList.add("is-visible"));
  const dismiss = () => {
    toast.classList.add("is-leaving");
    window.setTimeout(() => toast.remove(), 220);
  };
  window.setTimeout(dismiss, durationMs);
}

function triggerPremiumMoment(kind = "result", options = {}) {
  const overlay = document.getElementById("premiumMomentOverlay");
  if (!overlay || document.body?.classList.contains("access-reduced-motion")) return;
  const { variant } = getPremiumFeedbackTheme();
  if (!isMobileLayoutViewport() || variant === "default") return;
  clearTimeout(premiumMomentTimer);
  overlay.hidden = false;
  overlay.className = "premium-moment-overlay";
  overlay.dataset.variant = variant;
  overlay.dataset.kind = String(kind || "result");
  overlay.dataset.result = String(options.result || "");
  void overlay.offsetWidth;
  overlay.classList.add("is-active");
  premiumMomentTimer = window.setTimeout(() => {
    overlay.classList.remove("is-active");
    overlay.hidden = true;
  }, 980);
}

function pulsePremiumAvatarCelebration() {
  if (document.body?.classList.contains("access-reduced-motion")) return;
  const targets = [
    document.getElementById("profileAvatarWrap"),
    document.querySelector(".profile-avatar-ring"),
    document.getElementById("mobileHeaderProfileBtn")
  ].filter(Boolean);
  if (!targets.length) return;
  clearTimeout(premiumAvatarCelebrateTimer);
  targets.forEach((target) => target.classList.add("is-premium-celebrating"));
  premiumAvatarCelebrateTimer = window.setTimeout(() => {
    targets.forEach((target) => target.classList.remove("is-premium-celebrating"));
  }, 920);
}

function updatePeakRankAfterMatchSave(profile = getActiveProfile()) {
  const activeProfile = profile || getActiveProfile();
  if (!activeProfile?.id) {
    return { isNewPeak: false, peakData: computePeakProfileProgress(activeProfile) };
  }
  const peakData = computePeakProfileProgress(activeProfile);
  const nextPeakRR = safeNumber(peakData?.peakRR);
  const previousPeakRR = safeNumber(activeProfile?.peakRR);
  const hasPreviousPeak = previousPeakRR > 0;
  const shouldPersistPeak = nextPeakRR > previousPeakRR || !hasPreviousPeak;
  const isNewPeak = hasPreviousPeak && nextPeakRR > previousPeakRR;
  if (shouldPersistPeak) {
    updateProfile(activeProfile.id, { peakRR: nextPeakRR });
  }
  return {
    isNewPeak,
    peakData: { ...peakData, peakRR: nextPeakRR },
    previousPeakRR
  };
}

function onMatchSaved(record, options = {}) {
  const importedCount = Math.max(1, Math.round(safeNumber(options.importedCount) || 1));
  const { variant } = getPremiumFeedbackTheme();
  const hasPeakEventOverride = Boolean(options.peakData) || options.isNewPeak != null;
  const peakEvent = hasPeakEventOverride
    ? {
        isNewPeak: Boolean(options.isNewPeak),
        peakData: options.peakData || computePeakProfileProgress(getActiveProfile())
      }
    : updatePeakRankAfterMatchSave(options.profile || getActiveProfile());
  const peakData = peakEvent.peakData || computePeakProfileProgress(getActiveProfile());
  const result = String(record?.result || record?.metadata?.result || "").trim().toLowerCase();
  if (peakEvent.isNewPeak) {
    showToast(`Peak reached: ${peakData?.tierLabel || "New personal best"}.`, {
      title: "New peak rank!",
      iconUrl: peakData?.rankIconUrl || "",
      variant
    });
    triggerPremiumMoment("peak", { result });
    pulsePremiumAvatarCelebration();
    scheduleProfileStreakAnnouncement(1150);
    return;
  }
  const title = importedCount > 1 ? "History updated" : "Match saved";
  const message = importedCount > 1
    ? `${importedCount} matches imported into this profile.`
    : "Match report saved to this profile.";
  showToast(message, { title, variant });
  if (result === "win" || result === "loss") {
    triggerPremiumMoment("result", { result });
  }
  scheduleProfileStreakAnnouncement(1150);
}

function getCanonicalMatchRecordCount() {
  return window.RankedCoachMatchRecord?.getRuntimeRecords?.({
    matches,
    logEntries: getProfileLogEntries(activeProfileId, { authoredOnly: true }),
    profile: getActiveProfile()
  })?.length || 0;
}

const COACH_READINESS_UNLOCKS = [
  { key: "match-impact", label: "Post-match impact", requiredMatches: 1 },
  { key: "recent-trends", label: "Recent trends", requiredCurrentSeasonMatches: 5 },
  { key: "stats-confidence", label: "Stats confidence", requiredCurrentSeasonMatches: 10 },
  { key: "deep-insights", label: "Deep insights", requiredMatches: 20, requiredCurrentSeasonMatches: 10, requiredLogs: 5 }
];

function getCoachReadinessModel() {
  const profile = getActiveProfile();
  const matchCount = getCanonicalMatchRecordCount();
  const authoredLogCount = getProfileLogEntries(activeProfileId, { authoredOnly: true }).length;
  const profileMatches = Array.isArray(profile?.matches) ? profile.matches : [];
  const currentSeasonLabel = normalizeValorantSeasonLabel(profile?.trackerAnalytics?.currentAct || CURRENT_VALORANT_SEASON_LABEL);
  const currentSeasonMatchCount = profileMatches.filter(match => getMatchSeasonLabel(match) === currentSeasonLabel).length;
  const recentMatches = getSortedMatches(profileMatches).slice(-20);
  const completeMatches = recentMatches.filter(match => {
    const core = getMatchCore(match);
    return core.map && core.map !== "Unknown"
      && core.agent && core.agent !== "Unknown"
      && Number.isFinite(Number(core.kills))
      && Number.isFinite(Number(core.deaths))
      && ["win", "loss", "draw"].includes(String(core.result || "").toLowerCase());
  }).length;
  const historyProgress = Math.min(1, matchCount / 20);
  const currentSeasonProgress = Math.min(1, currentSeasonMatchCount / 10);
  const reflectionProgress = Math.min(1, authoredLogCount / 5);
  const completenessProgress = recentMatches.length ? completeMatches / recentMatches.length : 0;
  const percent = Math.round(
    (historyProgress * 40)
    + (currentSeasonProgress * 25)
    + (reflectionProgress * 25)
    + (completenessProgress * 10)
  );
  const unlocks = COACH_READINESS_UNLOCKS.map(item => {
    const requirements = [];
    if (item.requiredMatches) {
      requirements.push({ current: matchCount, required: item.requiredMatches, label: "games" });
    }
    if (item.requiredCurrentSeasonMatches) {
      requirements.push({ current: currentSeasonMatchCount, required: item.requiredCurrentSeasonMatches, label: "season" });
    }
    if (item.requiredLogs) {
      requirements.push({ current: authoredLogCount, required: item.requiredLogs, label: "logs" });
    }
    const complete = requirements.every(requirement => requirement.current >= requirement.required);
    const progress = requirements.length
      ? Math.min(...requirements.map(requirement => Math.min(100, Math.round((requirement.current / requirement.required) * 100))))
      : 0;
    const progressLabel = requirements
      .filter(requirement => requirement.current < requirement.required)
      .map(requirement => `${Math.min(requirement.current, requirement.required)}/${requirement.required} ${requirement.label}`)
      .join(" · ");
    return { ...item, complete, progress, progressLabel };
  });
  const nextUnlock = unlocks.find(item => !item.complete);
  const unlocked = unlocks.filter(item => item.complete);
  const copyParts = [`${matchCount} ranked matches imported`];
  copyParts.push(`${currentSeasonMatchCount}/10 current-season matches`);
  copyParts.push(`${authoredLogCount}/5 reflection logs`);
  const copy = nextUnlock
    ? `${copyParts.join(". ")}. Next: ${nextUnlock.label} (${nextUnlock.progressLabel}).`
    : `${copyParts.join(". ")}. Match-driven reads are unlocked; rating grows with current-season play and your own reflections.`;
  return {
    matchCount,
    authoredLogCount,
    currentSeasonMatchCount,
    completenessProgress,
    percent,
    copy,
    nextUnlock,
    unlocked,
    unlocks
  };
}

function getReadinessLockedMarkup(required, label) {
  const model = getCoachReadinessModel();
  const remaining = Math.max(0, required - model.matchCount);
  const progress = Math.min(100, Math.round((model.matchCount / Math.max(1, required)) * 100));
  return `
    <div class="coach-readiness-locked" data-required="${required}">
      <div class="coach-readiness-locked-title">${escapeHtml(label)}</div>
      <div class="coach-readiness-locked-copy">
        ${model.matchCount}/${required} games logged${remaining ? `. Add ${remaining} more to unlock this read.` : "."}
      </div>
      <div class="coach-readiness-locked-bar"><span style="--profile-progress:${progress};width:${progress}%"></span></div>
    </div>
  `;
}

function renderCoachReadinessUI() {
  const card = document.getElementById("coachReadinessCard");
  const widget = document.getElementById("profileRatingWidget");
  if (!card && !widget) return;
  const model = getCoachReadinessModel();

  const writeUnlocks = (target, options = {}) => {
    if (!target) return;
    target.innerHTML = model.unlocks.map(item => `
      <div class="profile-rating-unlock coach-readiness-unlock ${item.complete ? "is-complete" : "is-locked"}">
        <span>${escapeHtml(item.label)}</span>
        <strong>${item.complete ? "Unlocked" : escapeHtml(item.progressLabel)}</strong>
        <div class="coach-readiness-mini-bar"><span style="--profile-progress:${item.progress};width:${item.progress}%"></span></div>
      </div>
    `).join("") + (options.includeActivity ? buildProfileActivityHeatmapMarkup(getActiveProfile?.()) : "");
  };

  if (card) {
    const value = document.getElementById("coachReadinessValue");
    const copy = document.getElementById("coachReadinessCopy");
    const fill = document.getElementById("coachReadinessFill");
    const unlocks = document.getElementById("coachReadinessUnlocks");

    card.dataset.readinessPercent = String(model.percent);
    card.classList.toggle("is-ready", model.percent >= 100);
    if (value) value.textContent = `${model.percent}%`;
    if (copy) copy.textContent = model.copy;
    if (fill) {
      fill.style.setProperty("--profile-progress", String(model.percent));
      fill.style.width = `${model.percent}%`;
    }
    writeUnlocks(unlocks);
  }

  if (widget) {
    const widgetValue = document.getElementById("profileRatingValue");
    const dropdownValue = document.getElementById("profileRatingDropdownValue");
    const copy = document.getElementById("profileRatingCopy");
    const fill = document.getElementById("profileRatingFill");
    const unlocks = document.getElementById("profileRatingUnlocks");
    widget.dataset.readinessPercent = String(model.percent);
    widget.classList.toggle("is-ready", model.percent >= 100);
    if (widgetValue) widgetValue.textContent = `${model.percent}%`;
    if (dropdownValue) dropdownValue.textContent = `${model.percent}%`;
    if (copy) copy.textContent = model.copy;
    if (fill) {
      fill.style.setProperty("--profile-progress", String(model.percent));
      fill.style.width = `${model.percent}%`;
    }
    writeUnlocks(unlocks, { includeActivity: true });
  }

  writeMobileProfileRating?.(model);
  scheduleProfileStreakAnnouncement(1300);
}

function setProfileRatingDropdownOpen(open) {
  const widget = document.getElementById("profileRatingWidget");
  const dropdown = document.getElementById("profileRatingDropdown");
  if (!dropdown) return;
  const shouldOpen = Boolean(open);
  dropdown.hidden = !shouldOpen;
  dropdown.classList.toggle("open", shouldOpen);
  widget?.classList.toggle("open", shouldOpen);
  widget?.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
  if (shouldOpen) {
    positionProfileRatingDropdown();
  }
}

function positionProfileRatingDropdown() {
  const dropdown = document.getElementById("profileRatingDropdown");
  if (!dropdown || dropdown.hidden) return;

  if (isMobileLayoutViewport?.()) {
    ["position", "top", "left", "right", "width", "max-height"].forEach(property => {
      dropdown.style.removeProperty(property);
    });
    return;
  }

  const navRight = document.querySelector(".nav-right");
  const anchor = document.querySelector(".profile-rating-anchor");
  const rect = navRight?.getBoundingClientRect?.() || anchor?.getBoundingClientRect?.();
  if (!rect) return;

  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  const width = Math.min(340, Math.max(280, viewportWidth - 24));
  const left = Math.min(Math.max(8, rect.left), Math.max(8, viewportWidth - width - 8));
  const top = Math.min(Math.max(8, rect.bottom + 8), Math.max(8, viewportHeight - 220));

  dropdown.style.setProperty("position", "fixed", "important");
  dropdown.style.setProperty("left", `${left}px`, "important");
  dropdown.style.setProperty("right", "auto", "important");
  dropdown.style.setProperty("top", `${top}px`, "important");
  dropdown.style.setProperty("width", `${width}px`, "important");
  dropdown.style.setProperty("max-height", `${Math.max(220, viewportHeight - top - 12)}px`, "important");
}

function hasCompletedAppEntryChoice() {
  return Boolean(localStorage.getItem(APP_ENTRY_CHOICE_KEY));
}

function setAppEntryChoice(mode = "guest") {
  localStorage.setItem(APP_ENTRY_CHOICE_KEY, String(mode || "guest"));
}

function getRiotPromptDismissKey(user = currentAuthUser) {
  const identity = user?.id || user?.email || "guest";
  return `${RIOT_PROFILE_PROMPT_DISMISS_KEY}:${identity}`;
}

function activeProfileHasRiotId() {
  return Boolean(String(getActiveProfile?.()?.riotId || "").trim());
}

function setLoginInitializationProgress(percent = 0, copy = "", activeStep = "", detail = "") {
  const overlay = document.getElementById("loginInitOverlay");
  const bar = document.getElementById("loginInitProgressBar");
  const percentEl = document.getElementById("loginInitProgressPercent");
  const copyEl = document.getElementById("loginInitCopy");
  const detailEl = document.getElementById("loginInitDetail");
  const titleEl = document.getElementById("loginInitTitle");
  const nextPercent = Math.max(0, Math.min(100, Math.round(percent)));

  if (bar) bar.style.width = `${nextPercent}%`;
  if (percentEl) percentEl.textContent = `${nextPercent}%`;
  const progressEl = overlay?.querySelector?.(".login-init-progress");
  progressEl?.setAttribute("aria-valuenow", String(nextPercent));
  progressEl?.classList.toggle("is-busy", nextPercent > 0 && nextPercent < 100);
  if (copyEl && copy) copyEl.textContent = copy;
  if (detailEl) detailEl.textContent = detail || "";
  if (titleEl) titleEl.textContent = nextPercent >= 100 ? "You are ready" : "Warming up your account";

  const stepOrder = ["Profile", "Security", "Coach", "Ready"];
  const activeIndex = stepOrder.indexOf(activeStep);
  stepOrder.forEach((step, index) => {
    const el = document.getElementById(`loginInitStep${step}`);
    if (!el) return;
    el.classList.toggle("is-active", index === activeIndex);
    el.classList.toggle("is-complete", activeIndex >= 0 && index < activeIndex);
  });
}

function showLoginInitializationOverlay(copy = "", detail = "") {
  applyLoginInitializationTheme(getActiveProfile());
  setLoginInitializationProgress(
    6,
    copy || "Opening your RankedCoach account.",
    "Profile",
    detail || "Saved profiles with more matches and notes can take a little longer to load back in."
  );
  showModalById?.("loginInitOverlay");
}

function releaseInitialAppBootGuard() {
  document.documentElement?.classList.remove("app-booting");
  document.getElementById("loginInitOverlay")?.classList.remove("app-boot-overlay");
}

function hideLoginInitializationOverlay() {
  setLoginInitializationProgress(100, "Everything is ready.", "Ready", "Your saved profile, settings, and coaching pages are ready.");
  window.setTimeout(() => {
    releaseInitialAppBootGuard();
    hideModalById?.("loginInitOverlay");
    clearLoginInitializationTheme();
  }, 420);
}

function dismissLoginInitializationOverlay() {
  releaseInitialAppBootGuard();
  hideModalById?.("loginInitOverlay");
  clearLoginInitializationTheme();
}

function shouldShowRiotProfilePrompt(options = {}) {
  if (!currentAuthUser) return false;
  if (activeProfileHasRiotId()) return false;
  if (options.force) return true;
  return sessionStorage.getItem(getRiotPromptDismissKey()) !== "1";
}

function hideRiotProfilePrompt(options = {}) {
  const prompt = document.getElementById("riotProfilePrompt");
  if (prompt) prompt.hidden = true;
  if (options.persist) {
    sessionStorage.setItem(getRiotPromptDismissKey(), "1");
  }
}

function showRiotProfilePrompt(options = {}) {
  const prompt = document.getElementById("riotProfilePrompt");
  if (!prompt || !shouldShowRiotProfilePrompt(options)) {
    if (!options.force) hideRiotProfilePrompt();
    return;
  }
  prompt.hidden = false;
}

function refreshRiotProfilePrompt() {
  if (shouldShowRiotProfilePrompt()) {
    showRiotProfilePrompt();
  } else {
    hideRiotProfilePrompt();
  }
}

function openRiotProfileConfirmModal() {
  showModalById?.("riotProfileConfirmModal");
}

function closeRiotProfileConfirmModal() {
  hideModalById?.("riotProfileConfirmModal");
}

function beginRiotProfileLinkFlow() {
  closeRiotProfileConfirmModal();
  hideRiotProfilePrompt({ persist: true });
  openRiotModal?.();
}

function isLocalDevelopmentHost() {
  return /^(localhost|127\.0\.0\.1)$/i.test(window.location.hostname || "");
}

function sanitizeAccountName(value = "", fallback = "Guest") {
  const clean = String(value || "")
    .replace(/[^a-z0-9_-]/gi, "")
    .slice(0, 16);
  return clean || String(fallback || "Guest").slice(0, 16);
}

function isValidAccountUsername(value = "") {
  return /^[a-z0-9_-]{3,16}$/i.test(String(value || "").trim());
}

function getAccountSecurityMetadata(user = currentAuthUser) {
  return user?.user_metadata || {};
}

function isMissingAccountSecurityPreferencesError(error) {
  if (!error) return false;
  const text = [
    error.status,
    error.code,
    error.message,
    error.details,
    error.hint
  ].filter(Boolean).join(" ");
  return error.status === 404
    || /PGRST205/i.test(text)
    || /account_security_preferences/i.test(text)
    || /schema cache/i.test(text)
    || /\bNot Found\b/i.test(text);
}

function markAccountSecurityPreferencesUnavailable(error) {
  accountSecurityPreferencesBackendAvailable = false;
  if (!accountSecurityPreferencesMissingNoticeShown) {
    accountSecurityPreferencesMissingNoticeShown = true;
    console.info(
      "Account security preferences table is unavailable; using Supabase auth metadata fallback.",
      error?.message || error || ""
    );
  }
}

async function safeUpsertAccountSecurityPreferences(payload = {}, label = "Security preference save failed") {
  if (!accountSecurityPreferencesBackendAvailable || !supabaseClient?.from) return false;
  const userId = payload.user_id || currentAuthUser?.id;
  if (!userId) return false;

  const { error } = await supabaseClient
    .from("account_security_preferences")
    .upsert({
      ...payload,
      user_id: userId,
      updated_at: payload.updated_at || nowISO()
    }, { onConflict: "user_id" });

  if (!error) return true;
  if (isMissingAccountSecurityPreferencesError(error)) {
    markAccountSecurityPreferencesUnavailable(error);
    return false;
  }
  console.warn(label, error);
  return false;
}

function maskEmail(value = "") {
  const clean = String(value || "").trim();
  if (!clean || !clean.includes("@")) return "Not set";
  const [name, domain] = clean.split("@");
  const visibleName = name.slice(0, 2);
  return `${visibleName}${"*".repeat(Math.max(2, name.length - 2))}@${domain}`;
}

function maskPhone(value = "") {
  const clean = String(value || "").replace(/\D/g, "");
  if (!clean) return "Not set";
  return `${"*".repeat(Math.max(0, clean.length - 4))}${clean.slice(-4)}`;
}

function setSecurityTotpSetupVisibility(show = false) {
  const setup = document.getElementById("securityTotpSetup");
  if (setup) setup.hidden = !show;
}

function clearSecurityTotpEnrollment() {
  securityTotpEnrollment = null;
  const qr = document.getElementById("securityTotpQr");
  const code = document.getElementById("securityTotpCode");
  const secret = document.getElementById("securityTotpSecret");
  if (qr) qr.removeAttribute("src");
  if (code) code.value = "";
  if (secret) secret.textContent = "";
}

function setSecurityMfaMethodVisibility() {
  const mfaInput = document.getElementById("securityMfaEnabled");
  if (!mfaInput?.checked) {
    setSecurityTotpSetupVisibility(false);
    clearSecurityTotpEnrollment();
  }
}

function setSecurityRecoveryMasks(email = "", phone = "") {
  const emailMask = document.getElementById("securityRecoveryEmailMask");
  const phoneMask = document.getElementById("securityRecoveryPhoneMask");
  if (emailMask) emailMask.textContent = `Current: ${maskEmail(email)}`;
  if (phoneMask) phoneMask.textContent = `Current: ${maskPhone(phone)}`;
}

function resetSecuritySettingsFormForGuest() {
  const usernameInput = document.getElementById("securityUsernameInput");
  const recoveryEmailInput = document.getElementById("securityRecoveryEmailInput");
  const recoveryPhoneInput = document.getElementById("securityRecoveryPhoneInput");
  const mfaInput = document.getElementById("securityMfaEnabled");

  if (usernameInput) usernameInput.value = "";
  if (recoveryEmailInput) recoveryEmailInput.value = "";
  if (recoveryPhoneInput) recoveryPhoneInput.value = "";
  if (mfaInput) mfaInput.checked = false;
  setSecurityRecoveryMasks("", "");
  clearSecurityTotpEnrollment();
  setSecurityTotpSetupVisibility(false);
  setAuthStatus("securitySettingsStatus", "");
}

function populateSecuritySettingsModal() {
  const metadata = getAccountSecurityMetadata();
  const usernameInput = document.getElementById("securityUsernameInput");
  const recoveryEmailInput = document.getElementById("securityRecoveryEmailInput");
  const recoveryPhoneInput = document.getElementById("securityRecoveryPhoneInput");
  const mfaInput = document.getElementById("securityMfaEnabled");

  if (usernameInput) {
    usernameInput.value = getUserAccountName(currentAuthUser);
  }
  if (recoveryEmailInput) {
    recoveryEmailInput.value = metadata.recovery_email || "";
  }
  if (recoveryPhoneInput) {
    recoveryPhoneInput.value = metadata.recovery_phone || "";
  }
  if (mfaInput) {
    mfaInput.checked = Boolean(metadata.mfa_requested || metadata.mfa_enabled);
  }
  setSecurityRecoveryMasks(metadata.recovery_email || "", metadata.recovery_phone || "");
  setSecurityMfaMethodVisibility();
  setAuthStatus("securitySettingsStatus", "");
}

async function hydrateSecuritySettingsFromBackend() {
  if (!accountSecurityPreferencesBackendAvailable || !currentAuthUser || !supabaseClient?.from) return;
  const { data, error } = await supabaseClient
    .from("account_security_preferences")
    .select("recovery_email,recovery_phone,mfa_enabled,mfa_method")
    .eq("user_id", currentAuthUser.id)
    .maybeSingle();
  if (error) {
    if (isMissingAccountSecurityPreferencesError(error)) {
      markAccountSecurityPreferencesUnavailable(error);
    } else {
      console.warn("Security preference load failed", error);
    }
    return;
  }
  if (!data) return;

  const recoveryEmailInput = document.getElementById("securityRecoveryEmailInput");
  const recoveryPhoneInput = document.getElementById("securityRecoveryPhoneInput");
  const mfaInput = document.getElementById("securityMfaEnabled");
  if (recoveryEmailInput) recoveryEmailInput.value = data.recovery_email || recoveryEmailInput.value || "";
  if (recoveryPhoneInput) recoveryPhoneInput.value = data.recovery_phone || recoveryPhoneInput.value || "";
  if (mfaInput) mfaInput.checked = Boolean(data.mfa_enabled || currentAuthUser?.user_metadata?.mfa_requested);
  setSecurityRecoveryMasks(data.recovery_email || "", data.recovery_phone || "");
  setSecurityMfaMethodVisibility();
}

async function saveSecurityPreferenceRecord({
  recoveryEmail = "",
  recoveryPhone = "",
  mfaEnabled = false,
  source = "security_settings_modal"
} = {}) {
  await safeUpsertAccountSecurityPreferences({
    recovery_email: recoveryEmail || null,
    recovery_phone: recoveryPhone || null,
    mfa_enabled: Boolean(mfaEnabled),
    mfa_method: mfaEnabled ? "totp" : null,
    security_json: { source }
  });
}

async function getVerifiedTotpFactors() {
  const factors = await getVerifiedMfaFactors();
  return factors.filter(factor => getMfaFactorType(factor) === "totp");
}

async function refreshSecurityTotpState() {
  const mfaInput = document.getElementById("securityMfaEnabled");
  if (!currentAuthUser || !supabaseClient?.auth?.mfa) return;
  try {
    const verifiedTotp = await getVerifiedTotpFactors();
    if (mfaInput) mfaInput.checked = verifiedTotp.length > 0 || Boolean(currentAuthUser?.user_metadata?.mfa_requested);
    if (verifiedTotp.length > 0) {
      setSecurityTotpSetupVisibility(false);
      clearSecurityTotpEnrollment();
      setAuthStatus("securitySettingsStatus", "Authenticator app MFA is active for this account.");
    }
  } catch (error) {
    console.warn("Unable to refresh MFA state", error);
  }
}

async function startSecurityTotpEnrollment() {
  const mfaInput = document.getElementById("securityMfaEnabled");
  if (!currentAuthUser || !supabaseClient?.auth?.mfa?.enroll) {
    if (mfaInput) mfaInput.checked = false;
    setAuthStatus("securitySettingsStatus", "Log in before setting up authenticator MFA.");
    return;
  }

  const existingTotp = await getVerifiedTotpFactors();
  if (existingTotp.length) {
    setSecurityTotpSetupVisibility(false);
    setAuthStatus("securitySettingsStatus", "Authenticator app MFA is already active.");
    return;
  }
  if (getMfaFactorId(securityTotpEnrollment || {})) {
    setSecurityTotpSetupVisibility(true);
    setAuthStatus("securitySettingsStatus", "Scan the QR code already shown, then enter the 6-digit code from your authenticator app.");
    return;
  }

  clearSecurityTotpEnrollment();
  const { data, error } = await supabaseClient.auth.mfa.enroll({
    factorType: "totp",
    friendlyName: "RankedCoach"
  });
  if (error) {
    if (mfaInput) mfaInput.checked = false;
    throw error;
  }

  securityTotpEnrollment = data || null;
  const qr = document.getElementById("securityTotpQr");
  const code = document.getElementById("securityTotpCode");
  const secret = document.getElementById("securityTotpSecret");
  const qrCode = data?.totp?.qr_code || data?.totp?.qrCode || "";
  const secretText = data?.totp?.secret || "";
  if (qr && qrCode) qr.src = qrCode;
  if (secret) secret.textContent = secretText ? `Manual setup key: ${secretText}` : "";
  setSecurityTotpSetupVisibility(true);
  setAuthStatus("securitySettingsStatus", "Scan the QR code, then enter the 6-digit code from your authenticator app.");
  window.setTimeout(() => code?.focus(), 80);
}

async function verifySecurityTotpEnrollment() {
  const factorId = getMfaFactorId(securityTotpEnrollment || {});
  const code = String(document.getElementById("securityTotpCode")?.value || "").trim();
  if (!factorId) throw new Error("Start MFA setup first so RankedCoach can create the QR code.");
  if (!code) throw new Error("Enter the 6-digit code from your authenticator app.");

  const { error } = await supabaseClient.auth.mfa.challengeAndVerify({
    factorId,
    code
  });
  if (error) throw error;

  const mfaInput = document.getElementById("securityMfaEnabled");
  const recoveryEmail = document.getElementById("securityRecoveryEmailInput")?.value?.trim() || "";
  const recoveryPhone = document.getElementById("securityRecoveryPhoneInput")?.value?.trim() || "";
  if (mfaInput) mfaInput.checked = true;
  const { data, error: updateError } = await supabaseClient.auth.updateUser({
    data: {
      ...getAccountSecurityMetadata(),
      mfa_requested: false,
      mfa_enabled: true,
      mfa_method: "totp"
    }
  });
  if (updateError) throw updateError;
  currentAuthUser = data?.user || (await getSupabaseUser()) || currentAuthUser;
  await saveSecurityPreferenceRecord({
    recoveryEmail,
    recoveryPhone,
    mfaEnabled: true,
    source: "totp_enrollment"
  });
  clearSecurityTotpEnrollment();
  setSecurityTotpSetupVisibility(false);
  updateAuthUI?.(currentAuthUser);
  setAuthStatus("securitySettingsStatus", "Authenticator app MFA is active. You will be asked for a code on future logins.");
}

async function disableSecurityTotpMfa() {
  const recoveryEmail = document.getElementById("securityRecoveryEmailInput")?.value?.trim() || "";
  const recoveryPhone = document.getElementById("securityRecoveryPhoneInput")?.value?.trim() || "";
  const factors = await getVerifiedTotpFactors();
  for (const factor of factors) {
    const factorId = getMfaFactorId(factor);
    if (!factorId || !supabaseClient?.auth?.mfa?.unenroll) continue;
    const { error } = await supabaseClient.auth.mfa.unenroll({ factorId });
    if (error) throw error;
  }
  const { data, error } = await supabaseClient.auth.updateUser({
    data: {
      ...getAccountSecurityMetadata(),
      mfa_requested: false,
      mfa_enabled: false,
      mfa_method: null
    }
  });
  if (error) throw error;
  currentAuthUser = data?.user || (await getSupabaseUser()) || currentAuthUser;
  await saveSecurityPreferenceRecord({
    recoveryEmail,
    recoveryPhone,
    mfaEnabled: false,
    source: "totp_disabled"
  });
  clearSecurityTotpEnrollment();
  setSecurityTotpSetupVisibility(false);
  updateAuthUI?.(currentAuthUser);
  setAuthStatus("securitySettingsStatus", "Authenticator app MFA is disabled.");
}

function openSecuritySettingsModal() {
  if (!currentAuthUser) {
    openAuthModal?.();
    return;
  }
  openAccountSupportModal("account");
}

function closeSecuritySettingsModal() {
  closeAccountSupportModal();
}

async function saveSecuritySettingsModal() {
  if (!currentAuthUser || !supabaseClient?.auth) {
    setAuthStatus("securitySettingsStatus", "Log in to change security settings.");
    return;
  }

  const username = sanitizeAccountName(document.getElementById("securityUsernameInput")?.value || "", "");
  const recoveryEmail = document.getElementById("securityRecoveryEmailInput")?.value?.trim() || "";
  const recoveryPhone = document.getElementById("securityRecoveryPhoneInput")?.value?.trim() || "";
  const mfaEnabled = Boolean(document.getElementById("securityMfaEnabled")?.checked);

  if (!isValidAccountUsername(username)) {
    setAuthStatus("securitySettingsStatus", "Username must be 3-16 characters and use only letters, numbers, underscores, or dashes.");
    return;
  }

  const saveBtn = document.getElementById("securitySettingsSave");
  const restoreButton = setAuthButtonLoading(saveBtn, "Saving...");

  try {
    const verifiedTotp = await getVerifiedTotpFactors();
    if (mfaEnabled && !verifiedTotp.length) {
      setAuthStatus("securitySettingsStatus", "Finish the authenticator QR setup before saving MFA as enabled.");
      await startSecurityTotpEnrollment();
      return;
    }

    const { data, error } = await supabaseClient.auth.updateUser({
      data: {
        ...getAccountSecurityMetadata(),
        account_name: username,
        recovery_email: recoveryEmail || null,
        recovery_phone: recoveryPhone || null,
        mfa_requested: false,
        mfa_enabled: mfaEnabled,
        mfa_method: mfaEnabled ? "totp" : null
      }
    });
    if (error) throw error;
    currentAuthUser = data?.user || (await getSupabaseUser()) || currentAuthUser;

    await saveSecurityPreferenceRecord({
      recoveryEmail,
      recoveryPhone,
      mfaEnabled,
      source: "security_settings_modal"
    });

    updateAuthUI?.(currentAuthUser);
    updateProfileHeaderUI?.();
    setSecurityRecoveryMasks(recoveryEmail, recoveryPhone);
    queuePersistentAccountSave?.("security-settings");
    setAuthStatus("securitySettingsStatus", "Security settings saved.");
  } catch (error) {
    setAuthStatus("securitySettingsStatus", error?.message || "Unable to save security settings.");
  } finally {
    restoreButton();
  }
}

function getUserAccountName(user = currentAuthUser) {
  const metadata = user?.user_metadata || {};
  const raw = metadata.account_name
    || metadata.name
    || metadata.full_name
    || String(user?.email || "").split("@")[0]
    || "Guest";
  return sanitizeAccountName(raw, "User");
}

function createGuestProfileRecord() {
  return normalizeProfileRecord({
    id: uuid(),
    name: "Guest",
    accountName: "Guest",
    riotId: "",
    region: "NA",
    startingRR: 0,
    matches: [],
    manualEntryMode: false,
    themeKey: getActiveProfile?.()?.themeKey || "default",
    frameTheme: getActiveProfile?.()?.frameTheme || "default",
    avatarAgent: getDefaultProfileAvatarAgent?.() || "jett",
    avatarUrl: getDefaultProfileAvatarUrl?.() || ""
  });
}

let appLoadingVeilDepth = 0;

function ensureAppLoadingVeil() {
  let veil = document.getElementById("appLoadingVeil");
  if (veil) return veil;
  veil = document.createElement("div");
  veil.id = "appLoadingVeil";
  veil.className = "app-loading-veil";
  veil.setAttribute("aria-live", "polite");
  veil.setAttribute("aria-hidden", "true");
  veil.innerHTML = `
    <div class="app-loading-card">
      <div class="app-loading-mark">RC</div>
      <div class="app-loading-title" id="appLoadingTitle">Loading RankedCoach</div>
      <div class="app-loading-copy" id="appLoadingCopy">Preparing your dashboard...</div>
      <div class="app-loading-progress-meta"><span id="appLoadingProgressLabel">Loading</span><strong id="appLoadingPercent">0%</strong></div>
      <div class="app-loading-bar" id="appLoadingProgress" role="progressbar" aria-label="Loading progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span id="appLoadingProgressBar"></span></div>
    </div>
  `;
  document.body?.appendChild(veil);
  return veil;
}

function setAppLoadingVeilProgress(percent = 0, message = "") {
  const nextPercent = Math.max(0, Math.min(100, Math.round(safeNumber(percent))));
  const progress = document.getElementById("appLoadingProgress");
  const bar = document.getElementById("appLoadingProgressBar");
  const percentEl = document.getElementById("appLoadingPercent");
  if (bar) bar.style.width = `${nextPercent}%`;
  if (percentEl) percentEl.textContent = `${nextPercent}%`;
  progress?.setAttribute("aria-valuenow", String(nextPercent));
  if (message) setAppLoadingVeilMessage(message);
}

function showAppLoadingVeil(message = "Preparing your dashboard...", options = {}) {
  const veil = ensureAppLoadingVeil();
  appLoadingVeilDepth += 1;
  const title = document.getElementById("appLoadingTitle");
  const progressLabel = document.getElementById("appLoadingProgressLabel");
  const copy = document.getElementById("appLoadingCopy");
  if (title) title.textContent = options.title || "Loading RankedCoach";
  if (progressLabel) progressLabel.textContent = options.progressLabel || "Loading";
  if (copy) copy.textContent = message;
  setAppLoadingVeilProgress(options.percent ?? 8);
  veil.hidden = false;
  veil.setAttribute("aria-hidden", "false");
  veil.classList.add("is-visible");
  document.body?.classList.add("app-loading-active");
}

function setAppLoadingVeilMessage(message = "Preparing your dashboard...") {
  const copy = document.getElementById("appLoadingCopy");
  if (copy) copy.textContent = message;
}

function hideAppLoadingVeil({ force = false } = {}) {
  appLoadingVeilDepth = force ? 0 : Math.max(0, appLoadingVeilDepth - 1);
  if (appLoadingVeilDepth > 0) return;
  const veil = document.getElementById("appLoadingVeil");
  if (!veil) return;
  veil.classList.remove("is-visible");
  veil.setAttribute("aria-hidden", "true");
  document.body?.classList.remove("app-loading-active");
  window.setTimeout(() => {
    if (!veil.classList.contains("is-visible")) veil.hidden = true;
  }, 260);
}

async function withAppLoadingVeil(message = "Preparing your dashboard...", task = async () => {}) {
  showAppLoadingVeil(message, { percent: 8 });
  const startedAt = Date.now();
  try {
    return await task();
  } finally {
    const remaining = Math.max(0, 520 - (Date.now() - startedAt));
    window.setTimeout(() => {
      setAppLoadingVeilProgress(100);
      hideAppLoadingVeil();
    }, remaining);
  }
}

let profileDeleteConfirmResolver = null;

function ensureProfileDeleteConfirmModal() {
  let modal = document.getElementById("profileDeleteConfirmModal");
  if (modal) return modal;

  modal = document.createElement("div");
  modal.id = "profileDeleteConfirmModal";
  modal.className = "profile-delete-confirm-modal";
  modal.setAttribute("aria-hidden", "true");
  modal.hidden = true;
  modal.innerHTML = `
    <div class="profile-delete-confirm-card" role="dialog" aria-modal="true" aria-labelledby="profileDeleteConfirmTitle">
      <div class="profile-delete-confirm-kicker">Remove Profile</div>
      <h2 id="profileDeleteConfirmTitle">Remove this profile?</h2>
      <p id="profileDeleteConfirmCopy">This removes the selected profile from RankedCoach on this device.</p>
      <div class="profile-delete-confirm-actions">
        <button class="profile-delete-confirm-remove" type="button">Remove Profile</button>
        <button class="profile-delete-confirm-cancel" type="button">Cancel</button>
      </div>
    </div>
  `;
  document.body?.appendChild(modal);

  const resolveModal = (confirmed) => {
    modal.classList.remove("is-visible");
    modal.setAttribute("aria-hidden", "true");
    document.body?.classList.remove("profile-delete-confirm-active");
    window.setTimeout(() => {
      if (!modal.classList.contains("is-visible")) modal.hidden = true;
    }, 180);
    const resolver = profileDeleteConfirmResolver;
    profileDeleteConfirmResolver = null;
    resolver?.(confirmed);
  };

  modal.querySelector(".profile-delete-confirm-cancel")?.addEventListener("click", () => resolveModal(false));
  modal.querySelector(".profile-delete-confirm-remove")?.addEventListener("click", () => resolveModal(true));
  modal.addEventListener("click", (event) => {
    if (event.target === modal) resolveModal(false);
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && modal.classList.contains("is-visible")) {
      resolveModal(false);
    }
  });

  return modal;
}

function openProfileDeleteConfirmModal(profile) {
  const modal = ensureProfileDeleteConfirmModal();
  const title = modal.querySelector("#profileDeleteConfirmTitle");
  const copy = modal.querySelector("#profileDeleteConfirmCopy");
  const profileName = String(profile?.name || profile?.riotId || "this profile").trim();
  if (title) title.textContent = `Remove ${profileName}?`;
  if (copy) {
    copy.textContent = "RankedCoach will remove this profile, clear the old profile view, and rebuild the dashboard from the next active profile.";
  }
  profileDeleteConfirmResolver?.(false);
  return new Promise((resolve) => {
    profileDeleteConfirmResolver = resolve;
    modal.hidden = false;
    modal.setAttribute("aria-hidden", "false");
    document.body?.classList.add("profile-delete-confirm-active");
    window.requestAnimationFrame(() => modal.classList.add("is-visible"));
    window.setTimeout(() => modal.querySelector(".profile-delete-confirm-cancel")?.focus?.(), 30);
  });
}

function ensureProfileCleanupVeil() {
  let veil = document.getElementById("profileCleanupVeil");
  if (veil) return veil;

  veil = document.createElement("div");
  veil.id = "profileCleanupVeil";
  veil.className = "profile-cleanup-veil";
  veil.setAttribute("aria-live", "polite");
  veil.setAttribute("aria-hidden", "true");
  veil.hidden = true;
  veil.innerHTML = `
    <div class="profile-cleanup-card">
      <div class="profile-cleanup-kicker">Cleaning Profile Cache</div>
      <div class="profile-cleanup-copy" id="profileCleanupCopy">Preparing cleanup...</div>
      <div class="profile-cleanup-meter" aria-hidden="true"><span id="profileCleanupFill"></span></div>
      <div class="profile-cleanup-percent" id="profileCleanupPercent">0%</div>
    </div>
  `;
  document.body?.appendChild(veil);
  return veil;
}

function updateProfileCleanupProgress(message, progress = 0) {
  const veil = ensureProfileCleanupVeil();
  const copy = document.getElementById("profileCleanupCopy");
  const fill = document.getElementById("profileCleanupFill");
  const percent = document.getElementById("profileCleanupPercent");
  const safeProgress = Math.max(0, Math.min(100, Number(progress) || 0));
  if (copy) copy.textContent = message;
  if (fill) fill.style.width = `${safeProgress}%`;
  if (percent) percent.textContent = `${Math.round(safeProgress)}%`;
  return veil;
}

async function runProfileCleanupTask(task = async () => {}) {
  const pause = (ms) => new Promise(resolve => window.setTimeout(resolve, ms));
  const veil = updateProfileCleanupProgress("Closing old profile view...", 8);
  veil.hidden = false;
  veil.setAttribute("aria-hidden", "false");
  document.body?.classList.add("profile-cleanup-active");
  window.requestAnimationFrame(() => veil.classList.add("is-visible"));

  try {
    await pause(90);
    updateProfileCleanupProgress("Removing saved profile data...", 35);
    const result = await task();
    await pause(110);
    updateProfileCleanupProgress("Clearing stale coaching reads...", 68);
    await pause(110);
    updateProfileCleanupProgress("Rebuilding your dashboard...", 92);
    await pause(120);
    updateProfileCleanupProgress("Cleanup complete.", 100);
    await pause(180);
    return result;
  } finally {
    veil.classList.remove("is-visible");
    veil.setAttribute("aria-hidden", "true");
    document.body?.classList.remove("profile-cleanup-active");
    window.setTimeout(() => {
      if (!veil.classList.contains("is-visible")) veil.hidden = true;
    }, 220);
  }
}

function enterGuestModeAfterLogout() {
  currentAuthUser = null;
  setAppEntryChoice("guest");
  const guestProfile = createGuestProfileRecord();
  profiles = [guestProfile];
  activeProfileId = guestProfile.id;
  matches = [];
  logEntries = [];
  forceRRTotalDisplayValue?.(0);
  saveProfiles?.();
  saveLogEntries?.({ skipBackend: true });
  updateAuthUI?.(null);
  updateProfileHeaderUI?.();
  rebuildProfileListUI?.();
  recomputeFromMatches?.();
  updateDisplays?.();
  renderInsights?.();
  renderStatsAgents?.();
  renderStatsMaps?.();
  renderLogFeed?.({ force: true });
  renderChart?.(currentSize);
}

