function ensureChartTooltipLayer(){
  if (!tooltip) tooltip = document.getElementById("chartTooltip");
  if (tooltip && tooltip.parentElement !== document.body) {
    tooltip.classList.add("chart-tooltip-floating");
    document.body.appendChild(tooltip);
  }
  return tooltip;
}

function chartScopeAllowsTooltip(size = currentSize) {
  const numericSize = Number(size);
  return Number.isFinite(numericSize) && numericSize <= 50;
}

function normalizeChartWindowSize(size = currentSize) {
  const normalized = String(size || "5").toLowerCase();
  return normalized === "all" ? "all" : String(Number(normalized) || 5);
}

function getChartSelectedSeasonLabel(profile = getActiveProfile?.()) {
  const explicit = getStatsSelectedActLabel?.(profile);
  if (explicit) return explicit;
  const analytics = profile?.trackerAnalytics || null;
  return String(analytics?.currentAct || activeStatsActLabel || "Current Season").trim();
}

function getChartWindowMatchRequirement(size = currentSize) {
  const normalized = normalizeChartWindowSize(size);
  if (normalized === "all") return 0;
  return Math.max(1, Number(normalized) || 5);
}

function isChartWindowDisabled(size = currentSize, matchCount = 0) {
  const normalized = normalizeChartWindowSize(size);
  if (normalized === "all" || normalized === "5") return false;
  return safeNumber(matchCount) < getChartWindowMatchRequirement(normalized);
}

function getAvailableChartWindowSize(size = currentSize, matchCount = 0) {
  return isChartWindowDisabled(size, matchCount) ? "5" : normalizeChartWindowSize(size);
}

function updateChartWindowControls(matchCount = 0, activeSize = currentSize) {
  const activeKey = normalizeChartWindowSize(activeSize);
  document.querySelectorAll(".graph-btn").forEach((button) => {
    const size = normalizeChartWindowSize(button.dataset.size || "5");
    const disabled = isChartWindowDisabled(size, matchCount);
    button.disabled = disabled;
    button.classList.toggle("is-disabled", disabled);
    button.setAttribute("aria-disabled", disabled ? "true" : "false");
    button.classList.toggle("active", size === activeKey && !disabled);
    button.title = disabled
      ? `Play ${getChartWindowMatchRequirement(size)} games in this season to unlock this window.`
      : "";
  });
}

function getFreshCurrentRRAbsolute(profile = getActiveProfile?.()) {
  if (profile && isHenrikProfileData(profile)) {
    const snapshotRR = getRankSnapshotAbsoluteRR(getProfileCurrentRankSnapshot(profile));
    if (Number.isFinite(snapshotRR)) return snapshotRR;
  }
  const sourceMatches = Array.isArray(profile?.matches)
    ? profile.matches
    : (matches || []);
  const start = profile ? safeNumber(profile.startingRR) : 0;
  return sourceMatches.reduce((total, match) => total + safeNumber(match?.rr), start);
}

function isVerifiedHenrikRrMatch(match = {}) {
  return match?.rrVerified === true || match?.metadata?.rrVerified === true || match?.matchRecord?.rank?.verified === true;
}

function getChartMatchRRDelta(match = {}) {
  if (isVerifiedHenrikRrMatch(match)) {
    return safeNumber(match?.verifiedRrDelta ?? match?.matchRecord?.rank?.rrDelta);
  }
  return safeNumber(match?.rr);
}

function updateRRChartDataStatus(chartSource = {}) {
  const status = document.getElementById("rrChartDataStatus");
  if (!status) return;
  status.dataset.retainedMatchCount = String(safeNumber(chartSource.totalMatchCount));
  status.dataset.verifiedRrCount = String(safeNumber(chartSource.verifiedRrCount));
  status.dataset.hasHenrikMatches = chartSource.hasHenrikMatches ? "true" : "false";
  if (!chartSource.hasHenrikMatches) {
    status.textContent = "Click a game dot to inspect the imported match.";
    return;
  }
  const total = safeNumber(chartSource.totalMatchCount);
  const verified = safeNumber(chartSource.verifiedRrCount);
  const rankSnapshots = safeNumber(chartSource.rankSnapshotCount);
  if (chartSource.isLifetimeRankTimeline && rankSnapshots) {
    status.textContent = `${rankSnapshots} retained matches include rank snapshots. Lifetime plots rank position without estimating missing RR gains or losses.`;
    return;
  }
  status.textContent = verified
    ? `${verified} of ${total} retained matches have verified RR snapshots. Missing RR is not estimated.`
    : `Match stats are available for ${total} retained matches, but Henrik has no verified RR snapshots for this selection.`;
}

function getChartSourceEntries(size = currentSize) {
  const profile = getActiveProfile?.();
  const normalizedSize = normalizeChartWindowSize(size);
  const sourceMatches = Array.isArray(profile?.matches)
    ? profile.matches
    : (matches || []);
  const selectedSeasonLabel = getChartSelectedSeasonLabel(profile);
  const canFilterBySeason = Boolean(selectedSeasonLabel && selectedSeasonLabel !== "Current Season");

  let runningRR = 0;
  const allEntries = sourceMatches.map((match, index) => {
    const snapshot = getMatchRankSnapshot(match);
    const snapshotAbsolute = isVerifiedHenrikRrMatch(match) ? getRankSnapshotAbsoluteRR(snapshot) : null;
    const delta = getChartMatchRRDelta(match);
    const absoluteBefore = Number.isFinite(snapshotAbsolute)
      ? snapshotAbsolute - delta
      : runningRR;
    runningRR = Number.isFinite(snapshotAbsolute) ? snapshotAbsolute : runningRR + delta;
    return {
      match,
      index,
      displayIndex: index,
      absoluteBefore,
      absoluteAfter: runningRR
    };
  });

  const seasonEntries = canFilterBySeason
    ? allEntries.filter((entry) => getMatchSeasonLabel(entry.match) === selectedSeasonLabel)
    : allEntries;
  const scopedEntries = normalizedSize === "all" ? allEntries : seasonEntries;
  const hasHenrikMatches = scopedEntries.some(entry =>
    String(entry?.match?.source || entry?.match?.metadata?.source || "").toLowerCase() === "henrik_sync"
  );
  const verifiedRrCount = scopedEntries.filter(entry => isVerifiedHenrikRrMatch(entry.match)).length;
  const rankSnapshotEntries = scopedEntries.filter(entry => {
    const snapshot = getMatchRankSnapshot(entry.match);
    return Number.isFinite(getRankSnapshotAbsoluteRR(snapshot));
  });
  const chartEntries = normalizedSize === "all"
    ? rankSnapshotEntries
    : hasHenrikMatches
      ? scopedEntries.filter(entry => {
        const source = String(entry?.match?.source || entry?.match?.metadata?.source || "").toLowerCase();
        return source !== "henrik_sync" || isVerifiedHenrikRrMatch(entry.match);
      })
      : scopedEntries;
  const entries = chartEntries
    .map((entry, displayIndex) => ({ ...entry, displayIndex }));
  const scopeLabel = normalizedSize === "all" ? "All-time profile" : selectedSeasonLabel;

  return {
    entries,
    scopeEntries: scopedEntries,
    scopeLabel,
    seasonLabel: selectedSeasonLabel,
    isCurrentSessionScoped: false,
    isRecentAccountWindow: false,
    isSeasonScoped: normalizedSize !== "all",
    matchCount: entries.length,
    totalMatchCount: scopedEntries.length,
    verifiedRrCount,
    rankSnapshotCount: rankSnapshotEntries.length,
    isLifetimeRankTimeline: normalizedSize === "all",
    hasHenrikMatches
  };
}

function getChartAxisWindowSize(size = currentSize, matchCount = 0) {
  const normalized = String(size || "5").toLowerCase();
  if (normalized === "all") {
    return Math.max(50, safeNumber(matchCount));
  }
  const numericSize = Number(normalized);
  return Number.isFinite(numericSize) && numericSize > 0 ? numericSize : 5;
}

function setChartTooltipSuppressed(suppressed = true) {
  chartTooltipSuppressed = Boolean(suppressed);
  if (chartTooltipSuppressed) {
    hideChartTooltip();
  }
}

function canRenderChartTooltip() {
  if (chartTooltipSuppressed) return false;
  if (!chartScopeAllowsTooltip(currentSize)) return false;
  const chartPage = chartRow?.closest?.(".page");
  if (!chartPage || chartPage.id !== "page-home") return false;
  if (!chartPage.classList.contains("active")) return false;
  if (chartPage.classList.contains("exiting")) return false;
  if (document.body.classList.contains("has-active-modal")) return false;
  return true;
}

function hideChartTooltip(){
  if (selectedChartTooltipRaf) {
    window.cancelAnimationFrame(selectedChartTooltipRaf);
    selectedChartTooltipRaf = 0;
  }
  const tip = tooltip || document.getElementById("chartTooltip");
  if (tip) {
    tip.classList.remove("chart-tooltip-pop");
    tip.style.opacity = 0;
    tip.style.visibility = "hidden";
  }
  if (crosshair) {
    crosshair.style.opacity = 0;
    crosshair.setAttribute("opacity", "0");
  }
  chartRow?.querySelectorAll(".chart-rank-marker.is-tooltip-paired").forEach(marker => {
    resetChartRankMarkerPosition(marker);
  });
  chartRow?.querySelectorAll(".chart-rank-marker.is-near-selected").forEach(marker => {
    revealChartRankMarkerImmediately(marker);
  });
}

function setChartRankMarkerPosition(marker, centerX, centerY) {
  if (!marker || !Number.isFinite(centerX) || !Number.isFinite(centerY)) return;
  const circle = marker.querySelector("circle");
  const image = marker.querySelector("image");
  const text = marker.querySelector(".chart-rank-arrow");
  const arrowOffset = 19;

  revealChartRankMarkerImmediately(marker);
  marker.classList.add("is-tooltip-paired");
  marker.removeAttribute("transform");
  circle?.setAttribute("cx", centerX);
  circle?.setAttribute("cy", centerY);
  image?.setAttribute("x", centerX - 10);
  image?.setAttribute("y", centerY - 10);
  image?.setAttribute("width", 20);
  image?.setAttribute("height", 20);
  text?.setAttribute("x", centerX - arrowOffset);
  text?.setAttribute("y", centerY + 7);
}

function resetChartRankMarkerPosition(marker) {
  if (!marker) return;
  const circle = marker.querySelector("circle");
  const image = marker.querySelector("image");
  const text = marker.querySelector(".chart-rank-arrow");
  const baseX = Number(marker.dataset?.baseX || circle?.getAttribute("cx"));
  const baseY = Number(marker.dataset?.baseY || circle?.getAttribute("cy"));
  if (!Number.isFinite(baseX) || !Number.isFinite(baseY)) return;

  marker.classList.remove("is-tooltip-paired");
  revealChartRankMarkerImmediately(marker);
  marker.removeAttribute("transform");
  circle?.setAttribute("cx", baseX);
  circle?.setAttribute("cy", baseY);
  image?.setAttribute("x", baseX - 10);
  image?.setAttribute("y", baseY - 10);
  image?.setAttribute("width", 20);
  image?.setAttribute("height", 20);
  text?.setAttribute("x", baseX - 19);
  text?.setAttribute("y", baseY + 7);
}

function revealChartRankMarkerImmediately(marker) {
  if (!marker) return;
  marker.classList.remove("is-near-selected");
  marker.style.opacity = "1";
  marker.style.visibility = "visible";
  marker.style.animation = "none";
  marker.style.transform = "scale(1)";
}

function updateNearbyChartRankMarkerFade(svg, activeMarker, groupBounds, activeScreenY) {
  if (!svg || !activeMarker) return;
  const sizeKey = String(currentSize || "").toLowerCase();
  if (!["5", "10", "20", "50"].includes(sizeKey) || !selectedDot) return;

  svg.querySelectorAll(".chart-rank-marker").forEach(marker => {
    if (marker === activeMarker) return;
    marker.classList.add("is-near-selected");
  });
}

function animateChartTooltipPop() {
  const tip = ensureChartTooltipLayer();
  if (!tip) return;
  tip.classList.remove("chart-tooltip-pop");
  void tip.offsetWidth;
  tip.classList.add("chart-tooltip-pop");
}

function positionTooltipToHit(hit, options = {}){
  const { pop = false } = options;

  const tip = ensureChartTooltipLayer();
  if(!tip || !chartRow || !hit) return;
  if (!canRenderChartTooltip()) {
    hideChartTooltip();
    return;
  }
  const svg = chartRow.querySelector("svg");
  if(!svg) return;
  const anchorEl = getChartDotFromHit(hit) || hit;
  const viewBox = svg.viewBox.baseVal;
  const svgRect = svg.getBoundingClientRect();
  const anchorCx = Number(anchorEl.getAttribute("cx") || hit.getAttribute("cx") || 0);
  const anchorCy = Number(anchorEl.getAttribute("cy") || hit.getAttribute("cy") || 0);
  const x = svgRect.left + (((anchorCx - viewBox.x) / viewBox.width) * svgRect.width);
  const y = svgRect.top + (((anchorCy - viewBox.y) / viewBox.height) * svgRect.height);
  const hasRankMarker = String(hit.dataset.rankChange || anchorEl.dataset.rankChange || "") === "true";

  tip.style.visibility = "visible";
  tip.style.opacity = 1;
  const rankRr = String(hit.dataset.rankRr || "").trim();
  const rankLabel = String(hit.dataset.rankLabel || "").trim();
  const rrDelta = safeNumber(hit.dataset.rr);
  tip.textContent = rankRr
    ? `${rankLabel ? `${rankLabel} ` : ""}${rankRr} RR | ${rrDelta >= 0 ? "+" : ""}${rrDelta} RR`
    : `${safeNumber(hit.dataset.totalRr, hit.dataset.rr)} RR`;

  // ========================
  // SMART TOOLTIP POSITION
  // ========================

  const DOT_CLEARANCE_BELOW = 22;
  const DOT_CLEARANCE_ABOVE = 12;
  const tipWidth = tip.offsetWidth || 96;
  const tipHeight = tip.offsetHeight || 32;
  const viewportPad = 10;
  svg.querySelectorAll(".chart-rank-marker.is-tooltip-paired").forEach(marker => {
    resetChartRankMarkerPosition(marker);
  });
  svg.querySelectorAll(".chart-rank-marker.is-near-selected").forEach(marker => {
    revealChartRankMarkerImmediately(marker);
  });
  if (hasRankMarker) {
    const markerMatchIndex = String(hit.dataset.matchIndex || anchorEl.dataset.matchIndex || "");
    const marker = Array.from(svg.querySelectorAll(".chart-rank-marker"))
      .find(item => String(item.dataset.matchIndex || "") === markerMatchIndex);
    const markerCircle = marker?.querySelector("circle");
    const markerCx = Number(markerCircle?.getAttribute("cx") || anchorCx);
    const markerCy = Number(markerCircle?.getAttribute("cy") || anchorCy);
    const markerRadius = Math.max(8, Number(markerCircle?.getAttribute("r") || 14));
    const markerRadiusPx = markerRadius * (svgRect.width / viewBox.width);
    const markerArrowOffsetPx = 19 * (svgRect.width / viewBox.width);
    const markerArrowWidthPx = 13;
    const markerLeftWidthPx = markerRadiusPx + markerArrowOffsetPx + markerArrowWidthPx;
    const markerRightWidthPx = markerRadiusPx;
    const pairGapPx = 12;
    const groupWidthPx = markerLeftWidthPx + markerRightWidthPx + pairGapPx + tipWidth;
    const minTipLeft = viewportPad + tipWidth / 2;
    const maxTipLeft = window.innerWidth - viewportPad - tipWidth / 2;
    const minMarkerScreenX = Math.max(viewportPad + markerRadiusPx, svgRect.left + markerRadiusPx);
    const maxMarkerScreenX = Math.min(window.innerWidth - viewportPad - markerRadiusPx, svgRect.right - markerRadiusPx);
    const selectedGroupOffsetPx = 0;
    const groupLeft = x - (groupWidthPx / 2) + selectedGroupOffsetPx;
    const desiredMarkerScreenX = Math.max(minMarkerScreenX, Math.min(maxMarkerScreenX, groupLeft + markerLeftWidthPx));
    const desiredLeft = Math.max(minTipLeft, Math.min(maxTipLeft, groupLeft + markerLeftWidthPx + markerRightWidthPx + pairGapPx + (tipWidth / 2)));
    const selectedMarkerCx = viewBox.x + (((desiredMarkerScreenX - svgRect.left) / svgRect.width) * viewBox.width);
    let selectedMarkerCy = markerCy;
    let markerScreenY = svgRect.top + (((markerCy - viewBox.y) / viewBox.height) * svgRect.height);
    const tipHalfHeightChartUnits = ((tipHeight / 2) / svgRect.height) * viewBox.height;
    const selectedNeedsBelow = markerCy < anchorCy
      && (markerCy - tipHalfHeightChartUnits < PAD_TOP + 4 || markerScreenY - (tipHeight / 2) < viewportPad);
    if (selectedNeedsBelow) {
      selectedMarkerCy = Math.min(PAD_BOTTOM - 18, Math.max(PAD_TOP + 18, anchorCy + 32));
      markerScreenY = svgRect.top + (((selectedMarkerCy - viewBox.y) / viewBox.height) * svgRect.height);
    }
    setChartRankMarkerPosition(marker, selectedMarkerCx, selectedMarkerCy);
    const selectedGroupBounds = {
      left: Math.min(desiredMarkerScreenX - markerLeftWidthPx, desiredLeft - (tipWidth / 2)),
      right: Math.max(desiredMarkerScreenX + markerRightWidthPx, desiredLeft + (tipWidth / 2))
    };
    updateNearbyChartRankMarkerFade(svg, marker, selectedGroupBounds, markerScreenY);
    tip.style.left = Math.max(minTipLeft, Math.min(maxTipLeft, desiredLeft)) + "px";
    tip.style.top = Math.max(viewportPad + tipHeight / 2, Math.min(window.innerHeight - viewportPad - tipHeight / 2, markerScreenY)) + "px";
    tip.style.setProperty("--chart-tooltip-base-transform", "translate(-50%, -50%)");
    tip.style.transform = "var(--chart-tooltip-base-transform)";
    if (pop) animateChartTooltipPop();
    return;
  }

  const left = Math.max(viewportPad + tipWidth / 2, Math.min(window.innerWidth - viewportPad - tipWidth / 2, x));
  const flipBelow = (y - DOT_CLEARANCE_ABOVE - tipHeight) < Math.max(viewportPad, svgRect.top);

  tip.style.left = left + "px";

  if (flipBelow) {
    tip.style.top = Math.min(window.innerHeight - viewportPad - tipHeight, y + DOT_CLEARANCE_BELOW) + "px";
    tip.style.setProperty("--chart-tooltip-base-transform", "translate(-50%, 0%)");
    tip.style.transform = "var(--chart-tooltip-base-transform)";
  } else {
    tip.style.top = Math.max(viewportPad + tipHeight, y - DOT_CLEARANCE_ABOVE) + "px";
    tip.style.setProperty("--chart-tooltip-base-transform", "translate(-50%, -100%)");
    tip.style.transform = "var(--chart-tooltip-base-transform)";
  }

  if (pop) animateChartTooltipPop();

}

