function updateCompassPercentages(aim, sense, team, discipline){
  const normalize = (value) => {
    const n = safeNumber(value);
    return clampPercent(n <= 1 ? n * 100 : n);
  };

  const pAim = normalize(aim);
  const pSense = normalize(sense);
  const pTeam = normalize(team);
  const pDisc = normalize(discipline);

  document.querySelector(".percent-aim").textContent = `${pAim}`;
  document.querySelector(".percent-sense").textContent = `${pSense}`;
  document.querySelector(".percent-team").textContent = `${pTeam}`;
  document.querySelector(".percent-discipline").textContent = `${pDisc}`;

  updateCompassPolygon(pAim, pSense, pTeam, pDisc);
}

function updateCompassPolygon(a,s,t,d){

  const polygon = document.getElementById("compassPolygon");
  if(!polygon) return;

  const cx = 100;
  const cy = 100;
  const rMax = 80;
  const toRadius = (percent) => rMax * (clampPercent(percent) / 100);

  const points = [
    `${cx},${cy - toRadius(a)}`,
    `${cx + toRadius(s)},${cy}`,
    `${cx},${cy + toRadius(t)}`,
    `${cx - toRadius(d)},${cy}`
  ].join(" ");

  polygon.setAttribute("points",points);
}

function setCrestPreviewMeta(isPlaying, label = "Live Build") {
  if (crestCycleBtn) {
    crestCycleBtn.classList.toggle("is-playing", !!isPlaying);
    crestCycleBtn.textContent = isPlaying ? "Stop Cycle" : "Cycle Profiles";
  }

  if (crestCycleLabelEl) {
    crestCycleLabelEl.textContent = label;
  }
}

function getCompassTierLabel(score) {
  const value = clampPercent(score);
  if (value >= 80) return "Strong";
  if (value >= 65) return "Stable";
  if (value >= 45) return "Developing";
  return "Needs Work";
}

function getCompassProfileLabel(values = {}) {
  const entries = Object.entries(values).sort((a, b) => safeNumber(b[1]) - safeNumber(a[1]));
  const top = entries[0]?.[0];
  const second = entries[1]?.[0];
  const topValue = safeNumber(entries[0]?.[1]);
  const secondValue = safeNumber(entries[1]?.[1]);
  const hasAnyScore = entries.some(([, value]) => safeNumber(value) > 0);

  if (!hasAnyScore) return "No Data";
  if (!top) return "Balanced Build";
  if (Math.abs(topValue - secondValue) <= 4) return "Balanced Build";

  return `${COMPASS_LENS_META[top]?.label || "Skill"} Primary`;
}

const COMPASS_RANK_AVERAGE_TARGETS = {
  iron: 36,
  bronze: 40,
  silver: 46,
  gold: 54,
  platinum: 62,
  diamond: 70,
  ascendant: 77,
  immortal: 84,
  radiant: 90
};

function getCompassRankExpectation(tierLabel = "") {
  const key = String(tierLabel || "").trim().toLowerCase().split(/\s+/)[0] || "iron";
  const order = ["iron", "bronze", "silver", "gold", "platinum", "diamond", "ascendant", "immortal", "radiant"];
  const index = Math.max(0, order.indexOf(key));
  const currentKey = order[index] || "iron";
  const nextKey = order[index + 1] || null;

  return {
    key: currentKey,
    currentTarget: COMPASS_RANK_AVERAGE_TARGETS[currentKey] || 36,
    nextKey,
    nextTarget: nextKey ? COMPASS_RANK_AVERAGE_TARGETS[nextKey] || null : null,
    nextLabel: nextKey ? nextKey.charAt(0).toUpperCase() + nextKey.slice(1) : ""
  };
}

function getCompassRoleContext(roleName = "", strongestLens = "", weakestLens = "") {
  const roleKey = String(roleName || "").trim().toLowerCase();
  const comboKey = `${roleKey}:${strongestLens}:${weakestLens}`;
  const comboMap = {
    "duelist:aim:teamplay": "On a duelist-leaning sample, that usually means you can open fights but still bleed rounds when trades and follow-through are not synced.",
    "duelist:aim:discipline": "On a duelist-leaning sample, that often looks like strong first-fight mechanics getting wasted by overpeeks or forcing one fight too many.",
    "controller:gamesense:discipline": "On a controller-leaning sample, that usually shows up as good reads that still need cleaner utility pacing and economy discipline.",
    "initiator:gamesense:teamplay": "On an initiator-leaning sample, it often means your reads are solid but the setup timing is not always turning into full team value.",
    "sentinel:discipline:aim": "On a sentinel-leaning sample, that usually means your structure is stable but your punish damage still needs to convert more cleanly."
  };

  if (comboMap[comboKey]) {
    return comboMap[comboKey];
  }

  const roleMap = {
    duelist: "The recent sample leans duelist, so entry pressure, follow-through, and self-created fights weigh heavily in this read.",
    initiator: "The recent sample leans initiator, so setup timing, info value, and teammate conversion weigh heavily in this read.",
    controller: "The recent sample leans controller, so utility pacing, map control, and round structure weigh heavily in this read.",
    sentinel: "The recent sample leans sentinel, so anchor stability, survival value, and punish timing weigh heavily in this read."
  };

  return roleMap[roleKey] || "";
}

function buildCompassProfileDescription(values = {}, model = null) {
  if (values?.noData || (model && !safeNumber(model?.overview?.matchesPlayed))) {
    return "Import match history before RankedCoach builds a compass read. The four category scores stay at zero until real player data is available.";
  }

  const strongestLens = values?.strongestLens || "aim";
  const weakestLens = values?.weakestLens || "discipline";
  const averageScore = Math.round(averageValue([
    safeNumber(values?.aim),
    safeNumber(values?.gamesense),
    safeNumber(values?.teamplay),
    safeNumber(values?.discipline)
  ]));
  const currentRank = getTierRank(computeCurrentRRAbsolute())?.tierLabel || "Iron 1";
  const rankExpectation = getCompassRankExpectation(currentRank);
  const roleName = String(model?.scoring?.activeRoleName || model?.roles?.[0]?.role || "").trim();
  const agentName = String(model?.scoring?.activeAgentName || model?.agents?.[0]?.agent || "").trim();
  const strongestReadMap = {
    aim: "Your strongest collected stats are raw mechanical conversion and direct duel pressure.",
    gamesense: "Your strongest collected stats are timing, round awareness, and better decision flow.",
    teamplay: "Your strongest collected stats are spacing, trading, and coordinated round play.",
    discipline: "Your strongest collected stats are steadiness, restraint, and repeatable round structure."
  };
  const weakestReadMap = {
    aim: "The main issue is still finishing fights cleanly enough to cash those rounds in.",
    gamesense: "The main issue is still reading the round early enough to turn good advantages into cleaner outcomes.",
    teamplay: "The main issue is still linking your value with teammates through trades, timing, and follow-through.",
    discipline: "The main issue is still protecting value through patience, economy control, and fewer unnecessary commits."
  };
  const baselineGap = averageScore - rankExpectation.currentTarget;
  const nextGap = rankExpectation.nextTarget == null
    ? null
    : Math.max(0, Math.round(rankExpectation.nextTarget - averageScore));
  const lowRankNote = ["iron", "bronze", "silver"].includes(rankExpectation.key)
    ? "Lower ranks naturally run lower four-lens averages, so the goal is steady improvement rather than forcing every category into elite territory immediately."
    : "";
  const agentRoleLabel = [agentName, roleName].filter(Boolean).join(" / ");
  const benchmarkSentence = baselineGap >= 0
    ? `At ${averageScore} average, this profile is about ${Math.abs(Math.round(baselineGap))} points above the usual ${currentRank} benchmark.`
    : `At ${averageScore} average, this profile is about ${Math.abs(Math.round(baselineGap))} points below the usual ${currentRank} benchmark.`;
  const nextRankSentence = rankExpectation.nextTarget == null
    ? "At the top end, progress usually comes from shaving down the last weak lens rather than adding one more specialty focus."
    : `${rankExpectation.nextLabel} profiles tend to be closer to ${rankExpectation.nextTarget} average, so roughly ${nextGap} more average points is the next rung to chase.`;
  const roleSentence = getCompassRoleContext(roleName, strongestLens, weakestLens);

  return [
    `${agentRoleLabel ? `${agentRoleLabel} is reading as a ` : "This is a "}${COMPASS_LENS_META[strongestLens]?.label || "core"}-leaning profile. ${strongestReadMap[strongestLens] || ""} ${weakestReadMap[weakestLens] || ""}`.trim(),
    roleSentence || benchmarkSentence,
    roleSentence ? `${benchmarkSentence} ${nextRankSentence} ${lowRankNote}`.trim() : `${nextRankSentence} ${lowRankNote}`.trim()
  ].filter(Boolean).join(" ");
}

function updateBuildCoreVisual(aim, sense, team, discipline) {
  const values = {
    aim: clampPercent(aim),
    sense: clampPercent(sense),
    team: clampPercent(team),
    discipline: clampPercent(discipline)
  };

  const topLength = 80 * (values.aim / 100);
  const rightLength = 80 * (values.sense / 100);
  const bottomLength = 80 * (values.team / 100);
  const leftLength = 80 * (values.discipline / 100);
  const topNode = document.getElementById("coreNodeAim");
  const rightNode = document.getElementById("coreNodeSense");
  const bottomNode = document.getElementById("coreNodeTeam");
  const leftNode = document.getElementById("coreNodeDiscipline");

  if (topNode) {
    topNode.setAttribute("cx", "100");
    topNode.setAttribute("cy", `${100 - topLength}`);
    topNode.setAttribute("r", `${4 + (values.aim / 40)}`);
  }
  if (rightNode) {
    rightNode.setAttribute("cx", `${100 + rightLength}`);
    rightNode.setAttribute("cy", "100");
    rightNode.setAttribute("r", `${4 + (values.sense / 40)}`);
  }
  if (bottomNode) {
    bottomNode.setAttribute("cx", "100");
    bottomNode.setAttribute("cy", `${100 + bottomLength}`);
    bottomNode.setAttribute("r", `${4 + (values.team / 40)}`);
  }
  if (leftNode) {
    leftNode.setAttribute("cx", `${100 - leftLength}`);
    leftNode.setAttribute("cy", "100");
    leftNode.setAttribute("r", `${4 + (values.discipline / 40)}`);
  }

  updateCompassPolygon(values.aim, values.sense, values.team, values.discipline);
}

function getLiveCompassValues() {
  const model = getPlayerModel();
  return {
    aim: safeNumber(model?.compass?.aim),
    gamesense: safeNumber(model?.compass?.gamesense),
    teamplay: safeNumber(model?.compass?.teamplay),
    discipline: safeNumber(model?.compass?.discipline),
    source: model?.compass?.source || model?.currentAct || "Current Window",
    profileShare: model?.compass?.profileShare || {},
    strongestLens: model?.compass?.strongestLens,
    weakestLens: model?.compass?.weakestLens,
    noData: model?.compass?.noData || !safeNumber(model?.overview?.matchesPlayed),
    model
  };
}

function applyCompassVisual(values = {}) {
  const hasModelContext = Boolean(values?.model);
  const noData = Boolean(values?.noData || (hasModelContext && !safeNumber(values?.model?.overview?.matchesPlayed)));
  const profileShare = values?.profileShare || normalizeDistributionTo100({
    aim: safeNumber(values?.aim),
    gamesense: safeNumber(values?.gamesense),
    teamplay: safeNumber(values?.teamplay),
    discipline: safeNumber(values?.discipline)
  });
  const strongestLens = noData ? "" : (values?.strongestLens || Object.entries({
    aim: safeNumber(values?.aim),
    gamesense: safeNumber(values?.gamesense),
    teamplay: safeNumber(values?.teamplay),
    discipline: safeNumber(values?.discipline)
  }).sort((a, b) => b[1] - a[1])[0]?.[0] || "aim");
  const weakestLens = noData ? "" : (values?.weakestLens || Object.entries({
    aim: safeNumber(values?.aim),
    gamesense: safeNumber(values?.gamesense),
    teamplay: safeNumber(values?.teamplay),
    discipline: safeNumber(values?.discipline)
  }).sort((a, b) => a[1] - b[1])[0]?.[0] || "discipline");
  const averageScore = Math.round(averageValue([
    safeNumber(values?.aim),
    safeNumber(values?.gamesense),
    safeNumber(values?.teamplay),
    safeNumber(values?.discipline)
  ]));
  const profileLabel = noData ? "No Data" : (values?.profileLabel || getCompassProfileLabel({
    aim: safeNumber(values?.aim),
    gamesense: safeNumber(values?.gamesense),
    teamplay: safeNumber(values?.teamplay),
    discipline: safeNumber(values?.discipline)
  }));

  updateCompassPercentages(
    safeNumber(values?.aim),
    safeNumber(values?.gamesense),
    safeNumber(values?.teamplay),
    safeNumber(values?.discipline)
  );
  updateBuildCoreVisual(
    safeNumber(values?.aim),
    safeNumber(values?.gamesense),
    safeNumber(values?.teamplay),
    safeNumber(values?.discipline)
  );

  const sourcePill = document.getElementById("compassSourcePill");
  const profileTitle = document.getElementById("compassProfileTitle");
  const profileCopy = document.getElementById("compassProfileCopy");
  const averageScoreEl = document.getElementById("compassAverageScore");
  const strongestEl = document.getElementById("compassStrongestCallout");
  const weakestEl = document.getElementById("compassWeakestCallout");
  const profileDescriptionEl = document.getElementById("compassProfileDescription");

  if (sourcePill) sourcePill.textContent = noData ? "No Data" : (values?.source || "Recent Matches");
  if (profileTitle) profileTitle.textContent = profileLabel;
  if (profileCopy) {
    profileCopy.textContent = noData
      ? "Import match history to unlock category scores."
      : values?.summary
      || `${COMPASS_LENS_META[strongestLens]?.label || "Aim"} is your best category, while ${COMPASS_LENS_META[weakestLens]?.label || "Teamwork"} has the most room to improve.`;
  }
  if (averageScoreEl) averageScoreEl.textContent = `Avg ${averageScore}`;
  if (strongestEl) strongestEl.textContent = noData ? "Strongest: No Data" : `Strongest: ${COMPASS_LENS_META[strongestLens]?.label || "Aim"}`;
  if (weakestEl) weakestEl.textContent = noData ? "Weakest: No Data" : `Weakest: ${COMPASS_LENS_META[weakestLens]?.label || "Teamwork"}`;
  if (profileDescriptionEl) {
    profileDescriptionEl.textContent = values?.description || buildCompassProfileDescription(values, values?.model || null);
  }
  syncCompassDescriptionToggleState(false);

  [
    { key: "aim", suffix: "Aim" },
    { key: "gamesense", suffix: "Sense" },
    { key: "teamplay", suffix: "Team" },
    { key: "discipline", suffix: "Discipline" }
  ].forEach(({ key, suffix }) => {
    const score = Math.round(clampPercent(safeNumber(values?.[key])));
    const scoreEl = document.getElementById(`compassScore${suffix}`);
    const tierEl = document.getElementById(`compassTier${suffix}`);
    const metaEl = document.getElementById(`compassMeta${suffix}`);
    const barEl = document.getElementById(`compassBar${suffix}`);
    const cardEl = document.getElementById(`compassCard${suffix}`);
    const share = noData ? 0 : Math.round(safeNumber(profileShare?.[key]));

    if (scoreEl) scoreEl.textContent = `${score}`;
    if (tierEl) tierEl.textContent = noData ? "No Data" : getCompassTierLabel(score);
    if (metaEl) metaEl.textContent = `Profile share ${share}% Â· ${COMPASS_LENS_META[key]?.summary || ""}`;
    if (metaEl && noData) metaEl.textContent = "No match data yet.";
    if (barEl) barEl.style.width = `${score}%`;
    if (cardEl) cardEl.classList.toggle("is-strongest", !noData && key === strongestLens);
  });
}

function stopCrestPreview() {
  if (crestPreviewTimer) {
    clearInterval(crestPreviewTimer);
    crestPreviewTimer = null;
  }
  crestPreviewActive = false;
  crestPreviewIndex = 0;
  setCrestPreviewMeta(false, "Live Snapshot");
  applyCompassVisual(getLiveCompassValues());
}

function stepCrestPreview() {
  const state = CREST_PREVIEW_STATES[crestPreviewIndex % CREST_PREVIEW_STATES.length];
  crestPreviewIndex += 1;
  setCrestPreviewMeta(true, state.label);
  applyCompassVisual(state);
}

function startCrestPreview() {
  if (crestPreviewTimer) {
    clearInterval(crestPreviewTimer);
  }

  crestPreviewActive = true;
  crestPreviewIndex = 0;
  stepCrestPreview();
  crestPreviewTimer = setInterval(() => {
    stepCrestPreview();
  }, 1400);
}

// ========================
// CHART HELPERS
// ========================

function cancelChartFrame() {
  if (chartAnimFrame) {
    cancelAnimationFrame(chartAnimFrame);
    chartAnimFrame = null;
  }
}

function buildCumulativeRR(matchList) {
  const cumulative = [];
  let total = 0;

  matchList.forEach(match => {
    total += getChartMatchRRDelta(match);
    cumulative.push(total);
  });

  return cumulative;
}

function getRetainedMatchDate(match = {}) {
  const rawDate =
    match?.metadata?.playedAt ||
    match?.matchRecord?.playedAt ||
    match?.playedAt ||
    match?.createdAt ||
    match?.metadata?.createdAt ||
    "";
  const date = new Date(rawDate);
  return Number.isNaN(date.getTime()) ? null : date;
}

function getRetainedHenrikMatchDates(profile = getActiveProfile?.()) {
  return (Array.isArray(profile?.matches) ? profile.matches : [])
    .filter(match => ["henrik", "henrik_sync"].includes(String(
      match?.source || match?.metadata?.source || match?.matchRecord?.source || ""
    ).toLowerCase()))
    .map(getRetainedMatchDate)
    .filter(Boolean)
    .sort((a, b) => a - b);
}

function getOldestRetainedHenrikMatchDate(profile = getActiveProfile?.()) {
  return getRetainedHenrikMatchDates(profile)[0] || null;
}

function formatRetainedHistoryDate(date, { includeDay = true } = {}) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    ...(includeDay ? { day: "numeric" } : {}),
    year: "numeric",
    timeZone: "UTC"
  }).format(date);
}

function buildLifetimeRankSeries(entries = []) {
  const rankedEntries = (entries || []).map(entry => {
    const snapshot = getMatchRankSnapshot(entry?.match || {});
    const absolute = getRankSnapshotAbsoluteRR(snapshot);
    return Number.isFinite(absolute) ? { ...entry, lifetimeRankAbsolute: absolute } : null;
  }).filter(Boolean);
  if (!rankedEntries.length) return { entries: [], slice: [] };
  const first = rankedEntries[0];
  const firstDelta = getOptionalFiniteNumber(first?.match?.verifiedRrDelta ?? first?.match?.matchRecord?.rank?.rrDelta ?? first?.match?.rr) || 0;
  return {
    entries: rankedEntries,
    slice: [first.lifetimeRankAbsolute - firstDelta, ...rankedEntries.map(entry => entry.lifetimeRankAbsolute)]
  };
}

function getLifetimeSeasonTransitions(entries = []) {
  const transitions = [];
  let previousSeason = "";
  (entries || []).forEach((entry) => {
    const season = getMatchSeasonLabel(entry?.match || {});
    if (!season) return;
    if (!previousSeason || season !== previousSeason) {
      transitions.push({
        index: Number(entry?.index),
        season,
        isFirst: !previousSeason,
        isPlacementMatch: isPlacementRankedMatch(entry?.match)
      });
    }
    previousSeason = season;
  });
  return transitions;
}

function formatLifetimeSeasonMarker(season = "") {
  const label = String(season || "").trim();
  const act = label.match(/(?:act|a)\s*(\d+)/i)?.[1] || "";
  const valorantYear = label.match(/(?:season|v)\s*(20)?(\d{2})/i)?.[2] || "";
  const episode = label.match(/episode\s*(\d+)/i)?.[1] || "";
  return {
    title: valorantYear ? `V${valorantYear}` : episode ? `E${episode}` : label,
    act: act ? `A${act}` : ""
  };
}

function buildLifetimeSeasonBoundaryMarkup(transitions = [], points = []) {
  return (transitions || []).map((transition) => {
    const nextPointIndex = points.findIndex(point => point?.matchIndex >= transition.index);
    if (nextPointIndex < 1) return "";
    const nextPoint = points[nextPointIndex];
    const previousPoint = points[nextPointIndex - 1] || nextPoint;
    const x = transition.isFirst
      ? safeNumber(nextPoint.x)
      : (safeNumber(previousPoint.x) + safeNumber(nextPoint.x)) / 2;
    const marker = formatLifetimeSeasonMarker(transition.season);
    return `
      <g class="chart-season-boundary" data-season="${escapeHtml(transition.season)}">
        <line x1="${x}" y1="${PAD_TOP}" x2="${x}" y2="${PAD_BOTTOM}" />
        <text x="${x}" y="${PAD_TOP + 13}" text-anchor="middle">
          <tspan class="chart-season-title" x="${x}">${escapeHtml(marker.title)}</tspan>
          ${marker.act ? `<tspan class="chart-season-act" x="${x}" dy="14">${escapeHtml(marker.act)}</tspan>` : ""}
        </text>
      </g>`;
  }).join("");
}

function getLifetimeRankBounds(slice = []) {
  const finite = slice.filter(Number.isFinite);
  const fallback = getRankSnapshotAbsoluteRR(getProfileCurrentRankSnapshot()) || 0;
  const lowValue = finite.length ? Math.min(...finite) : fallback;
  const highValue = finite.length ? Math.max(...finite) : fallback;
  const lowMatch = RANK_THRESHOLDS.findIndex(rank => lowValue >= rank.min && lowValue < rank.max);
  const highMatch = RANK_THRESHOLDS.findIndex(rank => highValue >= rank.min && highValue < rank.max);
  const lowIndex = Math.max(0, lowMatch);
  const highIndex = Math.max(lowIndex, highMatch < 0 ? RANK_THRESHOLDS.length - 1 : highMatch);
  const startIndex = Math.max(0, lowIndex - 1);
  const endIndex = Math.min(RANK_THRESHOLDS.length - 1, Math.max(highIndex + 1, startIndex + 2));
  const minTick = safeNumber(RANK_THRESHOLDS[startIndex]?.min);
  const endRank = RANK_THRESHOLDS[endIndex];
  const maxTick = Number.isFinite(endRank?.max) ? endRank.max : safeNumber(endRank?.min) + 500;
  return { minTick, maxTick, startIndex, endIndex };
}

function buildLifetimeRankYTicks(bounds, y) {
  const start = safeNumber(bounds?.startIndex);
  const end = Math.max(start, safeNumber(bounds?.endIndex));
  const span = Math.max(1, end - start);
  const step = Math.max(1, Math.ceil(span / 5));
  const indexes = [];
  for (let index = start; index <= end; index += step) indexes.push(index);
  if (indexes[indexes.length - 1] !== end) indexes.push(end);
  const tickPositions = indexes.map(index => y(safeNumber(RANK_THRESHOLDS[index]?.min)));
  const minimumGap = tickPositions.length > 1
    ? Math.min(...tickPositions.slice(1).map((position, index) => Math.abs(position - tickPositions[index])))
    : 40;
  const preferredIconSize = isMobileLayoutViewport() ? 26 : 30;
  const iconSize = Math.max(14, Math.min(preferredIconSize, Math.floor(minimumGap * 0.72)));
  return indexes.map(index => {
    const rank = RANK_THRESHOLDS[index];
    const value = safeNumber(rank?.min);
    const yy = y(value);
    const iconUrl = getRankIconUrl(rank?.tierLabel || "");
    return `
<line x1="${PAD_LEFT}" y1="${yy}" x2="${CHART_W - PAD_RIGHT}" y2="${yy}" stroke="rgba(148,163,184,0.25)"/>
<g class="chart-rank-axis-icon" aria-label="${escapeHtml(rank?.tierLabel || "Rank")}">
  <title>${escapeHtml(rank?.tierLabel || "Rank")}</title>
  <image href="${escapeHtml(iconUrl)}" x="${PAD_LEFT - iconSize - 10}" y="${yy - (iconSize / 2)}" width="${iconSize}" height="${iconSize}" preserveAspectRatio="xMidYMid meet"/>
</g>`;
  }).join("");
}

function getMatchIdentityKey(match = {}) {
  if (!match) return "";

  const id = String(match?.id || match?.matchId || "").trim();
  if (id) {
    return `id:${id}`;
  }

  const core = getMatchCore(match);
  const createdAt = String(match?.createdAt || match?.metadata?.playedAt || core?.createdAt || "").trim();
  const agent = String(match?.metadata?.agent || match?.agent || core?.agent || "").trim().toLowerCase();
  const map = String(match?.metadata?.mapName || match?.map || core?.map || "").trim().toLowerCase();
  const rr = Number(match?.rr);

  if (!createdAt && !agent && !map && !Number.isFinite(rr)) {
    return "";
  }

  return `fallback:${createdAt}|${agent}|${map}|${Number.isFinite(rr) ? rr : ""}`;
}

function findImpactSnapshotForMatch(match, matchIndex, impactSnapshots = []) {
  if (!Array.isArray(impactSnapshots) || !impactSnapshots.length) {
    return null;
  }

  const matchKey = getMatchIdentityKey(match);
  if (matchKey) {
    const exact = impactSnapshots.find(snapshot => getMatchIdentityKey(snapshot) === matchKey);
    if (exact) {
      return exact;
    }
  }

  const matchId = String(match?.id || match?.matchId || "").trim();
  if (matchId) {
    const byId = impactSnapshots.find(snapshot =>
      String(snapshot?.id || "").trim() === matchId ||
      String(snapshot?.matchId || "").trim() === matchId
    );
    if (byId) {
      return byId;
    }
  }

  if (Number.isInteger(matchIndex) && matchIndex >= 0) {
    return impactSnapshots.find(snapshot => Number(snapshot?.matchIndex) === matchIndex) || null;
  }

  return null;
}

function getChartSliceWithEntries(cumulative, entries, size) {
  const matchCount = Array.isArray(entries) ? entries.length : 0;
  const maxWindow = String(size).toLowerCase() === "all"
    ? matchCount
    : Math.min(matchCount, Number(size) || 5);
  const startIndex = Math.max(0, matchCount - maxWindow);
  const baseline = startIndex > 0 ? safeNumber(cumulative[startIndex - 1]) : 0;
  const visibleCumulative = cumulative
    .slice(startIndex)
    .map(value => safeNumber(value));

  return {
    slice: [baseline, ...visibleCumulative],
    entries: (entries || []).slice(startIndex)
  };
}

function getChartRankChange(entry = null) {
  if (!entry) return null;
  const before = getTierRank(safeNumber(entry.absoluteBefore));
  const after = getTierRank(safeNumber(entry.absoluteAfter));
  if (!before || !after || before.tierLabel === after.tierLabel) return null;

  const direction = safeNumber(after.min) > safeNumber(before.min) ? "up" : "down";
  return {
    direction,
    tierLabel: after.tierLabel,
    iconUrl: getRankIconUrl(after.tierLabel)
  };
}

function getChartIntroTiming(size, segmentCount, useContinuousIntro = false) {
  const normalizedSize = String(size || "5").toLowerCase();
  const baseSegmentMs = 360;
  const readableMinMs = 70;

  if (!useContinuousIntro) {
    return {
      segmentMs: baseSegmentMs,
      finalPauseMs: 120,
      finalSegmentMs: 620
    };
  }

  let segmentMs = baseSegmentMs;

  if (normalizedSize === "20") {
    segmentMs = baseSegmentMs / 2;
  } else if (normalizedSize === "50") {
    segmentMs = baseSegmentMs / 3;
  } else if (normalizedSize === "all") {
    const visibleSegments = Math.max(1, Number(segmentCount) || 1);
    segmentMs = 6000 / visibleSegments;
  }

  const minimumSegmentMs = normalizedSize === "all" ? 1 : readableMinMs;
  segmentMs = Math.max(minimumSegmentMs, Math.round(segmentMs * 1000) / 1000);

  return {
    segmentMs,
    finalPauseMs: 0,
    finalSegmentMs: segmentMs
  };
}

function getChartBounds(slice) {
  const rawMax = Math.max(...slice, 25);
  const rawMin = Math.min(...slice, -25);

  const maxTick = Math.ceil(rawMax / 25) * 25;
  const minTick = Math.floor(rawMin / 25) * 25;

  return { minTick, maxTick };
}

function makeChartY(minTick, maxTick) {
  return function y(v) {
    return PAD_BOTTOM - ((v - minTick) / (maxTick - minTick)) * (PAD_BOTTOM - PAD_TOP);
  };
}

function buildChartPoints(slice, y, visibleEntries = null) {
  const plotWidth = CHART_W - PAD_LEFT - PAD_RIGHT;
  const step = slice.length > 1 ? plotWidth / (slice.length - 1) : 0;
  const visibleMatchCount = Math.max(0, slice.length - 1);
  const scopedEntries = Array.isArray(visibleEntries) ? visibleEntries : null;
  const startMatchIndex = Math.max(0, matches.length - visibleMatchCount);
  const impactSnapshots = getPlayerModel()?.scoring?.impactSnapshots || [];

  return slice.map((value, index) => {
    if (index === 0) {
      return {
        x: PAD_LEFT + index * step,
        y: y(value),
        rr: 0,
        value,
        matchIndex: -1,
        match: null,
        snapshot: null,
        matchId: "",
        matchKey: ""
      };
    }

    const scopedEntry = scopedEntries?.[index - 1] || null;
    const matchIndex = scopedEntry
      ? Number(scopedEntry.index)
      : startMatchIndex + index - 1;
    const match = scopedEntry?.match || matches[matchIndex] || null;
    const snapshot = findImpactSnapshotForMatch(match, matchIndex, impactSnapshots);

    return {
      x: PAD_LEFT + index * step,
      y: y(value),
      rr: value - slice[index - 1],
      value,
      matchIndex,
      sessionIndex: Number.isInteger(scopedEntry?.displayIndex) ? scopedEntry.displayIndex : index - 1,
      match,
      snapshot,
      rankChange: getChartRankChange(scopedEntry),
      rankRr: isVerifiedHenrikRrMatch(match)
        ? safeNumber(match?.rrTotal ?? match?.matchRecord?.rank?.rr)
        : null,
      rankLabel: isVerifiedHenrikRrMatch(match)
        ? String(match?.rank || match?.matchRecord?.rank?.rank || "").trim()
        : "",
      matchId: String((match?.id || match?.matchId || snapshot?.id || snapshot?.matchId || "")),
      matchKey: getMatchIdentityKey(match || snapshot || {})
    };
  });
}

function buildDotMarkup(point, { final = false, intro = false, introDelayMs = 0 } = {}) {
  if (!point || !Number.isInteger(point.matchIndex) || point.matchIndex < 0) {
    return "";
  }

  const snapshot = point.snapshot || {};
  const fill = snapshot?.impactColor || (final ? "#facc15" : "#e5e7eb");
  const dotClass = `${final ? "final-end" : "rr-dot"}${intro ? " chart-intro-dot" : ""}${final && intro ? " chart-intro-dot-final" : ""}`;
  const matchStats = {
    kills: Number.isFinite(Number(snapshot?.kills)) ? Number(snapshot.kills) : getMatchPanelStats(point.match || {}).kills,
    deaths: Number.isFinite(Number(snapshot?.deaths)) ? Number(snapshot.deaths) : getMatchPanelStats(point.match || {}).deaths,
    assists: Number.isFinite(Number(snapshot?.assists)) ? Number(snapshot.assists) : getMatchPanelStats(point.match || {}).assists,
    acs: Number.isFinite(Number(snapshot?.acs)) ? Number(snapshot.acs) : getMatchPanelStats(point.match || {}).acs
  };
  const statsAttrs = `
data-kills="${Number.isFinite(Number(matchStats.kills)) ? Math.round(Number(matchStats.kills)) : ""}"
data-deaths="${Number.isFinite(Number(matchStats.deaths)) ? Math.round(Number(matchStats.deaths)) : ""}"
data-assists="${Number.isFinite(Number(matchStats.assists)) ? Math.round(Number(matchStats.assists)) : ""}"
data-acs="${Number.isFinite(Number(matchStats.acs)) ? Math.round(Number(matchStats.acs)) : ""}"
data-map="${escapeHtml(snapshot?.map || point?.match?.metadata?.mapName || point?.match?.map || "")}"
data-agent="${escapeHtml(snapshot?.agent || point?.match?.metadata?.agent || point?.match?.agent || "")}"
data-result="${escapeHtml(point?.match?.result || point?.match?.metadata?.result || "")}"
data-created-at="${escapeHtml(point?.match?.createdAt || point?.match?.metadata?.playedAt || snapshot?.createdAt || "")}"
data-impact-tier="${escapeHtml(snapshot?.impactTier || "")}"
data-impact-score="${Number.isFinite(Number(snapshot?.impactScore)) ? Math.round(Number(snapshot?.impactScore)) : ""}"
data-impact-color="${escapeHtml(snapshot?.impactColor || "")}"
data-match-id="${escapeHtml(point?.matchId || snapshot?.id || point?.match?.id || point?.match?.matchId || "")}"
data-match-key="${escapeHtml(point?.matchKey || "")}"`;

  const introStyle = intro
    ? `--intro-delay:${introDelayMs}ms;opacity:0;transform:scale(.2);transform-box:fill-box;transform-origin:center;`
    : "";

  return `
<circle class="rr-hit"
cx="${point.x}"
cy="${point.y}"
r="${HIT_RADIUS}"
data-rr="${point.rr}"
data-total-rr="${point.value}"
data-rank-rr="${point.rankRr !== null && point.rankRr !== undefined && String(point.rankRr).trim() !== "" && Number.isFinite(Number(point.rankRr)) ? Number(point.rankRr) : ""}"
data-rank-label="${escapeHtml(point.rankLabel || "")}"
data-index="${point.matchIndex}"
data-match-index="${point.matchIndex}"
data-session-index="${Number.isInteger(point.sessionIndex) ? point.sessionIndex : point.matchIndex}"
data-rank-change="${point?.rankChange?.iconUrl ? "true" : "false"}"
${statsAttrs}/>

<circle class="${dotClass}"
cx="${point.x}"
cy="${point.y}"
r="${DOT_RADIUS}"
data-rr="${point.rr}"
data-total-rr="${point.value}"
data-rank-rr="${point.rankRr !== null && point.rankRr !== undefined && String(point.rankRr).trim() !== "" && Number.isFinite(Number(point.rankRr)) ? Number(point.rankRr) : ""}"
data-rank-label="${escapeHtml(point.rankLabel || "")}"
data-index="${point.matchIndex}"
data-match-index="${point.matchIndex}"
data-session-index="${Number.isInteger(point.sessionIndex) ? point.sessionIndex : point.matchIndex}"
data-match-id="${escapeHtml(point?.matchId || snapshot?.id || point?.match?.id || point?.match?.matchId || "")}"
data-match-key="${escapeHtml(point?.matchKey || "")}"
data-rank-change="${point?.rankChange?.iconUrl ? "true" : "false"}"
data-impact-tier="${escapeHtml(snapshot?.impactTier || "")}"
data-impact-score="${Number.isFinite(Number(snapshot?.impactScore)) ? Math.round(Number(snapshot?.impactScore)) : ""}"
fill="${fill}"
style="${introStyle}"/>`;
}

function buildRankChangeMarkerMarkup(point, { intro = false, introDelayMs = 0 } = {}) {
  if (!point?.rankChange?.iconUrl) return "";
  const direction = point.rankChange.direction === "down" ? "down" : "up";
  const markerBelow = point.y - 34 < PAD_TOP + 18;
  const markerX = Math.min(CHART_W - PAD_RIGHT - 18, Math.max(PAD_LEFT + 18, point.x));
  const markerY = Math.min(PAD_BOTTOM - 18, Math.max(PAD_TOP + 18, point.y + (markerBelow ? 32 : -32)));
  const arrow = direction === "down" ? "↓" : "↑";
  const arrowX = markerX - 19;
  const introStyle = intro
    ? `--intro-delay:${introDelayMs}ms;opacity:0;transform:scale(.2);transform-box:fill-box;transform-origin:center;`
    : "";

  return `
<g class="chart-rank-marker chart-rank-${direction}" data-match-index="${point.matchIndex}" data-base-x="${markerX}" data-base-y="${markerY}" style="${introStyle}">
  <circle cx="${markerX}" cy="${markerY}" r="14"></circle>
  <image href="${escapeHtml(point.rankChange.iconUrl)}"
    x="${markerX - 10}" y="${markerY - 10}"
    width="20" height="20"
    preserveAspectRatio="xMidYMid meet"></image>
  <text class="chart-rank-arrow" x="${arrowX}" y="${markerY + 7}" text-anchor="middle">${arrow}</text>
</g>`;
}
function buildLifetimeDateTicks(points = []) {
  const datedPoints = (points || [])
    .map((point, index) => ({ point, index, date: getRetainedMatchDate(point?.match || {}) }))
    .filter(entry => entry.date);
  if (!datedPoints.length) return "";

  const first = datedPoints[0];
  const last = datedPoints[datedPoints.length - 1];
  const firstX = safeNumber(points[0]?.x, first.point.x);
  const lastX = safeNumber(last.point.x, firstX);
  const ticks = [{
    x: firstX,
    date: first.date,
    label: formatRetainedHistoryDate(first.date),
    anchor: "start",
    kind: "start"
  }];

  if (first.date.getUTCFullYear() !== last.date.getUTCFullYear()) {
    for (let year = first.date.getUTCFullYear() + 1; year <= last.date.getUTCFullYear(); year += 1) {
      const yearStart = Date.UTC(year, 0, 1);
      const entry = datedPoints.find(candidate => candidate.date.getTime() >= yearStart);
      if (!entry || entry === last) continue;
      const x = safeNumber(entry.point.x);
      if (x - firstX < 72 || lastX - x < 72) continue;
      ticks.push({ x, date: entry.date, label: String(year), anchor: "middle", kind: "year" });
    }
  }

  if (last !== first) {
    ticks.push({
      x: lastX,
      date: last.date,
      label: formatRetainedHistoryDate(last.date),
      anchor: "end",
      kind: "end"
    });
  }

  return ticks.map(tick => `
<g class="chart-lifetime-date-tick chart-lifetime-date-${tick.kind}" data-date="${escapeHtml(tick.date.toISOString())}">
  <line x1="${tick.x}" y1="${PAD_BOTTOM}"
        x2="${tick.x}" y2="${PAD_BOTTOM + 5}"
        stroke="#64748b" stroke-width="1"/>
  <text class="chart-lifetime-date-label" x="${tick.x}" y="${PAD_BOTTOM + 23}"
        text-anchor="${tick.anchor}">${escapeHtml(tick.label)}</text>
</g>`).join("");
}

function buildXTicks(points, sliceLength, matchCount) {
  let xTicks = "";

  const visibleMatches = Math.min(matchCount, sliceLength - 1);
  const startGame = matchCount - visibleMatches + 1;
  const normalizedSize = String(currentSize || "").toLowerCase();
  const isFiftyWindow = normalizedSize === "50";
  const isLifetimeWindow = normalizedSize === "all";
  const isMobileTwentyWindow = isMobileLayoutViewport() && normalizedSize === "20";

  if (isLifetimeWindow) {
    return buildLifetimeDateTicks(points);
  }

  if (points[0] && !isMobileTwentyWindow && !isFiftyWindow) {
    xTicks += `
<line x1="${points[0].x}" y1="${PAD_BOTTOM}"
      x2="${points[0].x}" y2="${PAD_BOTTOM + 4}"
      stroke="#64748b" stroke-width="1"/>

<text x="${points[0].x}" y="${PAD_BOTTOM + 24}"
      font-size="18"
      fill="#94a3b8"
      text-anchor="middle">${startGame - 1}</text>
`;
  }

  for (let i = 1; i <= visibleMatches; i++) {

    const p = points[i];
    if (!p) continue;

    const game = startGame + i - 1;

    let showLabel = true;

    if (isMobileTwentyWindow) {
      showLabel = game === startGame || game === matchCount;
    }

    if (isFiftyWindow) {
      showLabel = game === startGame || game === matchCount;
    }

    if (!showLabel) continue;

    xTicks += `
<line x1="${p.x}" y1="${PAD_BOTTOM}"
      x2="${p.x}" y2="${PAD_BOTTOM + 4}"
      stroke="#64748b" stroke-width="1"/>

<text x="${p.x}" y="${PAD_BOTTOM + 24}"
      font-size="18"
      fill="#94a3b8"
      text-anchor="middle">${game}</text>
`;
  }

  return xTicks;
}

function buildChartAxisTitle(label = "Current Season", options = {}) {
  const axisLabel = options?.lifetimeRankTimeline
    ? options?.oldestRetainedDate
      ? `Matches since ${formatRetainedHistoryDate(options.oldestRetainedDate)}`
      : "Matches in available rank history"
    : `Games from ${label || "Current Season"}`;
  const x = PAD_LEFT + ((CHART_W - PAD_LEFT - PAD_RIGHT) / 2);
  const isMobileFooterLayout = isMobileLayoutViewport();
  const titleY = isMobileFooterLayout ? PAD_BOTTOM + 46 : Math.min(CHART_H - 28, PAD_BOTTOM + 58);
  const legendY = isMobileFooterLayout ? PAD_BOTTOM + 68 : Math.min(CHART_H - 4, titleY + 24);
  const legendWidth = 146;
  const legendX = Math.max(PAD_LEFT, Math.min(x - (legendWidth / 2), CHART_W - PAD_RIGHT - legendWidth));
  const legendItems = [
    { label: "Poor", color: "#ef4444", x: 0 },
    { label: "Solid", color: "#eab308", x: 50 },
    { label: "Carry", color: "#22c55e", x: 104 }
  ].map((item) => `
<g class="chart-axis-legend-item" transform="translate(${legendX + item.x} ${legendY})">
  <circle class="chart-axis-legend-dot" cx="0" cy="0" r="4.5" fill="${item.color}"></circle>
  <text class="chart-axis-legend-text" x="8" y="4">${escapeHtml(item.label)}</text>
</g>`).join("");
  return `
<text class="chart-axis-title"
      x="${x}"
      y="${titleY}"
      font-size="14"
      fill="#94a3b8"
      font-weight="800"
      letter-spacing=".08em"
      text-anchor="middle">${escapeHtml(axisLabel)}</text>
<g class="chart-axis-legend">${legendItems}</g>`;
}

function buildYTicks(minTick, maxTick, y) {
  let yTicks = "";

  for (let i = 0; i <= 4; i++) {
    const val = minTick + ((maxTick - minTick) / 4) * i;
    const yy = y(val);

    yTicks += `
<line x1="${PAD_LEFT}" y1="${yy}"
      x2="${CHART_W - PAD_RIGHT}" y2="${yy}"
      stroke="rgba(148,163,184,0.25)"/>

<text x="${PAD_LEFT - 10}" y="${yy + 4}"
      fill="#94a3b8"
      font-size="18"
      font-weight="600"
      text-anchor="end">${Math.round(val)}</text>
`;
  }

  return yTicks;
}

// ========================
// RANK HELPER FUNCTIONS
// ========================

function getNextTierRank(rr){
  const current =
    RANK_THRESHOLDS.findIndex(r => rr >= r.min && rr < r.max);

  if(current === -1 || current === RANK_THRESHOLDS.length - 1){
    return RANK_THRESHOLDS[RANK_THRESHOLDS.length - 1];
  }

  return RANK_THRESHOLDS[current + 1];
}

function getTierBoundsByLabel(label){
  if(!label) return null;

  const normalized = normalizeTierLabel(label);
  const canonical = normalized === "Radiant +" ? "Radiant" : normalized;

  return RANK_THRESHOLDS.find(
    r => r.tierLabel.toLowerCase() === String(canonical).toLowerCase()
  );
}

function isImmortalOrRadiantRank(label){
  const normalized = normalizeTierLabel(label).toLowerCase();
  return normalized.startsWith("immortal") || normalized === "radiant" || normalized === "radiant +";
}

function getActRRForAbsoluteRR(rr, rank = null){
  const absoluteRR = Math.max(0, Math.round(safeNumber(rr, 0)));
  const resolvedRank = rank || getTierRank(absoluteRR);
  if(isImmortalOrRadiantRank(resolvedRank?.tierLabel)){
    return Math.max(0, Math.round(absoluteRR - IMMORTAL_ACT_RR_BASE));
  }
  return Math.max(0, Math.round(absoluteRR - safeNumber(resolvedRank?.min, 0)));
}

function getRankLocalRRForAbsoluteRR(rr, rank = null){
  const absoluteRR = Math.max(0, Math.round(safeNumber(rr, 0)));
  const resolvedRank = rank || getTierRank(absoluteRR);
  if(!resolvedRank) return absoluteRR;
  return getActRRForAbsoluteRR(absoluteRR, resolvedRank);
}

function formatRankLocalRR(rr, options = {}){
  const resolvedRank = options.rank || getTierRank(rr);
  const localRR = getRankLocalRRForAbsoluteRR(rr, resolvedRank);
  const includeRank = Boolean(options.includeRank);
  const withUnit = options.withUnit !== false;
  const suffix = options.suffix || "";
  const rankPrefix = includeRank && resolvedRank?.tierLabel ? `${resolvedRank.tierLabel} ` : "";
  const unit = withUnit ? " RR" : "";
  return `${rankPrefix}${localRR}${unit}${suffix}`;
}

function getAbsoluteRRForRankLocalRR(rankLabel, rr){
  const bounds = getTierBoundsByLabel(rankLabel) || getTierRank(0);
  const localRR = Math.max(0, Math.round(safeNumber(rr, 0)));
  if(isImmortalOrRadiantRank(bounds?.tierLabel)){
    return getAbsoluteRRForActRR(localRR);
  }
  return safeNumber(bounds?.min, 0) + Math.min(RANK_RR_STEP - 1, localRR);
}

function getAbsoluteRRForActRR(actRR){
  return IMMORTAL_ACT_RR_BASE + Math.max(0, Math.round(safeNumber(actRR, 0)));
}

function normalizeRadiantGoalRRInput(rr){
  const rawRR = Math.max(0, Math.round(safeNumber(rr, RADIANT_MIN_RR)));
  const actRR = rawRR >= IMMORTAL_ACT_RR_BASE
    ? rawRR - IMMORTAL_ACT_RR_BASE
    : rawRR;
  return Math.max(RADIANT_MIN_RR, actRR || RADIANT_MIN_RR);
}

function getMinimumRadiantPlusGoalRR(){
  return RADIANT_MIN_RR + 1;
}

function getMinimumRadiantGoalRR(label){
  const normalized = normalizeTierLabel(label);
  const minimum = getCurrentGoalMinimum();
  const currentRankLabel = normalizeTierLabel(minimum.currentRank?.tierLabel || "");
  const currentActRR = Math.max(0, Math.round(safeNumber(minimum.currentActRR, 0)));
  const currentIsRadiant = currentRankLabel === "Radiant";

  if(normalized === "Radiant +"){
    return Math.max(getMinimumRadiantPlusGoalRR(), currentIsRadiant ? currentActRR + 1 : getMinimumRadiantPlusGoalRR());
  }

  if(normalized === "Radiant"){
    return Math.max(minimum.radiantMinRR, currentIsRadiant ? currentActRR : minimum.radiantMinRR);
  }

  return minimum.radiantMinRR;
}

function getGoalRankTarget(label, requestedRR = null){
  const normalized = normalizeTierLabel(label);
  const bounds = getTierBoundsByLabel(normalized);
  if(!bounds) return null;

  const isRadiantPlus = normalized === "Radiant +";
  const isRadiant = bounds.tierLabel === "Radiant";
  const radiantFallbackRR = isRadiantPlus ? getMinimumRadiantGoalRR("Radiant +") : RADIANT_MIN_RR;
  const rawTarget = safeNumber(requestedRR, isRadiant ? radiantFallbackRR : bounds.min);
  const goalRR = isRadiant
    ? Math.max(radiantFallbackRR, normalizeRadiantGoalRRInput(rawTarget))
    : null;
  const isRadiantPlusGoal = isRadiant && (isRadiantPlus || goalRR > RADIANT_MIN_RR);
  const targetRR = isRadiant
    ? getAbsoluteRRForActRR(goalRR)
    : bounds.min;

  return {
    bounds,
    targetRR,
    goalRR,
    goalRankLabel: isRadiantPlusGoal ? "Radiant +" : bounds.tierLabel,
    isRadiantPlus: isRadiantPlusGoal
  };
}

function getProfileGoalTarget(profile){
  if(!profile?.goalRank) return null;
  return getGoalRankTarget(profile.goalRank, profile.goalRR);
}

function getCurrentGoalMinimum(){
  const computedRR = Math.max(0, Math.round(safeNumber(computeCurrentRRAbsolute(), 0)));
  const visibleRankLabel = normalizeTierLabel(
    document.getElementById("navCurrentTierText")?.textContent ||
    document.getElementById("navGoalCurrentIcon")?.alt ||
    ""
  );
  const visibleRank = getTierBoundsByLabel(visibleRankLabel);
  const computedRank = getTierRank(computedRR) || RANK_THRESHOLDS[0];
  const currentRank = visibleRank && safeNumber(visibleRank.min) > safeNumber(computedRank.min)
    ? visibleRank
    : computedRank;
  const currentRR = Math.max(computedRR, safeNumber(currentRank?.min, 0));
  const currentRankMin = Math.max(0, safeNumber(currentRank?.min, 0));
  const currentActRR = getActRRForAbsoluteRR(currentRR, currentRank);
  const radiantMinRR = RADIANT_MIN_RR;

  return { currentRR, currentRank, currentRankMin, currentActRR, radiantMinRR };
}

function getNextGoalRankSelection(){
  const minimum = getCurrentGoalMinimum();
  const nextRank = RANK_THRESHOLDS.find(rank => safeNumber(rank.min) > minimum.currentRR);
  if(nextRank){
    const target = getGoalRankTarget(nextRank.tierLabel);
    return {
      goalRank: nextRank.tierLabel,
      goalRR: null,
      target
    };
  }

  const goalRR = getMinimumRadiantGoalRR("Radiant +");
  return {
    goalRank: "Radiant +",
    goalRR,
    target: getGoalRankTarget("Radiant +", goalRR)
  };
}

function isGoalRankSelectionAllowed(label, requestedRR = null){
  const target = getGoalRankTarget(label, requestedRR);
  if(!target?.bounds) return false;

  const minimum = getCurrentGoalMinimum();
  if(target.targetRR <= minimum.currentRR) return false;
  if(target.bounds.tierLabel === "Radiant" && safeNumber(target.goalRR, 0) < getMinimumRadiantGoalRR(target.goalRankLabel || target.bounds.tierLabel)) return false;

  return true;
}

function getClampedGoalRankSelection(label, requestedRR = null){
  const target = getGoalRankTarget(label, requestedRR);
  if(target?.bounds && isGoalRankSelectionAllowed(target.goalRankLabel || target.bounds.tierLabel, target.goalRR ?? target.targetRR)){
    return {
      goalRank: target.goalRankLabel || target.bounds.tierLabel,
      goalRR: target.goalRR ?? target.targetRR,
      target
    };
  }

  return getNextGoalRankSelection();
}

function ensureProfileGoalRank(profile = getActiveProfile()){
  if(!profile) return null;
  const existingTarget = getProfileGoalTarget(profile);
  const currentRR = getCurrentGoalMinimum().currentRR;
  if(existingTarget?.bounds && existingTarget.targetRR > currentRR){
    return existingTarget;
  }

  const nextGoal = getNextGoalRankSelection();
  const changed = profile.goalRank !== nextGoal.goalRank || profile.goalRR !== nextGoal.goalRR;
  profile.goalRank = nextGoal.goalRank;
  profile.goalRR = nextGoal.goalRR;
  if(changed){
    profiles = profiles.map(item => item.id === profile.id
      ? { ...item, goalRank: profile.goalRank, goalRR: profile.goalRR }
      : item);
    saveProfiles();
  }
  return nextGoal.target;
}

