function updateLogAgentDisplay(agent){
  const display = document.getElementById("logAgentDisplay");
  const logAgentImg = document.getElementById("logAgentImg");
  const logAgentText = document.getElementById("logAgentText");
  const hasAgent = Boolean(String(agent || "").trim());

  if(display){
    if(hasAgent){
      display.dataset.agent = agent;
    } else {
      delete display.dataset.agent;
    }
    display.classList.toggle("is-empty", !hasAgent);
    display.setAttribute("aria-label", hasAgent ? `Selected agent ${agent}. Open agent selector.` : "Choose agent");
  }

  if(logAgentText){
    logAgentText.textContent = agent || "Choose agent";
  }

  if(logAgentImg){
    if(hasAgent){
      logAgentImg.src = getAgentIconUrl(agent);
      logAgentImg.classList.remove("is-silhouette");
      logAgentImg.style.display = "block";
    } else {
      logAgentImg.src = DEFAULT_AGENT_SILHOUETTE_SRC;
      logAgentImg.classList.add("is-silhouette");
      logAgentImg.style.display = "block";
    }
  }

  syncLoggingRoleTone(agentRoles?.[agent] || activeRole);
  updateLoggingDebriefPreview();
}

function setFocusOtherVisibility(show, value = ""){
  const wrapper = document.getElementById("focusOtherWrap");
  const input = document.getElementById("logFocusOther");
  const confirm = document.getElementById("confirmFocusOther");
  const focusWrapper = document.querySelector(".focus-wrapper");

  if(wrapper){
    wrapper.style.display = show ? "flex" : "none";
    wrapper.hidden = !show;
    wrapper.setAttribute("aria-hidden", String(!show));
  }
  focusWrapper?.classList.toggle("is-custom-focus-editing", Boolean(show));
  focusWrapper?.classList.toggle("custom-focus-committed", false);

  if(input){
    if(show){
      input.disabled = false;
      input.style.display = "";
      if(value) input.value = value;
      requestAnimationFrame(() => input.focus());
    } else {
      input.value = "";
      input.disabled = true;
    }
  }
  if(confirm){
    confirm.style.display = "";
  }
}

function setCustomFocusCommitted(value = ""){
  const wrapper = document.querySelector(".focus-wrapper");
  const otherWrap = document.getElementById("focusOtherWrap");
  const preview = document.getElementById("focusPreviewText");
  const input = document.getElementById("logFocusOther");
  const confirm = document.getElementById("confirmFocusOther");
  const select = document.getElementById("logFocusSelect");
  const isOtherFocus = select?.value === "Other";
  const roleClasses = [
    "role-duelist",
    "role-controller",
    "role-initiator",
    "role-sentinel"
  ];

  if(preview){
    preview.textContent = value || "";
    preview.classList.remove(...roleClasses);
    if(input){
      const activeRoleClass = roleClasses.find(cls => input.classList.contains(cls));
      if(activeRoleClass){
        preview.classList.add(activeRoleClass);
      }
    }
  }

  if(input && value){
    input.value = value;
  }

  wrapper?.classList.toggle("custom-focus-committed", !!value);
  wrapper?.classList.toggle("is-custom-focus-editing", !value && isOtherFocus);
  if(otherWrap){
    const shouldShowOtherWrap = Boolean(value || isOtherFocus);
    otherWrap.style.display = shouldShowOtherWrap ? "flex" : "none";
    otherWrap.hidden = !shouldShowOtherWrap;
    otherWrap.setAttribute("aria-hidden", String(!shouldShowOtherWrap));
  }
  if(input){
    input.disabled = !!value;
  }
  if(confirm){
    confirm.style.display = value ? "none" : "";
  }
  syncLogFocusCustomDropdown();
}

function resetCustomFocusUI(){
  const select = document.getElementById("logFocusSelect");
  setCustomFocusCommitted("");
  setFocusOtherVisibility(false);
  if(select){
    select.style.display = "";
  }
  syncLogFocusCustomDropdown();
  updateLoggingDebriefPreview();
}

function closeLogFocusCustomDropdown() {
  const shell = document.getElementById("logFocusCustomSelect");
  const menu = document.getElementById("logFocusCustomMenu");
  const trigger = document.getElementById("logFocusCustomTrigger");
  shell?.classList.remove("open");
  if (menu) menu.hidden = true;
  trigger?.setAttribute("aria-expanded", "false");
}

function positionLogFocusCustomDropdown() {
  const trigger = document.getElementById("logFocusCustomTrigger");
  const menu = document.getElementById("logFocusCustomMenu");
  if (!trigger || !menu || menu.hidden) return;
  const rect = trigger.getBoundingClientRect();
  const viewportPadding = 12;
  const requestedWidth = Math.min(280, Math.max(190, rect.width));
  menu.style.minWidth = `${requestedWidth}px`;
  const menuWidth = Math.min(280, Math.max(requestedWidth, menu.offsetWidth || requestedWidth));
  const maxLeft = Math.max(viewportPadding, window.innerWidth - menuWidth - viewportPadding);
  const left = Math.min(maxLeft, Math.max(viewportPadding, rect.right - menuWidth));
  const top = Math.min(rect.bottom + 6, window.innerHeight - viewportPadding);
  menu.style.position = "fixed";
  menu.style.top = `${Math.max(viewportPadding, top)}px`;
  menu.style.left = `${left}px`;
  menu.style.right = "auto";
}

function syncLogFocusCustomDropdown() {
  const select = document.getElementById("logFocusSelect");
  const valueEl = document.getElementById("logFocusCustomValue");
  const menu = document.getElementById("logFocusCustomMenu");
  const trigger = document.getElementById("logFocusCustomTrigger");
  if (!select) return;

  const value = String(select.value || "").trim();
  const mobileBrowseLabel = isMobileLayoutViewport();
  if (valueEl) valueEl.textContent = mobileBrowseLabel ? "Browse" : (value && value !== "Other" ? value : "Browse");

  const roleClasses = ["role-duelist", "role-controller", "role-initiator", "role-sentinel"];
  trigger?.classList.remove(...roleClasses);
  roleClasses.forEach((roleClass) => {
    if (select.classList.contains(roleClass)) trigger?.classList.add(roleClass);
  });

  menu?.querySelectorAll(".log-focus-custom-option").forEach((option) => {
    const isActive = option.dataset.value === value;
    option.classList.toggle("is-active", isActive);
    option.setAttribute("aria-selected", isActive ? "true" : "false");
  });
}

function syncLogFocusSelectOptions() {
  const select = document.getElementById("logFocusSelect");
  if (!select) return;

  const currentValue = String(select.value || "");
  const optionValues = ["", ...focusesList, "Other"];
  const optionLabels = new Map([
    ["", "Focus Category"],
    ["Other", "Other"]
  ]);

  select.innerHTML = "";
  optionValues.forEach((value) => {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = optionLabels.get(value) || value;
    select.appendChild(option);
  });

  if (optionValues.includes(currentValue)) {
    select.value = currentValue;
  }
}

function setupLogFocusCustomDropdown() {
  const select = document.getElementById("logFocusSelect");
  const shell = select?.closest(".focus-select-shell");
  if (!select || !shell) return;

  select.classList.add("log-focus-native-select");
  select.setAttribute("aria-hidden", "true");
  select.tabIndex = -1;
  shell.classList.add("has-custom-focus-select");

  if (select.dataset.logFocusCustomBound === "1") {
    syncLogFocusCustomDropdown();
    return;
  }

  let customShell = document.getElementById("logFocusCustomSelect");
  if (!customShell) {
    customShell = document.createElement("div");
    customShell.id = "logFocusCustomSelect";
    customShell.className = "log-focus-custom-select";
    customShell.innerHTML = `
      <button id="logFocusCustomTrigger" class="log-focus-custom-trigger" type="button" aria-haspopup="listbox" aria-expanded="false">
        <span id="logFocusCustomValue"></span>
        <span class="log-focus-custom-chevron" aria-hidden="true">v</span>
      </button>
    `;
    shell.appendChild(customShell);
  }
  let menu = document.getElementById("logFocusCustomMenu");
  if (!menu) {
    menu = document.createElement("div");
    menu.id = "logFocusCustomMenu";
    menu.className = "log-focus-custom-menu";
    menu.role = "listbox";
    menu.hidden = true;
  }
  document.body.appendChild(menu);

  const trigger = document.getElementById("logFocusCustomTrigger");
  if (!trigger || !menu) return;

  menu.innerHTML = "";
  Array.from(select.options).forEach((option) => {
    if (!option.value) return;
    const item = document.createElement("button");
    item.type = "button";
    item.className = "log-focus-custom-option";
    item.dataset.value = option.value;
    item.role = "option";
    item.textContent = option.textContent || option.value;
    menu.appendChild(item);
  });

  trigger.addEventListener("click", (e) => {
    e.preventDefault();
    e.stopPropagation();
    const willOpen = menu.hidden;
    closeLogFocusCustomDropdown();
    if (willOpen) {
      customShell.classList.add("open");
      menu.hidden = false;
      trigger.setAttribute("aria-expanded", "true");
      syncLogFocusCustomDropdown();
      positionLogFocusCustomDropdown();
    }
  });

  menu.addEventListener("click", (e) => {
    const option = e.target.closest(".log-focus-custom-option");
    if (!option) return;
    e.preventDefault();
    e.stopPropagation();
    select.value = option.dataset.value || select.value;
    select.dispatchEvent(new Event("change", { bubbles: true }));
    closeLogFocusCustomDropdown();
  });

  document.addEventListener("click", (e) => {
    if (!customShell.contains(e.target) && !menu.contains(e.target)) closeLogFocusCustomDropdown();
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") closeLogFocusCustomDropdown();
  });
  window.addEventListener("resize", positionLogFocusCustomDropdown);
  window.addEventListener("scroll", positionLogFocusCustomDropdown, true);

  select.dataset.logFocusCustomBound = "1";
  syncLogFocusCustomDropdown();
}

function syncLoggingFocusPreviewText(value = "") {
  const preview = document.getElementById("focusPreviewText");
  if (!preview) return;
  const isEditingCustomFocus = document.querySelector(".focus-wrapper")?.classList.contains("is-custom-focus-editing");
  if (isEditingCustomFocus) {
    preview.textContent = "";
    preview.classList.add("is-placeholder");
    return;
  }
  const resolved = String(value || "").trim();
  preview.textContent = resolved || "Focus Category";
  preview.classList.toggle("is-placeholder", !resolved);
}

function getLoggingDebriefTone(rating, mood) {
  const normalizedMood = String(mood || "").toLowerCase();
  if (Number(rating) >= 4 || ["focused", "fun", "calm"].includes(normalizedMood)) {
    return {
      key: "strong",
      label: "Strong Session Read"
    };
  }
  if (Number(rating) && Number(rating) <= 2 || ["annoyed", "tilted"].includes(normalizedMood)) {
    return {
      key: "reset",
      label: "Reset Session Read"
    };
  }
  return {
    key: "steady",
    label: "Steady Session Read"
  };
}

function updateLoggingDebriefPreview() {
  const toneEl = document.getElementById("loggingLiveTone");
  const focusEl = document.getElementById("loggingLiveFocus");
  const metaEl = document.getElementById("loggingLiveMeta");
  if (!toneEl || !focusEl || !metaEl) return;

  const agent = document.getElementById("logAgentDisplay")?.dataset?.agent || "";
  const focusSelect = document.getElementById("logFocusSelect");
  const customFocus = document.getElementById("logFocusOther")?.value?.trim() || "";
  const map = document.getElementById("logMap")?.value?.trim() || "";
  const notes = document.getElementById("logNotes")?.value?.trim() || "";
  let focus = focusSelect?.value || "";
  if (focus === "Other") {
    focus = customFocus || "";
  }
  if (!focus) {
    focus = customFocus || "";
  }

  syncLoggingFocusPreviewText(focus);

  const tone = getLoggingDebriefTone(selectedLogRating, selectedLogMood);
  toneEl.classList.remove("tone-strong", "tone-steady", "tone-reset");
  toneEl.classList.add(`tone-${tone.key}`);
  toneEl.textContent = tone.label;

  const focusParts = [];
  if (agent) focusParts.push(agent);
  if (focus) focusParts.push(focus);
  focusEl.textContent = focusParts.length
    ? `${focusParts.join(" | ")}`
    : "Pick an agent and focus category to build the debrief.";

  const hasSelectedNumber = value => value !== null
    && value !== undefined
    && String(value).trim() !== ""
    && Number.isFinite(Number(value));
  const metaParts = [];
  if (hasSelectedNumber(selectedLogRating)) metaParts.push(`Self Rating ${selectedLogRating}/5`);
  if (selectedLogMood) metaParts.push(selectedLogMood);
  if (hasSelectedNumber(selectedLogTeamComms)) metaParts.push(`Team Comms ${selectedLogTeamComms}/5`);
  if (hasSelectedNumber(selectedLogSelfComms)) metaParts.push(`Self Comms ${selectedLogSelfComms}/5`);
  if (map) metaParts.push(map);
  if (notes) metaParts.push(`${Math.min(notes.length, 140)} chars captured`);
  metaEl.textContent = metaParts.length
    ? metaParts.join(" | ")
    : "Add a rating, mood, or map to see it here.";
}

function renderInsightCards() {
  return renderInsightCardsModel();
  const container = document.getElementById("insightsList");
  if (!container) return;

  container.innerHTML = "";

  let list = cachedInsights.slice();

  if (activeInsightFilter !== "all") {
    list = list.filter(insight => insight.type === activeInsightFilter);
  }

  if (!list.length && cachedInsights.length) {
    list = cachedInsights.slice();
  }

  list.forEach((insight) => {
    const el = document.createElement("div");
    el.className = `insight-card insight-${insight.type}`;
    el.style.position = "relative";

    el.innerHTML = `
      <div class="insight-header">
        <div class="insight-header-main">
          <div class="insight-title">${escapeHtml(insight.title)}</div>
          <div class="insight-tag">${escapeHtml(insight.type.toUpperCase())}</div>
        </div>
      </div>

      <div class="insight-preview">
        ${escapeHtml(insight.preview || "")}
      </div>

      <div class="insight-expand">
        <div class="insight-block">
          <div class="insight-label">WHAT</div>
          ${escapeHtml(insight.what || "")}
        </div>

        <div class="insight-block">
          <div class="insight-label">WHY</div>
          ${escapeHtml(insight.why || "")}
        </div>

        <div class="insight-block">
          <div class="insight-label">ACTION</div>
          ${escapeHtml(insight.action || "Review recent matches and adjust your approach")}
        </div>

        <div class="insight-sources">
          ${(insight.sources || []).map((s) => `<span class="insight-source">${escapeHtml(s)}</span>`).join("")}
        </div>
      </div>
    `;

    container.appendChild(el);
  });

  bindInsightCards();
  scheduleInsightListOverflowSync(container);
}

function syncInsightListOverflow(container = document.getElementById("insightsList")) {
  if (!container) return;

  if (isMobileLayoutViewport()) {
    container.classList.remove("is-scrollable");
    container.style.removeProperty("--insights-scroll-height");
    container.style.removeProperty("height");
    container.style.removeProperty("min-height");
    container.style.removeProperty("max-height");
    container.style.removeProperty("overflow-y");
    container.style.removeProperty("overflow-x");
    container.style.removeProperty("padding-right");
    container.style.removeProperty("padding-bottom");
    container.style.removeProperty("box-sizing");
    container.style.removeProperty("scrollbar-gutter");
    return;
  }

  const cards = [...container.querySelectorAll(".insight-card")];
  const hasOpenCard = container.classList.contains("has-open-card");
  const shouldScroll = cards.length > 3;
  const customHeight = getThemeBuilderGroupOverrideValue("insights-top-card", "insights-list", "groupHeight");
  const shouldLockHeight = Boolean(customHeight) || hasOpenCard || shouldScroll;

  container.classList.toggle("is-scrollable", shouldLockHeight);

  if (!shouldLockHeight) {
    container.style.removeProperty("--insights-scroll-height");
    container.style.removeProperty("height");
    container.style.removeProperty("min-height");
    container.style.removeProperty("max-height");
    container.style.removeProperty("overflow-y");
    container.style.removeProperty("overflow-x");
    container.style.removeProperty("padding-right");
    container.style.removeProperty("padding-bottom");
    container.style.removeProperty("box-sizing");
    container.style.removeProperty("scrollbar-gutter");
    return;
  }

  const computed = window.getComputedStyle(container);
  const gap = parseFloat(computed.rowGap || computed.gap || "0") || 0;
  const visibleCards = hasOpenCard
    ? cards.filter((card) => card.classList.contains("open")).slice(0, 1)
    : cards.slice(0, 3);
  const measuredHeight = visibleCards.reduce((sum, card) => sum + card.getBoundingClientRect().height, 0) + (gap * Math.max(0, visibleCards.length - 1));
  const hostCard = container.closest(".insights-top-card");
  const hostStyle = hostCard ? window.getComputedStyle(hostCard) : null;
  const hostInnerHeight = hostCard
    ? hostCard.clientHeight
      - (parseFloat(hostStyle?.paddingTop || "0") || 0)
      - (parseFloat(hostStyle?.paddingBottom || "0") || 0)
    : 0;
  const availableListHeight = hostCard && Number.isFinite(hostInnerHeight) && hostInnerHeight > 0
    ? Math.max(120, Math.floor(hostInnerHeight - (container.offsetTop || 0) - 2))
    : 0;
  const fallbackHeight = Math.max(hasOpenCard ? 320 : 220, Math.floor(measuredHeight));
  const targetViewportHeight = availableListHeight > 0
    ? availableListHeight
    : (hasOpenCard && Number.isFinite(hostInnerHeight) && hostInnerHeight > 0
        ? Math.floor(hostInnerHeight * 0.82)
        : fallbackHeight);
  const minimumLockedHeight = hasOpenCard
    ? Math.min(220, targetViewportHeight || fallbackHeight)
    : 120;
  const lockedHeight = customHeight
    ? appendThemeBuilderPxIfNeeded(customHeight, "px", "y")
    : `${Math.max(minimumLockedHeight, targetViewportHeight || fallbackHeight)}px`;

  container.style.setProperty("--insights-scroll-height", lockedHeight);
  container.style.setProperty("box-sizing", "border-box");
  container.style.setProperty("height", lockedHeight, "important");
  container.style.setProperty("min-height", lockedHeight, "important");
  container.style.setProperty("max-height", lockedHeight, "important");
  container.style.setProperty("overflow-y", "scroll");
  container.style.setProperty("overflow-x", "hidden");
  container.style.setProperty("padding-right", "6px");
  container.style.setProperty("padding-bottom", "6px");
  container.style.setProperty("scrollbar-gutter", "stable");
}

function getThemeBuilderGroupOverrideValue(parentId = "", groupId = "", field = "") {
  if (THEME_BUILDER_LAUNCH_LOCKED) return "";
  if (!parentId || !groupId || !field) return "";
  const themeKey = typeof getCurrentThemeBuilderThemeKey === "function"
    ? getCurrentThemeBuilderThemeKey()
    : (document.body?.dataset?.theme || "");
  const value = themeBuilderState?.[themeKey]?.groups?.[parentId]?.[groupId]?.[field];
  return String(value ?? "").trim();
}

function scheduleInsightListOverflowSync(container = document.getElementById("insightsList")) {
  if (!container) return;
  syncInsightListOverflow(container);
  requestAnimationFrame(() => {
    syncInsightListOverflow(container);
    window.setTimeout(() => syncInsightListOverflow(container), 80);
  });
}

function bindInsightFilters() {
  const buttons = document.querySelectorAll(".insight-filter-btn");
  if (!buttons.length) return;

  const allowedFilters = new Set(["all", "bad", "warn", "good"]);
  if (!allowedFilters.has(activeInsightFilter)) {
    activeInsightFilter = "all";
  }

  if (activeInsightFilter !== "all" && !getFilteredInsightDisplayList(activeInsightFilter).length) {
    activeInsightFilter = "all";
  }

  buttons.forEach(button => {
    const filter = button.dataset.filter || "all";
    const hasCards = filter === "all" || getFilteredInsightDisplayList(filter).length > 0;
    button.disabled = !hasCards;
    button.classList.toggle("is-empty", !hasCards);
    button.setAttribute("aria-disabled", hasCards ? "false" : "true");
    button.classList.toggle("active", filter === activeInsightFilter && hasCards);
    button.onclick = () => {
      if (button.disabled) return;
      const nextFilter = button.dataset.filter || "all";
      activeInsightFilter = allowedFilters.has(nextFilter) ? nextFilter : "all";

      buttons.forEach(btn => {
        btn.classList.toggle("active", btn.dataset.filter === activeInsightFilter);
      });

      if (activeInsightFilter === "all") {
        const allBtn = document.querySelector('.insight-filter-btn[data-filter="all"]');
        allBtn?.classList.add("active");
      }

      document.getElementById("insightsList")?.classList.remove("has-open-card");
      renderInsightCards();
    };
  });
}

function renderTrendBreakdown() {
  return renderTrendBreakdownModel();
  const analytics = getActiveAnalytics();
  const trendBlocks = {
    performance: [
      `Current KD: ${document.getElementById("statKD")?.textContent || "--"}`,
      `Current win rate: ${document.getElementById("statWinrate")?.textContent || "--"}`,
      analytics?.overview?.adr ? `Current ADR this act: ${Math.round(analytics.overview.adr)}` : "ADR trend builds as more demo/live imports are added."
    ],
    behavior: [
      `Weekly sessions counted: ${getWeeklySessions().length}`,
      `Most repeated focus category this week: ${document.getElementById("weeklyFocusPrimary")?.textContent || "--"}`,
      `Mood analysis uses logging data, which is where future behavior ML will anchor.`
    ],
    role: [
      ...(analytics?.roles || []).slice(0, 3).map(role =>
        `${role.role}: ${Number(role.kd || 0).toFixed(2)} KD across ${role.matchesPlayed} matches`
      ),
      !analytics?.roles?.length ? "Role impact is reported after imported analytics are available." : null
    ].filter(Boolean),
    consistency: [
      `Recent imported matches: ${matches.length}`,
      analytics?.overview?.attackKAST ? `Attack KAST: ${Math.round(analytics.overview.attackKAST)}%` : "Attack-side stability pending richer data.",
      analytics?.overview?.defenseKAST ? `Defense KAST: ${Math.round(analytics.overview.defenseKAST)}%` : "Defense-side stability pending richer data."
    ]
  };

  Object.entries(trendBlocks).forEach(([key, items]) => {
    const content = document.querySelector(`[data-trend-content="${key}"]`);
    if (!content) return;
    content.innerHTML = items.map(item => `<div class="trend-line">${escapeHtml(item)}</div>`).join("");
  });
}

function bindInsightCards(){
  const container = document.getElementById("insightsList");
  if(!container) return;

  const cards = [...container.querySelectorAll(".insight-card:not(.insight-empty)")];
  const getRenderedInsights = () => {
    const model = getPlayerModel();
    return getFilteredInsightDisplayList(activeInsightFilter, model);
  };
  const closeAll = () => {
    cards.forEach(c => c.classList.remove("open"));
    container.classList.remove("has-open-card");
    scheduleInsightListOverflowSync(container);
  };

  cards.forEach(card => {
    card.onclick = (event) => {
      const feedbackButton = event.target.closest(".insight-feedback-btn");
      if (feedbackButton) {
        event.preventDefault();
        event.stopPropagation();
        const insight = getRenderedInsights()[safeNumber(card.dataset.insightIndex, -1)];
        if (!insight) return;
        const rating = feedbackButton.dataset.feedbackRating || "helpful";
        recordInsightFeedback(insight, rating);
        card.querySelectorAll(".insight-feedback-btn").forEach(button => {
          button.classList.toggle("is-active", button === feedbackButton);
        });
        const label = card.querySelector(".insight-feedback-label");
        if (label) label.textContent = rating === "helpful" ? "Saved as useful." : "Saved for review.";
        return;
      }

      if (event.target.closest(".insight-close")) {
        event.preventDefault();
        event.stopPropagation();
        closeAll();
        return;
      }

      const isOpen = card.classList.contains("open");

      closeAll();

      if(isOpen){
        return;
      }

      card.classList.add("open");
      container.classList.add("has-open-card");
      scheduleInsightListOverflowSync(container);
    };
  });
}

function replayOpenInsightTrendAnimation() {
  const content = document.querySelector(".trend-content.open");
  if (!content) return;
  content.classList.remove("trend-content-animate");
  void content.offsetWidth;
  content.classList.add("trend-content-animate");
}

function syncCompassDescriptionToggleState(forceExpanded = null) {
  const shell = document.querySelector(".compass-summary-shell");
  const button = document.getElementById("compassDescriptionToggle");
  if (!shell || !button) return;

  if (typeof forceExpanded === "boolean") {
    shell.classList.toggle("is-expanded", forceExpanded);
  }

  const expanded = shell.classList.contains("is-expanded");
  button.setAttribute("aria-expanded", expanded ? "true" : "false");
  button.textContent = expanded ? "Hide description" : "Show description";
}

function bindInsightTrendRows(){
  const wrap = document.querySelector(".insight-trends");
  const rows = document.querySelectorAll(".insight-trend-row");
  const contents = document.querySelectorAll(".trend-content");
  if (!wrap || !rows.length) return;

  const setActiveTrend = (trendKey = "") => {
    const normalizedKey = String(trendKey || "").trim().toLowerCase();
    wrap.dataset.openTrend = normalizedKey;

    rows.forEach((row) => {
      const isOpen = String(row.dataset.trend || "").trim().toLowerCase() === normalizedKey;
      row.classList.toggle("open", isOpen);
    });

    contents.forEach((content) => {
      const isOpen = String(content.dataset.trendContent || "").trim().toLowerCase() === normalizedKey;
      content.classList.toggle("open", isOpen);
      if (isOpen) {
        content.classList.remove("trend-content-animate");
        void content.offsetWidth;
        content.classList.add("trend-content-animate");
      } else {
        content.classList.remove("trend-content-animate");
      }
    });

    wrap.classList.toggle("has-open-card", !!normalizedKey);
  };

  rows.forEach((row) => {
    row.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();

      const trendKey = String(row.dataset.trend || "").trim().toLowerCase();
      setActiveTrend(trendKey);
    };
  });

  const existingTrend =
    wrap.dataset.openTrend ||
    [...rows].find((row) => row.classList.contains("open"))?.dataset.trend ||
    rows[0]?.dataset.trend ||
    "";

  setActiveTrend(existingTrend);
}

