function getMatchPanelStats(match = null) {
  const core = getMatchCore(match || {});
  return {
    kills: Number.isFinite(Number(match?.kills)) ? Number(match.kills) : (Number.isFinite(core?.kills) ? core.kills : safeNumber(match?.kills, null)),
    deaths: Number.isFinite(Number(match?.deaths)) ? Number(match.deaths) : (Number.isFinite(core?.deaths) ? core.deaths : safeNumber(match?.deaths, null)),
    assists: Number.isFinite(Number(match?.assists)) ? Number(match.assists) : (Number.isFinite(core?.assists) ? core.assists : safeNumber(match?.assists, null)),
    acs: Number.isFinite(Number(match?.acs)) ? Number(match.acs) : (Number.isFinite(core?.acs) ? core.acs : safeNumber(match?.acs ?? match?.adr, null))
  };
}

function hasMatchPanelStats(match = null) {
  const stats = getMatchPanelStats(match);
  return ["kills", "deaths", "assists", "acs"].some(key => {
    const value = Number(stats?.[key]);
    return Number.isFinite(value);
  });
}

function updateRRMatchStats(match = null, matchIndex = null, options = {}) {
  const panel = {
    kills: rrKillsEl,
    deaths: rrDeathsEl,
    assists: rrAssistsEl,
    acs: rrACSEl
  };

  if (!panel.kills || !panel.deaths || !panel.assists || !panel.acs) return;

  if (!match) {
    if (rrMatchTitleEl) rrMatchTitleEl.textContent = "Latest Game";
    if (rrMatchMetaEl) rrMatchMetaEl.textContent = "Select a game dot to inspect its snapshot.";
    panel.kills.textContent = "--";
    panel.deaths.textContent = "--";
    panel.assists.textContent = "--";
    panel.acs.textContent = "--";
    updateImpactRolePill(null, null);
    updateImpactBar(0);
    return;
  }

  const stats = getMatchPanelStats(match);
  const displayIndex = Number.isInteger(options?.displayIndex)
    ? options.displayIndex
    : matchIndex;
  const gameLabel = Number.isInteger(displayIndex) && displayIndex >= 0
    ? `Game ${displayIndex + 1}`
    : "Selected Game";
  const rrDelta = getOptionalFiniteNumber(
    isVerifiedHenrikRrMatch(match)
      ? match?.verifiedRrDelta ?? match?.matchRecord?.rank?.rrDelta
      : match?.rr
  );
  const rrLabel = Number.isFinite(rrDelta)
    ? `${rrDelta > 0 ? "+" : ""}${rrDelta} RR`
    : "RR unavailable";
  const resultLabel = String(match?.result || match?.metadata?.result || "draw")
    .replace(/^./, char => char.toUpperCase());
  const agentLabel = match?.metadata?.agent || match?.agent || "Unknown Agent";
  const mapLabel = match?.metadata?.mapName || match?.map || "Unknown Map";
  const impactTier = String(match?.impactTier || "").trim();
  const impactScore = Number(match?.impactScore);
  const statsAvailable = hasMatchPanelStats(match);

  if (rrMatchTitleEl) rrMatchTitleEl.textContent = gameLabel;
  if (rrMatchMetaEl) {
    rrMatchMetaEl.textContent = statsAvailable
      ? `${resultLabel} Â· ${rrLabel} Â· ${agentLabel}`
      : `${resultLabel} Â· ${rrLabel} Â· ${agentLabel} Â· No saved combat snapshot`;
  }
  if (rrMatchMetaEl) {
    const impactLabel = impactTier
      ? `${impactTier}${Number.isFinite(impactScore) ? ` ${Math.round(impactScore)}` : ""}`
      : "No impact rating";
    rrMatchMetaEl.textContent = statsAvailable
      ? `${resultLabel} | ${rrLabel} | ${agentLabel} | ${mapLabel} | ${impactLabel}`
      : `${resultLabel} | ${rrLabel} | ${agentLabel} | ${mapLabel} | ${impactLabel} | No saved combat snapshot`;
  }
  panel.kills.textContent = Number.isFinite(Number(stats.kills)) ? `${Math.round(Number(stats.kills))}` : "N/A";
  panel.deaths.textContent = Number.isFinite(Number(stats.deaths)) ? `${Math.round(Number(stats.deaths))}` : "N/A";
  panel.assists.textContent = Number.isFinite(Number(stats.assists)) ? `${Math.round(Number(stats.assists))}` : "N/A";
  panel.acs.textContent = Number.isFinite(Number(stats.acs)) ? `${Math.round(Number(stats.acs))}` : "N/A";
  updateImpactRolePill(match, matchIndex, { displayIndex });
  if (Number.isFinite(impactScore)) {
    updateImpactBar(Math.round(impactScore));
  }
}

function updateRRMatchStatsFromHit(hit) {
  const matchIndex = Number(hit?.dataset?.matchIndex);
  const sessionIndex = Number(hit?.dataset?.sessionIndex);
  const matchId = String(hit?.dataset?.matchId || "").trim();
  const matchKey = String(hit?.dataset?.matchKey || "").trim();
  if (!Number.isInteger(matchIndex) || matchIndex < 0 || matchIndex >= matches.length) {
    updateRRMatchStats(null, null);
    return;
  }

  const model = getPlayerModel();
  const impactSnapshots = model?.scoring?.impactSnapshots || [];
  const fallbackMatch = matches[matchIndex] || null;
  const match = matches.find(item => {
    const itemKey = getMatchIdentityKey(item);
    return (matchKey && itemKey === matchKey)
      || (matchId && (
        String(item?.id || "").trim() === matchId
        || String(item?.matchId || "").trim() === matchId
      ));
  }) || fallbackMatch;
  const snapshot = findImpactSnapshotForMatch(match, matchIndex, impactSnapshots)
    || (matchKey
      ? (impactSnapshots.find(item => getMatchIdentityKey(item) === matchKey) || null)
      : null);
  const hitStats = {
    kills: snapshot?.kills ?? hit?.dataset?.kills,
    deaths: snapshot?.deaths ?? hit?.dataset?.deaths,
    assists: snapshot?.assists ?? hit?.dataset?.assists,
    acs: snapshot?.acs ?? hit?.dataset?.acs,
    map: snapshot?.map || hit?.dataset?.map,
    agent: snapshot?.agent || hit?.dataset?.agent,
    result: match?.result || match?.metadata?.result || hit?.dataset?.result,
    createdAt: match?.createdAt || match?.metadata?.playedAt || hit?.dataset?.createdAt,
    impactTier: snapshot?.impactTier || hit?.dataset?.impactTier,
    impactScore: snapshot?.impactScore ?? hit?.dataset?.impactScore,
    impactColor: snapshot?.impactColor || hit?.dataset?.impactColor
  };

  updateRRMatchStats({
    ...(match || {}),
    kills: Number.isFinite(Number(hitStats.kills)) ? Number(hitStats.kills) : match?.kills,
    deaths: Number.isFinite(Number(hitStats.deaths)) ? Number(hitStats.deaths) : match?.deaths,
    assists: Number.isFinite(Number(hitStats.assists)) ? Number(hitStats.assists) : match?.assists,
    acs: Number.isFinite(Number(hitStats.acs)) ? Number(hitStats.acs) : match?.acs,
    map: hitStats.map || match?.map,
    agent: hitStats.agent || match?.agent,
    result: hitStats.result || match?.result,
    createdAt: hitStats.createdAt || match?.createdAt,
    impactTier: hitStats.impactTier || match?.impactTier,
    impactScore: Number.isFinite(Number(hitStats.impactScore)) ? Number(hitStats.impactScore) : match?.impactScore,
    impactColor: hitStats.impactColor || match?.impactColor,
    metadata: {
      ...(match?.metadata || {}),
      mapName: hitStats.map || match?.metadata?.mapName,
      agent: hitStats.agent || match?.metadata?.agent
    }
  }, matchIndex, {
    displayIndex: Number.isInteger(sessionIndex) && sessionIndex >= 0 ? sessionIndex : matchIndex
  });
}

function getChartHitFromTarget(target) {
  const element = target?.closest?.(".rr-hit, .rr-dot, .final-end");
  if (!element) return null;

  if (element.classList.contains("rr-hit")) {
    return element;
  }

  const indexedHit = getChartHitFromDot(element);
  if (indexedHit) {
    return indexedHit;
  }

  const siblingHit = element.previousElementSibling;
  if (siblingHit?.classList?.contains("rr-hit")) {
    return siblingHit;
  }

  return null;
}

function getChartDotFromHit(hit) {
  const siblingDot = hit?.nextElementSibling;
  if (siblingDot?.classList?.contains("rr-dot") || siblingDot?.classList?.contains("final-end")) {
    return siblingDot;
  }

  return null;
}

function getChartHitFromDot(dot) {
  if (!dot) return null;
  const matchIndex = String(dot.dataset?.matchIndex || dot.dataset?.index || "");
  if (!matchIndex) return null;
  return Array.from(chartRow?.querySelectorAll?.(".rr-hit") || [])
    .find(hit => String(hit.dataset?.matchIndex || hit.dataset?.index || "") === matchIndex) || null;
}

const AGENT_REEL_STRIP_RESET_DELAY_MS = 420;

function getAgentReelStepHeight(reel, frame) {
  const hostFrame = frame || reel?.closest?.(".agent-frame");
  return syncAgentUnifiedFrameGeometry(hostFrame);
}

function syncAgentReelGeometry(reel, strip, frame) {
  if (!reel || !strip) return 120;

  const hostFrame = frame || reel.closest?.(".agent-frame");
  const stepHeight = getAgentReelStepHeight(reel, hostFrame);
  hostFrame?.style.setProperty("--agent-reel-step", `${stepHeight}px`);
  reel.style.setProperty("--agent-reel-step", `${stepHeight}px`);
  strip.querySelectorAll(".reel-icon").forEach(img => {
    img.style.height = `${stepHeight}px`;
    img.style.flexBasis = `${stepHeight}px`;
  });

  return stepHeight;
}

function settleReelVisualState(reel) {
  if (!reel) return;
  reel.classList.remove("reel-placeholder", "reel-spinning");
  reel.style.opacity = "";
  reel.style.filter = "";
  reel.closest(".agent-frame")?.classList.remove("reel-active");
  const strip = reel.querySelector(".reel-strip");
  if (strip) {
    window.setTimeout(() => {
      if (reel.classList.contains("reel-spinning") || reel.closest(".agent-frame")?.classList.contains("reel-active")) {
        return;
      }
      strip.style.transition = "none";
      strip.style.transform = "translateY(0px)";
    }, AGENT_REEL_STRIP_RESET_DELAY_MS);
  }
}

function refreshActiveModalState() {
  const body = document.body;
  if (!body) return;

  const hasActiveModal = Array.from(document.querySelectorAll(".lens-modal-overlay, .agent-modal, .profile-edit-overlay, .auth-modal-overlay")).some((modal) => {
    const isModalActive =
      modal.classList.contains("active") ||
      modal.classList.contains("is-opening") ||
      modal.classList.contains("is-closing");
    if (!isModalActive || modal.hidden || modal.getAttribute("aria-hidden") === "true") return false;
    const style = window.getComputedStyle(modal);
    return style.display !== "none" && style.visibility !== "hidden" && style.pointerEvents !== "none";
  });

  body.classList.toggle("has-active-modal", hasActiveModal);
  body.classList.toggle("mobile-modal-open", hasActiveModal && isMobileLayoutViewport());
  applyMobileScrollSurfaceState();
  if (hasActiveModal) hideChartTooltip();
}

function showModalById(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  if (
    modal.classList.contains("lens-modal-overlay") &&
    (modal.id !== "goalRankModal" || !isMobileLayoutViewport()) &&
    modal.parentElement !== document.body
  ) {
    document.body.appendChild(modal);
  }
  if (modal._modalTransitionTimer) {
    window.clearTimeout(modal._modalTransitionTimer);
    modal._modalTransitionTimer = 0;
  }
  modal.style.display = "flex";
  modal.hidden = false;
  modal.setAttribute("aria-hidden", "false");
  modal.classList.remove("is-closing");
  if (modal.classList.contains("active")) {
    refreshActiveModalState();
    return;
  }
  modal.classList.add("is-opening");
  void modal.offsetWidth;
  refreshActiveModalState();
  window.requestAnimationFrame(() => {
    if (!modal.isConnected) return;
    modal.classList.add("active");
    refreshActiveModalState();
    modal._modalTransitionTimer = window.setTimeout(() => {
      if (!modal.isConnected) return;
      modal.classList.remove("is-opening");
      modal._modalTransitionTimer = 0;
      refreshActiveModalState();
    }, 320);
  });
}

function hideModalById(id) {
  const modal = document.getElementById(id);
  if (!modal) return;
  const style = window.getComputedStyle(modal);
  const hasVisibleModalState =
    modal.classList.contains("active")
    || modal.classList.contains("is-opening")
    || modal.classList.contains("is-closing");
  const isAlreadyHidden =
    modal.hidden
    || modal.getAttribute("aria-hidden") === "true"
    || style.display === "none"
    || style.visibility === "hidden"
    || style.pointerEvents === "none"
    || Number.parseFloat(style.opacity || "1") <= 0;
  if (!hasVisibleModalState && isAlreadyHidden) return;
  if (modal.contains(document.activeElement) && typeof document.activeElement?.blur === "function") {
    document.activeElement.blur();
  }
  if (modal._modalTransitionTimer) {
    window.clearTimeout(modal._modalTransitionTimer);
    modal._modalTransitionTimer = 0;
  }
  modal.classList.remove("is-opening");
  modal.classList.remove("active");
  modal.classList.add("is-closing");
  refreshActiveModalState();
  modal._modalTransitionTimer = window.setTimeout(() => {
    if (!modal.isConnected) return;
    modal.classList.remove("is-closing");
    modal.style.display = "none";
    modal.setAttribute("aria-hidden", "true");
    refreshActiveModalState();
  }, 340);
}

function dismissLensModal(modal) {
  if (!(modal instanceof HTMLElement)) return;
  switch (modal.id) {
    case "dailyWarmupModal":
      closeDailyTrainingMenu();
      break;
    case "authModal":
      closeAuthModal();
      break;
    case "riotModal":
      closeRiotModal();
      break;
    case "riotProfileConfirmModal":
      closeRiotProfileConfirmModal();
      break;
    case "accountSupportModal":
      closeAccountSupportModal();
      break;
    case "securitySettingsModal":
      closeSecuritySettingsModal();
      break;
    case "timelineStatsModal":
      setTimelinePulloutOpen(false);
      hideModalById(modal.id);
      break;
    case "guestTutorialChoiceModal":
      closeGuestTutorialChoice();
      break;
    case "guestTutorialCompleteModal":
      closeGuestTutorialComplete();
      break;
    default:
      hideModalById(modal.id);
  }
}

document.addEventListener("click", event => {
  const modal = event.target;
  if (!(modal instanceof HTMLElement) || !modal.matches(".lens-modal-overlay")) return;
  if (!modal.classList.contains("active") && !modal.classList.contains("is-opening")) return;
  dismissLensModal(modal);
});

document.addEventListener("keydown", event => {
  if (event.key !== "Escape") return;
  const activeModals = [...document.querySelectorAll(".lens-modal-overlay.active, .lens-modal-overlay.is-opening")];
  const modal = activeModals[activeModals.length - 1];
  if (modal) dismissLensModal(modal);
});

function openAuthModal() {
  const closeBtn = document.getElementById("authModalClose");
  if (closeBtn) closeBtn.style.display = "";
  setAuthPanel?.("login");
  showModalById("authModal");
}

function openAuthModalForSecurityReview() {
  openAuthModal();
  setAuthPanel?.("signup");
}

function closeAuthModal(force = false) {
  if (!force && !currentAuthUser && !hasCompletedAppEntryChoice()) return;
  hideModalById("authModal");
}

function openRiotModal() {
  showModalById("riotModal");
}

function closeRiotModal() {
  hideModalById("riotModal");
}

function openImpactModal() {
  const modal = document.getElementById("lensModalOverlay");
  const list = document.getElementById("lensStatsList");
  const title = document.getElementById("lensModalTitle");
  const weightingBlock = document.getElementById("lensWeightingBlock");
  const weightingTitle = document.getElementById("lensModalWeightingTitle");
  const statsTitle = document.getElementById("lensModalStatsTitle");

  if (!modal || !list) return;

  const model = getPlayerModel();
  const impactSnapshots = model?.scoring?.impactSnapshots || [];
  const selectedMatchIndex = Number(impactRolePill?.dataset?.matchIndex);
  const selectedDisplayIndex = Number(impactRolePill?.dataset?.displayIndex);
  const fallbackIndex = matches.length - 1;
  const matchIndex = Number.isInteger(selectedMatchIndex) && selectedMatchIndex >= 0
    ? selectedMatchIndex
    : fallbackIndex;
  const match = matches[matchIndex] || matches[fallbackIndex] || null;
  const snapshot = findImpactSnapshotForMatch(match, matchIndex, impactSnapshots) || impactSnapshots[impactSnapshots.length - 1] || null;
  const core = getMatchCore(match || {});
  const resultLabel = String(core?.result || snapshot?.result || "draw").toLowerCase();
  const impactScore = Math.round(safeNumber(snapshot?.impactScore));
  const impactTier = snapshot?.impactTier || getImpactTierMeta(impactScore).tier;
  const roleLabel = getImpactRoleLabel(match, matchIndex, Number.isInteger(selectedDisplayIndex) ? selectedDisplayIndex : null);
  const roleKey = snapshot?.impactRoleKey || getCompassRoleKey(core?.role || snapshot?.role);
  const roleWeightEntries = Array.isArray(snapshot?.impactWeights) && snapshot.impactWeights.length
    ? snapshot.impactWeights
    : getRoleImpactWeightEntries(roleKey);
  const componentMap = snapshot?.impactComponents || {};
  const openingComponent = componentMap?.opening || null;
  const openingRawValue = openingComponent?.rawValue || null;
  const impactWeights = roleWeightEntries.map(entry => [
    entry.label,
    `${Math.round(safeNumber(entry.weight) * 100)}%`,
    componentMap?.[entry.key]?.formula || `${entry.label} is part of the selected match role-impact formula.`
  ]);
  const componentStats = roleWeightEntries
    .map(entry => componentMap?.[entry.key])
    .filter(Boolean)
    .map(component => ({
      label: component.label,
      value: `${Math.round(safeNumber(component.score))}/100`,
      formula: component.formula
    }));
  const impactStats = [
    { label: "Role Impact", value: `${impactScore}%`, formula: snapshot?.impactFormula || "Final weighted role-impact score after the selected role components are combined." },
    { label: "How It Looked", value: impactTier, formula: "Carry starts at 85+. Solid starts at 60+. Result matters, but a strong loss can still rate well." },
    { label: "Role Context", value: roleLabel || "Current role", formula: "Role label inferred from the selected match agent and current role mapping." },
    { label: "Map", value: snapshot?.map || core.map || "--", formula: "Direct map label from the selected match snapshot." },
    { label: "Agent", value: snapshot?.agent || core.agent || "--", formula: "Direct agent label from the selected match snapshot." },
    { label: "Match Result", value: resultLabel.replace(/^./, (char) => char.toUpperCase()), formula: "Direct result label from the selected match." }
  ].concat(componentStats);

  if (openingRawValue) {
    impactStats.push(
      {
        label: "First Bloods",
        value: `${Math.round(safeNumber(openingRawValue.firstBloods))}`,
        formula: "Direct first-blood count from the selected match."
      },
      {
        label: "First Deaths",
        value: `${Math.round(safeNumber(openingRawValue.firstDeaths))}`,
        formula: "Direct first-death count from the selected match."
      },
      {
        label: "First Contact Ratio",
        value: formatFirstContactRatioDisplay(openingRawValue),
        formula: "First bloods divided by first deaths, with the raw first-blood to first-death count shown in parentheses."
      }
    );
  }

  if (title) title.textContent = "Selected Match Impact";
  if (weightingTitle) weightingTitle.textContent = "What Moved This Score";
  if (statsTitle) statsTitle.textContent = "Why This Score Changed";

  list.innerHTML = "";
  if (weightingBlock) weightingBlock.innerHTML = "";

  impactWeights.forEach(([label, value, formula]) => {
    if (!weightingBlock) return;
    weightingBlock.appendChild(createLensWeightPill({
      label,
      value,
      formula,
      prefixWeighted: true
    }));
  });
  wireLensWeightPills(weightingBlock);

  impactStats.forEach((item) => {
    const row = document.createElement("li");
    row.className = `lens-stat${item.formula ? " lens-stat-has-formula" : ""}`;
    if (item.formula) {
      row.dataset.formula = item.formula;
    }
    row.innerHTML = `
      <span>${escapeHtml(item.label)}</span>
      <strong>${escapeHtml(item.value)}</strong>
    `;
    list.appendChild(row);
  });

  showModalById("lensModalOverlay");

}

// ========================
// AGENT MODAL RENDER
// ========================

function renderAgentModal(){
  if(!agentGrid){
    agentGrid = document.getElementById("agentModalGrid");
  }

  if(!agentGrid) return;
  agentGrid.style.pointerEvents = "auto";

  agentGrid.innerHTML = "";

  allAgents.forEach(agent => {

    if(agentRoles[agent] !== activeRole) return;

    const card = document.createElement("div");
    card.className = "agent-card";

    const key = agent.toLowerCase();

    card.innerHTML = `
      <img src="${getAgentIconUrl(key)}" />
      <span>${agent}</span>
    `;

card.style.cursor = "pointer";
card.style.pointerEvents = "auto";

const img = card.querySelector("img");
if (img) {
  img.style.pointerEvents = "none";
}

    card.setAttribute("data-agent", agent);

    card.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();

      const isLogging = getActivePageElement()?.id === "page-logging";

      if(isLogging){
        selectAgentInstant(agent);
      } else {
        selectAgentFromModal(agent);
      }
    });

    agentGrid.appendChild(card);

  });

}

// ========================
// ROLE SELECTOR
// ========================

function renderRoleSelector(){

  const container = document.getElementById("agentRoleSelect");
  if(!container) return;

  container.innerHTML = "";

  const roles = ["duelist","initiator","controller","sentinel"];

  roles.forEach(role => {

    const btn = document.createElement("div");
    btn.className = "agent-role-btn";

    if(role === activeRole){
      btn.classList.add("active");
    }

    const icon = ROLE_ICON_MAP[role];

    btn.innerHTML = icon
      ? `<img src="${icon}" />`
      : `<span>${role}</span>`;

    btn.onclick = () => {

      activeRole = role;
      activeRoleFilter = role;

      renderRoleSelector();
      setTimeout(()=>{ renderRoleSelector(); },0);

      renderAgentModal();

      const agentRoleDropdown = document.getElementById("agentRoleDropdown");
      if(agentRoleDropdown){
        agentRoleDropdown.value = role;
      }

      document.querySelectorAll(".role-filter-btn").forEach(btn => {
        btn.classList.toggle(
          "active",
          btn.dataset.role?.toLowerCase() === role
        );
      });
    };

    container.appendChild(btn);

  });

}

