      const elementStates = themeState?.elements || {};
      const wideAsset = normalizeThemeBuilderAssetValue(overlayAssets.wide || "");
      const squareAsset = normalizeThemeBuilderAssetValue(overlayAssets.square || "");
      const hasParentOverrides = Object.values(parentStates).some(parentState => parentState && Object.keys(parentState).length);
      const hasGroupOverrides = Object.values(groupStates).some(parentMap => parentMap && Object.keys(parentMap).length);
      const hasElementOverrides = enableAdvancedElements && Object.values(elementStates).some(parentMap =>
        parentMap && Object.values(parentMap).some(elementState => elementState && Object.keys(elementState).length)
      );
      const hasHoverFx = Object.values(parentStates).some(parentState => parentState?.hoverFxEnabled);
      const forceOverlays = Boolean(globals.forceOverlays);
      const hideOverlays = Boolean(globals.hideOverlays);
      if (!wideAsset && !squareAsset && !hasParentOverrides && !hasGroupOverrides && !hasElementOverrides && !forceOverlays && !hideOverlays) return "";

      const hasStateForConfig = (config) => {
        const parentState = parentStates?.[config.id] || {};
        const groupState = groupStates?.[config.id] || {};
        const elementState = elementStates?.[config.id] || {};
        const hasElementState = Object.values(elementState).some(entry => entry && Object.keys(entry).length);
        return Boolean(Object.keys(parentState).length || Object.keys(groupState).length || hasElementState);
      };
