// ========================
// TIMELINE RENDER
// ========================

function renderTimeline(){

  const wrap = document.getElementById("timelineEvents");
  if(!wrap) return;

  const scope = getTimelineContext();
  syncImprovementCardSub(scope);
  wrap.innerHTML = "";

  buildTimelineEventsFromModel(scope.model)
    .slice()
    .reverse()
    .forEach((e, index)=>{

      const el = document.createElement("div");
      el.className = `timeline-event event-rank-${Math.min(index, 3)}`;

      el.innerHTML = `
        <div class="timeline-dot"></div>
        <div class="timeline-title">${e.title}</div>
        <div class="timeline-date">${e.date}</div>
      `;

      wrap.appendChild(el);

    });

}

function setTimelinePulloutOpen(isOpen = false) {
  const pullout = document.getElementById("timelinePullout");
  const tab = document.getElementById("timelinePulloutTab");
  if (!pullout || !tab) return;
  pullout.classList.toggle("is-open", !!isOpen);
  tab.setAttribute("aria-expanded", isOpen ? "true" : "false");
}

function refreshImprovementTimeline({ animate = true } = {}) {
  improvementTimelineAnimationVersion += 1;
  renderTimeline();
  if (shouldAnimateImprovementTimeline(animate)) {
    runImprovementTimelineAnimation();
    return;
  }

  const scope = getTimelineContext();
  const items = buildTimelineItemsFromModel(scope.model);
  const pills = [
    document.getElementById("timelinePill0"),
    document.getElementById("timelinePill1"),
    document.getElementById("timelinePill2"),
    document.getElementById("timelinePill3")
  ].filter(Boolean);

  pills.forEach((pill, index) => {
    const item = items[index] || items[0] || null;
    if (!item) return;
    pill.dataset.timelineKey = item.key || "";
    pill.classList.remove("is-loading", "is-spinning", "is-settled");
    setTimelinePillVisual(pill, item);
  });
}

function openTimelineStatsModal(itemKey = "") {
  const modal = document.getElementById("timelineStatsModal");
  const list = document.getElementById("timelineStatsList");
  if (!modal || !list) return;

  const scope = getTimelineContext();
  const items = buildTimelineItemsFromModel(scope.model);
  const target = items.find(item => item.key === itemKey) || items[0] || null;
  if (!target || target.disabled) return;
  const currentValue = escapeHtml(target.format(target.value));
  const changeValue = escapeHtml(formatTimelineDelta(target));
  const trendTone = getTimelineToneFromDelta(target.delta);
  const trendValue = escapeHtml(trendTone.replace(/^./, char => char.toUpperCase()));
  const scopeValue = escapeHtml(scope.scopeDetail);
  const comparisonValue = escapeHtml(target.comparisonLabel || "Recent role window compared against the earlier role baseline.");
  const sourceValue = escapeHtml(target.sourceLabel || "Derived from Riot match history and/or Logging inside the selected scope.");
  const formulaValue = escapeHtml(target.formula || "Recent role window minus earlier baseline.");
  const implicationValue = escapeHtml(target.detail || "This is the current coaching read for the selected improvement signal.");

  list.innerHTML = `
    <section class="timeline-insight-hero">
      <span class="timeline-insight-kicker">Session Improvement</span>
      <h3 class="timeline-insight-signal">${escapeHtml(target.label)}</h3>
      <div class="timeline-insight-meta">
        <span class="timeline-insight-chip">Current ${currentValue}</span>
        <span class="timeline-insight-chip is-${trendTone}">${changeValue}</span>
        <span class="timeline-insight-chip is-${trendTone}">${trendValue}</span>
      </div>
    </section>
    <section class="timeline-insight-grid">
      <article class="timeline-insight-card">
        <h4 class="timeline-insight-card-title">Games Compared</h4>
        <p class="timeline-insight-card-body">${comparisonValue}</p>
      </article>
      <article class="timeline-insight-card">
        <h4 class="timeline-insight-card-title">Games Used</h4>
        <p class="timeline-insight-card-body">This read only uses <strong>${scopeValue}</strong>.</p>
      </article>
      <article class="timeline-insight-card">
        <h4 class="timeline-insight-card-title">How This Was Figured Out</h4>
        <p class="timeline-insight-card-body">${formulaValue}</p>
        <p class="timeline-insight-card-body">${sourceValue}</p>
      </article>
      <article class="timeline-insight-card">
        <h4 class="timeline-insight-card-title">Current Read</h4>
        <p class="timeline-insight-card-body">${implicationValue}</p>
      </article>
    </section>
  `;

  setTimelinePulloutOpen(false);
  showModalById("timelineStatsModal");
}

