function scrollLoggingFormToTopAfterSave() {
  const page = document.getElementById("page-logging");
  if (page?.dataset) page.dataset.mobileLoggingView = "form";
  ensureMobileLoggingTabs();

  window.requestAnimationFrame(() => {
    const target =
      document.getElementById("mobileLoggingTabs")
      || page?.querySelector(".logging-card")
      || page;
    if (!target) return;
    target.scrollIntoView({ behavior: "smooth", block: "start" });
  });
}

function ensureLogFormWarning() {
  const actions = document.querySelector("#page-logging .logging-actions");
  if (!actions) return null;
  let warning = document.getElementById("logFormWarning");
  if (!warning) {
    warning = document.createElement("div");
    warning.id = "logFormWarning";
    warning.className = "logging-form-warning";
    warning.setAttribute("role", "alert");
    warning.hidden = true;
    actions.insertAdjacentElement("beforebegin", warning);
  }
  return warning;
}

function setLogFormWarning(message = "") {
  const warning = ensureLogFormWarning();
  if (!warning) return;
  warning.textContent = message;
  warning.hidden = !message;
}

function isFiniteLogNumber(value) {
  return Number.isFinite(Number(value));
}

function isManualInputFilled(id) {
  return String(document.getElementById(id)?.value ?? "").trim() !== "";
}

function snapLoggingFormToTarget(target = null) {
  const page = document.getElementById("page-logging");
  if (page?.dataset) page.dataset.mobileLoggingView = "form";
  ensureMobileLoggingTabs();

  window.requestAnimationFrame(() => {
    const fallback =
      document.getElementById("mobileLoggingTabs")
      || page?.querySelector(".logging-card")
      || page;
    const scrollTarget = target || fallback;
    scrollTarget?.scrollIntoView?.({ behavior: "smooth", block: "center" });
    scrollTarget?.focus?.({ preventScroll: true });
  });
}

function getLogFormMissingFields(entry = {}) {
  const missing = [];
  if (!String(entry.agent || "").trim()) missing.push("agent");
  if (!String(entry.focus || "").trim() || entry.focus === "Other" || entry.focus === "Select Focus") missing.push("focus category");
  if (!String(entry.map || "").trim()) missing.push("map");
  if (!isFiniteLogNumber(entry.rating)) missing.push("performance");
  if (!String(entry.mood || "").trim()) missing.push("mood");
  if (!isFiniteLogNumber(entry.teamComms)) missing.push("team comms");
  if (!isFiniteLogNumber(entry.selfComms)) missing.push("self comms");
  if (!String(entry.notes || "").trim()) missing.push("notes");

  if (isManualEntryModeEnabled()) {
    [
      ["manualRR", "RR"],
      ["manualRoundsWon", "rounds won"],
      ["manualRoundsLost", "rounds lost"],
      ["manualKills", "kills"],
      ["manualDeaths", "deaths"],
      ["manualAssists", "assists"],
      ["manualACS", "ACS"],
      ["manualADR", "ADR"],
      ["manualHS", "HS %"]
    ].forEach(([id, label]) => {
      if (!isManualInputFilled(id)) missing.push(label);
    });
  }

  return missing;
}

function focusFirstMissingLogField(missing = []) {
  const first = missing[0] || "";
  const target =
    first === "agent" ? document.getElementById("logAgentDisplay") :
    first === "focus category" ? document.getElementById("logFocusSelect") :
    first === "map" ? document.getElementById("logMap") :
    first === "performance" ? document.querySelector("#logRatingRow [data-rating], [data-rating]") :
    first === "mood" ? document.querySelector("#logMoodRow [data-mood], [data-mood]") :
    first === "team comms" ? document.querySelector("#logTeamCommsRow [data-team-comms], [data-team-comms]") :
    first === "self comms" ? document.querySelector("#logSelfCommsRow [data-self-comms], [data-self-comms]") :
    first === "notes" ? document.getElementById("logNotes") :
    first === "RR" ? document.getElementById("manualRR") :
    first === "rounds won" ? document.getElementById("manualRoundsWon") :
    first === "rounds lost" ? document.getElementById("manualRoundsLost") :
    first === "kills" ? document.getElementById("manualKills") :
    first === "deaths" ? document.getElementById("manualDeaths") :
    first === "assists" ? document.getElementById("manualAssists") :
    first === "ACS" ? document.getElementById("manualACS") :
    first === "ADR" ? document.getElementById("manualADR") :
    first === "HS %" ? document.getElementById("manualHS") :
    document.getElementById("logSaveBtn");
  snapLoggingFormToTarget(target);
}

function validateLogFormBeforeSave(entry = {}) {
  const missing = getLogFormMissingFields(entry);
  if (!missing.length) {
    setLogFormWarning("");
    return true;
  }
  setLogFormWarning("Not all fields are filled in the form.");
  focusFirstMissingLogField(missing);
  return false;
}

function addLogEntry(){

  const entry = getLogFormValues();
  if (!validateLogFormBeforeSave(entry)) return;
  const editingId = editingLogEntryId;
  const isEditing = Boolean(editingId);
  const previousEntry = isEditing
    ? (logEntries.find(existing => existing.id === editingId) || editingLogEntrySnapshot)
    : null;
  const completesPlaceholder = isMatchPlaceholderLogEntry(previousEntry || {});

  entry.profileId = activeProfileId || entry.profileId || "";
  entry.isPlayerAuthored = true;
  entry.isMatchPlaceholder = false;
  entry.source = completesPlaceholder ? "player-reflection" : (entry.source || "player-reflection");
  entry.authoredAt = entry.authoredAt || nowISO();

if(!entry.focus || entry.focus === "Select Focus"){
  entry.focus = "general";
}

  if (isEditing) {
    let replaced = false;
    logEntries = logEntries.map(existing => {
      if (existing.id !== editingId) return existing;
      replaced = true;
      return {
        ...existing,
        ...entry,
        id: existing.id,
        createdAt: existing.createdAt || entry.createdAt
      };
    });

    if (!replaced) {
      logEntries.unshift(entry);
    }
  } else {
    logEntries.unshift(entry);
  }

  const manualMatchId = upsertManualMatchForLogEntry(entry);
  if (manualMatchId) {
    logEntries = logEntries.map(existing => (
      existing.id === entry.id
        ? { ...existing, matchId: manualMatchId, manualMatchId }
        : existing
    ));
  }

  if (!isEditing) {
    persistWarmupTrainingEntry(getActiveProfile(), getTrainingEntryDate(entry));
  }

  editingLogEntryId = null;
  editingLogEntrySnapshot = null;

  pendingFocusFromLog = entry.focus;
  pendingAgentFromLog = entry.agent;

  // SYNC HOME FOCUS + AGENT
if(entry.agent){
  applyAgentToHome(entry.agent);
}

if(entry.focus){
  focusDisplay.textContent = entry.focus;
}

  renderLogFeed();
  renderInsights();
  calculateFocusProgress();
  updateFocusProgressUI();
  updateInsightFocusUI();
  syncWeeklyFocus();
  if (manualMatchId) {
    const savedRecord = matches.find(match => String(match?.matchId || match?.id || "") === String(manualMatchId)) || null;
    onMatchSaved(savedRecord, {
      profile: getActiveProfile(),
      source: "manual"
    });
  }

  // reset form
  const logMap = document.getElementById("logMap");
  const logNotes = document.getElementById("logNotes");
  const logFocusSelect = document.getElementById("logFocusSelect");
  const logFocusOther = document.getElementById("logFocusOther");
  const focusOtherWrap = document.getElementById("focusOtherWrap");
  const preview = document.getElementById("focusPreviewText");
  const logAgentImg = document.getElementById("logAgentImg");

  if(logMap) logMap.value = "";
  if(logNotes) logNotes.value = "";
  if(logFocusSelect) logFocusSelect.value = "";
  if(logFocusOther) logFocusOther.value = "";
  if(focusOtherWrap){
    focusOtherWrap.style.display = "none";
    focusOtherWrap.hidden = true;
    focusOtherWrap.setAttribute("aria-hidden", "true");
  }
  if(preview) preview.textContent = "Focus Category";
  preview?.classList?.add("is-placeholder");
  setCustomFocusCommitted("");
  if(logFocusOther) logFocusOther.disabled = true;
  updateLogAgentDisplay("");
  resetManualReportForm();

  selectedLogRating = null;
  selectedLogMood = null;
  selectedLogTeamComms = null;
  selectedLogSelfComms = null;

  setExclusiveChipSelection("[data-rating]", null, "rating");
  setExclusiveChipSelection("[data-mood]", null, "mood");
  setExclusiveChipSelection("[data-team-comms]", null, "teamComms");
  setExclusiveChipSelection("[data-self-comms]", null, "selfComms");
  setLoggingQuickMenuOpen(false);
  syncLoggingQuickChipStates();
  updateLoggingDebriefPreview();
  saveLogEntries();
  scrollLoggingFormToTopAfterSave();
}
