function syncLogInputs(){

  const focusSelect = document.getElementById("logFocusSelect");
  const focusOther = document.getElementById("logFocusOther");
  const focusOtherWrap = document.getElementById("focusOtherWrap");

  if(!focusSelect || !focusOther) return;

  if(pendingFocusFromLog){

    const exists = [...focusSelect.options]
      .some(opt => opt.value === pendingFocusFromLog);

    if(exists){
      focusSelect.value = pendingFocusFromLog;
      setFocusOtherVisibility(false);
      setCustomFocusCommitted("");
    } else {
      focusSelect.value = "Other";
      focusOther.value = pendingFocusFromLog;
      setFocusOtherVisibility(true, pendingFocusFromLog);
      setCustomFocusCommitted(pendingFocusFromLog);
    }

    pendingFocusFromLog = null;
  }

  if(pendingAgentFromLog){
    applyAgentToHome(pendingAgentFromLog);
    pendingAgentFromLog = null;
  }

}

function getLogRatingBadge(rating){
  const score = Number(rating || 0);

  if(score >= 5){
    return { icon: "â­", label: String(score || 5), tone: "good" };
  }

  if(score >= 3){
    return { icon: "â—", label: String(score), tone: "okay" };
  }

  return { icon: "âœ•", label: String(score || "-"), tone: "bad" };
}

function getMoodTone(mood){
  const key = String(mood || "").toLowerCase();

  if(key === "tilted") return "bad";
  if(key === "focused") return "good";
  if(key === "calm") return "calm";
  return "neutral";
}

function getLogSessions() {
  const grouped = new Map();

  getProfileLogEntries().forEach(entry => {
    const key = getTrainingEntryDate(entry) || formatLocalDateKey(new Date());
    if (!grouped.has(key)) {
      grouped.set(key, []);
    }
    grouped.get(key).push(entry);
  });

  return [...grouped.entries()]
    .map(([key, entries]) => ({ key, entries }))
    .sort((a, b) => new Date(b.key) - new Date(a.key));
}

function getLogAverageSummary() {
  const entries = getProfileLogEntries(activeProfileId, { authoredOnly: true });
  const now = new Date();
  const weekStart = getWeekStart(now);
  const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
  monthStart.setHours(0, 0, 0, 0);

  const weeklyCount = entries.filter(entry => new Date(entry.createdAt || 0) >= weekStart).length;
  const monthlyCount = entries.filter(entry => new Date(entry.createdAt || 0) >= monthStart).length;
  const weekDaysElapsed = Math.max(1, Math.min(7, Math.floor((now - weekStart) / 86400000) + 1));
  const monthDaysElapsed = Math.max(1, now.getDate());

  return {
    weeklyCount,
    monthlyCount,
    weeklyAverage: weeklyCount / weekDaysElapsed,
    monthlyAverage: monthlyCount / monthDaysElapsed
  };
}

function renderLogFeedFootnote() {
  const summary = getLogAverageSummary();
  return `
    <div class="log-feed-footnote">
      Weekly average: ${summary.weeklyAverage.toFixed(1)} game logs/day from ${summary.weeklyCount} log${summary.weeklyCount === 1 ? "" : "s"} this week.
      Monthly average: ${summary.monthlyAverage.toFixed(1)} game logs/day from ${summary.monthlyCount} log${summary.monthlyCount === 1 ? "" : "s"} this month.
    </div>
  `;
}

function getLogEntryMatchContext(entry = {}) {
  const entryMatchId = String(entry.matchId || entry.riotMatchId || "").trim();
  const entryCreatedAt = new Date(entry.createdAt || 0).getTime();
  const entryAgent = String(entry.agent || "").toLowerCase();
  const entryMap = String(entry.map || "").toLowerCase();

  const linkedMatch = (matches || []).find((match) => {
    const ids = [
      match?.id,
      match?.matchId,
      match?.metadata?.matchId
    ].map(value => String(value || "").trim()).filter(Boolean);
    if (entryMatchId && ids.includes(entryMatchId)) return true;

    const core = getMatchCore(match);
    const matchCreatedAt = new Date(core.createdAt || match?.createdAt || match?.metadata?.playedAt || 0).getTime();
    const sameTime = entryCreatedAt && matchCreatedAt && Math.abs(entryCreatedAt - matchCreatedAt) < 60000;
    return sameTime
      && String(core.agent || "").toLowerCase() === entryAgent
      && String(core.map || "").toLowerCase() === entryMap;
  }) || null;

  const core = linkedMatch ? getMatchCore(linkedMatch) : {};
  const result = String(entry.result || core.result || "").toLowerCase();
  const rr = entry.rr !== null && entry.rr !== undefined && entry.rr !== "" && Number.isFinite(Number(entry.rr))
    ? Number(entry.rr)
    : linkedMatch?.rr !== null && linkedMatch?.rr !== undefined && linkedMatch?.rr !== "" && Number.isFinite(Number(linkedMatch?.rr))
      ? Number(linkedMatch.rr)
      : null;

  return { match: linkedMatch, result, rr };
}

function isPlacementRankedMatch(match = {}) {
  return match?.isPlacementMatch === true
    || match?.metadata?.isPlacementMatch === true
    || match?.matchRecord?.isPlacementMatch === true;
}

function getLogCountByDate() {
  const counts = new Map();
  getProfileLogEntries().forEach(entry => {
    const key = getTrainingEntryDate(entry) || formatLocalDateKey(new Date());
    counts.set(key, (counts.get(key) || 0) + 1);
  });
  return counts;
}

function setLogCountBadge(dateKey = activeLogSessionFilter, countMap = getLogCountByDate()) {
  const badge = document.getElementById("logSessionCountBadge");
  if (!badge) return;
  const count = countMap.get(dateKey) || 0;
  badge.hidden = false;
  badge.textContent = `${count} log${count === 1 ? "" : "s"}`;
  badge.classList.remove("is-rolling");
  void badge.offsetWidth;
  badge.classList.add("is-rolling");
}

function formatCurrentSessionLabel(dateKey = activeLogSessionFilter) {
  const todayKey = formatLocalDateKey(new Date());
  const label = formatDateLabel(dateKey);
  return dateKey === todayKey ? `Today / ${label}` : label;
}

function renderLogCalendarPopover(countMap = getLogCountByDate()) {
  const popover = document.getElementById("logCalendarPopover");
  if (!popover) return;

  const selectedKey = activeLogSessionFilter === "all"
    ? formatLocalDateKey(new Date())
    : activeLogSessionFilter;
  const todayKey = formatLocalDateKey(new Date());
  const monthStart = new Date(activeLogCalendarMonth.getFullYear(), activeLogCalendarMonth.getMonth(), 1);
  const gridStart = new Date(monthStart);
  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
  const monthLabel = monthStart.toLocaleDateString(undefined, { month: "long", year: "numeric" });
  const maxCount = Math.max(1, ...countMap.values());
  const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

  const days = [];
  for (let index = 0; index < 42; index += 1) {
    const date = new Date(gridStart);
    date.setDate(gridStart.getDate() + index);
    const key = formatLocalDateKey(date);
    const count = countMap.get(key) || 0;
    const heat = count ? Math.max(.18, Math.min(.92, count / maxCount)) : .04;
    days.push(`
      <button
        class="logging-calendar-day${date.getMonth() !== monthStart.getMonth() ? " is-muted" : ""}${key === todayKey ? " is-today" : ""}${key === selectedKey ? " is-selected" : ""}"
        type="button"
        data-log-date="${key}"
        data-log-count="${count}"
        style="--log-heat:${heat.toFixed(2)}"
        aria-label="${escapeHtml(formatDateLabel(key))}, ${count} log${count === 1 ? "" : "s"}"
      ><span>${date.getDate()}</span></button>
    `);
  }

  popover.innerHTML = `
    <div class="logging-calendar-head">
      <button class="logging-calendar-nav" type="button" data-calendar-nav="-1" aria-label="Previous month">â€¹</button>
      <div class="logging-calendar-title">${escapeHtml(monthLabel)}</div>
      <button class="logging-calendar-nav" type="button" data-calendar-nav="1" aria-label="Next month">â€º</button>
    </div>
    <div class="logging-calendar-grid">
      ${dayNames.map(day => `<div class="logging-calendar-dow">${day}</div>`).join("")}
      ${days.join("")}
    </div>
  `;

  const previousMonthButton = popover.querySelector('[data-calendar-nav="-1"]');
  const nextMonthButton = popover.querySelector('[data-calendar-nav="1"]');
  if (previousMonthButton) previousMonthButton.textContent = "<";
  if (nextMonthButton) nextMonthButton.textContent = ">";
}

function renderLogSessionSelector() {
  const select = document.getElementById("logSessionSelect");
  const trigger = document.getElementById("logCalendarTrigger");
  if (!trigger) return;

  const sessions = getLogSessions();
  const countMap = getLogCountByDate();
  const todayKey = formatLocalDateKey(new Date());
  if (activeLogSessionFilter === "all") {
    activeLogSessionFilter = todayKey;
  }

  if (select) {
    select.innerHTML = "";

    sessions.forEach((session) => {
      const option = document.createElement("option");
      option.value = session.key;
      option.dataset.count = String(session.entries.length);
      option.textContent = `${formatDateLabel(session.key)} (${session.entries.length})`;
      select.appendChild(option);
    });
  }

  if (!/^\d{4}-\d{2}-\d{2}$/.test(activeLogSessionFilter)) {
    activeLogSessionFilter = todayKey;
  }

  if (select) select.value = activeLogSessionFilter;
  trigger.textContent = formatCurrentSessionLabel(activeLogSessionFilter);
  trigger.setAttribute("aria-label", `Current session: ${formatCurrentSessionLabel(activeLogSessionFilter)}`);
  setLogCountBadge(activeLogSessionFilter, countMap);
  renderLogCalendarPopover(countMap);
}

function buildDemoLogEntriesFromMatches(matchList = []) {
  const fallbackFocusOptions = [
    "Trade Conversion",
    "Duel Discipline",
    "Positioning",
    "Eco Conversion",
    "Map Awareness",
    "Team Utility",
    "Round Survivability",
    "Utility Timing",
    "Retake Timing",
    "Comms Discipline",
    "Weapon Pattern",
    "Mental Reset"
  ];
  const lossNotes = [
    "The loss was not just aim. Early deaths gave away too much map control before the team had a trade setup.",
    "This was a player-bias check: the flashy round looked good, but the next two rounds were lost because the economy broke.",
    "The team kept calling the same rotate late. The app should connect that pattern to map awareness instead of one bad duel.",
    "The round fell apart after chasing a multikill instead of resetting into post-plant discipline.",
    "Shotgun value showed up in one lane, but it did not convert enough rounds to justify forcing the same look repeatedly.",
    "The match felt close individually, but deaths after first contact kept turning winnable rounds into saves."
  ];
  const winNotes = [
    "The win came from cleaner trade timing and fewer solo fights after first contact.",
    "The team converted low-buy pressure because spacing stayed tight enough for follow-up fights.",
    "This game is useful because the result was positive while still showing a clear focus category to practice.",
    "Good map control made the late round easier. This should show as a strength without hiding the next review area.",
    "The role plan was simple and repeatable: take space, pause, then use utility before the next fight.",
    "This was a good example of impact without needing every stat to be perfect."
  ];
  const neutralNotes = [
    "The match had mixed signals, so the app should avoid overreacting to one number.",
    "Several rounds were decided by economy swings rather than one clean mechanical issue."
  ];
  const moods = ["Focused", "Calm", "Confident", "Tired", "Annoyed", "Tilted", "Frustrated", "Composed"];

  return (matchList || []).map((match, index) => {
    const createdAt = match?.createdAt || match?.metadata?.playedAt || nowISO();
    const result = String(match?.result || match?.metadata?.result || "draw").toLowerCase();
    const demoRoundData = match?.advanced?.rounds || [];
    const role = agentRoles?.[match?.metadata?.agent] || activeRole || "";
    const roleBase = {
      duelist: { rolePlan: 74, utility: 69, entry: 76, spacing: 71 },
      initiator: { rolePlan: 77, utility: 81, entry: 70, spacing: 75 },
      controller: { rolePlan: 79, utility: 84, entry: 68, spacing: 78 },
      sentinel: { rolePlan: 81, utility: 79, entry: 66, spacing: 80 }
    }[String(role || "").toLowerCase()] || { rolePlan: 74, utility: 74, entry: 72, spacing: 72 };
    const resultBoost = result === "win" ? 8 : result === "loss" ? -6 : 2;
    const focus = match?.metadata?.demoFocus || fallbackFocusOptions[index % fallbackFocusOptions.length];
    const demoAct = match?.metadata?.demoAct || "";
    const mood = result === "win"
      ? moods[index % 4]
      : moods[4 + (index % 4)];
    const notePool = result === "win" ? winNotes : result === "loss" ? lossNotes : neutralNotes;
    const scenario = match?.metadata?.demoScenario || notePool[index % notePool.length];
    const weaponBias = match?.metadata?.demoWeapon
      ? ` Weapon tendency: ${match.metadata.demoWeapon}.`
      : "";
    const survivorBiasNote = index % 9 === 1
      ? " This is a survivor-bias example: one big play should not outweigh the full match result."
      : "";

    return {
      id: uuid(),
      matchId: String(match?.id || match?.matchId || match?.metadata?.matchId || ""),
      result,
      rr: Number.isFinite(Number(match?.rr)) ? Number(match.rr) : 0,
      lockedOutcome: true,
      source: match?.source || "demo-match",
      createdAt,
      demoAct,
      act: demoAct,
      agent: match?.metadata?.agent || "Jett",
      focus,
      map: match?.metadata?.mapName || "Unknown",
      rating: result === "win"
        ? (index % 5 === 0 ? 3 : 4 + (index % 2))
        : result === "loss"
          ? (index % 6 === 2 ? 4 : 2 + (index % 2))
          : 3,
      mood,
      tilt: mood,
      teamComms: result === "win" ? 3 + (index % 3) : Math.max(0, 1 + (index % 4)),
      selfComms: result === "win" ? 3 + (index % 2) : Math.max(0, 1 + ((index + 1) % 4)),
      warmup: index % 10 === 0,
      notes: `${scenario} ${notePool[index % notePool.length]}${weaponBias}${survivorBiasNote}`,
      role,
      musicOn: index % 3 === 0,
      commsDisabled: index % 4 === 0,
      duoQueued: index % 2 === 0,
      afkMention: index % 5 === 0,
      disconnectMention: index % 4 === 1,
      rolePlanScore: clampScore(roleBase.rolePlan + resultBoost + ((index % 3) - 1) * 2, 40, 100),
      utilityTimingScore: clampScore(roleBase.utility + resultBoost + ((index % 4) - 1.5) * 2, 40, 100),
      entryTimingScore: clampScore(roleBase.entry + resultBoost + ((index % 5) - 2) * 2, 40, 100),
      spacingScore: clampScore(roleBase.spacing + resultBoost + ((index % 4) - 1.5) * 2, 40, 100),
      roundExamples: demoRoundData
    };
  });
}

// ========================
// LOG FEED RENDER
// ========================

function renderLogFeed(options = {}){

  const container = document.getElementById("logFeed");
  if(!container) return;

  const force = options.force === true;
  if (!force && !isLoggingPageActive()) {
    markLoggingFeedDirty();
    return;
  }

  renderLogSessionSelector();
  renderLoggingTrainingMenuState();
  container.innerHTML = "";
  loggingFeedDirty = false;
  loggingFeedRendered = true;

  const profileEntries = getProfileLogEntries();
  const trainingMarkers = getDailyTrainingFeedMarkers(profileEntries, getActiveProfile());
  if(!profileEntries.length){
    container.innerHTML = `
      <div class="log-empty">
        No logs yet -- track your sessions to unlock insights
      </div>
    `;
    return;
  }

  const sessions = getLogSessions().filter(session =>
    activeLogSessionFilter === "all" || session.key === activeLogSessionFilter
  );

  if(!sessions.length){
    container.innerHTML = `
      <div class="log-empty">
        No logs for ${escapeHtml(formatCurrentSessionLabel(activeLogSessionFilter))}.
      </div>
      ${renderLogFeedFootnote()}
    `;
    return;
  }

  const fragment = document.createDocumentFragment();
  sessions.forEach(session => {
    const sessionWrap = document.createElement("div");
    sessionWrap.className = "log-session-group";
    sessionWrap.innerHTML = `
      <div class="log-session-heading">
        <span class="log-session-date">${formatDateLabel(session.key)}</span>
        <span class="log-session-count">${session.entries.length} game${session.entries.length === 1 ? "" : "s"}</span>
      </div>
    `;

    session.entries.forEach(entry => {

      const ratingBadge = getLogRatingBadge(entry.rating);
      const moodLabel = entry.mood || entry.tilt || "-";
      const moodTone = getMoodTone(moodLabel);
      const matchContext = getLogEntryMatchContext(entry);
      const resultTone = matchContext.result === "win"
        ? "win"
        : matchContext.result === "loss"
          ? "loss"
          : "";
      const hasVerifiedRr = Number.isFinite(matchContext.rr);
      const matchSource = String(
        matchContext.match?.source
        || matchContext.match?.metadata?.source
        || entry.source
        || ""
      ).toLowerCase();
      const isSyncedHenrikMatch = matchSource === "henrik_sync" || matchSource === "henrik-match-placeholder";
      const isPlacementMatch = isPlacementRankedMatch(matchContext.match) || entry.isPlacementMatch === true;
      const rrLabel = hasVerifiedRr
        ? `${matchContext.rr > 0 ? "+" : ""}${Math.round(matchContext.rr)} RR`
        : isPlacementMatch ? "Placements" : isSyncedHenrikMatch ? "RR unverified" : "";
      const rrClasses = hasVerifiedRr
        ? `log-result-rr-${resultTone || "neutral"}`
        : isPlacementMatch
          ? "log-result-rr-neutral log-result-rr-placement"
          : "log-result-rr-neutral log-result-rr-unverified";
      const isEditingEntry = entry.id === editingLogEntryId;
      const isPlaceholder = isMatchPlaceholderLogEntry(entry);
      const trainingMarker = trainingMarkers.get(entry.id) || null;
      const notesCopy = isPlaceholder
        ? "Add your reflection for this ranked match."
        : (entry.notes || "-");
      const el = document.createElement("div");
      el.className = `log-entry${resultTone ? ` log-entry-${resultTone}` : ""}${isEditingEntry ? " log-entry-editing" : ""}${isPlaceholder ? " log-entry-placeholder" : ""}`;
      el.dataset.logEntryId = String(entry.id || "");

      el.innerHTML = `
        <div class="log-header">
          <span class="log-meta-agent">${
            entry.agent
              ? `<img src="${getAgentIconUrl(entry.agent)}" alt="${entry.agent}">`
              : "?"
          }</span>
          ${rrLabel ? `<span class="log-result-rr ${rrClasses}">${escapeHtml(rrLabel)}</span>` : ""}
          ${trainingMarker?.warmup ? `<button class="log-training-icon log-training-fire" type="button" data-training-date="${escapeHtml(trainingMarker.date)}" data-tooltip="Edit" aria-label="Edit warm-up for this session" title="Edit"><span class="log-training-fire-glyph" aria-hidden="true">&#128293;</span></button>` : ""}
          ${trainingMarker?.postGame ? `<button class="log-training-icon log-training-crosshair" type="button" data-training-date="${escapeHtml(trainingMarker.date)}" data-tooltip="Edit" aria-label="Edit post-game aim training for this session" title="Edit">${getTrainingCrosshairMarkup()}</button>` : ""}
          <span class="log-rating">â­ ${escapeHtml(entry.rating ?? "-")}</span>
        </div>

        <div class="log-body">
          <div class="log-meta">
            <span class="log-meta-agent">${
              entry.agent
                ? `<img src="${getAgentIconUrl(entry.agent)}" alt="${entry.agent}">`
                : "?"
            }</span>
            <span>${escapeHtml(entry.role || "-")}</span>
            <span>Mood: ${escapeHtml(moodLabel)}</span>
          </div>

          <div class="log-notes">
            ${escapeHtml(notesCopy)}
          </div>
        </div>

        <div class="log-actions">
          <button class="log-edit-btn">${isEditingEntry ? "Editing" : isPlaceholder ? "Add Reflection" : "Edit"}</button>
        </div>
      `;

      const headerRating = el.querySelector(".log-header .log-rating");
      if(headerRating){
        headerRating.style.display = "none";
      }

      const meta = el.querySelector(".log-meta");
      if(meta){
        meta.innerHTML = `
          <div class="log-tier-row">
            <span class="log-tier-label">Focus Category</span>
            <span class="log-tier-value">${escapeHtml(entry.focus || "-")}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Map</span>
            <span class="log-tier-value">${escapeHtml(entry.map || "-")}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Self Rating</span>
            <span class="log-tier-value log-rating log-rating-${ratingBadge.tone}">${escapeHtml(entry.rating ?? "-")}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Mood</span>
            <span class="log-tier-value log-mood log-mood-${moodTone}">${escapeHtml(moodLabel)}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Team Comms</span>
            <span class="log-tier-value">${escapeHtml(entry.teamComms ?? "-")}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Self Comms</span>
            <span class="log-tier-value">${escapeHtml(entry.selfComms ?? "-")}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Warmup</span>
            <span class="log-tier-value">${trainingMarker?.warmup ? "Yes" : "No"}</span>
          </div>
          <div class="log-tier-row">
            <span class="log-tier-label">Post-game aim</span>
            <span class="log-tier-value">${trainingMarker?.postGame ? "Yes" : "No"}</span>
          </div>
        `;
      }

      const notes = el.querySelector(".log-notes");
      if(notes){
        notes.outerHTML = `
          <div class="log-tier-row log-tier-notes">
            <span class="log-tier-label">Notes</span>
            <div class="log-notes">${escapeHtml(notesCopy)}</div>
          </div>
        `;
      }

      const editBtn = el.querySelector(".log-edit-btn");
      const warmupBtn = el.querySelector(".log-training-fire");
      const postGameBtn = el.querySelector(".log-training-crosshair");

      editBtn?.addEventListener("click", () => editLogEntry(entry.id));
      warmupBtn?.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openDailyTrainingMenu({ mode: "warmup", date: warmupBtn.dataset.trainingDate, dismissBehavior: "close" });
      });
      postGameBtn?.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        openDailyTrainingMenu({ mode: "postgame", date: postGameBtn.dataset.trainingDate, dismissBehavior: "close" });
      });

      sessionWrap.appendChild(el);

    });

    fragment.appendChild(sessionWrap);
  });

  container.appendChild(fragment);
  container.insertAdjacentHTML("beforeend", renderLogFeedFootnote());

}

// ========================
// PROFILES SYSTEM
// ========================

// ========================
// LOAD / SAVE
// ========================

function persistProfilesToLocalCache() {
  const compactProfiles = globalThis.RankedCoachPersistencePolicy?.compactProfilesForLocalCache;
  const candidates = [
    profiles,
    compactProfiles?.(profiles, 1),
    compactProfiles?.(profiles, 2),
    compactProfiles?.(profiles, 3)
  ].filter(Boolean);
  let profilesSaved = false;

  for (const candidate of candidates) {
    try {
      localStorage.setItem(STORAGE_KEY_PROFILES, JSON.stringify(candidate));
      profilesSaved = true;
      break;
    } catch (_error) {
      // Continue toward the smallest local cache. The complete account state is
      // still retained in memory and saved to the signed-in cloud account.
    }
  }

  try {
    localStorage.setItem(STORAGE_KEY_ACTIVE_ID, activeProfileId || "");
  } catch (_error) {
    // A full origin must not interrupt profile changes or cloud persistence.
  }

  return profilesSaved;
}

function saveProfiles(){
  persistProfilesToLocalCache();
  queuePersistentAccountSave("profiles");
}

function createProfileTheme(value, label, mode, colors = {}) {
  const isLight = mode === "light";
  const text = isLight ? "#0f172a" : "#f8fafc";
  const muted = isLight ? "#334155" : "#a8b3c7";
  const base = colors.base || (isLight ? "#f8fafc" : "#071029");
  const base2 = colors.base2 || (isLight ? "#e2e8f0" : "#071b2b");
  const card = colors.card || (isLight ? "#ffffff" : "#0b1220");
  const card2 = colors.card2 || (isLight ? "#e7eef5" : "#0f172a");
  const accent = colors.accent || "#ff4655";
  const accent2 = colors.accent2 || "#f97316";
  return {
    value,
    label,
    mode,
    motion: colors.motion || "static",
    colors: {
      base,
      base2,
      nav: colors.nav || (isLight ? `color-mix(in srgb, ${base} 90%, transparent)` : "rgba(11,18,32,.86)"),
      card,
      card2,
      input: colors.input || (isLight ? card2 : "#111827"),
      modal: colors.modal || (isLight ? card : "#080d18"),
      overlay: colors.overlay || (isLight ? "rgba(15,23,42,.42)" : "rgba(3,7,18,.78)"),
      border: colors.border || (isLight ? "rgba(15,23,42,.16)" : "rgba(148,163,184,.16)"),
      borderStrong: colors.borderStrong || `${accent}66`,
      text: colors.text || text,
      muted: colors.muted || muted,
      accent,
      accent2,
      button: colors.button || (isLight ? card2 : "#1e293b"),
      buttonHover: colors.buttonHover || (isLight ? base2 : "#334155"),
      glow: colors.glow || `${accent}42`,
      pattern: colors.pattern || `radial-gradient(circle at 18% 14%, ${accent}24, transparent 28%), linear-gradient(135deg, transparent 0 48%, ${accent2}14 76%, transparent 100%)`,
      pattern2: colors.pattern2 || `radial-gradient(circle at 82% 18%, ${accent2}20, transparent 24%)`
    }
  };
}

function getHexColorLuminance(value) {
  const match = String(value || "").match(/#([0-9a-f]{3}|[0-9a-f]{6})\b/i);
  if (!match) return null;
  const hex = match[1].length === 3
    ? match[1].split("").map(char => char + char).join("")
    : match[1];
  const channels = [0, 2, 4].map(offset => {
    const raw = parseInt(hex.slice(offset, offset + 2), 16) / 255;
    return raw <= 0.03928 ? raw / 12.92 : Math.pow((raw + 0.055) / 1.055, 2.4);
  });
  return (channels[0] * 0.2126) + (channels[1] * 0.7152) + (channels[2] * 0.0722);
}

function getThemeVisualMode(theme = getThemePreset("default")) {
  const colors = theme?.colors || {};
  const luminanceValues = [colors.card, colors.card2, colors.base]
    .map(getHexColorLuminance)
    .filter(value => Number.isFinite(value));
  if (luminanceValues.length) {
    const averageLuminance = luminanceValues.reduce((sum, value) => sum + value, 0) / luminanceValues.length;
    return averageLuminance >= 0.52 ? "light" : "dark";
  }
  return theme?.mode || "dark";
}

