function getDefaultProfileAvatarAgent() {
  return "jett";
}

function getDefaultProfileAvatarUrl(agentName = getDefaultProfileAvatarAgent()) {
  return getAgentIconUrl(String(agentName || "jett").toLowerCase());
}

function normalizeAccessibilityLayoutMode(value) {
  return value === "mobile" ? "mobile" : "web";
}

function normalizeThemeAccentColor(value = "") {
  const trimmed = String(value || "").trim();
  const match = trimmed.match(/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!match) return "";
  const raw = match[1].toLowerCase();
  const expanded = raw.length === 3
    ? raw.split("").map(char => char + char).join("")
    : raw;
  return `#${expanded}`;
}

function hexToRgb(value = "") {
  const hex = normalizeThemeAccentColor(value).replace("#", "");
  if (!hex) return null;
  return {
    r: parseInt(hex.slice(0, 2), 16),
    g: parseInt(hex.slice(2, 4), 16),
    b: parseInt(hex.slice(4, 6), 16)
  };
}

function clampColorChannel(value = 0) {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function rgbToHex({ r = 0, g = 0, b = 0 } = {}) {
  return `#${[r, g, b].map(channel => clampColorChannel(channel).toString(16).padStart(2, "0")).join("")}`;
}

function blendHexColors(primary = "", secondary = "", ratio = 0.5) {
  const start = hexToRgb(primary);
  const end = hexToRgb(secondary);
  if (!start) return normalizeThemeAccentColor(secondary);
  if (!end) return normalizeThemeAccentColor(primary);
  const mix = Math.max(0, Math.min(1, Number.isFinite(Number(ratio)) ? Number(ratio) : 0.5));
  return rgbToHex({
    r: (start.r * (1 - mix)) + (end.r * mix),
    g: (start.g * (1 - mix)) + (end.g * mix),
    b: (start.b * (1 - mix)) + (end.b * mix)
  });
}

function normalizeFreeThemeMotionMode(value = "static") {
  return value === "ambient" ? "ambient" : "static";
}

function normalizeProfileRecord(profile = {}) {
  const avatarAgent = String(profile.avatarAgent || "").trim() || getDefaultProfileAvatarAgent();
  return {
    ...profile,
    name: profile.name || "Main",
    accountName: sanitizeAccountName(profile.accountName || profile.name || "Guest", "Guest"),
    riotId: profile.riotId || "",
    puuid: profile.puuid || "",
    region: profile.region || "NA",
    startingRR: safeNumber(profile.startingRR),
    startingRRDate: String(profile.startingRRDate || ""),
    startingRRSource: String(profile.startingRRSource || ""),
    henrikHistoryWindowSize: Math.max(0, safeNumber(profile.henrikHistoryWindowSize)),
    henrikHistoryCursor: Math.max(0, safeNumber(profile.henrikHistoryCursor)),
    henrikHistoryBackfillVersion: Math.max(0, safeNumber(profile.henrikHistoryBackfillVersion)),
    henrikHistoryBackfillTargetVersion: Math.max(0, safeNumber(profile.henrikHistoryBackfillTargetVersion)),
    henrikHistoryBackfillCompleteAt: String(profile.henrikHistoryBackfillCompleteAt || ""),
    henrikHistoryReachedLimit: profile.henrikHistoryReachedLimit === true,
    lastDailyProfileSyncDate: String(profile.lastDailyProfileSyncDate || ""),
    goalRank: profile.goalRank || null,
    goalRR: Number.isFinite(Number(profile.goalRR)) ? Number(profile.goalRR) : null,
    peakRR: safeNumber(profile.peakRR),
    matches: Array.isArray(profile.matches) ? profile.matches : [],
    lastWarmupPromptDate: String(profile.lastWarmupPromptDate || ""),
    warmupLog: normalizeWarmupLog(profile.warmupLog),
    themeKey: profile.themeKey || "default",
    frameTheme: profile.frameTheme || profile.themeKey || "default",
    customAccent: normalizeThemeAccentColor(profile.customAccent || ""),
    freeThemeMotion: normalizeFreeThemeMotionMode(profile.freeThemeMotion),
    avatarAgent,
    avatarUrl: profile.avatarUrl || getDefaultProfileAvatarUrl(avatarAgent),
    navBackgroundUrl: profile.navBackgroundUrl || "",
    manualEntryMode: !!profile.manualEntryMode,
    profileBorderColor: normalizeProfileBorderColor(profile.profileBorderColor || "theme"),
    profileBorder: normalizeProfileBorderStyle(profile.profileBorder || "standard"),
    profileBorderRotate: !!profile.profileBorderRotate,
    bannerStyle: normalizeProfileBannerStyle(profile.bannerStyle || "theme"),
    accessibility: {
      contrastMode: profile?.accessibility?.contrastMode || "standard",
      motionMode: profile?.accessibility?.motionMode || "standard",
      layoutMode: normalizeAccessibilityLayoutMode(profile?.accessibility?.layoutMode)
    }
  };
}

function loadProfiles(){

  try{
    const raw = localStorage.getItem(STORAGE_KEY_PROFILES);
    profiles = raw ? JSON.parse(raw) : [];
  }catch(e){
    profiles = [];
  }

  profiles = (profiles || []).map(normalizeProfileRecord);
  activeProfileId =
    localStorage.getItem(STORAGE_KEY_ACTIVE_ID);

  if (profiles.length && !profiles.some(profile => profile.id === activeProfileId)) {
    activeProfileId = profiles[0].id;
  }

  if(!profiles.length){

    const defaultProfile = {
      id: uuid(),
      name: "Main",
      accountName: "Guest",
      riotId: "",
      region: "NA",
      startingRR: 0,
      startingRRDate: "",
      startingRRSource: "",
      themeKey: "default",
      frameTheme: "default",
      customAccent: "",
      freeThemeMotion: "static",
      avatarAgent: getDefaultProfileAvatarAgent(),
      avatarUrl: getDefaultProfileAvatarUrl(),
      navBackgroundUrl: "",
      manualEntryMode: false,
      profileBorderColor: "theme",
      profileBorder: "standard",
      profileBorderRotate: false,
      bannerStyle: "theme",
      goalRank: null,
      goalRR: null,
      peakRR: 0,
      lastWarmupPromptDate: "",
      warmupLog: [],
      accessibility: {
        contrastMode: "standard",
        motionMode: "standard",
        layoutMode: "web"
      }
    };

    profiles.push(normalizeProfileRecord(defaultProfile));
    activeProfileId = defaultProfile.id;

    saveProfiles();
  }

  logEntries = readLocalLogEntries({ profileId: activeProfileId });

}

