function clearDeletedProfileLocalCache(deletedProfileId) {
  setProfileRatingDropdownOpen?.(false);
  closeProfileDropdown?.();
  profileSwitcher?.classList.remove("open");
  profileDropdown?.classList.remove("open");

  try {
    localStorage.removeItem(WEEKLY_FOCUS_KEY);
    localStorage.removeItem(WEEKLY_FOCUS_WEEK_KEY);
    localStorage.removeItem(ASK_COACH_CHAT_STORAGE_KEY);
    localStorage.removeItem(getRRTotalAnimationStorageKey());
    localStorage.removeItem(getRRTotalAnimationPayloadKey());
  } catch (error) {
    console.warn("Unable to clear profile view cache", error);
  }

  if (Array.isArray(logEntries) && deletedProfileId) {
    const nextLogEntries = logEntries.filter(entry => String(entry?.profileId || "") !== String(deletedProfileId));
    if (nextLogEntries.length !== logEntries.length) {
      logEntries = nextLogEntries;
      saveLogEntries?.({ skipBackend: true });
    }
  }

  const active = getActiveProfile();
  matches = active?.matches ? active.matches.slice() : [];
  recomputeFromMatches?.();
  renderProfilesUI?.();
  rebuildProfileListUI?.();
  updateProfileHeaderUI?.();
  updateDisplays?.();
  initStatsPage?.();
  renderStatsAgents?.();
  renderStatsMaps?.();
  renderStatsWeapons?.();
  renderInsights?.();
  renderLogFeed?.({ force: true });
  refreshImprovementTimeline?.({ animate: false });
  renderCoachReadinessUI?.();
  updateNavRRToRank?.();
  updateNavRRToGoalRank?.();
  renderChart?.(currentSize);
  syncManualEntryModeUI?.();
}

async function requestDeleteProfile(id) {
  const profile = profiles.find(p => p.id === id);
  if (!profile) return;

  const confirmed = await openProfileDeleteConfirmModal(profile);
  if (!confirmed) return;

  await runProfileCleanupTask(() => {
    deleteProfile(id, { cleanup: true });
  });
}

function deleteProfile(id, options = {}){

  const deletedProfileId = String(id || "");
  const activeBeforeDelete = activeProfileId === id;

  profiles = profiles.filter(p => p.id !== id);

  if(!profiles.length){
    profiles.push(createFallbackProfileAfterDelete());
  }

  if(activeBeforeDelete || !profiles.some(profile => profile.id === activeProfileId)){
    activeProfileId = profiles[0]?.id || null;
  }

  saveProfiles();

  if (options.cleanup) {
    clearDeletedProfileLocalCache(deletedProfileId);
  } else {
    renderProfilesUI();
  }

}

// ========================
// UPDATE PROFILE
// ========================

function updateProfile(id, data){

  const profile = profiles.find(p => p.id === id);
  if(!profile) return;

  const previousRiotId = String(profile.riotId || "").trim().toLowerCase();
  const nextRiotId = data.riotId != null
    ? String(data.riotId || "").trim().toLowerCase()
    : previousRiotId;
  const previousRegion = String(profile.region || "").trim().toUpperCase();
  const nextRegion = data.region != null
    ? String(data.region || "").trim().toUpperCase()
    : previousRegion;
  const previousPeakRR = safeNumber(profile.peakRR);
  const nextPeakRR = data.peakRR != null
    ? safeNumber(data.peakRR)
    : previousPeakRR;

  profile.name = data.name ?? profile.name;
  profile.accountName = data.accountName ?? profile.accountName;
  profile.riotId = data.riotId ?? profile.riotId;
  profile.region = data.region ?? profile.region;
  if (data.peakRR != null) {
    profile.peakRR = nextPeakRR;
  }
  if (data.lastWarmupPromptDate != null) {
    profile.lastWarmupPromptDate = String(data.lastWarmupPromptDate || "");
  }
  if (data.warmupLog != null) {
    profile.warmupLog = normalizeWarmupLog(data.warmupLog);
  }

  if (nextRiotId !== previousRiotId || nextRegion !== previousRegion) {
    profile.startingRRDate = "";
    profile.startingRRSource = "";
    profile.puuid = "";
    profile.henrikHistoryWindowSize = 0;
    profile.henrikHistoryCursor = 0;
    profile.henrikHistoryBackfillVersion = 0;
    profile.henrikHistoryBackfillTargetVersion = 0;
    profile.henrikHistoryBackfillCompleteAt = "";
  }

  if (data.themeKey != null || data.frameTheme != null) {
    const nextTheme = String(data.themeKey || data.frameTheme || "default");
    profile.themeKey = nextTheme;
    profile.frameTheme = nextTheme;
  }

  if (data.customAccent != null) {
    profile.customAccent = normalizeThemeAccentColor(data.customAccent || "");
  }

  if (data.freeThemeMotion != null) {
    profile.freeThemeMotion = normalizeFreeThemeMotionMode(data.freeThemeMotion);
  }

  if (data.avatarAgent != null) {
    profile.avatarAgent = String(data.avatarAgent || getDefaultProfileAvatarAgent()).toLowerCase();
    profile.avatarUrl = getDefaultProfileAvatarUrl(profile.avatarAgent);
  }

  if (data.navBackgroundUrl != null) {
    profile.navBackgroundUrl = String(data.navBackgroundUrl || "").trim();
  }

  if (data.manualEntryMode != null) {
    profile.manualEntryMode = !!data.manualEntryMode;
  }

  if (data.profileBorderColor != null) {
    profile.profileBorderColor = normalizeProfileBorderColor(data.profileBorderColor || "theme");
  }

  if (data.profileBorder != null) {
    profile.profileBorder = normalizeProfileBorderStyle(data.profileBorder || "standard");
  }

  if (data.profileBorderRotate != null) {
    profile.profileBorderRotate = !!data.profileBorderRotate;
  }

  if (data.bannerStyle != null) {
    profile.bannerStyle = normalizeProfileBannerStyle(data.bannerStyle || "theme");
  }

  if (data.accessibility != null) {
    profile.accessibility = {
      contrastMode: data?.accessibility?.contrastMode || profile?.accessibility?.contrastMode || "standard",
      motionMode: data?.accessibility?.motionMode || profile?.accessibility?.motionMode || "standard",
      layoutMode: normalizeAccessibilityLayoutMode(data?.accessibility?.layoutMode || profile?.accessibility?.layoutMode)
    };
  }

  saveProfiles();
  renderProfilesUI();
  updateProfileHeaderUI();
  initStatsPage();
  scheduleRiotAutoSync();

}

// ========================
// SET ACTIVE PROFILE
// ========================

function setActiveProfile(id){

  const current = getActiveProfile();

  // save current matches
  if(current){
    current.matches = matches.slice();
  }

  activeProfileId = id;
  activeStatsActLabel = "";

  const next = getActiveProfile();

  // restore matches
  matches = next?.matches ? next.matches.slice() : [];
  if (next?.lastSyncSource === "henrik" || next?.importSource === "henrik") {
    syncRankedMatchPlaceholderLogs(matches, next);
  }
  activeLogSessionFilter = "all";

  recomputeFromMatches();

  saveProfiles();

  renderProfilesUI();
  updateProfileHeaderUI();
  updateDisplays();

  renderChart(currentSize);
  renderInsights?.();
  renderLogFeed?.({ force: true });
  scheduleRiotAutoSync();
  scheduleDailyWarmupCheck(450);

}

// ========================
// PROFILE ACTIONS (MANUAL)
