// ========================
// AUTH FLOW HELPERS
// ========================

let authResetTimer = 0;
let authResetExpiresAt = 0;
let authVerifiedRecoveryEmail = "";
let authRecoveryInProgress = false;
let authRecoverySessionReady = false;
let authPasswordLoginInProgress = false;
let authMfaChallengeInProgress = false;
let authMfaPendingFactors = [];

function setAuthPanel(panelName = "login") {
  document.querySelectorAll("[data-auth-panel]").forEach(panel => {
    panel.hidden = panel.dataset.authPanel !== panelName;
  });
  const title = document.getElementById("authModalTitle");
  if (title) {
    title.textContent = panelName === "signup"
      ? "Create account"
      : panelName === "forgot"
        ? "Password recovery"
        : panelName === "mfa"
          ? "2-factor verification"
          : "Welcome back";
  }
}

function getMfaFactorId(factor = {}) {
  return factor.id || factor.factor_id || factor.factorId || "";
}

function getMfaFactorType(factor = {}) {
  return String(factor.factor_type || factor.factorType || factor.type || "totp").toLowerCase();
}

function getMfaFactorLabel(factor = {}, index = 0) {
  const type = getMfaFactorType(factor);
  const friendlyName = factor.friendly_name || factor.friendlyName || factor.name;
  if (friendlyName) return friendlyName;
  if (type === "phone") return `Phone verification ${index + 1}`;
  return `Authenticator app ${index + 1}`;
}

function getVerifiedMfaFactorsFromData(data = {}) {
  const buckets = [
    ...(Array.isArray(data?.totp) ? data.totp : []),
    ...(Array.isArray(data?.phone) ? data.phone : []),
    ...(Array.isArray(data?.all) ? data.all : [])
  ];
  const seen = new Set();
  return buckets.filter(factor => {
    const id = getMfaFactorId(factor);
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return String(factor.status || "verified").toLowerCase() === "verified";
  });
}

function renderMfaChallengePanel(factors = []) {
  const select = document.getElementById("authMfaFactorSelect");
  const field = document.getElementById("authMfaFactorField");
  const codeInput = document.getElementById("authMfaCode");
  if (select) {
    select.innerHTML = factors.map((factor, index) => {
      const id = getMfaFactorId(factor);
      const type = getMfaFactorType(factor);
      return `<option value="${escapeHtml(id)}">${escapeHtml(getMfaFactorLabel(factor, index))}${type === "phone" ? " (phone)" : ""}</option>`;
    }).join("");
  }
  if (field) field.hidden = factors.length <= 1;
  if (codeInput) {
    codeInput.value = "";
    window.setTimeout(() => codeInput.focus(), 80);
  }
  const hasPhoneOnly = factors.length > 0 && factors.every(factor => getMfaFactorType(factor) === "phone");
  setAuthStatus(
    "authMfaLoginStatus",
    hasPhoneOnly
      ? "Phone MFA needs the Supabase Phone provider or Send SMS Hook before codes can be delivered."
      : ""
  );
}

async function getVerifiedMfaFactors() {
  if (!supabaseClient?.auth?.mfa?.listFactors) return [];
  const { data, error } = await supabaseClient.auth.mfa.listFactors();
  if (error) throw error;
  return getVerifiedMfaFactorsFromData(data || {});
}

async function shouldRequireMfaChallenge() {
  if (!supabaseClient?.auth?.mfa?.getAuthenticatorAssuranceLevel) return false;
  const { data, error } = await supabaseClient.auth.mfa.getAuthenticatorAssuranceLevel();
  if (error) throw error;
  return data?.nextLevel === "aal2" && data?.currentLevel !== "aal2";
}

async function prepareMfaChallengeAfterLogin() {
  if (!(await shouldRequireMfaChallenge())) return false;
  const factors = await getVerifiedMfaFactors();
  if (!factors.length) return false;
  authMfaChallengeInProgress = true;
  authMfaPendingFactors = factors;
  currentAuthUser = await getSupabaseUser();
  renderMfaChallengePanel(factors);
  setAuthPanel("mfa");
  showModalById("authModal");
  return true;
}

async function verifyPendingMfaChallenge() {
  if (!supabaseClient?.auth?.mfa?.challengeAndVerify) {
    throw new Error("RankedCoach MFA is not connected yet.");
  }
  const factorId = document.getElementById("authMfaFactorSelect")?.value || getMfaFactorId(authMfaPendingFactors[0] || {});
  const code = String(document.getElementById("authMfaCode")?.value || "").trim();
  if (!factorId) throw new Error("No verified 2-factor method was found for this account.");
  if (!code) throw new Error("Enter your 2-factor code.");

  const { error } = await supabaseClient.auth.mfa.challengeAndVerify({
    factorId,
    code
  });
  if (error) throw error;

  const stillRequiresMfa = await shouldRequireMfaChallenge();
  if (stillRequiresMfa) {
    throw new Error("That code was not accepted. Try the newest code from your authenticator app.");
  }

  authMfaChallengeInProgress = false;
  authMfaPendingFactors = [];
  const user = await getSupabaseUser();
  currentAuthUser = user || currentAuthUser;
  setAppEntryChoice("auth");
  closeAuthModal();
  await initializeSignedInAccount(currentAuthUser, { reason: "mfa-login" });
}

async function cancelPendingMfaChallenge() {
  authMfaChallengeInProgress = false;
  authMfaPendingFactors = [];
  authPasswordLoginInProgress = false;
  await supabaseClient?.auth?.signOut?.();
  currentAuthUser = null;
  setAuthStatus("authMfaLoginStatus", "");
  setAuthPanel("login");
  showModalById("authModal");
}

function getPasswordHistoryKey(email = "") {
  return `rankedcoach_password_history_${String(email || "").trim().toLowerCase()}`;
}

function getStoredPasswordFingerprints(email = "") {
  try {
    const raw = localStorage.getItem(getPasswordHistoryKey(email));
    const parsed = JSON.parse(raw || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function getPasswordFingerprint(password = "") {
  try {
    return btoa(unescape(encodeURIComponent(String(password || "")))).slice(0, 120);
  } catch {
    return String(password || "").slice(0, 120);
  }
}

function rememberPasswordFingerprint(email = "", password = "") {
  if (!email || !password) return;
  const next = [
    getPasswordFingerprint(password),
    ...getStoredPasswordFingerprints(email).filter(value => value !== getPasswordFingerprint(password))
  ].slice(0, 5);
  localStorage.setItem(getPasswordHistoryKey(email), JSON.stringify(next));
}

function validateRankedCoachPassword(email = "", password = "", confirmPassword = "") {
  const normalizedEmail = String(email || "").trim().toLowerCase();
  const localPart = normalizedEmail.split("@")[0] || "";
  const passwordText = String(password || "");
  const lowerPassword = passwordText.toLowerCase();
  const repeatedPassword = getStoredPasswordFingerprints(normalizedEmail).includes(getPasswordFingerprint(passwordText));

  const rules = [
    { label: "At least 10 characters", pass: passwordText.length >= 10 },
    { label: "Includes one uppercase letter", pass: /[A-Z]/.test(passwordText) },
    { label: "Includes one number", pass: /\d/.test(passwordText) },
    { label: "Does not contain your email name", pass: !localPart || localPart.length < 3 || !lowerPassword.includes(localPart.toLowerCase()) },
    { label: "No 3-number sequences like 123 or 987", pass: !/(012|123|234|345|456|567|678|789|987|876|765|654|543|432|321|210)/.test(passwordText) },
    { label: "Matches the confirmation field", pass: !confirmPassword || passwordText === confirmPassword },
    { label: "Not one of the last 5 passwords on this device", pass: !repeatedPassword }
  ];

  return {
    rules,
    valid: rules.every(rule => rule.pass)
  };
}

function renderPasswordRules(targetId = "", email = "", password = "", confirmPassword = "") {
  const target = document.getElementById(targetId);
  if (!target) return false;
  const result = validateRankedCoachPassword(email, password, confirmPassword);
  const failedRules = result.rules.filter(rule => !rule.pass);
  target.innerHTML = failedRules.map(rule => `
    <div class="is-fail">Needs: ${escapeHtml(rule.label)}</div>
  `).join("");
  return result.valid;
}

function clearPasswordRules(targetId = "") {
  const target = document.getElementById(targetId);
  if (!target) return;
  target.innerHTML = "";
  target.dataset.show = "0";
}

function setAuthStatus(id = "", message = "") {
  const el = document.getElementById(id);
  if (el) el.textContent = message;
}

function resetPasswordRecoveryPanel() {
  authVerifiedRecoveryEmail = "";
  authRecoveryInProgress = false;
  authRecoverySessionReady = false;
  if (authResetTimer) {
    window.clearInterval(authResetTimer);
    authResetTimer = 0;
  }
  authResetExpiresAt = 0;
  setPasswordRecoveryStage("email");
  const codeStage = document.getElementById("authResetCodeStage");
  const newPasswordStage = document.getElementById("authNewPasswordStage");
  const codeInput = document.getElementById("authResetCode");
  const newPassword = document.getElementById("authNewPassword");
  const newPasswordConfirm = document.getElementById("authNewPasswordConfirm");
  const resendBtn = document.getElementById("authResendResetCodeBtn");
  if (codeStage) codeStage.hidden = true;
  if (newPasswordStage) newPasswordStage.hidden = true;
  if (codeInput) codeInput.value = "";
  if (newPassword) newPassword.value = "";
  if (newPasswordConfirm) newPasswordConfirm.value = "";
  if (resendBtn) resendBtn.disabled = true;
  setAuthStatus("authResetStatus", "");
  clearPasswordRules("authResetPasswordRules");
}

function setPasswordRecoveryStage(stage = "email") {
  const stages = {
    email: document.getElementById("authResetEmailStage"),
    code: document.getElementById("authResetCodeStage"),
    password: document.getElementById("authNewPasswordStage")
  };
  Object.entries(stages).forEach(([key, el]) => {
    if (el) el.hidden = key !== stage;
  });
}

function setAuthButtonLoading(button, loadingText = "Working...") {
  if (!button) return () => {};
  const originalText = button.textContent;
  button.disabled = true;
  button.textContent = loadingText;
  return () => {
    button.disabled = false;
    button.textContent = originalText;
  };
}

function startAuthResetCountdown() {
  const countdown = document.getElementById("authResetCountdown");
  const resendBtn = document.getElementById("authResendResetCodeBtn");
  authResetExpiresAt = Date.now() + 120000;
  if (resendBtn) resendBtn.disabled = true;
  if (authResetTimer) window.clearInterval(authResetTimer);
  const tick = () => {
    const remaining = Math.max(0, Math.ceil((authResetExpiresAt - Date.now()) / 1000));
    if (countdown) countdown.textContent = remaining ? `Code expires in ${remaining}s` : "Code expired. You can resend now.";
    if (!remaining) {
      if (resendBtn) resendBtn.disabled = false;
      window.clearInterval(authResetTimer);
      authResetTimer = 0;
    }
  };
  tick();
  authResetTimer = window.setInterval(tick, 1000);
}

async function requestPasswordRecoveryCode(email = "") {
  if (!supabaseClient?.auth) throw new Error("RankedCoach auth is not connected yet.");
  const { error } = await supabaseClient.auth.resetPasswordForEmail(email, {
    redirectTo: window.location.href
  });
  if (error) throw error;
}

async function verifyPasswordRecoveryCode(email = "", code = "") {
  if (!supabaseClient?.auth) throw new Error("RankedCoach auth is not connected yet.");
  authRecoveryInProgress = true;
  const { error } = await supabaseClient.auth.verifyOtp({
    email,
    token: String(code || "").replace(/\D/g, ""),
    type: "recovery"
  });
  if (error) throw error;
}

