function updateWeeklyFocusDetailsModel(topInsights = []) {
  updateWeeklyFocusDateLabel();
  const whyEl = document.getElementById("insightFocusWhy");
  const howEl = document.getElementById("insightFocusHow");
  const sourceEl = document.getElementById("insightFocusSource");
  const priorityEl = document.getElementById("insightPriorityPill");
  const confidenceEl = document.getElementById("insightConfidencePill");
  const summaryEl = document.getElementById("weeklyFocusSummary");
  const model = getPlayerModel();
  const weekly = model?.weekly || {};
  const weeklyCards = weekly.cards || {};
  const weeklyCandidates = model?.scoring?.weeklyCandidates || [];
  const primaryCandidate = weeklyCandidates[0] || null;
  const leadInsight = topInsights[0] || cachedInsights[0] || null;

  const applyConfidencePillClass = (el, confidence = {}) => {
    const label = confidence.label || "Low";
    el.classList.remove("confidence-high", "confidence-medium", "confidence-low");
    el.classList.add(
      label === "High" ? "confidence-high" :
      label === "Medium" ? "confidence-medium" :
      "confidence-low"
    );
    return label;
  };

  const weeklyPillMeta = {
    tilt: { title: "Tilt Pattern", fallback: weekly.topMood || "No mood trend yet", confidence: weeklyCards.primary },
    ratings: { title: "Self-Rating Pattern", fallback: weekly.weakestTheme || "No low-rating pattern yet", confidence: weeklyCards.secondary },
    losses: { title: "Loss Pattern", fallback: "No repeated loss context yet", confidence: { label: "Low", detail: "Waiting for loss-pattern confidence data." } },
    impactful: { title: "Biggest Focus Gap", fallback: "No clear focus gap yet", confidence: weeklyCards.tertiary }
  };

  if (summaryEl) {
    const renderedCandidates = weeklyCandidates.length
      ? weeklyCandidates.slice(0, 4)
      : [
          { key: "tilt", label: weekly.topMood || "No mood trend yet", confidence: weeklyCards.primary?.label || "Low", detail: weeklyCards.primary?.detail || "Waiting for confidence data." },
          { key: "ratings", label: weekly.weakestTheme || "No low-rating pattern yet", confidence: weeklyCards.secondary?.label || "Low", detail: weeklyCards.secondary?.detail || "Waiting for confidence data." },
          { key: "losses", label: "No repeated loss context yet", confidence: "Low", detail: "Waiting for confidence data." },
          { key: "impactful", label: weekly.mostPracticed || activeInsightFocus || "No repeated focus category yet", confidence: weeklyCards.tertiary?.label || "Low", detail: weeklyCards.tertiary?.detail || "Waiting for confidence data." }
        ];

    summaryEl.innerHTML = renderedCandidates.map((candidate, index) => {
      const meta = weeklyPillMeta[candidate?.key] || { title: `Weekly Read ${index + 1}`, fallback: "Waiting for weekly read", confidence: { label: candidate?.confidence || "Low", detail: candidate?.detail || "Waiting for confidence data." } };
      const confidenceConfig = {
        label: candidate?.confidence || meta?.confidence?.label || "Low",
        detail: candidate?.detail || meta?.confidence?.detail || "Waiting for confidence data."
      };
      const confidenceClassName = confidenceConfig.label === "High"
        ? "confidence-high"
        : confidenceConfig.label === "Medium"
          ? "confidence-medium"
          : "confidence-low";
      const pillBody = normalizeRankedCoachCopy(candidate?.summary || candidate?.label || meta.fallback);

      return `
        <button class="weekly-focus-pill" type="button" data-weekly-key="${escapeHtml(candidate?.key || "")}" title="${escapeHtml(candidate?.sourceLabel || confidenceConfig.detail)}">
          <div class="weekly-focus-pill-head">
            <span class="weekly-focus-key">${escapeHtml(meta.title)}</span>
            <span class="weekly-focus-confidence ${confidenceClassName}" title="${escapeHtml(confidenceConfig.detail)}">Confidence: ${escapeHtml(confidenceConfig.label)}</span>
          </div>
          <span class="weekly-focus-text">${escapeHtml(pillBody)}</span>
        </button>
      `;
    }).join("");
  }

  if (whyEl) {
    whyEl.textContent = primaryCandidate?.summary
      || primaryCandidate?.read
      || leadInsight?.preview
      || weekly.why
      || "Add more matches and logs to sharpen the weekly focus category.";
  }
  if (howEl) {
    howEl.textContent = model?.coachRecommendation
      || primaryCandidate?.read
      || leadInsight?.action
      || weekly.how
      || "Use one coaching focus category for the week and review whether the next match block improved it.";
  }
  if (sourceEl) {
    sourceEl.textContent = primaryCandidate?.sourceLabel
      || weekly.source
      || "Waiting for profile data";
  }
  if (priorityEl) {
    priorityEl.textContent = `Priority: ${model?.priorityLabel || "Watch"}`;
    applyInsightMetaPillTone(priorityEl, getInsightMetaToneClass("priority", model?.priorityLabel || "Watch"));
  }
  if (confidenceEl) {
    const confidenceLabel = String(model?.confidenceLabel || "Low Confidence").replace(/\s*Confidence$/i, "") || "Low";
    confidenceEl.textContent = `Confidence: ${confidenceLabel}`;
    applyInsightMetaPillTone(confidenceEl, getInsightMetaToneClass("confidence", model?.confidenceLabel || "Low Confidence"));
  }
}

function initStatsPageModel() {
  renderStatsSummaryMeta();
  renderStatsPeakProgress();
  renderStatsRoleProgress();
  renderStatsPerformance();
  renderStatsBreakdown();
  renderStatsAgents();
  renderStatsMaps();
  renderStatsWeapons();
  ensureMobileTrendCarousel();
  ensureMobileStatsBreakdownCarousel();

  const kdEl = document.getElementById("statKD");
  const wrEl = document.getElementById("statWinrate");
  const adrEl = document.getElementById("statADR");
  const hsEl = document.getElementById("statHS");
  const firstBloodsEl = document.getElementById("statFirstBloods");
  const damagePerRoundEl = document.getElementById("statDamagePerRound");
  const model = getPlayerModel();
  const overview = model?.overview || {};
  const scopedMatches = getScopedStatsData(getActiveProfile()).matches || [];
  const firstBloods = scopedMatches.reduce((total, match) => total + safeNumber(getMatchAdvancedImpactSignals(match).firstBloods), 0);

  if (!kdEl) return;

  kdEl.textContent = overview.matchesPlayed ? overview.kd.toFixed(2) : "--";
  wrEl.textContent = overview.matchesPlayed ? `${Math.round(overview.winrate)}%` : "--";
  adrEl.textContent = overview.matchesPlayed ? `${Math.round(overview.adr)}` : "--";
  hsEl.textContent = overview.matchesPlayed ? `${Math.round(overview.hs)}%` : "--";
  if (firstBloodsEl) firstBloodsEl.textContent = overview.matchesPlayed ? `${Math.round(firstBloods)}` : "--";
  if (damagePerRoundEl) damagePerRoundEl.textContent = overview.matchesPlayed ? `${Math.round(overview.adr)}` : "--";
}

let renderStatsPerformance = renderStatsPerformanceModel;
let renderStatsBreakdown = renderStatsBreakdownModel;
renderInsights = renderInsightsModel;
renderTrendBreakdown = renderTrendBreakdownModel;
updateWeeklyFocusDetails = updateWeeklyFocusDetailsModel;
initStatsPage = initStatsPageModel;

function renderStatsAgentsModel() {
  const container = document.getElementById("statsAgentsList");
  if (!container) return;

  const roleFilters = [
    { key: "duelist", label: "Duelist" },
    { key: "controller", label: "Controller" },
    { key: "initiator", label: "Initiator" },
    { key: "sentinel", label: "Sentinel" }
  ];
  const isMobile = isStatsMobileLayout();
  if (!roleFilters.some(role => role.key === mobileStatsAgentRole)) {
    mobileStatsAgentRole = "duelist";
  }

  const model = getPlayerModel();
  const agents = (model?.agents || []).slice();
  const agentByName = new Map(
    agents.map(agent => [String(agent?.agent || "").toLowerCase(), agent])
  );
  const grouped = {
    duelist: [],
    controller: [],
    initiator: [],
    sentinel: []
  };

  allAgents.forEach((agentName) => {
    const roleKey = String(agentRoles?.[agentName] || "").toLowerCase();
    if (!grouped[roleKey]) return;
    const data = agentByName.get(agentName.toLowerCase()) || null;
    grouped[roleKey].push({
      ...(data || {}),
      agent: agentName,
      role: roleKey,
      hasData: Boolean(data && safeNumber(data.matchesPlayed || data.matches) > 0)
    });
  });

  container.innerHTML = "";

  if (!isMobile) {
    container.className = "stats-agent-list stats-agent-category-grid stats-desktop-agent-columns";
    roleFilters.forEach((roleMeta) => {
      const items = (grouped[roleMeta.key] || []).slice().sort((a, b) =>
        Number(Boolean(b.hasData)) - Number(Boolean(a.hasData)) ||
        safeNumber(b.winrate) - safeNumber(a.winrate) ||
        safeNumber(b.matchesPlayed) - safeNumber(a.matchesPlayed) ||
        String(a.agent || "").localeCompare(String(b.agent || ""))
      );
      const column = document.createElement("section");
      column.className = `stats-agent-desktop-column role-${roleMeta.key}`;
      column.dataset.agentRole = roleMeta.key;
      column.innerHTML = `
        <div class="stats-agent-desktop-heading role-${escapeHtml(roleMeta.key)}" data-role="${escapeHtml(roleMeta.key)}">
          <img src="${escapeHtml(ROLE_ICON_MAP[roleMeta.key] || "")}" alt="">
          <span>${escapeHtml(roleMeta.label)}</span>
        </div>
      `;

      items.forEach((agent) => {
        const hasData = Boolean(agent.hasData);
        const winrateValue = safeNumber(agent.winrate);
        const kdValue = safeNumber(agent.kd);
        const winrateTone = hasData ? (winrateValue >= 50 ? "stats-value-positive" : "stats-value-negative") : "";
        const toneClass = hasData
          ? (winrateValue >= 50 ? "is-positive" : "is-negative")
          : "is-empty is-locked";
        const button = document.createElement("button");
        button.type = "button";
        button.disabled = !hasData;
        button.className = `stats-agent-mini-card ${toneClass}`;
        button.setAttribute("aria-label", hasData ? `Open ${agent.agent} agent insights` : `${agent.agent} has no data`);
        button.innerHTML = `
          <span class="stats-agent-mini-name">${escapeHtml(agent.agent)}</span>
          <img class="stats-agent-mini-image" src="${escapeHtml(getAgentIconUrl(agent.agent))}" alt="${escapeHtml(agent.agent)}">
          <span class="stats-card-meta stats-agent-mini-meta">
            <span class="stats-sub-text ${winrateTone}">${hasData ? `${Math.round(winrateValue)}% WR` : "No Data"}</span>
            <span class="stats-sub-text">${hasData ? `${kdValue.toFixed(2)} K/D` : escapeHtml(roleMeta.label)}</span>
          </span>
        `;
        if (hasData) {
          button.addEventListener("click", () => openStatsDetailModal("agent", agent.agent));
        }
        column.appendChild(button);
      });
      container.appendChild(column);
    });
    return;
  }

  container.className = "stats-agent-list stats-agent-grid";

  if (isMobile) {
    const filter = document.createElement("div");
    filter.className = "stats-mobile-role-filter";
    filter.setAttribute("aria-label", "Filter agents by role");
    filter.innerHTML = roleFilters.map((role) => `
      <button type="button" class="stats-mobile-role-filter-btn ${role.key === mobileStatsAgentRole ? "active" : ""}" data-stats-agent-role="${escapeHtml(role.key)}" aria-pressed="${role.key === mobileStatsAgentRole ? "true" : "false"}">
        <img src="${escapeHtml(ROLE_ICON_MAP[role.key] || "")}" alt="">
        <span>${escapeHtml(role.label)}</span>
      </button>
    `).join("");
    filter.addEventListener("click", (event) => {
      const button = event.target.closest("[data-stats-agent-role]");
      if (!button) return;
      event.preventDefault();
      mobileStatsAgentRole = String(button.dataset.statsAgentRole || "duelist").toLowerCase();
      renderStatsAgentsModel();
    });
    container.appendChild(filter);
  }

  Object.entries(grouped).filter(([role]) => !isMobile || role === mobileStatsAgentRole).forEach(([role, items]) => {
    items.sort((a, b) =>
      Number(Boolean(b.hasData)) - Number(Boolean(a.hasData)) ||
      safeNumber(b.winrate) - safeNumber(a.winrate) ||
      safeNumber(b.matchesPlayed) - safeNumber(a.matchesPlayed) ||
      String(a.agent || "").localeCompare(String(b.agent || ""))
    );

    const column = document.createElement("div");
    column.className = "stats-agent-column";
    column.dataset.agentRole = role;

    const heading = document.createElement("div");
    heading.className = "stats-agent-column-title";
    heading.dataset.role = role;
    heading.textContent = role.charAt(0).toUpperCase() + role.slice(1);
    column.appendChild(heading);

    if (!items.length) {
      const empty = document.createElement("div");
      empty.className = "stats-empty";
      empty.textContent = "No Data";
      column.appendChild(empty);
    } else {
      items.forEach((agent) => {
        const hasData = Boolean(agent.hasData);
        const winrateValue = safeNumber(agent.winrate);
        const kdValue = safeNumber(agent.kd);
        const winrateTone = hasData ? (winrateValue >= 50 ? "stats-value-positive" : "stats-value-negative") : "";
        const kdTone = hasData ? (kdValue >= 1 ? "stats-value-positive" : "stats-value-negative") : "";
        const toneClass = hasData
          ? (winrateValue >= 50 ? "is-positive" : "is-negative")
          : "is-empty is-locked";
        const row = document.createElement("div");
        row.className = `stats-agent-row ${hasData ? "stats-select-card" : ""} ${toneClass}`;
        row.setAttribute("aria-disabled", hasData ? "false" : "true");
        row.innerHTML = `
          <div class="stats-primary-cell">
            <img src="${getAgentIconUrl(agent.agent)}" class="stats-cell-icon stats-agent-tile-icon" />
            <div class="stats-agent-metrics-stack">
              <span class="stats-metric-line"><span class="stats-metric-label">${escapeHtml(agent.agent)}</span></span>
              <span class="stats-metric-line"><span class="stats-metric-label">W/R</span><span class="stats-metric-text ${winrateTone}">${hasData ? `${Math.round(winrateValue)}%` : "No Data"}</span></span>
              <span class="stats-metric-line"><span class="stats-metric-label">K/D</span><span class="stats-metric-text ${kdTone}">${hasData ? kdValue.toFixed(2) : "No Data"}</span></span>
            </div>
          </div>
        `;
        if (hasData) {
          row.addEventListener("click", () => openStatsDetailModal("agent", agent.agent));
        }
        column.appendChild(row);
      });
    }

    container.appendChild(column);
  });
}

function renderStatsMapsModel() {
  const container = document.getElementById("statsMapsList");
  if (!container) return;

  const model = getPlayerModel();
  const maps = (model?.maps || []).slice();
  const mapByName = new Map(
    maps.map(map => [String(map?.map || "").toLowerCase(), map])
  );
  const selectedAct = model?.currentAct || activeStatsActLabel || "";
  const playedMapNames = maps
    .filter(map => safeNumber(map?.matchesPlayed || map?.matches) > 0)
    .map(map => String(map?.map || "").trim())
    .filter(Boolean);
  const configuredPool = DEMO_ACT_MAP_POOLS[selectedAct] || [];
  const activePool = [...new Set([...configuredPool, ...playedMapNames])];
  if (!activePool.length) activePool.push(...COMPETITIVE_MAP_POOL);
  const poolSet = new Set(activePool.map(mapName => String(mapName).toLowerCase()));
  const activeMapNames = activePool.slice().sort((a, b) => {
    const mapA = mapByName.get(String(a).toLowerCase());
    const mapB = mapByName.get(String(b).toLowerCase());
    const hasA = Boolean(mapA && safeNumber(mapA.matchesPlayed || mapA.matches) > 0);
    const hasB = Boolean(mapB && safeNumber(mapB.matchesPlayed || mapB.matches) > 0);
    if (hasA !== hasB) return hasA ? -1 : 1;
    if (hasA && hasB) {
      const winrateDelta = safeNumber(mapB.winrate) - safeNumber(mapA.winrate);
      if (Math.abs(winrateDelta) > 0.01) return winrateDelta;
      const volumeDelta = safeNumber(mapB.matchesPlayed || mapB.matches) - safeNumber(mapA.matchesPlayed || mapA.matches);
      if (volumeDelta) return volumeDelta;
    }
    return String(a).localeCompare(String(b));
  });
  const excludedMapNames = ALL_VALORANT_MAP_NAMES
    .filter(mapName => !poolSet.has(String(mapName).toLowerCase()))
    .sort((a, b) => String(a).localeCompare(String(b)));
  const renderMapNames = [...activeMapNames, ...excludedMapNames];

  container.innerHTML = "";
  container.classList.add("stats-map-grid");

  renderMapNames.forEach((mapName) => {
    const map = mapByName.get(String(mapName || "").toLowerCase()) || null;
    const hasData = Boolean(map && safeNumber(map.matchesPlayed || map.matches) > 0);
    const isActivePool = poolSet.has(String(mapName || "").toLowerCase());
    const canOpen = hasData && isActivePool;
    const winrateValue = safeNumber(map?.winrate);
    const winrateTone = hasData ? (winrateValue >= 50 ? "stats-value-positive" : "stats-value-negative") : "";
    const card = document.createElement("button");
    card.type = "button";
    card.disabled = !canOpen;
    card.className = `stats-map-card ${canOpen ? (winrateValue >= 50 ? "is-positive" : "is-negative") : "is-empty is-locked"}${!isActivePool ? " is-excluded" : ""}`;
    card.innerHTML = `
      ${!canOpen ? `<span class="stats-map-excluded-x" aria-hidden="true">X</span>` : ""}
      <img class="stats-map-image" src="${getMapIconUrl(mapName)}" alt="${escapeHtml(mapName)}">
      <div class="stats-map-meta">
        <span class="stats-main-text">${escapeHtml(mapName)}</span>
        <span class="stats-sub-text ${canOpen ? winrateTone : ""}">${!isActivePool ? "Out-of-Season" : hasData ? `${Math.round(winrateValue)}% WR` : "No Data"}</span>
        ${!isActivePool ? `<span class="stats-map-out-badge">Out-of-Season</span>` : ""}
      </div>
    `;
    if (canOpen) {
      card.addEventListener("click", () => openStatsDetailModal("map", map.map));
    }
    container.appendChild(card);
  });
}

function renderStatsWeaponsModel() {
  const container = document.getElementById("statsWeaponsList");
  if (!container) return;

  const scoped = getScopedStatsData();
  const weaponSummaries = summarizeSpecificWeaponRounds(scoped.matches);
  const summaryMap = new Map(weaponSummaries.map(weapon => [weapon.weaponKey, weapon]));
  const isMobile = isStatsMobileLayout();
  if (!STATS_WEAPON_FAMILIES.some(family => family.key === mobileStatsWeaponFamily)) {
    mobileStatsWeaponFamily = STATS_WEAPON_FAMILIES[0]?.key || "rifle";
  }
  const familiesToRender = isMobile
    ? STATS_WEAPON_FAMILIES.filter(family => family.key === mobileStatsWeaponFamily)
    : STATS_WEAPON_FAMILIES;

  if (!isMobile) {
    container.innerHTML = "";
    container.className = "stats-weapon-list stats-weapon-family-list stats-desktop-weapon-rows";
    STATS_WEAPON_FAMILIES.forEach((family) => {
      const familySummary = getWeaponFamilySummary(family, summaryMap);
      const hasFamilyData = safeNumber(familySummary.rounds) > 0;
      const familyToneClass = hasFamilyData
        ? (safeNumber(familySummary.winrate) >= 50 ? "is-positive" : "is-negative")
        : "is-empty is-locked";
      const row = document.createElement("section");
      row.className = `stats-desktop-weapon-family-row ${familyToneClass}`;
      row.dataset.weaponFamily = family.key;
      row.style.setProperty("--weapon-count", String(family.weapons.length));
      row.innerHTML = `
        <div class="stats-desktop-weapon-family-head">
          <span class="stats-desktop-weapon-family-title">${escapeHtml(family.label)}</span>
          <span class="stats-desktop-weapon-family-meta ${hasFamilyData ? (safeNumber(familySummary.winrate) >= 50 ? "stats-value-positive" : "stats-value-negative") : ""}">
            ${hasFamilyData ? `${Math.round(safeNumber(familySummary.winrate))}% AVG WR` : "No Data"}
          </span>
        </div>
        <div class="stats-desktop-weapon-image-row"></div>
      `;
      const imageRow = row.querySelector(".stats-desktop-weapon-image-row");
      family.weapons.slice().sort((weaponA, weaponB) => {
        const summaryA = summaryMap.get(normalizeStatsWeaponKey(weaponA));
        const summaryB = summaryMap.get(normalizeStatsWeaponKey(weaponB));
        const hasA = safeNumber(summaryA?.rounds) > 0;
        const hasB = safeNumber(summaryB?.rounds) > 0;
        if (hasA !== hasB) return hasA ? -1 : 1;
        if (hasA && hasB) {
          const winrateDelta = safeNumber(summaryB?.winrate) - safeNumber(summaryA?.winrate);
          if (Math.abs(winrateDelta) > 0.01) return winrateDelta;
          return safeNumber(summaryB?.rounds) - safeNumber(summaryA?.rounds);
        }
        return getStatsWeaponOrderIndex(weaponA) - getStatsWeaponOrderIndex(weaponB);
      }).forEach((weaponName) => {
        const weaponKey = normalizeStatsWeaponKey(weaponName);
        const weapon = summaryMap.get(weaponKey);
        const hasWeaponData = safeNumber(weapon?.rounds) > 0;
        const weaponWinrate = safeNumber(weapon?.winrate);
        const weaponWinrateTone = hasWeaponData ? (weaponWinrate >= 50 ? "stats-value-positive" : "stats-value-negative") : "";
        const toneClass = hasWeaponData
          ? (weaponWinrate >= 50 ? "is-positive" : "is-negative")
          : "is-empty is-locked";
        const button = document.createElement("button");
        button.type = "button";
        button.disabled = !hasWeaponData;
        button.className = `stats-desktop-weapon-tile ${toneClass}`;
        button.dataset.weaponKey = weaponKey;
        button.setAttribute("aria-label", hasWeaponData ? `Open ${weaponName} weapon insights` : `${weaponName} has no data`);
        button.innerHTML = `
          <span class="stats-desktop-weapon-art-wrap">
            <img class="stats-desktop-weapon-art" src="${escapeHtml(getStatsWeaponAssetPath(weaponName))}" alt="${escapeHtml(weaponName)} weapon">
          </span>
          <span class="stats-card-meta stats-desktop-weapon-meta">
            <span class="stats-main-text">${escapeHtml(weaponName)}</span>
            <span class="stats-sub-text ${weaponWinrateTone}">${hasWeaponData ? `${Math.round(weaponWinrate)}% WR` : "No Data"}</span>
          </span>
        `;
        if (hasWeaponData) {
          button.addEventListener("click", () => openStatsDetailModal("weapon", weaponKey));
        }
        imageRow?.appendChild(button);
      });
      container.appendChild(row);
    });
    return;
  }

  const mobileFilterMarkup = isMobile ? `
    <div class="stats-mobile-weapon-filter" aria-label="Filter weapons by category">
      ${STATS_WEAPON_FAMILIES.map((family) => `
        <button type="button" class="stats-mobile-weapon-filter-btn ${family.key === mobileStatsWeaponFamily ? "active" : ""}" data-stats-weapon-family="${escapeHtml(family.key)}" aria-pressed="${family.key === mobileStatsWeaponFamily ? "true" : "false"}">
          ${escapeHtml(family.label)}
        </button>
      `).join("")}
    </div>
  ` : "";

  container.innerHTML = `${mobileFilterMarkup}${familiesToRender.map((family) => {
    const familySummary = getWeaponFamilySummary(family, summaryMap);
    const hasFamilyData = safeNumber(familySummary.rounds) > 0;
    const toneClass = hasFamilyData
      ? (safeNumber(familySummary.winrate) >= 50 ? "is-positive" : "is-negative")
      : "is-empty is-locked";
    const orderedWeapons = family.weapons.slice().sort((weaponA, weaponB) => {
      const summaryA = summaryMap.get(normalizeStatsWeaponKey(weaponA));
      const summaryB = summaryMap.get(normalizeStatsWeaponKey(weaponB));
      const hasA = safeNumber(summaryA?.rounds) > 0;
      const hasB = safeNumber(summaryB?.rounds) > 0;
      if (hasA !== hasB) return hasA ? -1 : 1;
      if (hasA && hasB) {
        const winrateDelta = safeNumber(summaryB?.winrate) - safeNumber(summaryA?.winrate);
        if (Math.abs(winrateDelta) > 0.01) return winrateDelta;
        return safeNumber(summaryB?.rounds) - safeNumber(summaryA?.rounds);
      }
      return String(weaponA).localeCompare(String(weaponB));
    });

    const weaponTiles = orderedWeapons.map((weaponName) => {
      const weaponKey = normalizeStatsWeaponKey(weaponName);
      const weapon = summaryMap.get(weaponKey);
      const hasWeaponData = safeNumber(weapon?.rounds) > 0;
      const assetPath = getStatsWeaponAssetPath(weaponName);
      const weaponWinrate = safeNumber(weapon?.winrate);
      const winrateLabel = hasWeaponData ? `${Math.round(weaponWinrate)}% WR` : "No Data";
      const weaponWinrateTone = hasWeaponData ? (weaponWinrate >= 50 ? "stats-value-positive" : "stats-value-negative") : "";
      const tileTone = hasWeaponData
        ? (weaponWinrate >= 50 ? "is-positive" : "is-negative")
        : "is-empty is-locked";

      return `
        <button type="button" class="stats-weapon-tile ${hasWeaponData ? "has-data" : "is-empty"} ${tileTone}" data-weapon-key="${escapeHtml(weaponKey)}" aria-label="Open ${escapeHtml(weaponName)} weapon insights" ${hasWeaponData ? "" : "disabled aria-disabled=\"true\""}>
          <span class="stats-weapon-art-wrap">
            <img class="stats-weapon-art" src="${escapeHtml(assetPath)}" alt="${escapeHtml(weaponName)} weapon">
          </span>
          <span class="stats-weapon-label-row">
            <span class="stats-weapon-name">${escapeHtml(weaponName)}</span>
            <span class="stats-weapon-mini"><span class="${weaponWinrateTone}">${escapeHtml(winrateLabel)}</span></span>
          </span>
        </button>
      `;
    }).join("");

    return `
      <section class="stats-weapon-family-row ${hasFamilyData ? "has-data" : "is-empty"} ${toneClass}" style="--weapon-count:${family.weapons.length}">
        <div class="stats-weapon-family-head" ${isMobile ? "hidden aria-hidden=\"true\"" : ""}>
          <span class="stats-weapon-family-title">${escapeHtml(family.label)}</span>
        </div>
        <div class="stats-weapon-image-row">
          ${weaponTiles}
        </div>
      </section>
    `;
  }).join("")}`;

  container.querySelectorAll("[data-stats-weapon-family]").forEach((button) => {
    button.addEventListener("click", (event) => {
      event.preventDefault();
      mobileStatsWeaponFamily = String(button.dataset.statsWeaponFamily || "rifle").toLowerCase();
      renderStatsWeaponsModel();
    });
  });

  container.querySelectorAll(".stats-weapon-tile").forEach((button) => {
    if (button.disabled || button.classList.contains("is-empty")) return;
    button.addEventListener("click", () => openStatsDetailModal("weapon", button.dataset.weaponKey || ""));
  });
}

let statsActMobileMenu = null;

function applyStatsActSelection(nextLabel = "") {
  activeStatsActLabel = String(nextLabel || "").trim();
  initStatsPage();
  renderStatsAgents();
  renderStatsMaps();
  renderStatsWeaponsModel();
  renderInsights();
  if (typeof updateHomeFromMatches === "function") updateHomeFromMatches();
  renderChart(currentSize);
}

function positionStatsActMobileMenu() {
  const trigger = document.getElementById("statsActMobileTrigger");
  const panel = statsActMobileMenu?.querySelector?.(".stats-act-mobile-menu-panel");
  if (!trigger || !panel || statsActMobileMenu?.hidden) return;
  const rect = trigger.getBoundingClientRect();
  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 390;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 844;
  const width = Math.min(Math.max(rect.width, 220), viewportWidth - 24);
  const optionCount = statsActMobileMenu.querySelectorAll("[data-stats-act-option]").length;
  const estimatedHeight = Math.min(292, 58 + (optionCount * 47));
  const left = Math.min(Math.max(12, rect.left), Math.max(12, viewportWidth - width - 12));
  const bottomNavHeight = document.getElementById("mobileBottomShell")?.getBoundingClientRect?.().height || 0;
  const usableBottom = viewportHeight - bottomNavHeight - 12;
  const spaceBelow = usableBottom - rect.bottom - 8;
  const top = spaceBelow >= estimatedHeight
    ? rect.bottom + 8
    : Math.max(12, rect.top - estimatedHeight - 8);
  panel.style.left = `${Math.round(left)}px`;
  panel.style.top = `${Math.round(top)}px`;
  panel.style.width = `${Math.round(width)}px`;
}

function ensureStatsActMobileMenu() {
  if (statsActMobileMenu?.isConnected) return statsActMobileMenu;
  statsActMobileMenu = document.createElement("div");
  statsActMobileMenu.id = "statsActMobileMenu";
  statsActMobileMenu.className = "stats-act-mobile-menu-overlay";
  statsActMobileMenu.hidden = true;
  statsActMobileMenu.innerHTML = `
    <div class="stats-act-mobile-menu-panel" role="listbox" aria-labelledby="statsActLabel">
      <div class="stats-act-mobile-menu-head">
        <span>Season Stats For</span>
        <button class="stats-act-mobile-menu-close" type="button" aria-label="Close season selector">Close</button>
      </div>
      <div class="stats-act-mobile-menu-list"></div>
    </div>
  `;
  statsActMobileMenu.addEventListener("click", (event) => {
    if (event.target === statsActMobileMenu || event.target.closest(".stats-act-mobile-menu-close")) {
      closeStatsActMobileMenu();
      return;
    }
    const option = event.target.closest("[data-stats-act-option]");
    if (!option) return;
    closeStatsActMobileMenu();
    applyStatsActSelection(option.dataset.statsActOption || "");
  });
  statsActMobileMenu.addEventListener("touchmove", (event) => event.stopPropagation(), { passive: true });
  document.body.appendChild(statsActMobileMenu);
  window.addEventListener("resize", positionStatsActMobileMenu, { passive: true });
  window.addEventListener("scroll", positionStatsActMobileMenu, { passive: true, capture: true });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && !statsActMobileMenu.hidden) closeStatsActMobileMenu();
  });
  return statsActMobileMenu;
}

function closeStatsActMobileMenu() {
  if (!statsActMobileMenu) return;
  statsActMobileMenu.hidden = true;
  statsActMobileMenu.classList.remove("is-open");
  document.body.classList.remove("stats-act-menu-open");
  const trigger = document.getElementById("statsActMobileTrigger");
  trigger?.setAttribute("aria-expanded", "false");
}

function openStatsActMobileMenu(options = [], selectedLabel = "") {
  const menu = ensureStatsActMobileMenu();
  const list = menu.querySelector(".stats-act-mobile-menu-list");
  list.innerHTML = options.map((label) => {
    const isSelected = label === selectedLabel;
    return `
      <button class="stats-act-mobile-option ${isSelected ? "is-selected" : ""}" type="button" role="option" aria-selected="${isSelected ? "true" : "false"}" data-stats-act-option="${escapeHtml(label)}">
        <span>${escapeHtml(label)}</span>
        <span class="stats-act-mobile-option-mark" aria-hidden="true">${isSelected ? "Selected" : ""}</span>
      </button>
    `;
  }).join("");
  menu.hidden = false;
  menu.classList.add("is-open");
  document.body.classList.add("stats-act-menu-open");
  document.getElementById("statsActMobileTrigger")?.setAttribute("aria-expanded", "true");
  positionStatsActMobileMenu();
  window.requestAnimationFrame(() => {
    list.querySelector(".is-selected")?.scrollIntoView?.({ block: "nearest" });
  });
}

function renderStatsSummaryMetaModel() {
  const selector = document.getElementById("statsActSelector");
  if (!selector) return;
  const label = document.querySelector("#page-stats .stats-act-label");
  if (label) label.textContent = "Season Stats For";

  const model = getPlayerModel();
  const fallbackSeasonLabel = CURRENT_VALORANT_SEASON_LABEL;
  const normalizeSeasonLabel = (label = "") => {
    const value = String(label || "").trim();
    if (isPlaceholderStatsActLabel(value)) {
      return fallbackSeasonLabel;
    }
    return value;
  };
  const currentLabel = normalizeSeasonLabel(activeStatsActLabel || model?.currentAct);
  const options = [...new Set((model?.acts?.length ? model.acts : [currentLabel]).map(normalizeSeasonLabel))];

  selector.innerHTML = "";
  options.forEach((label) => {
    const option = document.createElement("option");
    option.value = label;
    option.textContent = label;
    selector.appendChild(option);
  });
  selector.value = options.includes(currentLabel) ? currentLabel : options[0] || currentLabel;
  activeStatsActLabel = selector.value || activeStatsActLabel || currentLabel;
  selector.onchange = () => applyStatsActSelection(selector.value || "");

  const mobileTrigger = document.getElementById("statsActMobileTrigger");
  const mobileValue = document.getElementById("statsActMobileValue");
  if (mobileTrigger) {
    mobileTrigger.hidden = false;
    mobileTrigger.setAttribute("aria-expanded", "false");
    mobileTrigger.onclick = () => openStatsActMobileMenu(options, selector.value || currentLabel);
  }
  if (mobileValue) mobileValue.textContent = selector.value || currentLabel;

  selector.disabled = false;
  renderStatsHistoryBoundaryNote();
}

function renderStatsHistoryBoundaryNote(profile = getActiveProfile()) {
  const note = document.getElementById("statsHistoryBoundaryNote");
  if (!note) return;
  const retainedMatches = getRetainedHenrikMatchDates(profile);
  const show = isHenrikProfileData(profile) && retainedMatches.length > 0;
  note.hidden = !show;
  if (!show) {
    note.textContent = "";
    return;
  }
  const oldestDate = formatRetainedHistoryDate(retainedMatches[0]);
  note.textContent = `History limit: Riot's upstream match-history feed has an active retention limit of roughly 2 years. This account's available history begins ${oldestDate}; earlier matches are no longer retained.`;
}

function renderStatsPeakProgress() {
  const profile = getActiveProfile();
  const peak = computePeakProfileProgress(profile);
  const icon = document.getElementById("statsPeakRankIcon");
  const rankText = document.getElementById("statsPeakRankText");
  const rrText = document.getElementById("statsPeakRRText");
  const note = document.getElementById("statsPeakProofNote");

  if (icon) {
    icon.src = peak.rankIconUrl;
    icon.alt = peak.tierLabel;
  }
  if (rankText) rankText.textContent = peak.tierLabel;
  if (rrText) rrText.textContent = formatRankLocalRR(peak.peakRR, { suffix: " peak" });
  if (note) {
    const scopeLabel = peak.isSeasonScoped ? peak.scopeLabel : "this profile timeline";
    note.textContent = peak.rankDataFallback
      ? `No usable tier snapshot exists in ${scopeLabel}; showing the latest meaningful retained rank instead.`
      : peak.gainFromStart > 0
      ? `Visual proof of progress: +${Math.round(peak.gainFromStart)} RR above ${peak.isSeasonScoped ? `${peak.scopeLabel} starting point` : "your profile starting point"}.`
      : peak.matchCount
        ? `Highest point reached in ${scopeLabel} so far.`
        : `No RR movement found in ${scopeLabel} yet.`;
  }
}

function renderStatsRoleProgress() {
  const container = document.getElementById("statsRoleProgressRow");
  if (!container) return;

  const model = getPlayerModel();
  const roles = (model?.roles || []).slice();
  const importedRoles = getActiveProfile()?.trackerAnalytics?.roles || [];
  const roleSamples = new Map();
  const roleOrder = ["duelist", "controller", "initiator", "sentinel"];
  const roleDisplay = {
    duelist: "Duelist",
    controller: "Controller",
    initiator: "Initiator",
    sentinel: "Sentinel"
  };
  const normalizeRoleProgressKey = (entry = {}) => {
    const rawRole = entry?.role || entry?.roleKey || entry?.roleName || entry?.label || entry?.name || "";
    return getCompassRoleKey(rawRole);
  };
  const getRoleMatchesPlayed = (entry = {}) => safeNumber(
    entry?.matchesPlayed ?? entry?.matches ?? entry?.games ?? entry?.count
  );
  const getRoleMatchesWon = (entry = {}) => safeNumber(
    entry?.matchesWon ?? entry?.wins ?? entry?.matches_won
  );
  const getRoleWinRate = (entry = {}, matchesPlayed = getRoleMatchesPlayed(entry)) => {
    const explicitRaw = entry?.winrate ?? entry?.winRate ?? entry?.wr ?? entry?.winPct;
    const explicit = Number(explicitRaw);
    if (Number.isFinite(explicit)) {
      return explicit > 0 && explicit <= 1 ? explicit * 100 : explicit;
    }
    return matchesPlayed ? safeDivide(getRoleMatchesWon(entry) * 100, matchesPlayed) : 0;
  };
  getSortedMatches(matches || []).forEach((match) => {
    const core = getMatchCore(match);
    const roleKey = getCompassRoleKey(core.role);
    const result = String(core.result || "").toLowerCase();
    if (!roleOrder.includes(roleKey) || (result !== "win" && result !== "loss")) return;
    if (!roleSamples.has(roleKey)) roleSamples.set(roleKey, []);
    roleSamples.get(roleKey).push({ result });
  });
  const getRoleSampleWinRate = (entries = []) => {
    if (!entries.length) return 0;
    return safeDivide(entries.filter(entry => entry.result === "win").length * 100, entries.length);
  };
  const getExplicitRoleDelta = (...entries) => {
    for (const entry of entries) {
      if (!entry) continue;
      const raw = entry?.winRateDelta ?? entry?.deltaWinRate ?? entry?.wrDelta ?? entry?.delta;
      const value = Number(raw);
      if (Number.isFinite(value)) return value > -1 && value < 1 ? value * 100 : value;
    }
    return null;
  };
  const getRoleTrendDelta = (roleKey, currentWinRate, role = null, importedRole = null) => {
    const explicitDelta = getExplicitRoleDelta(role, importedRole);
    if (Number.isFinite(explicitDelta)) return explicitDelta;

    const sample = roleSamples.get(roleKey) || [];
    if (sample.length >= 2) {
      const recentCount = Math.min(5, Math.max(1, Math.ceil(sample.length / 2)));
      const recentSample = sample.slice(-recentCount);
      const previousSample = sample.slice(0, -recentCount);
      if (previousSample.length) {
        return getRoleSampleWinRate(recentSample) - getRoleSampleWinRate(previousSample);
      }
    }

    return currentWinRate - 50;
  };
  const findRoleEntry = (roleKey) => (
    roles.find(entry => normalizeRoleProgressKey(entry) === roleKey)
    || importedRoles.find(entry => normalizeRoleProgressKey(entry) === roleKey)
    || null
  );
  const roleCards = roleOrder.map((roleKey) => {
    const role = findRoleEntry(roleKey) || { role: roleKey, matchesPlayed: 0, matchesWon: 0, winrate: 0 };
    const matchesPlayed = getRoleMatchesPlayed(role);
    const currentWinRate = matchesPlayed ? getRoleWinRate(role, matchesPlayed) : 0;
    const importedRole = importedRoles.find(entry => normalizeRoleProgressKey(entry) === roleKey);
    const delta = matchesPlayed ? getRoleTrendDelta(roleKey, currentWinRate, role, importedRole) : 0;
    return {
      roleKey,
      label: roleDisplay[roleKey] || formatReadableLabel(roleKey),
      currentWinRate,
      matchesPlayed,
      delta
    };
  }).sort((a, b) => b.currentWinRate - a.currentWinRate || b.matchesPlayed - a.matchesPlayed);

  container.innerHTML = "";

  roleCards.forEach((role) => {
    const roundedDelta = Math.round(safeNumber(role.delta));
    const deltaClass = !role.matchesPlayed ? "" : roundedDelta > 0 ? "is-up" : roundedDelta < 0 ? "is-down" : "is-even";
    const deltaText = role.matchesPlayed ? `${roundedDelta >= 0 ? "+" : ""}${roundedDelta}%` : "--";

    const pill = document.createElement("div");
    pill.className = `stats-role-pill ${role.matchesPlayed ? "" : "is-empty"}`;
    pill.innerHTML = `
      <div class="stats-role-pill-main">
        <img class="stats-role-pill-icon" src="${escapeHtml(ROLE_ICON_MAP[role.roleKey] || "")}" alt="${escapeHtml(role.label)} role icon">
        <span class="stats-role-pill-label">${escapeHtml(role.label)}</span>
      </div>
      <div class="stats-role-pill-value">
        <span class="stats-role-pill-percent">${role.matchesPlayed ? `${Math.round(role.currentWinRate)}%` : "No Data"}</span>
        <span class="stats-role-pill-delta ${deltaClass}">${deltaText}</span>
      </div>
    `;
    container.appendChild(pill);
  });
}

function renderInsightCardsModel() {
  const container = document.getElementById("insightsList");
  if (!container) return;

  const model = getPlayerModel();
  const allInsights = getInsightDisplayPool(model);
  bindInsightFilters();
  const filterLabels = {
    all: "Priority Trends",
    bad: "Needs Work",
    warn: "Watch",
    good: "Strengths"
  };
  const list = getFilteredInsightDisplayList(activeInsightFilter, model);

  container.innerHTML = "";

  if (!list.length) {
    const hasAnyInsights = allInsights.length > 0;
    const filterLabel = filterLabels[activeInsightFilter] || "Priority Trends";
    const emptyCard = document.createElement("div");
    emptyCard.className = "insight-card insight-empty";
    emptyCard.innerHTML = `
      <div class="insight-header">
        <div class="insight-header-main">
          <div class="insight-title">${hasAnyInsights ? `No ${escapeHtml(filterLabel)} Insights Yet` : "RankedCoach Needs More Games"}</div>
          <div class="insight-tag">INFO</div>
        </div>
      </div>
      <div class="insight-preview">${hasAnyInsights ? "This filter is empty for the current profile window." : "This panel fills with ranked coaching reads after you import a few matches or save a few reflections."}</div>
      <div class="insight-block">
        <div class="insight-label">NEXT STEP</div>
        ${hasAnyInsights ? "Use All to review the available reads, or keep importing matches and logs until this group has enough signal." : "Import a few more matches or save a few reflections so RankedCoach can find a real pattern."}
      </div>
    `;
    container.appendChild(emptyCard);
    scheduleInsightListOverflowSync(container);
    return;
  }

  list.forEach((insight, index) => {
    const displayType = normalizeInsightFilterType(insight);
    const el = document.createElement("div");
    el.className = `insight-card insight-${displayType}`;
    if (insight?.coachingRuleId) el.dataset.coachingRule = insight.coachingRuleId;
    el.style.position = "relative";
    el.dataset.insightIndex = String(index);
    const signature = getInsightSignature(insight);
    const latestFeedback = getLatestInsightFeedback(signature);
    const priority = getPriorityLabel(insight.priority);
    const confidence = getConfidenceLabel((safeNumber(insight.priority) * 0.65) + (safeNumber(model?.confidenceScore) * 0.35));
    const priorityTone = getInsightMetaToneClass("priority", priority);
    const confidenceTone = getInsightMetaToneClass("confidence", confidence);
    const focusTone = getInsightMetaToneClass("focus", insight.focus || model?.focus || "Build Sample", displayType);
    const showPriorityMeta = displayType !== "good";
    el.innerHTML = `
      <div class="insight-header">
        ${getCoachingCategoryVisualMarkup(insight.focus || model?.focus || insight.title)}
        <div class="insight-header-main">
          <div class="insight-title">${escapeHtml(insight.title)}</div>
          <div class="insight-tag">${escapeHtml(getInsightFilterLabel(displayType))}</div>
        </div>
      </div>
      <div class="insight-preview">${escapeHtml(insight.preview || "")}</div>
      <div class="insight-meta-row">
        ${showPriorityMeta ? `<span class="insight-meta-pill ${priorityTone}">${escapeHtml(priority)} Priority</span>` : ""}
        <span class="insight-meta-pill ${confidenceTone}">${escapeHtml(confidence)}</span>
        <span class="insight-meta-pill ${focusTone}">Focus Category: ${escapeHtml(insight.focus || model?.focus || "Build Sample")}</span>
      </div>
      <div class="insight-expand">
        <div class="insight-block">
          <div class="insight-label">WHAT</div>
          ${escapeHtml(insight.what || "")}
        </div>
        <div class="insight-block">
          <div class="insight-label">WHY</div>
          ${escapeHtml(insight.why || "")}
        </div>
        <div class="insight-block">
          <div class="insight-label">ACTION</div>
          ${escapeHtml(insight.action || "")}
        </div>
        <div class="insight-sources">
          ${(insight.sources || []).map((source) => `<span class="insight-source">${escapeHtml(source)}</span>`).join("")}
        </div>
        <div class="insight-feedback-row" aria-label="Insight feedback">
          <span class="insight-feedback-label">Was this read useful?</span>
          <button type="button" class="insight-feedback-btn ${latestFeedback?.rating === "helpful" ? "is-active" : ""}" data-feedback-rating="helpful">Yes</button>
          <button type="button" class="insight-feedback-btn ${latestFeedback?.rating === "inaccurate" ? "is-active" : ""}" data-feedback-rating="inaccurate">Not really</button>
        </div>
      </div>
    `;
    container.appendChild(el);
  });

  bindInsightCards();
  mobileInsightCardIndex = Math.min(mobileInsightCardIndex, Math.max(0, container.querySelectorAll(".insight-card:not(.insight-empty)").length - 1));
  ensureMobileInsightCardCarousel();
  scheduleInsightListOverflowSync(container);
}

function renderStatsPerformanceClean() {
  const container = document.getElementById("statsPerformanceChart");
  if (!container) return;

  const model = getPlayerModel();
  container.className = "stats-chart-wrap stats-trends-list stats-trends-grid";

  if (!(model?.trends || []).length) {
    container.innerHTML = getReadinessLockedMarkup(5, "Recent Match Trends");
    return;
  }

  container.innerHTML = model.trends.map((trend) => {
    const toneMeta = getSignalToneMeta(trend?.tone);
    return `
      <button type="button" class="stats-trend-row stats-trend-card stats-trend-${toneMeta.tone} stats-select-card" data-trend-id="${escapeHtml(trend?.id || "")}">
        <div class="stats-trend-head">
          <span class="stats-trend-tone">${escapeHtml(toneMeta.label)}</span>
          <span class="stats-trend-kicker">${escapeHtml(trend?.kicker || "Current Window")}</span>
        </div>
        <div class="stats-trend-copy">
          <div class="stats-main-text">${escapeHtml(trend?.label || "Read")}</div>
          <div class="stats-sub-text">${escapeHtml(trend?.value || "--")}</div>
        </div>
        <div class="stats-trend-detail">${escapeHtml(trend?.detail || "No detail available yet.")}</div>
      </button>
    `;
  }).join("");

  container.querySelectorAll(".stats-trend-card").forEach((button) => {
    button.addEventListener("click", () => {
      openStatsDetailModal("trend", button.dataset.trendId || "");
    });
  });
  ensureMobileTrendCarousel();
  ensureMobileStatsBreakdownCarousel();
}

